"use strict";(self.webpackChunkkgenots=self.webpackChunkkgenots||[]).push([[8130],{7735:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"privileged-non-root-capabilities","metadata":{"permalink":"/blog/privileged-non-root-capabilities","source":"@site/blog/2026-09-04-privileged-non-root-capabilities/index.md","title":"privileged: true\uc778\ub370 permission denied\uac00 \ub0ac\uc2b5\ub2c8\ub2e4","description":"\ucee8\ud14c\uc774\ub108\uac00 \ube44 root \uc0ac\uc6a9\uc790\ub85c \uc2e4\ud589\ub418\uba74 privileged: true\ub97c \uc9c0\uc815\ud574\ub3c4 capability\uac00 \uc804\ub2ec\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ucee4\ub110\uc774 UID\ub97c \uc804\ud658\ud558\uba74\uc11c permitted \uc9d1\ud569\uacfc effective \uc9d1\ud569\uc744 \ube44\uc6b0\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.","date":"2026-09-04T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Kubernetes","permalink":"/blog/tags/kubernetes"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"},{"inline":true,"label":"Linux","permalink":"/blog/tags/linux"}],"readingTime":1.87,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"privileged: true\uc778\ub370 permission denied\uac00 \ub0ac\uc2b5\ub2c8\ub2e4","slug":"privileged-non-root-capabilities","authors":["kgenots"],"tags":["Reference","Kubernetes","Ops","Linux"],"image":"/assets/blog/cover-privileged-non-root-capabilities.webp","hide_table_of_contents":false},"unlisted":false,"nextItem":{"title":"\ub098\uba38\uc9c0 \uc5f0\uc0b0 \uc5c6\ub294 \ube60\ub978 \uc694\uc77c \uacc4\uc0b0, \uacf1\uc148 \ud55c \ubc88\uc774\uba74 \ub429\ub2c8\ub2e4","permalink":"/blog/fast-day-of-week"}},"content":"\ucee8\ud14c\uc774\ub108\uac00 \ube44 root \uc0ac\uc6a9\uc790\ub85c \uc2e4\ud589\ub418\uba74 `privileged: true`\ub97c \uc9c0\uc815\ud574\ub3c4 capability\uac00 \uc804\ub2ec\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ucee4\ub110\uc774 UID\ub97c \uc804\ud658\ud558\uba74\uc11c permitted \uc9d1\ud569\uacfc effective \uc9d1\ud569\uc744 \ube44\uc6b0\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \ubc31\uc5c5\uc774 \uc870\uc6a9\ud788 \uba48\ucdc4\uc2b5\ub2c8\ub2e4\\n\\nvelero\ub85c PVC\ub97c \ubc31\uc5c5\ud558\ub294\ub370 \uc5b4\ub290 \ub0a0\ubd80\ud130 \ud30c\uc77c\uc2dc\uc2a4\ud15c \ubc31\uc5c5\ub9cc \ub204\ub77d\ub418\uae30 \uc2dc\uc791\ud588\uc2b5\ub2c8\ub2e4. velero server \ud30c\ub4dc\ub294 \uacc4\uc18d Running\uc774\uc5c8\uace0 \ubc31\uc5c5 \uc624\ube0c\uc81d\ud2b8\ub3c4 \ub9cc\ub4e4\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. \uc0c1\ud0dc\ub9cc `PartiallyFailed`\uc600\uc2b5\ub2c8\ub2e4.\\n\\n\ud30c\uc77c\uc2dc\uc2a4\ud15c \ubc31\uc5c5\uc744 \ub2f4\ub2f9\ud558\ub294 \ucabd\uc740 `node-agent` DaemonSet\uc785\ub2c8\ub2e4. \ub85c\uadf8\uc5d0\ub294 \ud55c \uc904\uc774 \ubc18\ubcf5\ub418\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n```\\nopen /host_pods/: permission denied\\n```\\n\\n\ub9e4\ub2c8\ud398\uc2a4\ud2b8\uc5d0\ub294 `privileged: true`\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \uc694\uccad\ud55c capability\uc640 \uc2e4\uc81c capability\uac00 \ub2e4\ub985\ub2c8\ub2e4\\n\\n`privileged: true`\ub97c \uc9c0\uc815\ud588\ub294\ub370 \uad8c\ud55c\uc774 \uc5c6\ub2e4\uba74 \uc694\uccad\uac12\uacfc \uacb0\uacfc\uac12\uc744 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ucee8\ud14c\uc774\ub108\uac00 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc0ac\uc6a9\uc790\uc640 capability\ub85c \uc2e4\ud589 \uc911\uc778\uc9c0\ub294 `crictl`\ub85c \ubd05\ub2c8\ub2e4.\\n\\n```bash\\ncrictl inspect <container-id> \\\\\\n  | jq \'.info.runtimeSpec.process | {user, capabilities}\'\\n```\\n\\n\uc5ec\uae30\uc5d0\ub294 \uc694\uccad\ud55c capability 41\uac1c\uac00 \uadf8\ub300\ub85c \ubcf4\uc785\ub2c8\ub2e4. \ud504\ub85c\uc138\uc2a4\uac00 \uc2e4\uc81c\ub85c \ubcf4\uc720\ud55c \uac12\uc740 \ub2e4\ub985\ub2c8\ub2e4. \uac19\uc740 uid\ub85c \ud504\ub85c\ube0c \ud30c\ub4dc\ub97c \ub744\uc6cc `/proc/self/status`\ub97c \uc9c1\uc811 \uc77d\uc73c\uba74 \ucc28\uc774\uac00 \ub4dc\ub7ec\ub0a9\ub2c8\ub2e4.\\n\\n```bash\\nkubectl run capprobe --rm -it --restart=Never --image=nginx:alpine \\\\\\n  --overrides=\'{\\"spec\\":{\\"containers\\":[{\\"name\\":\\"p\\",\\"image\\":\\"nginx:alpine\\",\\n  \\"securityContext\\":{\\"privileged\\":true,\\"runAsUser\\":1002},\\n  \\"command\\":[\\"grep\\",\\"Cap\\",\\"/proc/self/status\\"]}]}}\'\\n```\\n\\n| \uc9d1\ud569 | \uac12 |\\n| --- | --- |\\n| CapBnd (bounding) | 41\uac1c \uc804\ubd80 |\\n| CapPrm (permitted) | 0 |\\n| CapEff (effective) | 0 |\\n\\n<span style={{ backgroundColor: \'#fff5b1\'}}>`privileged: true`\ub294 bounding set\ub9cc \ucc44\uc6c1\ub2c8\ub2e4.</span> \uc2e4\uc81c\ub85c \uad8c\ud55c\uc744 \ud589\uc0ac\ud558\ub294 effective set\uc740 \ube44\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \ub9e4\ub2c8\ud398\uc2a4\ud2b8\ub9cc \uc77d\uc5b4\uc11c\ub294 \uc774 \ucc28\uc774\uac00 \ubcf4\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## \ucee4\ub110\uc774 UID\ub97c \uc804\ud658\ud560 \ub54c \uc9d1\ud569\uc744 \ube44\uc6c1\ub2c8\ub2e4\\n\\n`capabilities(7)` \ubb38\uc11c\uc5d0 \uaddc\uce59\uc774 \uc801\ud600 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n> If the effective user ID is changed from nonzero to 0, then the permitted set is copied to the effective set.\\n\\n0\uc5d0\uc11c 0\uc774 \uc544\ub2cc \uac12\uc73c\ub85c \ubc14\ub014 \ub54c\ub294 \ubc18\ub300\ub85c \ub3d9\uc791\ud569\ub2c8\ub2e4. \ucee4\ub110\uc774 permitted \uc9d1\ud569\uacfc effective \uc9d1\ud569\uc744 \ube44\uc6c1\ub2c8\ub2e4. `SECBIT_NO_SETUID_FIXUP` \uc2dc\ud050\uc5b4\ube44\ud2b8\ub97c \uc124\uc815\ud558\uba74 \uc774 \ub3d9\uc791\uc744 \ub9c9\uc744 \uc218 \uc788\uc9c0\ub9cc, \ucee8\ud14c\uc774\ub108 \ub7f0\ud0c0\uc784\uc740 \uc774 \ube44\ud2b8\ub97c \uc124\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. Docker\uc5d0\uc11c\ub3c4 \uac19\uc740 \ub3d9\uc791\uc774 \ubcf4\uace0\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nbounding set\uc740 \uc55e\uc73c\ub85c \ud68d\ub4dd\ud560 \uc218 \uc788\ub294 capability\uc758 \uc0c1\ud55c\ub9cc \uc815\ud569\ub2c8\ub2e4. \uc774\ubbf8 \ube44\uc6cc\uc9c4 effective set\uc744 \ub418\uc0b4\ub9ac\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## \uc774\ubbf8\uc9c0\uc758 \uae30\ubcf8 \uc0ac\uc6a9\uc790\uac00 root\uac00 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4\\n\\n`velero/velero:v1.15.2`\uc758 \uae30\ubcf8 \uc0ac\uc6a9\uc790\ub97c \ud655\uc778\ud558\uba74 `cnb:cnb`\uac00 \ub098\uc635\ub2c8\ub2e4. uid 1002\uc785\ub2c8\ub2e4.\\n\\n```bash\\nnerdctl image inspect velero/velero:v1.15.2 | jq -r \'.[0].Config.User\'\\n# cnb:cnb\\n```\\n\\n\ud638\uc2a4\ud2b8\uc758 `/var/lib/kubelet/pods`\ub294 \uad8c\ud55c\uc774 `0750`\uc774\uace0 \uc18c\uc720\uc790\uac00 `root:root`\uc785\ub2c8\ub2e4. uid 1002\ub85c \uc2e4\ud589\ub418\ub294 \ud504\ub85c\uc138\uc2a4\uac00 `CAP_DAC_OVERRIDE` \uc5c6\uc774 \uc774 \ub514\ub809\ud130\ub9ac\ub97c \uc5f4\ub824\uace0 \ud558\uba74 \uac70\ubd80\ub2f9\ud569\ub2c8\ub2e4.\\n\\n## \ud30c\ub4dc \ub808\ubca8 runAsUser\ub97c 0\uc73c\ub85c \ub461\ub2c8\ub2e4\\n\\n\ucee8\ud14c\uc774\ub108 \ub808\ubca8 `privileged`\uac00 \uc544\ub2c8\ub77c \ud30c\ub4dc \ub808\ubca8 `runAsUser`\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n```yaml\\nspec:\\n  securityContext:\\n    runAsUser: 0\\n  containers:\\n    - name: node-agent\\n      securityContext:\\n        privileged: false\\n```\\n\\nupstream\uc758 `velero install --use-node-agent`\ub3c4 \uac19\uc740 \uc870\ud569\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. `runAsUser: 0`\uc774 \uc788\uc73c\uba74 containerd \uae30\ubcf8 capability \uc9d1\ud569\uc5d0 `CAP_DAC_OVERRIDE`\uac00 \ud3ec\ud568\ub418\ubbc0\ub85c `privileged`\ub97c \ucf24 \uc774\uc720\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n## \uba87 \ub2ec \ub3d9\uc548 \uc815\uc0c1\uc774\ub358 \uc124\uc815\uc774 \ubc30\ud3ec \ud55c \ubc88\uc5d0 \uc2e4\ud328\ud588\uc2b5\ub2c8\ub2e4\\n\\n\uc774 \ub9e4\ub2c8\ud398\uc2a4\ud2b8\ub294 \ucc98\uc74c\ubd80\ud130 \ud2c0\ub824 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370\ub3c4 \uba87 \ub2ec \ub3d9\uc548 \ubc31\uc5c5\uc774 \uc815\uc0c1\uc73c\ub85c \ub3d9\uc791\ud588\uc2b5\ub2c8\ub2e4. \uc774\ubbf8\uc9c0\uc758 \uae30\ubcf8 \uc0ac\uc6a9\uc790\uac00 \uc911\uac04\uc5d0 \ubc14\ub00c\uc5c8\uace0, \ud30c\ub4dc\ub294 \uadf8 \ub4a4\ub85c \uc7ac\uc0dd\uc131\ub418\uc9c0 \uc54a\uc544 \uc608\uc804 \uc774\ubbf8\uc9c0\ub97c \uacc4\uc18d \uc0ac\uc6a9\ud558\uace0 \uc788\uc5c8\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\nCI\uac00 \uc778\ud504\ub77c\ub97c \ubc30\ud3ec\ud558\uba74\uc11c \ud30c\ub4dc\ub97c \uc7ac\uc0dd\uc131\ud55c \uc21c\uac04 \uc0c8 \uc774\ubbf8\uc9c0\ub97c \uac00\uc838\uc654\uace0, \uadf8\ub54c \uc7a5\uc560\uac00 \ub4dc\ub7ec\ub0ac\uc2b5\ub2c8\ub2e4. **\uc774\ubbf8\uc9c0 \ud0dc\uadf8\uac00 \uac19\uc544\ub3c4 \ud30c\ub4dc\uac00 \uc7ac\uc0dd\uc131\ub420 \ub54c \uc774\ubbf8\uc9c0\uac00 \ud568\uaed8 \uad50\uccb4\ub429\ub2c8\ub2e4.**\\n\\n\uac10\uc9c0\uac00 \ub2a6\uc740 \uc774\uc720\ub294 \ub530\ub85c \uc788\uc5c8\uc2b5\ub2c8\ub2e4. velero server \ud30c\ub4dc\ub294 \uacc4\uc18d Running\uc774\ub77c `kubectl get pods`\ub9cc \ud655\uc778\ud574\uc11c\ub294 \uc815\uc0c1\uc73c\ub85c \ubcf4\uc600\uc2b5\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uba48\ucd98 \ucabd\uc740 DaemonSet\uc774\uc5c8\uace0, \uc99d\uc0c1\uc740 \ubc31\uc5c5 \uc624\ube0c\uc81d\ud2b8\uc758 `PartiallyFailed` \uc0c1\ud0dc\uc5d0\ub9cc \ub0a8\uc558\uc2b5\ub2c8\ub2e4. \ubcf5\uad6c\uae4c\uc9c0 25\uc2dc\uac04\uc774 \uac78\ub838\uc2b5\ub2c8\ub2e4.\\n\\n## \ub85c\uadf8\ub97c \ud655\uc778\ud560 \ub54c \uc2dc\uac04\ub300\ub97c \uc11e\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4\\n\\n`kubectl`\uc774 \ucd9c\ub825\ud558\ub294 \ud0c0\uc784\uc2a4\ud0ec\ud504\uc640 velero \ubc31\uc5c5 \uc774\ub984\uc740 UTC\ub97c \uc501\ub2c8\ub2e4. `journalctl`\uc758 `--since`\uc640 `--until`\uc740 \ub85c\uceec \uc2dc\uac04\uc744 \ubc1b\uc2b5\ub2c8\ub2e4. \ub450 \uac12\uc744 \uc11e\uc73c\uba74 9\uc2dc\uac04 \uc5b4\uae0b\ub09c \uad6c\uac04\uc744 \ud655\uc778\ud558\uac8c \ub429\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\\n\\n- [capabilities(7) - Linux manual page](https://man7.org/linux/man-pages/man7/capabilities.7.html)\\n- [moby#45491 Process capabilities cannot be retained when starting a container as non-root](https://github.com/moby/moby/issues/45491)"},{"id":"fast-day-of-week","metadata":{"permalink":"/blog/fast-day-of-week","source":"@site/blog/2026-08-28-fast-day-of-week/index.md","title":"\ub098\uba38\uc9c0 \uc5f0\uc0b0 \uc5c6\ub294 \ube60\ub978 \uc694\uc77c \uacc4\uc0b0, \uacf1\uc148 \ud55c \ubc88\uc774\uba74 \ub429\ub2c8\ub2e4","description":"\ub0a0\uc9dc\uc5d0\uc11c \uc694\uc77c\uc744 \uad6c\ud560 \ub54c \ud754\ud788 \uc4f0\ub294 % 7 \uc5c6\uc774, \uacf1\uc148 \ud55c \ubc88\uacfc \uc2dc\ud504\ud2b8\ub9cc\uc73c\ub85c \uc694\uc77c\uc744 \uad6c\ud558\ub294 \ubc29\ubc95\uc744 Ben Joffe\uc758 \uae00 Fast day-of-week computation\uc744 \ubc14\ud0d5\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-08-28T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Algorithm","permalink":"/blog/tags/algorithm"}],"readingTime":3.67,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ub098\uba38\uc9c0 \uc5f0\uc0b0 \uc5c6\ub294 \ube60\ub978 \uc694\uc77c \uacc4\uc0b0, \uacf1\uc148 \ud55c \ubc88\uc774\uba74 \ub429\ub2c8\ub2e4","slug":"fast-day-of-week","authors":["kgenots"],"tags":["Reference","Algorithm"],"image":"/assets/blog/cover-fast-day-of-week.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"privileged: true\uc778\ub370 permission denied\uac00 \ub0ac\uc2b5\ub2c8\ub2e4","permalink":"/blog/privileged-non-root-capabilities"},"nextItem":{"title":"\uc778\ud130\ub137 \uc5c6\ub294 \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \ubc30\ud3ec\ud558\uae30 (\uc5d0\uc5b4\uac2d)","permalink":"/blog/airgap-container-install"}},"content":"\ub0a0\uc9dc\uc5d0\uc11c \uc694\uc77c\uc744 \uad6c\ud560 \ub54c \ud754\ud788 \uc4f0\ub294 `% 7` \uc5c6\uc774, \uacf1\uc148 \ud55c \ubc88\uacfc \uc2dc\ud504\ud2b8\ub9cc\uc73c\ub85c \uc694\uc77c\uc744 \uad6c\ud558\ub294 \ubc29\ubc95\uc744 Ben Joffe\uc758 \uae00 [Fast day-of-week computation](https://www.benjoffe.com/fast-day-of-week)\uc744 \ubc14\ud0d5\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ub0a0\uc9dc\uc5d0\uc11c \uc694\uc77c\uc744 \uad6c\ud558\ub294 \ucf54\ub4dc\ub294 \ub300\uac1c `% 7`\ub85c \ub05d\ub0a9\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uc694\uc77c \uacc4\uc0b0\uc740 \uacf1\uc148 1\ubc88 + \ub367\uc148 1\ubc88 + \uc2dc\ud504\ud2b8 1\ubc88, \ucd1d 3\uc5f0\uc0b0\uc73c\ub85c\ub3c4 \ub05d\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uc874\uc5d0 \uac00\uc7a5 \ube60\ub974\ub2e4\uace0 \uc54c\ub824\uc9c4 \ubc29\ubc95(Neri, 2024) \ub300\ube44 4~6\ubc30 \ube60\ub985\ub2c8\ub2e4.\\n\\n```c\\n// rd: 1970-01-01 \uae30\uc900 \uacbd\uacfc \uc77c\uc218 (rata die), \uacb0\uacfc: 0=\uc77c\uc694\uc77c ~ 6=\ud1a0\uc694\uc77c\\nuint32_t weekday(int32_t rd) {\\n    const uint32_t M = 613566757;   // (2^32 / 7) + 1\\n    const uint32_t Z = 0x94920000;  // \uc5d0\ud3ec\ud06c(1970-01-01 = \ubaa9\uc694\uc77c) \uc815\ub82c\uc6a9\\n    return ((uint32_t)rd * M + Z) >> 29;\\n}\\n```\\n\\n\uc774 \uae00\uc758 \uc0c1\uc218\uc640 \ud56d\ub4f1\uc2dd\uc740 \ud30c\uc774\uc36c\uc73c\ub85c \uc804 \uad6c\uac04 \uc7ac\uac80\uc99d\uc744 \ud588\uace0, \ubaa8\ub450 \uc6d0\ubb38 \uc8fc\uc7a5\ub300\ub85c \ub3d9\uc791\ud588\uc2b5\ub2c8\ub2e4.\\n\\n## \uc694\uc77c \uacc4\uc0b0\uc740 \uc65c % 7 \uc778\uac00\\n\\n\uc694\uc77c \uacc4\uc0b0\uc758 \ucd9c\ubc1c\uc810\uc740 <b>rata die</b>, \uc989 \uae30\uc900\uc77c\ub85c\ubd80\ud130\uc758 \uacbd\uacfc \uc77c\uc218\uc785\ub2c8\ub2e4. \uc720\ub2c9\uc2a4 \uc5d0\ud3ec\ud06c(1970-01-01)\ub294 \ubaa9\uc694\uc77c\uc774\ubbc0\ub85c, \uc77c\uc694\uc77c\uc744 0\uc73c\ub85c \ub450\uba74 \uc694\uc77c\uc740 \uc774\ub807\uac8c \uad6c\ud569\ub2c8\ub2e4.\\n\\n```c\\nweekday = ((rd % 7) + 7 + 4) % 7   // C/C++: \uc74c\uc218 \ub098\uba38\uc9c0 \ubcf4\uc815 \ub54c\ubb38\uc5d0 \ub450 \ubc88\\nweekday = (rd + 4).rem_euclid(7)   // Rust: \uc591\uc218 \ub098\uba38\uc9c0 \ud55c \ubc88\\n```\\n\\n\uc77d\uae30 \uc27d\uace0 \uc720\uc9c0\ubcf4\uc218\ub3c4 \ud3b8\ud569\ub2c8\ub2e4. \ub2e4\ub9cc <span style={{ backgroundColor: \'#ffdce0\'}}>`% 7` \uc790\uccb4\uac00 CPU \uc785\uc7a5\uc5d0\uc11c \uc2fc \uc5f0\uc0b0\uc774 \uc544\ub2d9\ub2c8\ub2e4.</span>\\n\\n## % 7 \uc740 \uc65c \ub290\ub9b0\uac00\\n\\n\ub098\ub217\uc148\uc740 CPU\uc5d0\uc11c \uac00\uc7a5 \ub290\ub9b0 \uc0b0\uc220 \uc5f0\uc0b0\uc5d0 \uc18d\ud569\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucef4\ud30c\uc77c\ub7ec\ub294 \uc0c1\uc218 \ub098\ub217\uc148\uc744 \\"\uc5ed\uc218 \uacf1\uc148\\"\uc73c\ub85c \ubc14\uafc9\ub2c8\ub2e4. `x / 7`\uc744 `x * (2^32 / 7) >> 32` \ube44\uc2b7\ud55c \ud615\ud0dc\ub85c \ubc14\uafb8\ub294 \uac83\uc73c\ub85c, Hacker\'s Delight\ub77c\ub294 \ucc45\uc73c\ub85c \uc798 \uc54c\ub824\uc9c4 \uace0\uc804 \uae30\ubc95\uc785\ub2c8\ub2e4.\\n\\n\uadf8\ub7f0\ub370 7\uc740 \uc774 \ubcc0\ud658\uc774 \uae54\ub054\ud558\uac8c \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. `2^32 / 7 = 613566756.57...`\ucc98\ub7fc \uc18c\uc218\ubd80\uac00 \ub0a8\uc544\uc11c, \ucef4\ud30c\uc77c\ub7ec\uac00 \ub9cc\ub4e0 \ucf54\ub4dc\uc5d0 \uc624\ucc28 \ubcf4\uc815\uc6a9 \uc5f0\uc0b0\uc774 \uba87 \uac1c \ub354 \ubd99\uc2b5\ub2c8\ub2e4. \ub098\uba38\uc9c0(`% 7`)\uae4c\uc9c0 \uad6c\ud558\ub824\uba74 `x - (x/7)*7`\uc744 \ub610 \ud574\uc57c \ud558\ub2c8 \uc5f0\uc0b0\uc774 \ub354 \ub298\uc5b4\ub0a9\ub2c8\ub2e4.\\n\\n## \ud575\uc2ec \uc544\uc774\ub514\uc5b4: 7\uc77c\uc9dc\ub9ac \uc8fc\ub97c 8\uce78\uc5d0 \uc5b9\uae30\\n\\n7\uc740 \uba54\ub974\uc13c \uc218(2\xb3 - 1)\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub2e4\uc74c \ud56d\ub4f1\uc2dd\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4.\\n\\n```text\\nN % 7 == floor(N \xd7 8 / 7) % 8\\n```\\n\\n`% 8`\uc740 \ud558\uc704 3\ube44\ud2b8\ub9cc \uc77d\uc73c\uba74 \ub418\ub294 \uacf5\uc9dc \uc5f0\uc0b0\uc785\ub2c8\ub2e4. 7\ub85c \ub098\ub208 \ub098\uba38\uc9c0 \ubb38\uc81c\uac00, 8/7\ubc30\ub85c \ub298\ub9b0 \ub2e4\uc74c \ud558\uc704 3\ube44\ud2b8\ub97c \uc77d\ub294 \ubb38\uc81c\ub85c \ubc14\ub01d\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/fast-day-of-week-padding.webp\\"\\n    alt=\\"7\uc77c \uc8fc\uae30\ub97c 8\uce78 \uadf8\ub9ac\ub4dc\uc5d0 \ud328\ub529\ud574\uc11c \ud558\uc704 3\ube44\ud2b8\ub85c \uc694\uc77c\uc744 \uc77d\ub294 \uad6c\uc870\\"\\n  />\\n  <figcaption>7\uc77c \uc8fc\uae30\ub97c 8\uce78\uc5d0 \ub298\ub824 \uc5b9\uc73c\uba74, \uce78 \ubc88\ud638(\ud558\uc704 3\ube44\ud2b8)\uac00 \uace7 \uc694\uc77c\uc774 \ub429\ub2c8\ub2e4.</figcaption>\\n</figure>\\n\\n7\uc77c\ub9c8\ub2e4 \ubc18\ubcf5\ub418\ub294 \ub2ec\ub825\uc744, \ud55c \uc8fc\uac00 8\uce78\uc778 \uacf5\ucc45\uc5d0 \uae00\uc790 \ud3ed\uc744 8/7\ubc30\ub85c \ub298\ub824\uc11c \uc62e\uaca8 \uc801\uc2b5\ub2c8\ub2e4. \uc5b4\ub5a4 \ub0a0\uc774 \ubb34\uc2a8 \uc694\uc77c\uc778\uc9c0 \uc54c\uace0 \uc2f6\uc73c\uba74 \ub098\ub217\uc148 \uc5c6\uc774 \\"\uba87 \ubc88\uc9f8 \uce78\uc778\uac00\\"\ub9cc \ubcf4\uba74 \ub429\ub2c8\ub2e4.\\n\\n\uace0\ub300 \ub85c\ub9c8\uc5d0\ub294 \uc2e4\uc81c\ub85c 8\uc77c\ub9c8\ub2e4 \uc7a5\uc774 \uc11c\ub294 \ub208\ub514\ub214(nundinum) \uc8fc\uae30\uac00 \uc788\uc5c8\uace0, \uc6d0\ubb38 \uc800\uc790\ub294 \uc5ec\uae30\uc11c \uc774\ub984\uc744 \ub530 \uc774 \uae30\ubc95\uc744 \\"Nundinal Map\\"\uc774\ub77c \ubd80\ub985\ub2c8\ub2e4.\\n\\n\ub9e8 \uc704\uc758 3\uc5f0\uc0b0 \ucf54\ub4dc\ub294 \uc774 \uadf8\ub9bc \uadf8\ub300\ub85c\uc785\ub2c8\ub2e4.\\n\\n- `rd * M` : M \u2248 2\xb2\u2079 \xd7 8/7 \uc774\ubbc0\ub85c, \\"8/7\ubc30 \ub298\ub9ac\uae30\\"\uc640 \\"\uc0c1\uc704 \ube44\ud2b8\ub85c \ubc00\uc5b4\uc62c\ub9ac\uae30\\"\ub97c \uacf1\uc148 \ud55c \ubc88\uc5d0 \ud569\ub2c8\ub2e4.\\n- `+ Z` : \uacb0\uacfc\ub97c \uc5d0\ud3ec\ud06c \uc694\uc77c(\ubaa9\uc694\uc77c)\uc5d0 \ub9de\uac8c \ud68c\uc804\uc2dc\ud0a4\ub294 \uc624\ud504\uc14b\uc785\ub2c8\ub2e4.\\n- `>> 29` : \uc0c1\uc704 3\ube44\ud2b8\ub9cc \ub0a8\uae41\ub2c8\ub2e4. \uc774\uac8c `% 8`, \uace7 \uc694\uc77c\uc785\ub2c8\ub2e4.\\n\\n## \uc720\ud6a8 \ubc94\uc704: \uc57d \xb124\ub9cc \ub144\\n\\nM\uc774 8/7\uc758 \uadfc\uc0ac\uac12\uc774\ub77c\uc11c \uc785\ub825\uc774 \ucee4\uc9c8\uc218\ub85d \uc624\ucc28\uac00 \uc313\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c 3\uc5f0\uc0b0 \ubc84\uc804\uc740 <span style={{ backgroundColor: \'#fff5b1\'}}>\xb18,900\ub9cc \uc77c(\uc57d \xb124\ub9cc \ub144) \ubc94\uc704 \uc548\uc5d0\uc11c\ub9cc \uc815\ud655</span>\ud569\ub2c8\ub2e4. \uc9c1\uc811 \uac80\uc99d\ud574 \ubcf4\ub2c8 \uccab \uc624\ub2f5\uc740 +89,522,176\uc77c\uacfc -89,434,797\uc77c\uc5d0\uc11c \ub098\uc654\uc2b5\ub2c8\ub2e4.\\n\\n24\ub9cc \ub144\uc774\uba74 \ubd80\uc871\ud560 \uc77c\uc774 \uc5c6\uc5b4 \ubcf4\uc774\uc9c0\ub9cc, \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 int32 \uc804\uccb4 \ubc94\uc704(\xb158\uc5b5 \ub144 \uc0c1\ub2f9)\ub97c \ubc1b\ub294 \uacbd\uc6b0\uac00 \uc788\uc5b4 \uc6d0\ubb38\uc740 \uc804\uccb4 \ubc94\uc704 \ubcc0\ud615\ub3c4 \ud568\uaed8 \uc81c\uc2dc\ud569\ub2c8\ub2e4.\\n\\n## \uc804\uccb4 \ubc94\uc704\uac00 \ud544\uc694\ud558\uba74: \uc2dc\ud504\ud2b8 \ubcf4\uc815 \ubcc0\ud615\\n\\nint32 \uc804\uccb4 \ubc94\uc704\ub97c \ucee4\ubc84\ud558\ub294 \ubcc0\ud615 \uc911 \uac00\uc7a5 \ub2e8\uc21c\ud55c \ucabd\uc740, \ubc18\uc62c\ub9bc \ub300\uc2e0 \ub0b4\ub9bc \uc0c1\uc218\ub97c \uc4f0\uace0 \ubd80\uc871\ubd84\uc744 \uc2dc\ud504\ud2b8 \ub450 \ubc88\uc73c\ub85c \ucc44\uc6c1\ub2c8\ub2e4.\\n\\n```c\\nuint32_t weekday_full(int32_t rd) {\\n    const uint32_t M = 613566756;   // 2^32 / 7 \ub0b4\ub9bc\\n    const uint32_t Z = 0x95000000;\\n    uint32_t a = (uint32_t)rd * M + Z;\\n    uint32_t b = (rd >> 1) + (rd >> 4);  // 4/7 \u2248 1/2 + 1/16 \uadfc\uc0ac \ubcf4\uc815\\n    return (a + b) >> 29;\\n}\\n```\\n\\n\ub0b4\ub9bc\uc73c\ub85c \uc798\ub824 \ub098\uac04 \uc18c\uc218\ubd80\ub294 \uc815\ud655\ud788 4/7\uc785\ub2c8\ub2e4. `(x >> 1) + (x >> 4)`\ub294 0.5 + 0.0625 = 0.5625, \uc989 4/7(0.5714...)\uc758 \uadfc\uc0ac\uac12\uc774\ub77c \uc774 \ubd80\uc871\ubd84\uc744 \uba54\uc6cc \uc90d\ub2c8\ub2e4. \uc2dc\ud504\ud2b8\ub294 \uacf1\uc148\uc774 \ub3c4\ub294 \ub3d9\uc548 \ubcd1\ub82c\ub85c \uc2e4\ud589\ub418\ubbc0\ub85c \ucd94\uac00 \ube44\uc6a9\uc774 \uac70\uc758 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uc774 \ubcc0\ud615\ub3c4 int32 \uc804\uccb4 \ubc94\uc704\uc5d0\uc11c \ub79c\ub364 50\ub9cc \uac74\uacfc \uacbd\uacc4\uac12\uc73c\ub85c \uac80\uc99d\ud588\uace0 \uc804\ubd80 \uc815\ud655\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\uc774 \ubc16\uc5d0\ub3c4 64\ube44\ud2b8 \uacf1\uc73c\ub85c \uc815\ubc00\ub3c4\ub97c \uc62c\ub9b0 \ubcc0\ud615, \uacf1\uc148 2\uac1c\ub97c \ud30c\uc774\ud504\ub77c\uc778\uc73c\ub85c \uacb9\uce58\ub294 \ubcc0\ud615, x86\uc758 LEA \uba85\ub839\uc5b4 \ud558\ub098\uc5d0 \uacf1\uc148\xb7\ub367\uc148\xb7\uc0c1\uc218\ub97c \uc6b1\uc5ec\ub123\ub294 3\uc5f0\uc0b0 \ubcc0\ud615\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc790\uc138\ud55c \ub0b4\uc6a9\uc740 \uc6d0\ubb38\uc744 \ubcf4\uc2dc\uba74 \ub429\ub2c8\ub2e4.\\n\\n## \uc77c\ubc18\ud654: 2\uc758 \uac70\ub4ed\uc81c\uacf1 \ud328\ub529 (x % 24, x % 60)\\n\\n\uac19\uc740 \ud328\ub529\uc744 \ub2e4\ub978 \ub098\ub217\uc218\uc5d0\ub3c4 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```text\\nx mod D == (x + c \xd7 floor(x / D)) mod (D + c)    (D + c \uac00 2\uc758 \uac70\ub4ed\uc81c\uacf1\uc774 \ub418\ub3c4\ub85d c \uc120\ud0dd)\\n```\\n\\n\ub098\ub217\uc218\ub97c 2\uc758 \uac70\ub4ed\uc81c\uacf1\uae4c\uc9c0 \\"\ud328\ub529\\"\ud558\uba74 \ub098\uba38\uc9c0 \uc5f0\uc0b0\uc774 \ube44\ud2b8 AND\ub85c \ubc14\ub01d\ub2c8\ub2e4. \uc2dc\uac04 \uacc4\uc0b0\uc5d0 \ubc14\ub85c \uc368\uba39\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n| \uacc4\uc0b0 | \ud328\ub529 \uacf5\uc2dd | \ube44\uace0 |\\n| --- | --- | --- |\\n| `x % 24` (\uc2dc) | `(x + (x/24 << 3)) & 31` | 24 + 8 = 32 |\\n| `x % 60` (\ubd84\xb7\ucd08) | `(x + (x/60 << 2)) & 63` | 60 + 4 = 64 |\\n\\n`x / 24`\ub294 \uc5b4\ucc28\ud53c \ub0a0\uc9dc \uacc4\uc0b0\uc5d0\uc11c \ud568\uaed8 \uad6c\ud558\ub294 \uac12\uc774\ub77c, \uadf8 \ubd80\uc0b0\ubb3c\ub85c \ub098\uba38\uc9c0\ub97c \uacf5\uc9dc\uc5d0 \uac00\uae5d\uac8c \uc5bb\uc2b5\ub2c8\ub2e4. \ub450 \uacf5\uc2dd \ubaa8\ub450 0\ubd80\ud130 200\ub9cc\uae4c\uc9c0 \uc804\uc218 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.\\n\\n## \uc5bc\ub9c8\ub098 \ube60\ub978\uac00\\n\\n\uc6d0\ubb38 \ubca4\uce58\ub9c8\ud06c(AMD Ryzen 9, Apple M4 Pro)\uc785\ub2c8\ub2e4. \uae30\uc900\uc740 \uae30\uc874 \ucd5c\uace0 \uae30\ub85d\uc778 Neri(2024) = 1.0, \uc22b\uc790\uac00 \uc791\uc744\uc218\ub85d \ube60\ub985\ub2c8\ub2e4.\\n\\n| \uc54c\uace0\ub9ac\uc998 | \uc0c1\ub300 \ucc98\ub9ac\ub7c9 | \uc720\ud6a8 \ubc94\uc704 |\\n| --- | --- | --- |\\n| \uc21c\uc9c4\ud55c \uc774\uc911 `% 7` | ~2.8 | \uc804\uccb4 |\\n| Hinnant (2014) | ~2.9 | \uac70\uc758 \uc804\uccb4 |\\n| Neri (2024) | 1.0 (\uae30\uc900) | \uc804\uccb4 |\\n| <b>3\uc5f0\uc0b0 \ubc84\uc804</b> | <b>0.17 ~ 0.27</b> | \xb124\ub9cc \ub144 |\\n| \uc2dc\ud504\ud2b8 \ubcf4\uc815 \ubcc0\ud615 | 0.39 ~ 0.55 | \uc804\uccb4 |\\n\\n## \uc8fc\uc758\uc0ac\ud56d\\n\\n- 3\uc5f0\uc0b0 \ubc84\uc804\uc5d0\ub294 \ubc94\uc704 \uc81c\ud55c\uc774 \uc788\uc2b5\ub2c8\ub2e4. \xb124\ub9cc \ub144\uc744 \ub118\ub294 \uc785\ub825\uc774 \ub4e4\uc5b4\uc62c \uc218 \uc788\uc73c\uba74 \uc804\uccb4 \ubc94\uc704 \ubcc0\ud615\uc744 \uc4f0\uac70\ub098 \uc785\ub825\uc744 \uac78\ub7ec\uc57c \ud569\ub2c8\ub2e4. Rust\uc758 Jiff\ucc98\ub7fc \xb11\ub9cc \ub144\ub9cc \uc9c0\uc6d0\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\ub294 \uadf8\ub300\ub85c \uc548\uc804\ud569\ub2c8\ub2e4.\\n- \ubd80\ud638 \uc788\ub294 \uc815\uc218\ub97c unsigned\ub85c \uce90\uc2a4\ud305\ud558\ub294 \ubd80\ubd84\uc740 2\uc758 \ubcf4\uc218 \ub798\ud551\uc744 \uc804\uc81c\ud569\ub2c8\ub2e4. Rust\uc5d0\uc11c\ub294 \uc815\uc758\ub41c \ub3d9\uc791\uc774\uc9c0\ub9cc C/C++\uc5d0\uc11c\ub294 \uce90\uc2a4\ud305 \ubc29\uc2dd\uc744 \uc9c0\ucf1c\uc57c \ud569\ub2c8\ub2e4.\\n- \uc804\uccb4 \ubc94\uc704 \ubcc0\ud615\ub4e4\uc740 \ucef4\ud30c\uc77c\ub7ec\uac00 \ucd5c\uc801 \ucf54\ub4dc\ub85c \uad6c\uc6cc \uc8fc\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uac00 \uc788\uc5b4, \uc6d0\ubb38\uc740 x86 \uc5b4\uc148\ube14\ub9ac \uc218\uc900\uc758 \ubc30\uce58\uae4c\uc9c0 \ub2e4\ub8f9\ub2c8\ub2e4. \uc5ec\uae30\uae4c\uc9c0 \uac00\uae30 \uc804\uc5d0, \ub9c8\uc774\ud06c\ub85c \ucd5c\uc801\ud654\uac00 \ud544\uc694\ud55c \uc0c1\ud669\uc778\uc9c0\ubd80\ud130 \ub530\uc838 \ubcf4\ub294 \uac8c \uc21c\uc11c\uaca0\uc9c0\uc694.\\n\\n## Q&A\\n\\n- **\uc694\uc77c \uacc4\uc0b0\uc5d0 % 7 \uc744 \uc548 \uc4f0\uace0 \uacc4\uc0b0\ud558\ub294 \ubc29\ubc95\uc774 \uc788\ub098\uc694?**\\n  - \uc788\uc2b5\ub2c8\ub2e4. 7\uc774 2\xb3 - 1\uc774\ub77c\ub294 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 `N % 7 == floor(N \xd7 8 / 7) % 8`\uc774 \uc131\ub9bd\ud558\uace0, \uc774\ub97c \uacf1\uc148 1\ubc88 + \ub367\uc148 1\ubc88 + \uc2dc\ud504\ud2b8 1\ubc88\uc73c\ub85c \uad6c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc704\uc758 3\uc5f0\uc0b0 \ucf54\ub4dc\uac00 \uadf8 \uad6c\ud604\uc785\ub2c8\ub2e4.\\n- **\uc774 \ucd5c\uc801\ud654\uac00 \uc2e4\uc81c\ub85c \uc758\ubbf8\uac00 \uc788\ub098\uc694?**\\n  - \ub0a0\uc9dc \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \ub300\ub7c9 \ub370\uc774\ud130 \ucc98\ub9ac\ucc98\ub7fc \uc694\uc77c \uacc4\uc0b0\uc774 \ud56b\ud328\uc2a4\uc5d0 \uc788\uc73c\uba74 \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ud55c \ubc88 \ud638\ucd9c\ud558\uace0 \ub9c8\ub294 \uc560\ud50c\ub9ac\ucf00\uc774\uc158 \ucf54\ub4dc\ub77c\uba74 \uc77d\uae30 \uc26c\uc6b4 `% 7`\uc774 \ub0ab\uc2b5\ub2c8\ub2e4.\\n- **7 \ub9d0\uace0 \ub2e4\ub978 \uc218\uc5d0\ub3c4 \uc4f8 \uc218 \uc788\ub098\uc694?**\\n  - \ub098\ub217\uc218\ub97c 2\uc758 \uac70\ub4ed\uc81c\uacf1\uae4c\uc9c0 \ud328\ub529\ud558\ub294 \uc77c\ubc18\ud615\uc73c\ub85c \ud655\uc7a5\ub429\ub2c8\ub2e4. `x % 24`\ub294 32\ub85c, `x % 60`\uc740 64\ub85c \ud328\ub529\ud574\uc11c \ube44\ud2b8 AND\ub85c \ubc14\uafc0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n\\"\ucef4\ud30c\uc77c\ub7ec\uac00 \uc54c\uc544\uc11c \ucd5c\uc801\ud654\ud574 \uc8fc\uaca0\uc9c0\\" \ud558\ub294 \uc601\uc5ed\uc5d0\ub3c4 \uc0ac\ub78c \uc190\uc73c\ub85c \uc9dc\ub0bc \uc5ec\uc9c0\uac00 \ub0a8\uc544 \uc788\ub2e4\ub294 \uac8c \uc7ac\ubbf8\uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ub098\ub217\uc218\ub97c 8\ub85c \ubc14\uafd4\uce58\uae30\ud55c\ub2e4\ub294 \ubc1c\uc0c1\uc774 \uc624\ub798 \uae30\uc5b5\uc5d0 \ub0a8\uc744 \uac83 \uac19\uc544 \ub808\ud37c\ub7f0\uc2a4\ub85c \ub0a8\uae41\ub2c8\ub2e4.\\n\\n- \uc6d0\ubb38: [Fast day-of-week computation](https://www.benjoffe.com/fast-day-of-week) (Ben Joffe)\\n- \ucf54\ub4dc: [benjoffe/fast-world-calendars](https://github.com/benjoffe/fast-world-calendars) (MIT)"},{"id":"airgap-container-install","metadata":{"permalink":"/blog/airgap-container-install","source":"@site/blog/2026-06-19-airgap-container-install/index.md","title":"\uc778\ud130\ub137 \uc5c6\ub294 \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \ubc30\ud3ec\ud558\uae30 (\uc5d0\uc5b4\uac2d)","description":"\uc778\ud130\ub137\uc774 \ub9c9\ud78c \uc5d0\uc5b4\uac2d(air-gap) \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \uc774\ubbf8\uc9c0\ub97c \ubc18\uc785\ud558\uace0 \uc124\uce58\ud558\ub294 \ubc29\ubc95\uacfc, \\"\ubc1b\uc544\uc62c \uc218 \uc788\ub2e4\\"\ub294 \uac00\uc815 \ub54c\ubb38\uc5d0 \ub370\uc774\ub294 \uc9c0\uc810\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"},{"inline":true,"label":"Kubernetes","permalink":"/blog/tags/kubernetes"}],"readingTime":1.8,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\uc778\ud130\ub137 \uc5c6\ub294 \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \ubc30\ud3ec\ud558\uae30 (\uc5d0\uc5b4\uac2d)","slug":"airgap-container-install","authors":["kgenots"],"tags":["Reference","Ops","Kubernetes"],"image":"/assets/blog/cover-airgap-container-install.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ub098\uba38\uc9c0 \uc5f0\uc0b0 \uc5c6\ub294 \ube60\ub978 \uc694\uc77c \uacc4\uc0b0, \uacf1\uc148 \ud55c \ubc88\uc774\uba74 \ub429\ub2c8\ub2e4","permalink":"/blog/fast-day-of-week"},"nextItem":{"title":"S3 Parquet\ub97c DuckDB\ub85c \uc870\ud68c\ud558\uae30","permalink":"/blog/duckdb-parquet-on-s3"}},"content":"\uc778\ud130\ub137\uc774 \ub9c9\ud78c \uc5d0\uc5b4\uac2d(air-gap) \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \uc774\ubbf8\uc9c0\ub97c \ubc18\uc785\ud558\uace0 \uc124\uce58\ud558\ub294 \ubc29\ubc95\uacfc, \\"\ubc1b\uc544\uc62c \uc218 \uc788\ub2e4\\"\ub294 \uac00\uc815 \ub54c\ubb38\uc5d0 \ub370\uc774\ub294 \uc9c0\uc810\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ud544\uc694\ud55c \uc774\ubbf8\uc9c0\ub97c \ud558\ub098\ub3c4 \ube60\uc9d0\uc5c6\uc774 \ubbf8\ub9ac \ubb36\uc5b4 \ubc18\uc785\ud558\uace0, \uc124\uce58\ud560 \ub54c\ub294 \ub0b4\ubd80 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\uc5d0\uc11c\ub9cc \ubc1b\uac8c \ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ucf54\ub4dc\uc640 \uc2a4\ud06c\ub9bd\ud2b8\uc5d0 \uc228\uc5b4 \uc788\ub294 \\"\ud544\uc694\ud560 \ub54c \uc778\ud130\ub137\uc5d0\uc11c \ubc1b\uc544\uc628\ub2e4\\"\ub294 \uac00\uc815\uc744 \uc804\ubd80 \uac77\uc5b4\ub0c5\ub2c8\ub2e4.\\n\\n## \uc5d0\uc5b4\uac2d(air-gap)\uc774\ub780\\n\\n\uc5d0\uc5b4\uac2d\uc740 \ubcf4\uc548\uc744 \uc704\ud574 \uc678\ubd80 \uc778\ud130\ub137\uacfc \ubb3c\ub9ac\uc801\uc73c\ub85c \ubd84\ub9ac\ub41c \ud658\uacbd\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uace0\uac1d\uc0ac \ub370\uc774\ud130\uc13c\ud130\ucc98\ub7fc \ub370\uc774\ud130\uac00 \ubc16\uc73c\ub85c \ub098\uac00\uba74 \uc548 \ub418\ub294 \uacf3\uc5d0\uc11c \uc501\ub2c8\ub2e4.\\n\\n\ub9c8\ud2b8 \uc5c6\ub294 \uc0b0\uc7a5\uc5d0 \uc0b4\ub9bc\uc744 \ucc28\ub9ac\ub294 \uc77c\uacfc \ube44\uc2b7\ud569\ub2c8\ub2e4. \uc778\ud130\ub137\uc774 \ub418\ub294 \uacf3\uc5d0\uc11c\ub294 \uc7ac\ub8cc\uac00 \ub5a8\uc5b4\uc9c0\uba74 \uc0ac \uc624\uba74 \ub418\uc9c0\ub9cc, \uc5d0\uc5b4\uac2d\uc5d0\uc11c\ub294 \ud544\uc694\ud55c \uac83\uc744 \ud558\ub098\ub3c4 \ube60\uc9d0\uc5c6\uc774 \ubbf8\ub9ac \uc2f8 \ub4e4\uace0 \ub4e4\uc5b4\uac00\uc57c \ud569\ub2c8\ub2e4.\\n\\n## \uc5d0\uc5b4\uac2d \uc124\uce58\uac00 \uc5b4\ub824\uc6b4 \uc774\uc720\\n\\n\ud3c9\uc18c\uc758 \uc124\uce58 \uc808\ucc28\uac00 \uc778\ud130\ub137\uc5d0\uc11c \ubb34\uc5b8\uac00\ub97c \ubc1b\uc544\uc628\ub2e4\uace0 \uc804\uc81c\ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ucee8\ud14c\uc774\ub108 \uc774\ubbf8\uc9c0\ub294 \ubcf4\ud1b5 \uc678\ubd80 \ub808\uc9c0\uc2a4\ud2b8\ub9ac(Docker Hub \ub4f1)\uc5d0\uc11c \ubc1b\uc544\uc624\ub294\ub370, \uc5d0\uc5b4\uac2d\uc5d0\uc11c\ub294 \uadf8 \uacbd\ub85c\uac00 \ub9c9\ud600 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uac8c\ub2e4\uac00 \ubc1b\uc544\uc57c \ud560 \uac83\uc740 \uc6b0\ub9ac \uc11c\ube44\uc2a4 \uc774\ubbf8\uc9c0\ub9cc\uc774 \uc544\ub2d9\ub2c8\ub2e4. <span style={{ backgroundColor: \'#ffdce0\'}}>\ubca0\uc774\uc2a4 \uc774\ubbf8\uc9c0, \uc0ac\uc774\ub4dc\uce74, \ub370\uc774\ud130\ubca0\uc774\uc2a4, \ubaa8\ub2c8\ud130\ub9c1 \ub3c4\uad6c\uae4c\uc9c0</span> \uc804\ubd80 \ud544\uc694\ud569\ub2c8\ub2e4. \ud558\ub098\ub77c\ub3c4 \ube60\uc9c0\uba74 \uc124\uce58\uac00 \uc911\uac04\uc5d0 \uba48\ucda5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/airgap-container-install-2.webp\\"\\n    alt=\\"\uc571 \uc774\ubbf8\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ubca0\uc774\uc2a4\xb7\uc0ac\uc774\ub4dc\uce74\xb7DB\xb7OS \ud328\ud0a4\uc9c0\xb7\ud5ec\ub984 \ucc28\ud2b8\uae4c\uc9c0 \ubaa8\ub450 \ubc18\uc785\ud574\uc57c \ud55c\ub2e4\\"\\n  />\\n</figure>\\n\\n## \ubc30\ud3ec \ubc29\ubc95 (\ub124 \ub2e8\uacc4)\\n\\n\uc5d0\uc5b4\uac2d \ubc30\ud3ec\ub294 \ud06c\uac8c \ub124 \ub2e8\uacc4\uc785\ub2c8\ub2e4. \u2460 \ud544\uc694\ud55c \uc774\ubbf8\uc9c0\ub97c \ube60\uc9d0\uc5c6\uc774 \ubaa8\uc73c\uace0, \u2461 \ubb36\uc5b4\uc11c \ubc18\uc785\ud558\uace0, \u2462 \ub0b4\ubd80 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\uc5d0 \uc62c\ub9ac\uace0, \u2463 \ub9e4\ub2c8\ud398\uc2a4\ud2b8\uac00 \uadf8 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \uac00\ub9ac\ud0a4\uac8c \ud569\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/airgap-container-install.webp\\"\\n    alt=\\"\uc778\ud130\ub137 \uc788\ub294 \uacf3\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \ubb36\uc5b4 \ubc18\uc785\ud558\uace0 \ub0b4\ubd80 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub85c \ubc30\ud3ec\ud558\ub294 \uc5d0\uc5b4\uac2d \ud750\ub984\\"\\n  />\\n</figure>\\n\\n### 1. \ud544\uc694\ud55c \uc774\ubbf8\uc9c0 \ubaa9\ub85d \ub9cc\ub4e4\uae30\\n\\n\ub9e4\ub2c8\ud398\uc2a4\ud2b8(\ucfe0\ubc84\ub124\ud2f0\uc2a4 YAML, compose \ud30c\uc77c \ub4f1)\uc5d0\uc11c \uc4f0\ub294 \uc774\ubbf8\uc9c0\ub97c \uc804\ubd80 \ucd94\ucd9c\ud569\ub2c8\ub2e4. \ubca0\uc774\uc2a4\xb7\uc0ac\uc774\ub4dc\uce74\uae4c\uc9c0 \ub204\ub77d \uc5c6\uc774 \ubaa8\uc74d\ub2c8\ub2e4.\\n\\n```bash\\n# k8s \ub9e4\ub2c8\ud398\uc2a4\ud2b8\uc5d0\uc11c image: \uc904\ub9cc \ucd94\ucd9c\\ngrep -rhoE \'image:\\\\s*\\\\S+\' manifests/ | awk \'{print $2}\' | sort -u\\n```\\n\\n### 2. \uc774\ubbf8\uc9c0\ub97c \ubb36\uc5b4\uc11c \ubc18\uc785\\n\\n\uc778\ud130\ub137\uc774 \ub418\ub294 \uacf3\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \ubc1b\uc544 \ud558\ub098\uc758 \ud30c\uc77c\ub85c \ubb36\uc2b5\ub2c8\ub2e4.\\n\\n```bash\\n# \uc5ec\ub7ec \uc774\ubbf8\uc9c0\ub97c \ud55c tar \ub85c \uc800\uc7a5\\ndocker save -o bundle.tar app:1.0 postgres:16 nats:2.10 ...\\n# (\ub610\ub294 \ub808\uc9c0\uc2a4\ud2b8\ub9ac \uac04 \uc9c1\uc811 \ubcf5\uc0ac: skopeo copy / crane)\\n```\\n\\n\uc774 `bundle.tar`\ub97c USB\xb7\uc2b9\uc778\ub41c \ub9e4\uccb4\ub85c \uc5d0\uc5b4\uac2d \uc548\uc73c\ub85c \ubc18\uc785\ud569\ub2c8\ub2e4.\\n\\n### 3. \ub0b4\ubd80 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\uc5d0 \uc62c\ub9ac\uae30\\n\\n\uc5d0\uc5b4\uac2d \uc548\uc5d0 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \ub744\uc6b0\uace0, \ubc18\uc785\ud55c \uc774\ubbf8\uc9c0\ub97c \ud480\uc5b4 \uc62c\ub9bd\ub2c8\ub2e4.\\n\\n```bash\\ndocker load -i bundle.tar\\ndocker tag app:1.0 registry.internal:5000/app:1.0\\ndocker push registry.internal:5000/app:1.0\\n```\\n\\n### 4. \ub9e4\ub2c8\ud398\uc2a4\ud2b8\uac00 \ub0b4\ubd80 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \uac00\ub9ac\ud0a4\uac8c\\n\\n\uc774\ubbf8\uc9c0 \uc8fc\uc18c\ub97c \uc678\ubd80 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\uc5d0\uc11c \ub0b4\ubd80 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub85c \ubc14\uafc9\ub2c8\ub2e4. \uc124\uce58\ub294 \uc774\uc81c \uc778\ud130\ub137\uc774 \uc544\ub2c8\ub77c \ub0b4\ubd80\uc5d0\uc11c\ub9cc \uc774\ubbf8\uc9c0\ub97c \ubc1b\uc2b5\ub2c8\ub2e4.\\n\\n```yaml\\n# before: image: docker.io/library/app:1.0\\nimage: registry.internal:5000/app:1.0\\n```\\n\\n## \uc5d0\uc5b4\uac2d \ubc30\ud3ec\uc758 \ud754\ud55c \ud568\uc815\\n\\n- \uc758\uc874 \uc774\ubbf8\uc9c0 \ub204\ub77d: \uc6b0\ub9ac \uc571\ub9cc \ucc59\uae30\uace0 \ubca0\uc774\uc2a4\xb7\uc0ac\uc774\ub4dc\uce74\xb7DB\ub97c \ube60\ub728\ub9ac\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \ub208\uc73c\ub85c \ud6d1\uc9c0 \ub9d0\uace0 \ub9e4\ub2c8\ud398\uc2a4\ud2b8\uc5d0\uc11c \uae30\uacc4\uc801\uc73c\ub85c \uc804\ubd80 \ubf51\uc544 \ubaa8\uc74d\ub2c8\ub2e4.\\n- \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac pull\uc774 \ub290\ub9bc: \uc791\uc740 \uc774\ubbf8\uc9c0\ub294 \uad1c\ucc2e\uc9c0\ub9cc <span style={{ backgroundColor: \'#ffdce0\'}}>\ud070 \uc774\ubbf8\uc9c0\ub294 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \uac70\uce58\uba74 \uc624\ub798 \uac78\ub9bd\ub2c8\ub2e4.</span> \uc6a9\ub7c9\uc774 \ud070 \uc774\ubbf8\uc9c0\ub294 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \uac74\ub108\ub6f0\uace0 \ucee8\ud14c\uc774\ub108 \ub7f0\ud0c0\uc784\uc73c\ub85c \uc9c1\uc811 \ubc18\uc785\ud569\ub2c8\ub2e4(`ctr image import` \ub4f1).\\n- \uc124\uce58 \uc2a4\ud06c\ub9bd\ud2b8\uc5d0 \uc228\uc740 \uc778\ud130\ub137 \uac00\uc815: \ud328\ud0a4\uc9c0 \uc124\uce58, \uc678\ubd80 URL \ub2e4\uc6b4\ub85c\ub4dc \uac19\uc740 \ucf54\ub4dc\uac00 \uacf3\uacf3\uc5d0 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \ub9c9\ud78c \ud658\uacbd\uc5d0\uc11c\ub294 \uc904\uc904\uc774 \uba48\ucd94\ub2c8, \\"\ubc1b\uc544\uc628\ub2e4\\"\ub294 \uac00\uc815\uc744 \ud558\ub098\uc529 \ucc3e\uc544 \uc9c0\uc6c1\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **\uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac \uc5c6\uc774 \uadf8\ub0e5 \uc774\ubbf8\uc9c0\ub9cc \ub123\uc73c\uba74 \uc548 \ub418\ub098\uc694?**\\n  - \ub178\ub4dc\ub9c8\ub2e4 `docker load`\ub85c \uc9c1\uc811 \ub123\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \ub178\ub4dc\uac00 \ub298\uba74 \uad00\ub9ac\uac00 \ud798\ub4ed\ub2c8\ub2e4. \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \ud55c \ubc88 \ub744\uc6cc \ub450\ub294 \ud3b8\uc774 \uae54\ub054\ud569\ub2c8\ub2e4.\\n- **\uc5b4\ub5a4 \uc774\ubbf8\uc9c0\ub97c \ube60\ub728\ub838\ub294\uc9c0 \uc5b4\ub5bb\uac8c \ud655\uc778\ud558\ub098\uc694?**\\n  - \uc124\uce58\ub97c \ud55c \ubc88 \ub3cc\ub824 \ubcf4\uace0, \uc774\ubbf8\uc9c0 pull \uc2e4\ud328 \ub85c\uadf8\ub97c \ubaa8\uc74d\ub2c8\ub2e4. \uadf8 \ubaa9\ub85d\uc744 \ub2e4\uc74c \ubc88\ub4e4\uc5d0 \ucd94\uac00\ud569\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc644\ubcbd\ud788 \ubaa8\uc73c\uae34 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.\\n- **\uc774\ubbf8\uc9c0 \uc678\uc5d0 \ub610 \ucc59\uae38 \uac83\uc774 \uc788\ub098\uc694?**\\n  - \uc788\uc2b5\ub2c8\ub2e4. OS \ud328\ud0a4\uc9c0, \uc5b8\uc5b4 \ub7f0\ud0c0\uc784 \uc758\uc874\uc131, \ud5ec\ub984 \ucc28\ud2b8, \uc124\uce58 \uc2a4\ud06c\ub9bd\ud2b8\uac00 \ubc1b\ub294 \ubaa8\ub4e0 \uc678\ubd80 \ud30c\uc77c\uc774 \ub300\uc0c1\uc785\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- `docker save` / `docker load`, `skopeo copy`, `crane`\\n- containerd `ctr image import`"},{"id":"duckdb-parquet-on-s3","metadata":{"permalink":"/blog/duckdb-parquet-on-s3","source":"@site/blog/2026-06-19-duckdb-parquet-on-s3/index.md","title":"S3 Parquet\ub97c DuckDB\ub85c \uc870\ud68c\ud558\uae30","description":"\ubd84\uc11d\uc6a9 \ub370\uc774\ud130\ub97c \ubcc4\ub3c4 DB\ub85c \uc62e\uae30\uc9c0 \uc54a\uace0, S3\uc5d0 Parquet\ub85c \uc313\uc544 DuckDB\ub85c \uc9c1\uc811 SQL \uc870\ud68c\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"DB","permalink":"/blog/tags/db"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"}],"readingTime":1.83,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"S3 Parquet\ub97c DuckDB\ub85c \uc870\ud68c\ud558\uae30","slug":"duckdb-parquet-on-s3","authors":["kgenots"],"tags":["Reference","DB","Ops"],"image":"/assets/blog/cover-duckdb-parquet-on-s3.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\uc778\ud130\ub137 \uc5c6\ub294 \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \ubc30\ud3ec\ud558\uae30 (\uc5d0\uc5b4\uac2d)","permalink":"/blog/airgap-container-install"},"nextItem":{"title":"gRPC \ud5ec\uc2a4\uccb4\ud06c, HTTP\ub9cc\uc73c\ub860 \ubd80\uc871\ud55c \uc774\uc720","permalink":"/blog/grpc-health-check"}},"content":"\ubd84\uc11d\uc6a9 \ub370\uc774\ud130\ub97c \ubcc4\ub3c4 DB\ub85c \uc62e\uae30\uc9c0 \uc54a\uace0, S3\uc5d0 Parquet\ub85c \uc313\uc544 DuckDB\ub85c \uc9c1\uc811 SQL \uc870\ud68c\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ubd84\uc11d\uc6a9 \ub370\uc774\ud130\ub294 \uc6b4\uc601 DB\ub85c \uc62e\uae30\uc9c0 \uc54a\uc544\ub3c4 \ub429\ub2c8\ub2e4. S3\uc5d0 Parquet\ub85c \uc313\uc544 \ub450\uace0, DuckDB\ub85c \uadf8 \ud30c\uc77c\uc744 \uc9c1\uc811 SQL \uc870\ud68c\ud569\ub2c8\ub2e4.\\n\\n\ubcc4\ub3c4 \ubd84\uc11d DB\ub098 \ubb34\uac70\uc6b4 ETL \uc5c6\uc774 \uc77d\uae30 \uc804\uc6a9 \ubd84\uc11d\uc774 \ub429\ub2c8\ub2e4.\\n\\n## Parquet\uc640 DuckDB\ub780\\n\\nParquet\ub294 \uc5f4(\uceec\ub7fc) \ub2e8\uc704\ub85c \uc800\uc7a5\ud558\ub294 \ud30c\uc77c \ud615\uc2dd\uc774\uace0, DuckDB\ub294 \ud30c\uc77c\uc744 \uc9c1\uc811 \uc77d\uc5b4 SQL\uc744 \ub3cc\ub9ac\ub294 \uac00\ubcbc\uc6b4 \ubd84\uc11d\uc6a9 DB\uc785\ub2c8\ub2e4. \ub458\uc744 \ud569\uce58\uba74 S3\uc5d0 \uc62c\ub824 \ub454 Parquet \ud30c\uc77c\uc744 \uc62e\uae30\uc9c0 \uc54a\uace0 \uadf8\ub300\ub85c \uc870\ud68c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc11c\ub958\ud568\uc5d0 \ube44\uc720\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud589 \ub2e8\uc704 \uc800\uc7a5(CSV \ub4f1)\uc774 \uc11c\ub958\ub97c \ud1b5\uc9f8\ub85c \ubb36\uc5b4 \ub450\ub294 \ubc29\uc2dd\uc774\ub77c\uba74, Parquet\ub294 \ud56d\ubaa9\ubcc4 \uce78\uc73c\ub85c \ub098\ub220 \uc815\ub9ac\ud574 \ub454 \uc11c\ub958\ud568\uc785\ub2c8\ub2e4. \\"\uc774\ub984 \uce78\ub9cc \ubcf4\uace0 \uc2f6\ub2e4\\"\uba74 \uadf8 \uce78\ub9cc \uaebc\ub0b4\uba74 \ub429\ub2c8\ub2e4.\\n\\n## \uc65c DB\ub85c \uc62e\uae30\uc9c0 \uc54a\ub098\\n\\n\uc6b4\uc601 DB\uc5d0 \ubd84\uc11d \ucffc\ub9ac\ub97c \uc9c1\uc811 \ub3cc\ub9ac\uba74 <span style={{ backgroundColor: \'#ffdce0\'}}>\ubb34\uac70\uc6b4 \uc9d1\uacc4\uac00 \uc11c\ube44\uc2a4 \ud2b8\ub798\ud53d\uacfc \uc790\uc6d0\uc744 \ub2e4\ud23d\ub2c8\ub2e4.</span> \uadf8\ub807\ub2e4\uace0 \ubcf8\uaca9 \ub370\uc774\ud130 \uc6e8\uc5b4\ud558\uc6b0\uc2a4\ub97c \ub450\uae30\uc5d4 \ubb34\uac81\uace0 \ube44\uc309\ub2c8\ub2e4.\\n\\n\uadf8 \uc911\uac04\uc774 S3 Parquet + DuckDB\uc785\ub2c8\ub2e4. \ub370\uc774\ud130\ub294 S3\uc5d0 \uac12\uc2f8\uac8c \uc313\uc544 \ub450\uace0, \ubd84\uc11d\ud560 \ub54c\ub9cc DuckDB\uac00 \ud544\uc694\ud55c \ubd80\ubd84\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc6b4\uc601 DB\ub294 \uac74\ub4dc\ub9ac\uc9c0 \uc54a\uace0, \uc0c1\uc2dc \ub5a0 \uc788\ub294 \ubd84\uc11d \uc11c\ubc84\ub3c4 \ub450\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/duckdb-parquet-on-s3-2.webp\\"\\n    alt=\\"\uc6b4\uc601 DB\uc5d0 \ubd84\uc11d \ucffc\ub9ac\ub97c \uc9c1\uc811 \ub3cc\ub9ac\uba74 \ud2b8\ub798\ud53d\uacfc \uc790\uc6d0\uc744 \ub2e4\ud22c\ub294 \uacbd\uc6b0\uc640, S3 Parquet\uc5d0 \uc313\uace0 DuckDB\ub85c \ud544\uc694\ud560 \ub54c\ub9cc \uc77d\ub294 \uad6c\uc870 \ube44\uad50\\"\\n  />\\n</figure>\\n\\n## \uc870\ud68c \ubc29\ubc95 (S3 \uc9c1\uc811 \ucffc\ub9ac)\\n\\nDuckDB\uc5d0 S3 \uc811\uadfc \ud655\uc7a5(`httpfs`)\uc744 \uc62c\ub9ac\uba74, S3 \uacbd\ub85c\ub97c \ud14c\uc774\ube14\ucc98\ub7fc \ubc14\ub85c \uc870\ud68c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```sql\\nINSTALL httpfs; LOAD httpfs;\\nSET s3_region = \'ap-northeast-2\';\\n\\n-- S3 \uc758 Parquet \ub97c \uc9c1\uc811 \uc870\ud68c\\nSELECT count(*)\\nFROM read_parquet(\'s3://my-bucket/events/2026-06-19/*.parquet\');\\n```\\n\\n\uc5ec\ub7ec \ud30c\uc77c\uc740 \uae00\ub86d(`*`)\uc73c\ub85c \ud55c \ubc88\uc5d0 \uc77d\uc2b5\ub2c8\ub2e4. \ubcc4\ub3c4 \uc801\uc7ac(load) \ub2e8\uacc4\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n## \ube60\ub974\uac8c \ub9cc\ub4dc\ub294 \ubc95 (\ud30c\ud2f0\uc154\ub2dd)\\n\\n\ub0a0\uc9dc \uac19\uc740 \uae30\uc900\uc73c\ub85c \ud3f4\ub354\ub97c \ub098\ub220 \uc800\uc7a5\ud558\uba74(\ud30c\ud2f0\uc154\ub2dd) \ube68\ub77c\uc9d1\ub2c8\ub2e4. \ucffc\ub9ac \uc870\uac74\uc5d0 \uadf8 \uae30\uc900\uc774 \ub4e4\uc5b4\uac00\uba74, DuckDB\ub294 \ud574\ub2f9 \ud3f4\ub354\ub9cc \uc77d\uace0 \ub098\uba38\uc9c0\ub294 \uac74\ub108\ub701\ub2c8\ub2e4(\ud30c\ud2f0\uc158 \ud504\ub8e8\ub2dd).\\n\\n```sql\\n-- dt=YYYY-MM-DD \ub85c \ud3f4\ub354\uac00 \ub098\ub258\uc5b4 \uc788\uc73c\uba74\\nSELECT user_id, count(*)\\nFROM read_parquet(\'s3://my-bucket/events/*/*.parquet\', hive_partitioning = true)\\nWHERE dt = \'2026-06-19\'        -- \uc774 \ud3f4\ub354\ub9cc \uc77d\uc74c\\nGROUP BY user_id;\\n```\\n\\n\uc5ec\uae30\uc5d0 Parquet\uc758 \uceec\ub7fc \uc800\uc7a5 \ud2b9\uc131\uc774 \ub354\ud574\uc9d1\ub2c8\ub2e4. `SELECT user_id`\ub9cc \ud558\uba74 \uadf8 \uc5f4\ub9cc \uc77d\uace0, \ub098\uba38\uc9c0 \uc5f4\uc740 \ub514\uc2a4\ud06c\uc5d0\uc11c \uc77d\uc9c0\ub3c4 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n\ud30c\ud2f0\uc158\uc73c\ub85c \uc77d\uc744 \ud30c\uc77c \uc218\ub97c \uc904\uc774\uace0, \uceec\ub7fc\uc73c\ub85c \ud30c\uc77c \uc548\uc5d0\uc11c \uc77d\ub294 \uc591\uc744 \uc904\uc785\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/duckdb-parquet-on-s3-3.webp\\"\\n    alt=\\"\ud30c\ud2f0\uc158 \ud504\ub8e8\ub2dd\uc73c\ub85c \ud574\ub2f9 \ub0a0\uc9dc \ud3f4\ub354\ub9cc \uc77d\uace0, \uceec\ub7fc \uc800\uc7a5\uc73c\ub85c \ud544\uc694\ud55c \uc5f4\ub9cc \uc77d\uc5b4 \uc77d\ub294 \uc591\uc744 \uc904\uc774\ub294 \uc6d0\ub9ac\\"\\n  />\\n</figure>\\n\\n## \ud754\ud55c \ud568\uc815 (\uc791\uc740 \ud30c\uc77c\uacfc \ud30c\ud2f0\uc158)\\n\\n- \uc791\uc740 \ud30c\uc77c\uc774 \ub108\ubb34 \ub9ce\uc74c: \uc774\ubca4\ud2b8\ub97c \uac74\uac74\uc774 \uc791\uc740 \ud30c\uc77c\ub85c \uc313\uc73c\uba74 \ud30c\uc77c\uc774 \uc218\ub9cc \uac1c\uac00 \ub418\uace0, \ud30c\uc77c \ud558\ub098\ud558\ub098 \uc5ec\ub294 \ube44\uc6a9\uc774 \uc870\ud68c \uc2dc\uac04\uc744 \uc7a1\uc544\uba39\uc2b5\ub2c8\ub2e4. \uc8fc\uae30\uc801\uc73c\ub85c \ubb36\uc5b4 \uc801\ub2f9\ud55c \ud06c\uae30(\uc218\uc2ed~\uc218\ubc31 MB)\ub85c \ub9cc\ub4ed\ub2c8\ub2e4(compaction).\\n- \ud30c\ud2f0\uc158\uc744 \uc548 \ud0c0\ub294 \ucffc\ub9ac: `WHERE`\uc5d0 \ud30c\ud2f0\uc158 \uae30\uc900(dt \ub4f1)\uc774 \uc5c6\uc73c\uba74 \uc804\uccb4\ub97c \uc2a4\uce94\ud569\ub2c8\ub2e4. \uc870\ud68c\ub294 \uac00\ub2a5\ud55c \ud55c \ud30c\ud2f0\uc158 \uc870\uac74\uc744 \uac81\ub2c8\ub2e4.\\n- \uc77d\uae30 \uc804\uc6a9: \uc774 \ubc29\uc2dd\uc740 \ubd84\uc11d \uc870\ud68c\uc5d0 \ub9de\uc2b5\ub2c8\ub2e4. \uc7a6\uc740 \uac31\uc2e0\xb7\ud2b8\ub79c\uc7ad\uc158\uc774 \ud544\uc694\ud55c \ub370\uc774\ud130\ub294 \uc6b4\uc601 DB\uc5d0 \ub461\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **\uc6b4\uc601 DB \ub370\uc774\ud130\ub97c \uc5b4\ub5bb\uac8c S3 Parquet\ub85c \ubcf4\ub0b4\ub098\uc694?**\\n  - \ubcf4\ud1b5 \uc774\ubca4\ud2b8\ub098 \ubcc0\uacbd\ubd84\uc744 \uc8fc\uae30\uc801\uc73c\ub85c Parquet\ub85c \ub0b4\ubcf4\ub0b4(export) S3\uc5d0 \uc801\uc7ac\ud569\ub2c8\ub2e4. \uc2e4\uc2dc\uac04\uc774 \ud544\uc694\ud558\uba74 \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c, \uc544\ub2c8\uba74 \ubc30\uce58\ub85c \ucda9\ubd84\ud569\ub2c8\ub2e4.\\n- **DuckDB\ub97c \uc5b4\ub514\uc11c \uc2e4\ud589\ud558\ub098\uc694?**\\n  - \uc784\ubca0\ub514\ub4dc\ub77c \ubd84\uc11d \ucf54\ub4dc \uc548\uc5d0\uc11c \ubc14\ub85c \ub744\uc6c1\ub2c8\ub2e4. \uc0c1\uc2dc \uc11c\ubc84\uac00 \ud544\uc694 \uc5c6\uace0, \uc870\ud68c\ud560 \ub54c\ub9cc \ud504\ub85c\uc138\uc2a4\uac00 S3\ub97c \uc77d\uc2b5\ub2c8\ub2e4.\\n- **\ub370\uc774\ud130\uac00 \uc544\uc8fc \ucee4\uc9c0\uba74\uc694?**\\n  - \ud30c\ud2f0\uc154\ub2dd\uacfc compaction\uc73c\ub85c \uc0c1\ub2f9\ud788 \ubc84\ud301\ub2c8\ub2e4. \uadf8 \uc774\uc0c1\uc73c\ub85c \ucee4\uc9c0\uace0 \ub3d9\uc2dc \uc0ac\uc6a9\uc790\uac00 \ub9ce\uc544\uc9c0\uba74, \uadf8\ub54c \ubcf8\uaca9 \ub370\uc774\ud130 \uc6e8\uc5b4\ud558\uc6b0\uc2a4\ub97c \uac80\ud1a0\ud569\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- DuckDB Docs: `httpfs` / `read_parquet` / Hive Partitioning\\n- Apache Parquet: \uceec\ub7fc\ud615 \uc800\uc7a5 \ud615\uc2dd"},{"id":"grpc-health-check","metadata":{"permalink":"/blog/grpc-health-check","source":"@site/blog/2026-06-19-grpc-health-check/index.md","title":"gRPC \ud5ec\uc2a4\uccb4\ud06c, HTTP\ub9cc\uc73c\ub860 \ubd80\uc871\ud55c \uc774\uc720","description":"HTTP /health\uac00 200\uc744 \ubc18\ud658\ud574\ub3c4, \uac19\uc740 \ud504\ub85c\uc138\uc2a4 \uc548\uc758 gRPC \uc11c\ubc84\ub294 \uc8fd\uc5b4 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud45c\uc900 gRPC \ud5ec\uc2a4\uccb4\ud06c\ub97c \ud568\uaed8 \ub4f1\ub85d\ud574\uc57c \ud558\ub294 \uc774\uc720\uc640 \ubd99\uc774\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"gRPC","permalink":"/blog/tags/g-rpc"}],"readingTime":2.05,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"gRPC \ud5ec\uc2a4\uccb4\ud06c, HTTP\ub9cc\uc73c\ub860 \ubd80\uc871\ud55c \uc774\uc720","slug":"grpc-health-check","authors":["kgenots"],"tags":["Reference","Backend","gRPC"],"image":"/assets/blog/cover-grpc-health-check.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"S3 Parquet\ub97c DuckDB\ub85c \uc870\ud68c\ud558\uae30","permalink":"/blog/duckdb-parquet-on-s3"},"nextItem":{"title":"\ubaa8\ub178\ub808\ud3ec \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c \uc774\ud574\ud558\uae30 (\uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uc99d\ubd84 \ube4c\ub4dc)","permalink":"/blog/monorepo-workspace-tooling"}},"content":"HTTP `/health`\uac00 200\uc744 \ubc18\ud658\ud574\ub3c4, \uac19\uc740 \ud504\ub85c\uc138\uc2a4 \uc548\uc758 gRPC \uc11c\ubc84\ub294 \uc8fd\uc5b4 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud45c\uc900 gRPC \ud5ec\uc2a4\uccb4\ud06c\ub97c \ud568\uaed8 \ub4f1\ub85d\ud574\uc57c \ud558\ub294 \uc774\uc720\uc640 \ubd99\uc774\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \ud5ec\uc2a4\uccb4\ud06c\ub780\\n\\n\ud5ec\uc2a4\uccb4\ud06c\ub294 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130(\ucfe0\ubc84\ub124\ud2f0\uc2a4, ECS \ub4f1)\uac00 \uac01 \uc11c\ubc84\uac00 \uc0b4\uc544 \uc788\ub294\uc9c0 \uc8fc\uae30\uc801\uc73c\ub85c \ud655\uc778\ud558\ub294 \uc808\ucc28\uc785\ub2c8\ub2e4. \\"\uc815\uc0c1\\"\uc774\ub77c\uace0 \ub2f5\ud558\uba74 \ud2b8\ub798\ud53d\uc744 \ubcf4\ub0b4\uace0, \\"\ube44\uc815\uc0c1\\"\uc774\uba74 \ud2b8\ub798\ud53d\uc744 \ub04a\uac70\ub098 \uc7ac\uc2dc\uc791\ud569\ub2c8\ub2e4.\\n\\n\uac74\uac15\uac80\uc9c4\uacfc \ube44\uc2b7\ud569\ub2c8\ub2e4. \ubb38\uc744 \ub450\ub4dc\ub824 \\"\uacc4\uc138\uc694?\\"\uc5d0 \ub300\ub2f5\ub9cc \ud558\ub294 \uac83\uacfc, \uc2e4\uc81c\ub85c \uc9c4\ub8cc\ud574\uc11c \uc77c\ud560 \uc218 \uc788\ub294 \uc0c1\ud0dc\uc778\uc9c0 \ubcf4\ub294 \uac83\uc740 \ub2e4\ub985\ub2c8\ub2e4. \ud5ec\uc2a4\uccb4\ud06c\ub294 \ud6c4\uc790\uc5ec\uc57c \ud569\ub2c8\ub2e4.\\n\\n## \uc65c HTTP\ub9cc\uc73c\ub860 \ubd80\uc871\ud55c\uac00\\n\\nHTTP \ud5ec\uc2a4\uccb4\ud06c\ub9cc\uc73c\ub85c\ub294 \uac19\uc740 \ud504\ub85c\uc138\uc2a4 \uc548\uc758 gRPC \uc11c\ubc84\uac00 \uc8fd\uc5c8\ub294\uc9c0 \uc54c \uc218 \uc5c6\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub9ce\uc740 \uc11c\ube44\uc2a4\uac00 \ud55c \ud504\ub85c\uc138\uc2a4\uc5d0\uc11c HTTP \uc11c\ubc84\uc640 gRPC \uc11c\ubc84\ub97c \ud568\uaed8 \ub744\uc6c1\ub2c8\ub2e4. HTTP\ub294 \uc678\ubd80 \uc694\uccad\uc6a9, gRPC\ub294 \uc11c\ube44\uc2a4 \uac04 \ud1b5\uc2e0\uc6a9\uc785\ub2c8\ub2e4.\\n\\n\uc774\ub54c \ud5ec\uc2a4\uccb4\ud06c\ub97c HTTP `/health`\ub85c\ub9cc \ud558\uba74 \ubb38\uc81c\uac00 \uc0dd\uae41\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/grpc-health-check.webp\\"\\n    alt=\\"HTTP\ub294 \uc815\uc0c1\uc778\ub370 gRPC\ub294 \uc8fd\uc740 \uc0c1\ud669\uacfc, \ud45c\uc900 gRPC \ud5ec\uc2a4\uccb4\ud06c\ub85c \ub9c9\ub294 \ubc29\ubc95\\"\\n  />\\n</figure>\\n\\n:::warning \uc2e4\uc81c\ub85c \uacaa\uc740 \uc0c1\ud669\\ngRPC \uc11c\ubc84\uac00 \uc8fd\uc5c8\ub294\ub370 HTTP `/health`\ub294 \uba40\uca61\ud788 200\uc744 \ub3cc\ub824\uc92c\uc2b5\ub2c8\ub2e4. \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\ub294 \\"\uc774 \uc11c\ubc84 \uc815\uc0c1\\"\uc774\ub77c \ud310\ub2e8\ud558\uace0 \ud2b8\ub798\ud53d\uc744 \uacc4\uc18d \ubcf4\ub0c8\uace0, <span style={{ backgroundColor: \'#ffdce0\'}}>\uadf8\ucabd\uc73c\ub85c \uac04 gRPC \uc694\uccad\uc740 \uc804\ubd80 \uc2e4\ud328</span>\ud588\uc2b5\ub2c8\ub2e4. \uc815\uc0c1 \uc11c\ubc84\uc640 \uc11e\uc5ec \uc788\uc5b4 \uc2e4\ud328\uc728\uc774 \uc5b4\uc911\uac04\ud588\uace0, \\"\uc8fd\uc5c8\ub2e4\\"\uac00 \uc548 \ubcf4\uc5ec \uc624\ub798 \uac14\uc2b5\ub2c8\ub2e4. (\ud68c\uace0: [\ubaa8\ub178\ub808\ud3ec \ud3b8](/blog/monorepo-15-service-msa))\\n:::\\n\\n\uc11c\ubc84\ub294 \ub458\uc778\ub370 \ud5ec\uc2a4\uc758 \ub2f5\uc740 \ud558\ub098\ubfd0\uc774\uc5c8\uc2b5\ub2c8\ub2e4. HTTP\uac00 \uc0b4\uc544 \uc788\ub2e4\uace0 gRPC\uac00 \uc0b4\uc544 \uc788\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.\\n\\n## \ud45c\uc900 gRPC \ud5ec\uc2a4\uccb4\ud06c \ubd99\uc774\uae30\\n\\ngRPC\uc5d0\ub294 \ud45c\uc900 \ud5ec\uc2a4\uccb4\ud06c \ud504\ub85c\ud1a0\ucf5c(`grpc.health.v1.Health`)\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc11c\ubc84\uc5d0 \uc774 \uc11c\ube44\uc2a4\ub97c \ub4f1\ub85d\ud558\uba74 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 gRPC \ucabd \uc0c1\ud0dc\ub3c4 \uc9c1\uc811 \ubb3c\uc5b4\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ubd99\uc774\ub294 \uc21c\uc11c\ub294 \uc138 \ub2e8\uacc4\uc785\ub2c8\ub2e4. \u2460 \uc11c\ubc84\uc5d0 \ud45c\uc900 Health \uc11c\ube44\uc2a4\ub97c \ub4f1\ub85d\ud558\uace0, \u2461 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 gRPC \uc0c1\ud0dc\ub97c \uc9c1\uc811 \ud655\uc778\ud558\uac8c \ud558\uace0, \u2462 \uc885\ub8cc\ud560 \ub54c graceful shutdown\uc73c\ub85c \ud2b8\ub798\ud53d\uc744 \ube7c\ub0c5\ub2c8\ub2e4.\\n\\n### 1. \uc11c\ubc84\uc5d0 Health \uc11c\ube44\uc2a4 \ub4f1\ub85d\\n\\n```python\\nfrom grpc_health.v1 import health, health_pb2, health_pb2_grpc\\nfrom grpc import aio\\n\\nasync def serve() -> None:\\n    server = aio.server()\\n    add_my_servicer_to_server(MyServicer(), server)\\n\\n    # \ud45c\uc900 \ud5ec\uc2a4 \uc11c\ube44\uc2a4 \ub4f1\ub85d\\n    health_servicer = health.aio.HealthServicer()\\n    health_pb2_grpc.add_HealthServicer_to_server(health_servicer, server)\\n    # \uc11c\ube44\uc2a4\uac00 \uc900\ube44\ub418\uba74 SERVING \uc73c\ub85c \ud45c\uc2dc\\n    await health_servicer.set(\\"\\", health_pb2.HealthCheckResponse.SERVING)\\n\\n    server.add_insecure_port(\\"[::]:50051\\")\\n    await server.start()\\n    await server.wait_for_termination()\\n```\\n\\n\ube48 \ubb38\uc790\uc5f4 `\\"\\"` \ud0a4\ub294 \\"\uc11c\ubc84 \uc804\uccb4\\"\uc758 \uc0c1\ud0dc\ub97c \ub73b\ud569\ub2c8\ub2e4.\\n\\n### 2. \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 gRPC\ub97c \uc9c1\uc811 \ud655\uc778\ud558\uac8c\\n\\n\ucfe0\ubc84\ub124\ud2f0\uc2a4\ub294 gRPC probe\ub97c \uae30\ubcf8 \uc9c0\uc6d0\ud569\ub2c8\ub2e4.\\n\\n```yaml\\nlivenessProbe:\\n  grpc:\\n    port: 50051\\n  initialDelaySeconds: 5\\n  periodSeconds: 10\\n```\\n\\n\uae30\ubcf8 gRPC probe\uac00 \uc5c6\ub294 \ud658\uacbd\uc5d0\uc11c\ub294 [`grpc_health_probe`](https://github.com/grpc-ecosystem/grpc-health-probe) \ubc14\uc774\ub108\ub9ac\ub85c \ud655\uc778\ud569\ub2c8\ub2e4.\\n\\n```dockerfile\\n# \uc774\ubbf8\uc9c0\uc5d0 probe \uc124\uce58\\nRUN curl -fL \\"https://github.com/grpc-ecosystem/grpc-health-probe/releases/download/v0.4.24/grpc_health_probe-linux-amd64\\" \\\\\\n      -o /usr/local/bin/grpc_health_probe && chmod +x /usr/local/bin/grpc_health_probe\\n```\\n\\n```bash\\n# \uc0c1\ud0dc \ud655\uc778 (SERVING \uc774\uba74 \uc815\uc0c1 \uc885\ub8cc\ucf54\ub4dc 0)\\ngrpc_health_probe -addr=localhost:50051\\n```\\n\\n### 3. \uc885\ub8cc\ud560 \ub54c\ub294 \uacf1\uac8c (graceful shutdown)\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/grpc-health-check-2.webp\\"\\n    alt=\\"\uc885\ub8cc \uc2e0\ud638\ub97c \ubc1b\uc73c\uba74 NOT_SERVING\uc73c\ub85c \uc0c8 \ud2b8\ub798\ud53d\uc744 \ub04a\uace0, \ucc98\ub9ac \uc911 \uc694\uccad\uc744 \ub9c8\uce5c \ub4a4 \uc885\ub8cc\ud558\ub294 \uc138 \ub2e8\uacc4\\"\\n  />\\n</figure>\\n\\n\ubc30\ud3ec\ub85c \uc11c\ubc84\ub97c \ub0b4\ub9b4 \ub54c \ucc98\ub9ac \uc911\uc774\ub358 \uc694\uccad\uc744 \ub04a\uc73c\uba74 \uc5d0\ub7ec\uac00 \ud291\ub2c8\ub2e4. \uc885\ub8cc \uc2e0\ud638\ub97c \ubc1b\uc73c\uba74 \uba3c\uc800 \ud5ec\uc2a4\ub97c `NOT_SERVING`\uc73c\ub85c \ubc14\uafd4 \uc0c8 \ud2b8\ub798\ud53d\uc744 \ub04a\uace0, \ucc98\ub9ac \uc911\uc774\ub358 \uc694\uccad(in-flight)\uc744 \ub9c8\uce5c \ub4a4 \uc885\ub8cc\ud569\ub2c8\ub2e4.\\n\\n```python\\nimport signal\\n\\nasync def shutdown(server, health_servicer):\\n    # 1) \\"\uc774\uc81c \uc548 \ubc1b\uc74c\\", \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 \ud2b8\ub798\ud53d\uc744 \ube8c\\n    await health_servicer.set(\\"\\", health_pb2.HealthCheckResponse.NOT_SERVING)\\n    # 2) \uc7a0\uae50 \ub300\uae30 \ud6c4 in-flight \uc694\uccad drain \ud558\uba70 \uc885\ub8cc\\n    await server.stop(grace=10)\\n```\\n\\n## gRPC \ud5ec\uc2a4\uccb4\ud06c\uc758 \ud754\ud55c \ud568\uc815\\n\\n- \ud5ec\uc2a4\uc758 \uc815\uc758\uac00 \uc2e4\uc81c \ucc98\ub9ac \ub2a5\ub825\uacfc \uc5b4\uae0b\ub0a8: \\"\ud3ec\ud2b8\uac00 \uc5f4\ub838\ub098\\"\uac00 \uc544\ub2c8\ub77c \\"\uc694\uccad\uc744 \ubc1b\uc744 \uc218 \uc788\ub098\\"\ub97c \ub2f5\ud574\uc57c \ud569\ub2c8\ub2e4. \uc758\uc874\ud558\ub294 DB\ub098 \ub2e4\uc6b4\uc2a4\ud2b8\ub9bc\uc774 \uc8fd\uc5c8\uc73c\uba74 `NOT_SERVING`\uc744 \uace0\ub824\ud569\ub2c8\ub2e4.\\n- \uc885\ub8cc\ud560 \ub54c NOT_SERVING \uc804\ud658\uc744 \ube7c\uba39\uc74c: \ubc30\ud3ec\ud560 \ub54c\ub9c8\ub2e4 \ubbf8\uc138\ud55c \uc5d0\ub7ec \uc2a4\ud30c\uc774\ud06c\uac00 \ub0a9\ub2c8\ub2e4.\\n- HTTP\ub9cc \ubcf4\uace0 \uc548\uc2ec: \ud55c \ud504\ub85c\uc138\uc2a4\uc5d0 \uc11c\ubc84\uac00 \ub458\uc774\uba74 \ud5ec\uc2a4\uccb4\ud06c\ub3c4 \ub458 \ub2e4 \ubd10\uc57c \ud569\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **HTTP\ub9cc \uc4f0\ub294 \uc11c\ube44\uc2a4\ub3c4 gRPC \ud5ec\uc2a4\uccb4\ud06c\uac00 \ud544\uc694\ud55c\uac00\uc694?**\\n  - \uc544\ub2c8\uc694. gRPC \uc11c\ubc84\uac00 \uc5c6\uc73c\uba74 HTTP `/health`\ub85c \ucda9\ubd84\ud569\ub2c8\ub2e4. \ubb38\uc81c\ub294 \ub458\uc744 \ud55c \ud504\ub85c\uc138\uc2a4\uc5d0 \ud568\uaed8 \ub744\uc6b8 \ub54c\uc785\ub2c8\ub2e4.\\n- **liveness\uc640 readiness\ub97c \ub098\ub220\uc57c \ud558\ub098\uc694?**\\n  - \uad8c\ud569\ub2c8\ub2e4. liveness\ub294 \\"\uc7ac\uc2dc\uc791\uc774 \ud544\uc694\ud55c\uac00\\", readiness\ub294 \\"\uc9c0\uae08 \ud2b8\ub798\ud53d\uc744 \ubc1b\uc544\ub3c4 \ub418\ub098\\"\uc785\ub2c8\ub2e4. \uc885\ub8cc \uc9c1\uc804 readiness\ub9cc \ub044\uba74 \ud2b8\ub798\ud53d\uc744 \uae54\ub054\ud788 \ube84 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- gRPC Health Checking Protocol (`grpc.health.v1`)\\n- `grpc-ecosystem/grpc-health-probe`\\n- Kubernetes: Configure Liveness/Readiness/Startup Probes (gRPC)"},{"id":"monorepo-workspace-tooling","metadata":{"permalink":"/blog/monorepo-workspace-tooling","source":"@site/blog/2026-06-19-monorepo-workspace-tooling/index.md","title":"\ubaa8\ub178\ub808\ud3ec \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c \uc774\ud574\ud558\uae30 (\uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uc99d\ubd84 \ube4c\ub4dc)","description":"\ubaa8\ub178\ub808\ud3ec\uc5d0\uc11c \uacf5\ud1b5 \ucf54\ub4dc\ub97c \uacf5\uc720\ud558\uace0, \ubc14\ub010 \ubd80\ubd84\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\uac8c \ud574 \uc8fc\ub294 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c\uac00 \ubb34\uc5c7\uc774\uace0 \uc5b4\ub5bb\uac8c \ub098\ub258\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"}],"readingTime":1.74,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ubaa8\ub178\ub808\ud3ec \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c \uc774\ud574\ud558\uae30 (\uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uc99d\ubd84 \ube4c\ub4dc)","slug":"monorepo-workspace-tooling","authors":["kgenots"],"tags":["Reference","Architecture","Ops"],"image":"/assets/blog/cover-monorepo-workspace-tooling.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"gRPC \ud5ec\uc2a4\uccb4\ud06c, HTTP\ub9cc\uc73c\ub860 \ubd80\uc871\ud55c \uc774\uc720","permalink":"/blog/grpc-health-check"},"nextItem":{"title":"NATS JetStream \uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uc815\ucc45 \uc774\ud574\ud558\uae30","permalink":"/blog/nats-jetstream-retention"}},"content":"\ubaa8\ub178\ub808\ud3ec\uc5d0\uc11c \uacf5\ud1b5 \ucf54\ub4dc\ub97c \uacf5\uc720\ud558\uace0, \ubc14\ub010 \ubd80\ubd84\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\uac8c \ud574 \uc8fc\ub294 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c\uac00 \ubb34\uc5c7\uc774\uace0 \uc5b4\ub5bb\uac8c \ub098\ub258\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ubaa8\ub178\ub808\ud3ec \ub3c4\uad6c\ub294 \ub450 \uce35\uc704\ub85c \ub098\ub269\ub2c8\ub2e4. \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800\uc758 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\uac00 \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc5f0\uacb0\ud558\uace0, \ube4c\ub4dc \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 \ubc14\ub010 \ubd80\ubd84\ub9cc \ub2e4\uc2dc \ube4c\ub4dc(\uc99d\ubd84 \ube4c\ub4dc)\ud558\uace0 \uce90\uc2dc\ub97c \uad00\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\ub458\uc744 \ud55c \ub369\uc5b4\ub9ac\ub85c \ubcf4\uba74, \ube4c\ub4dc\uac00 \ub290\ub9b4 \ub54c \uc5b4\ub290 \ucabd\uc744 \uc190\ubd10\uc57c \ud558\ub294\uc9c0 \ud5f7\uac08\ub9bd\ub2c8\ub2e4.\\n\\n## \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c\ub780\\n\\n\uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c\ub294 \ud55c \ub808\ud3ec \uc548\uc758 \uc5ec\ub7ec \ud328\ud0a4\uc9c0\ub97c \ud568\uaed8 \uad00\ub9ac\ud558\uac8c \ud574 \uc8fc\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4. \uacf5\ud1b5 \ucf54\ub4dc\ub97c \uc5ec\ub7ec \uc571\uc774 \ub098\ub220 \uc4f0\uac8c \uc5f0\uacb0\ud558\uace0, \ubb34\uc5c7\uc744 \ub2e4\uc2dc \ube4c\ub4dc\ud560\uc9c0 \uc815\ub9ac\ud574 \uc90d\ub2c8\ub2e4.\\n\\n\uc694\ub9ac\uc5d0 \ube44\uc720\ud558\uba74, \uc5ec\ub7ec \uba54\ub274(\uc571)\uac00 \uacf5\uc6a9 \uc7ac\ub8cc \ucc3d\uace0(\uacf5\uc720 \ud328\ud0a4\uc9c0)\ub97c \ud568\uaed8 \uc501\ub2c8\ub2e4. \uc7ac\ub8cc\uac00 \ubc14\ub00c\uba74 \uadf8 \uc7ac\ub8cc\ub97c \uc4f0\ub294 \uba54\ub274\ub9cc \ub2e4\uc2dc \uc870\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\ucc3d\uace0\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uacfc \ub2e4\uc2dc \uc870\ub9ac\ud560 \uba54\ub274\ub97c \uace0\ub974\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub985\ub2c8\ub2e4.\\n\\n## \ub450 \uce35\uc704\ub85c \ub098\ub220 \ubcf4\uae30\\n\\n\ub3c4\uad6c\ub97c \ub450 \uce35\uc704\ub85c \ub098\ub220 \ubcf4\uba74 \uc5ed\ud560\uc774 \ubd84\uba85\ud574\uc9d1\ub2c8\ub2e4.\\n\\n| \uce35\uc704 | \uc5ed\ud560 | \ub300\ud45c \ub3c4\uad6c |\\n| --- | --- | --- |\\n| \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 | \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc5f0\uacb0(\uc758\uc874\uc131) | pnpm/yarn workspaces, uv, Cargo, Go workspace |\\n| \ube4c\ub4dc \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130 | task \uadf8\ub798\ud504 + \uc99d\ubd84 \ube4c\ub4dc\xb7\uce90\uc2dc | Turborepo, Nx |\\n\\n\ub458\uc740 \ud568\uaed8 \uc501\ub2c8\ub2e4. \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800\uac00 \\"\ubb34\uc5c7\uc744 \uacf5\uc720\ud558\ub294\uc9c0\\"\ub97c \uc54c\uace0, \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 \\"\ubb34\uc5c7\uc744 \ub2e4\uc2dc \ub9cc\ub4e4\uc9c0\\"\ub97c \uc815\ud569\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/monorepo-workspace-tooling-2.webp\\"\\n    alt=\\"\ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\uac00 \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc5f0\uacb0\ud558\uace0, \ube4c\ub4dc \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 \uc99d\ubd84 \ube4c\ub4dc\uc640 \uce90\uc2dc\ub97c \ub2f4\ub2f9\ud558\ub294 \ub450 \uce35\uc704 \uad6c\ubd84\\"\\n  />\\n</figure>\\n\\n## \uacf5\uc720 \ud328\ud0a4\uc9c0 \uc5f0\uacb0 (\ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800)\\n\\n\uccab \uce35\uc704\ub294 \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc785\ub2c8\ub2e4. \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\ub97c \uc120\uc5b8\ud558\uba74, \ud55c \ud328\ud0a4\uc9c0\ub97c \uace0\ucce4\uc744 \ub54c \uadf8\uac83\uc744 \uc4f0\ub294 \uc571\uc774 \uc989\uc2dc \uac19\uc740 \ucf54\ub4dc\ub97c \ubd05\ub2c8\ub2e4.\\n\\n\ubc84\uc804\uc744 \uc62c\ub824 \ubc30\ud3ec\ud558\uace0 \ub2e4\uc2dc \ubc1b\uc544\uc624\ub294 \uc655\ubcf5\uc774 \uc0ac\ub77c\uc9d1\ub2c8\ub2e4.\\n\\n```yaml\\n# pnpm-workspace.yaml\\npackages:\\n  - \\"apps/*\\"\\n  - \\"packages/*\\"\\n```\\n\\n```json\\n// apps/web/package.json (\uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uadf8\ub300\ub85c \uc758\uc874)\\n{ \\"dependencies\\": { \\"@acme/ui\\": \\"workspace:*\\" } }\\n```\\n\\n\uc774 \uc5f0\uacb0\uc774 [\ubaa8\ub178\ub808\ud3ec\uc758 \uac00\uc7a5 \ud070 \uc774\uc810](/blog/monorepo-15-service-msa)\uc785\ub2c8\ub2e4. \uacf5\uc720 \ucf54\ub4dc\uc640 \uacc4\uc57d\uc774 \ud55c \ucee4\ubc0b\uc5d0\uc11c \uac19\uc774 \uc6c0\uc9c1\uc785\ub2c8\ub2e4.\\n\\n## \ubc14\ub010 \uac83\ub9cc \ube4c\ub4dc (\uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130)\\n\\n\ub458\uc9f8 \uce35\uc704\ub294 \ubc14\ub010 \uac83\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\ub294 \uc77c\uc785\ub2c8\ub2e4. \ube4c\ub4dc \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\ub294 \ud328\ud0a4\uc9c0 \uc0ac\uc774\uc758 \uc758\uc874 \uadf8\ub798\ud504\ub97c \uc54c\uace0 \uc788\uc5b4\uc11c, \ubc14\ub010 \ud328\ud0a4\uc9c0\uc640 \uadf8 \uc601\ud5a5\uc744 \ubc1b\ub294 \uc571\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\uace0 \ub098\uba38\uc9c0\ub294 \uce90\uc2dc \uacb0\uacfc\ub97c \uc501\ub2c8\ub2e4.\\n\\n```bash\\nturbo run build       # \ubc14\ub010 \uac83 + \uc601\ud5a5\ubc1b\ub294 \uac83\ub9cc \ube4c\ub4dc, \ub098\uba38\uc9c0\ub294 \uce90\uc2dc\\n```\\n\\n\uc785\ub825(\uc18c\uc2a4\xb7\uc758\uc874\xb7\uc124\uc815)\uc774 \uadf8\ub300\ub85c\uba74 \uc774\uc804 \ube4c\ub4dc \uacb0\uacfc\ub97c \uce90\uc2dc\uc5d0\uc11c \uadf8\ub300\ub85c \uac00\uc838\uc635\ub2c8\ub2e4. \uc804\uccb4\ub97c \ub9e4\ubc88 \ub2e4\uc2dc \ube4c\ub4dc\ud558\uc9c0 \uc54a\uc73c\ub2c8, \ub808\ud3ec\uac00 \ucee4\uc838\ub3c4 \ud53c\ub4dc\ubc31\uc774 \ub290\ub824\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/monorepo-workspace-tooling-3.webp\\"\\n    alt=\\"\ubcc0\uacbd\ub41c \uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uadf8\uac83\uc744 \uc758\uc874\ud558\ub294 \uc571\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\uace0, \ubb34\uad00\ud55c \ud328\ud0a4\uc9c0\xb7\uc571\uc740 \uce90\uc2dc \uacb0\uacfc\ub97c \uac00\uc838\uc624\ub294 \uc99d\ubd84 \ube4c\ub4dc\\"\\n  />\\n</figure>\\n\\n## \ud754\ud55c \ud568\uc815 (\uc21c\ud658 \uc758\uc874\uacfc \uce90\uc2dc \ud0a4)\\n\\n- \uc21c\ud658 \uc758\uc874: \ud328\ud0a4\uc9c0 A\uac00 B\ub97c, B\uac00 \ub2e4\uc2dc A\ub97c \uc758\uc874\ud558\uba74 \uadf8\ub798\ud504\uac00 \uaf2c\uc5ec \uc99d\ubd84 \ube4c\ub4dc\uac00 \uc5b4\uae0b\ub0a9\ub2c8\ub2e4. \uc758\uc874 \ubc29\ud5a5\uc740 \ud55c\ucabd\uc73c\ub85c \uc720\uc9c0\ud569\ub2c8\ub2e4.\\n- \uce90\uc2dc \ud0a4\ub97c \uc798\ubabb \uc7a1\uc74c: \ube4c\ub4dc\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uc785\ub825(\ud658\uacbd \ubcc0\uc218\xb7\uc124\uc815 \ud30c\uc77c \ub4f1)\uc744 \uce90\uc2dc \ud0a4\uc5d0\uc11c \ube60\ub728\ub9ac\uba74, <span style={{ backgroundColor: \'#ffdce0\'}}>\ubc14\ub00c\uc5c8\ub294\ub370\ub3c4 \uc61b \uce90\uc2dc\ub97c \uac00\uc838\uc635\ub2c8\ub2e4.</span> \uc785\ub825\uc744 \ube60\uc9d0\uc5c6\uc774 \ud0a4\uc5d0 \ub123\uc2b5\ub2c8\ub2e4.\\n- \uacb0\uad6d \uc804\ubd80 \ube4c\ub4dc: \uc758\uc874\uc744 \ub108\ubb34 \ub113\uac8c \uac78\uba74 \uc791\uc740 \ubcc0\uacbd\uc5d0\ub3c4 \uc804\ubd80 \ub2e4\uc2dc \ube4c\ub4dc\ub429\ub2c8\ub2e4. \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc798\uac8c \ub098\ub220 \uc601\ud5a5 \ubc94\uc704\ub97c \uc881\ud799\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **\ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\ub9cc \uc788\uc73c\uba74 \uc548 \ub418\ub098\uc694?**\\n  - \uacf5\uc720\ub294 \ub429\ub2c8\ub2e4. \ub2e4\ub9cc \\"\ubb34\uc5c7\uc744 \ub2e4\uc2dc \ube4c\ub4dc\ud560\uc9c0\\"\ub294 \uc9c1\uc811 \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4. \ub808\ud3ec\uac00 \ucee4\uc9c0\uba74 \uc99d\ubd84 \ube4c\ub4dc\xb7\uce90\uc2dc\ub97c \uc8fc\ub294 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uc758 \uc774\uc810\uc774 \ucee4\uc9d1\ub2c8\ub2e4.\\n- **Turborepo\uc640 Nx \uc911 \ubb34\uc5c7\uc744 \uace0\ub974\ub098\uc694?**\\n  - \ud575\uc2ec \uae30\ub2a5(task \uadf8\ub798\ud504\xb7\uce90\uc2dc)\uc740 \ube44\uc2b7\ud569\ub2c8\ub2e4. \uc124\uc815\uc774 \uac00\ubccd\uace0 \ub2e8\uc21c\ud558\uba74 Turborepo, \ud50c\ub7ec\uadf8\uc778\uacfc \ucf54\ub4dc \uc0dd\uc131\uae4c\uc9c0 \ud3ed\ub113\uac8c \uc4f0\ub824\uba74 Nx\uac00 \ud754\ud55c \uc120\ud0dd\uc785\ub2c8\ub2e4.\\n- **JS\uac00 \uc544\ub2cc \uc5b8\uc5b4\ub3c4 \ub418\ub098\uc694?**\\n  - \ub429\ub2c8\ub2e4. uv(\ud30c\uc774\uc36c), Cargo(\ub7ec\uc2a4\ud2b8), Go workspace\uac00 \uac19\uc740 \\"\uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\\" \uac1c\ub150\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\ub3c4 \uc5b8\uc5b4 \ubb34\uad00\ud558\uac8c task\ub97c \ubb36\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- Turborepo / Nx Docs: Task Graph / Caching\\n- pnpm / uv / Cargo / Go Workspaces"},{"id":"nats-jetstream-retention","metadata":{"permalink":"/blog/nats-jetstream-retention","source":"@site/blog/2026-06-19-nats-jetstream-retention/index.md","title":"NATS JetStream \uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uc815\ucc45 \uc774\ud574\ud558\uae30","description":"NATS JetStream \uc2a4\ud2b8\ub9bc\uc774 \uba54\uc2dc\uc9c0\ub97c \uc5b8\uc81c\uae4c\uc9c0 \ubcf4\uad00\ud558\uace0 \uc5b8\uc81c \uc9c0\uc6b0\ub294\uc9c0, \uadf8\ub9ac\uace0 \ubcf4\uad00 \uae30\uac04\uc744 \uc798\ubabb \uc7a1\uc73c\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc0dd\uae30\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"NATS","permalink":"/blog/tags/nats"}],"readingTime":1.72,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"NATS JetStream \uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uc815\ucc45 \uc774\ud574\ud558\uae30","slug":"nats-jetstream-retention","authors":["kgenots"],"tags":["Reference","Backend","NATS"],"image":"/assets/blog/cover-nats-jetstream-retention.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ubaa8\ub178\ub808\ud3ec \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c \uc774\ud574\ud558\uae30 (\uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uc99d\ubd84 \ube4c\ub4dc)","permalink":"/blog/monorepo-workspace-tooling"},"nextItem":{"title":"OAuth \ud1a0\ud070, \uc5b4\ub514\uc5d0 \uc800\uc7a5\ud560\uae4c (\ucfe0\ud0a4 vs localStorage)","permalink":"/blog/oauth-bff-token-storage"}},"content":"NATS JetStream \uc2a4\ud2b8\ub9bc\uc774 \uba54\uc2dc\uc9c0\ub97c \uc5b8\uc81c\uae4c\uc9c0 \ubcf4\uad00\ud558\uace0 \uc5b8\uc81c \uc9c0\uc6b0\ub294\uc9c0, \uadf8\ub9ac\uace0 \ubcf4\uad00 \uae30\uac04\uc744 \uc798\ubabb \uc7a1\uc73c\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc0dd\uae30\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uae30\uac04(`max_age`)\uc740 \uc18c\ube44\uc790\uac00 \uba54\uc2dc\uc9c0\ub97c \uac00\uc838\uac00\ub294 \uc8fc\uae30\ubcf4\ub2e4 \ub109\ub109\ud788 \uae38\uac8c \uc7a1\uc2b5\ub2c8\ub2e4. \uc774 \uac12\uc774 \uc9e7\uc73c\uba74 \uc18c\ube44\uc790\uac00 \uc624\uae30 \uc804\uc5d0 \uba54\uc2dc\uc9c0\uac00 \ub9cc\ub8cc\ub418\uc5b4 \uc0ac\ub77c\uc9d1\ub2c8\ub2e4.\\n\\n\ubd84\uba85\ud788 \ubc1c\ud589\ud588\ub294\ub370 \uc18c\ube44 \ucabd\uc5d0\ub294 \uc544\ubb34\uac83\ub3c4 \ub3c4\ucc29\ud558\uc9c0 \uc54a\ub294 \uc0ac\uace0\uac00 \ub300\uac1c \uc5ec\uae30\uc11c \ub0a9\ub2c8\ub2e4.\\n\\n## JetStream \uc2a4\ud2b8\ub9bc\uacfc \ubcf4\uad00 \uc815\ucc45\uc774\ub780\\n\\nJetStream \uc2a4\ud2b8\ub9bc\uc740 NATS\uac00 \uba54\uc2dc\uc9c0\ub97c \ub514\uc2a4\ud06c\uc5d0 \uc800\uc7a5\ud574 \ub450\ub294 \uc800\uc7a5\uc18c\uc785\ub2c8\ub2e4. \uc77c\ubc18 NATS\ub294 \uba54\uc2dc\uc9c0\ub97c \ud758\ub824\ubcf4\ub0b4\uace0 \ub05d\uc774\uc9c0\ub9cc, JetStream\uc740 \uc2a4\ud2b8\ub9bc\uc5d0 \uc313\uc544 \ub450\uace0 \uc18c\ube44\uc790\uac00 \ub098\uc911\uc5d0 \uac00\uc838\uac08 \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4.\\n\\n\ubcf4\uad00 \uc815\ucc45(retention policy)\uc740 \uc774\ub807\uac8c \uc313\uc778 \uba54\uc2dc\uc9c0\ub97c \uc5b8\uc81c \uc9c0\uc6b8\uc9c0 \uc815\ud558\ub294 \uaddc\uce59\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \uba54\uc2dc\uc9c0\ub97c \uc601\uc6d0\ud788 \ub458 \uc218\ub294 \uc5c6\uc73c\ub2c8 \uc2a4\ud2b8\ub9bc\ub9c8\ub2e4 \uc9c0\uc6b0\ub294 \uae30\uc900\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n## \ubcf4\uad00 \uc815\ucc45 \uc138 \uac00\uc9c0\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/nats-jetstream-retention.webp\\"\\n    alt=\\"NATS JetStream \ubcf4\uad00 \uc815\ucc45 \uc138 \uac00\uc9c0\uc640 \uba54\uc2dc\uc9c0\uac00 \uc9c0\uc6cc\uc9c0\ub294 \uc870\uac74\\"\\n  />\\n</figure>\\n\\nNATS JetStream\uc758 \ubcf4\uad00 \uc815\ucc45\uc740 \uc138 \uac00\uc9c0\uc785\ub2c8\ub2e4.\\n\\n| \uc815\ucc45 | \uba54\uc2dc\uc9c0\ub97c \uc9c0\uc6b0\ub294 \uc2dc\uc810 | \uc4f0\ub294 \uacf3 |\\n| --- | --- | --- |\\n| Limits (\uae30\ubcf8) | \ud55c\ub3c4(\uac1c\uc218\xb7\uc6a9\ub7c9\xb7\uae30\uac04)\uc5d0 \ub3c4\ub2ec\ud558\uba74 \uc624\ub798\ub41c \uac83\ubd80\ud130 | \uc5ec\ub7ec \uc18c\ube44\uc790\uac00 \uac19\uc740 \uba54\uc2dc\uc9c0\ub97c \uac01\uc790 \uc77d\ub294 \uacbd\uc6b0 |\\n| Interest | \uad00\uc2ec \uc788\ub294 \ubaa8\ub4e0 \uc18c\ube44\uc790\uac00 ack\ud558\uba74 | \uad6c\ub3c5\uc790 \ubaa8\ub450 \ucc98\ub9ac\ud55c \ub4a4 \ube44\uc6cc\ub3c4 \ub420 \ub54c |\\n| WorkQueue | \uc18c\ube44\uc790 \ud558\ub098\uac00 ack\ud558\uba74 \uc989\uc2dc | \uc791\uc5c5 \ud050(\ud55c \uba54\uc2dc\uc9c0\ub97c \ud55c \ubc88\ub9cc \ucc98\ub9ac) |\\n\\n\ub300\ubd80\ubd84\uc740 Limits\ub97c \uc501\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud55c\ub3c4\ub97c \uc5b4\ub5bb\uac8c \uc7a1\ub290\ub0d0\uac00 \ubb38\uc81c\uac00 \ub429\ub2c8\ub2e4.\\n\\n## \uba54\uc2dc\uc9c0\ub294 \uc5b8\uc81c \uc9c0\uc6cc\uc9c0\ub098 (Limits \uc815\ucc45)\\n\\nLimits \uc815\ucc45\uc5d0\uc11c\ub294 \ub2e4\uc74c \uc138 \ud55c\ub3c4 \uc911 \ud558\ub098\ub77c\ub3c4 \ub118\uc73c\uba74 \uc624\ub798\ub41c \uba54\uc2dc\uc9c0\ubd80\ud130 \uc9c0\uc6cc\uc9d1\ub2c8\ub2e4.\\n\\n- `max_msgs`: \ucd5c\ub300 \uba54\uc2dc\uc9c0 \uac1c\uc218\\n- `max_bytes`: \ucd5c\ub300 \uc6a9\ub7c9\\n- `max_age`: \ucd5c\ub300 \ubcf4\uad00 \uae30\uac04(\uba54\uc2dc\uc9c0\uc758 \uc218\uba85)\\n\\n\uc774 \uc14b \uc911 \uc0ac\uace0\uac00 \uac00\uc7a5 \uc7a6\uc740 \uac12\uc774 `max_age`\uc785\ub2c8\ub2e4. \uac1c\uc218\uc640 \uc6a9\ub7c9\uc740 \uc2a4\ud2b8\ub9bc\uc774 \ucee4\uc9c8 \ub54c \uac78\ub9ac\uc9c0\ub9cc, \uae30\uac04\uc740 \uba54\uc2dc\uc9c0\uac00 \uba87 \uac74\uc774\ub4e0 \uadf8\ub0e5 \uc9c0\ub098\uac11\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/nats-jetstream-retention-2.webp\\"\\n    alt=\\"max_age\uac00 \uc18c\ube44 \uc8fc\uae30\ubcf4\ub2e4 \uc9e7\uc73c\uba74 \uc18c\ube44 \uc804\uc5d0 \uc0ad\uc81c\ub418\uace0, \uae38\uba74 \uc18c\ube44 \ud6c4 \ub9cc\ub8cc\ub418\uc5b4 \uc548\uc804\ud558\ub2e4\\"\\n  />\\n</figure>\\n\\n## \uc2a4\ud2b8\ub9bc \uc124\uc815 \ubc29\ubc95\\n\\n\uc2a4\ud2b8\ub9bc\uc744 \ub9cc\ub4e4 \ub54c `StreamConfig`\uc5d0 \uc815\ucc45\uacfc \ud55c\ub3c4\ub97c \uc9c0\uc815\ud569\ub2c8\ub2e4.\\n\\n```python\\nfrom nats.js.api import StreamConfig, RetentionPolicy\\n\\nconfig = StreamConfig(\\n    name=\\"MY_STREAM\\",\\n    subjects=[\\"my-service.>\\"],\\n    retention=RetentionPolicy.LIMITS,   # \uae30\ubcf8\\n    max_age=14 * 24 * 60 * 60,          # 14\uc77c (\ucd08 \ub2e8\uc704), \uc18c\ube44 \uc8fc\uae30\ubcf4\ub2e4 \uae38\uac8c\\n    # max_msgs, max_bytes \ub3c4 \ud568\uaed8 \ub458 \uc218 \uc788\uc74c\\n)\\nawait js.add_stream(config)\\n```\\n\\n`max_age`\ub294 \uc18c\ube44\uc790\uac00 \uba54\uc2dc\uc9c0\ub97c \uac00\uc838\uac00\ub294 \uc8fc\uae30\ubcf4\ub2e4 \ub109\ub109\ud788 \uc7a1\uc2b5\ub2c8\ub2e4. \ud558\ub8e8 \ud55c \ubc88 \ubaa8\uc544 \uac00\ub294 \uc18c\ube44\uc790\uac00 \uc788\ub2e4\uba74, \ud558\ub8e8\ub85c \uc7a1\uc9c0 \ub9d0\uace0 \uba70\uce60 \uc774\uc0c1 \ub450\ub294 \uc2dd\uc785\ub2c8\ub2e4.\\n\\n## max_age \uc124\uc815\uc5d0\uc11c \ud754\ud55c \ud568\uc815\\n\\n- `max_age`\ub97c \uc18c\ube44 \uc8fc\uae30\ubcf4\ub2e4 \uc9e7\uac8c \ub450\uae30: <span style={{ backgroundColor: \'#ffdce0\'}}>\uc18c\ube44 \uc804\uc5d0 \uba54\uc2dc\uc9c0\uac00 \uc0ad\uc81c\ub429\ub2c8\ub2e4.</span> \ubc1c\ud589\ub3c4 \uc0ad\uc81c\ub3c4 \uc815\uc0c1 \ub3d9\uc791\uc774\ub77c \uc624\ub958 \ub85c\uadf8\uac00 \ub0a8\uc9c0 \uc54a\uace0, \uadf8\ub798\uc11c \ucc3e\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. (\uc774 \uc0ac\uace0\ub97c \uc9c1\uc811 \uacaa\uc740 \uc774\uc57c\uae30\ub294 [\ud68c\uace0 \uae00](/blog/event-bus-nats-temporal)\uc5d0 \uc801\uc5c8\uc2b5\ub2c8\ub2e4.)\\n- CLI\ub85c \uc784\uc2dc \ubcc0\uacbd: `nats stream edit`\ub85c \ubc14\uafd4\ub3c4, \uc11c\ube44\uc2a4\uac00 \ucf54\ub4dc\uc758 `StreamConfig`\ub85c \uc2a4\ud2b8\ub9bc\uc744 \ub2e4\uc2dc \uac31\uc2e0\ud558\uba74 \ucf54\ub4dc\uac12\uc73c\ub85c \ub418\ub3cc\uc544\uac11\ub2c8\ub2e4. \uc601\uad6c\ud788 \ubc14\uafb8\ub824\uba74 \ucf54\ub4dc\ub97c \uace0\uce69\ub2c8\ub2e4.\\n- \uc2a4\ud2b8\ub9bc\ub9c8\ub2e4 \uc81c\uac01\uac01\uc778 \ubcf4\uad00 \uae30\uac04: \ud300\uc5d0\uc11c 1d/7d/30d\ub97c \uc784\uc758\ub85c \uc11e\uc73c\uba74 \uc2e4\uc218\uac00 \ub0a9\ub2c8\ub2e4. \uacf5\ud1b5 \uc0c1\uc218 \ud558\ub098\ub85c \uace0\uc815\ud558\ub294 \ud3b8\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **max_age\uc640 \uc18c\ube44\uc790(consumer)\uc758 ack\ub294 \ubb34\uc2a8 \uad00\uacc4\uc778\uac00\uc694?**\\n  - Limits \uc815\ucc45\uc5d0\uc11c\ub294 \ubb34\uad00\ud569\ub2c8\ub2e4. \uc18c\ube44\uc790\uac00 ack\ud558\uc9c0 \uc54a\uc544\ub3c4 `max_age`\uac00 \uc9c0\ub098\uba74 \uc9c0\uc6cc\uc9d1\ub2c8\ub2e4. ack \uae30\ubc18\uc73c\ub85c \uc9c0\uc6b0\ub824\uba74 Interest\ub098 WorkQueue \uc815\ucc45\uc744 \uc501\ub2c8\ub2e4.\\n- **\uba54\uc2dc\uc9c0\ub97c \uc783\uc9c0 \uc54a\uc73c\ub824\uba74 \uc5b4\ub5bb\uac8c \ud558\ub098\uc694?**\\n  - \uc18c\ube44 \uc8fc\uae30\ubcf4\ub2e4 `max_age`\ub97c \uae38\uac8c \ub450\uace0, \ucc98\ub9ac \uc2e4\ud328\ubd84\uc740 \ubcc4\ub3c4 DLQ(\ub370\ub4dc\ub808\ud130) \uc2a4\ud2b8\ub9bc\uc73c\ub85c \ubcf4\ub0c5\ub2c8\ub2e4. DLQ\ub294 \ubcf4\ud1b5 \ubcf4\uad00 \ud55c\ub3c4\ub97c \ub450\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n- **\ud55c\ub3c4\ub97c \uc5ec\ub7ec \uac1c \ub3d9\uc2dc\uc5d0 \uac78 \uc218 \uc788\ub098\uc694?**\\n  - \ub124. `max_msgs`, `max_bytes`, `max_age`\ub97c \ud568\uaed8 \ub450\uba74 \uac00\uc7a5 \uba3c\uc800 \ub3c4\ub2ec\ud55c \ud55c\ub3c4\uac00 \uc801\uc6a9\ub429\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- NATS Docs: JetStream Streams / Retention Policies\\n- NATS Docs: `nats stream add` / `StreamConfig`"},{"id":"oauth-bff-token-storage","metadata":{"permalink":"/blog/oauth-bff-token-storage","source":"@site/blog/2026-06-19-oauth-bff-token-storage/index.md","title":"OAuth \ud1a0\ud070, \uc5b4\ub514\uc5d0 \uc800\uc7a5\ud560\uae4c (\ucfe0\ud0a4 vs localStorage)","description":"\ub85c\uadf8\uc778 \ud6c4 \ubc1b\uc740 \ud1a0\ud070\uc744 \ube0c\ub77c\uc6b0\uc800 \uc5b4\ub514\uc5d0 \uc800\uc7a5\ud574\uc57c \ud558\ub294\uc9c0, \uc120\ud0dd\uc9c0\ubcc4 \uc7a5\ub2e8\uc810\uacfc \uace0\ub974\ub294 \uae30\uc900\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Auth","permalink":"/blog/tags/auth"},{"inline":true,"label":"Frontend","permalink":"/blog/tags/frontend"},{"inline":true,"label":"Security","permalink":"/blog/tags/security"}],"readingTime":2.5,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"OAuth \ud1a0\ud070, \uc5b4\ub514\uc5d0 \uc800\uc7a5\ud560\uae4c (\ucfe0\ud0a4 vs localStorage)","slug":"oauth-bff-token-storage","authors":["kgenots"],"tags":["Reference","Auth","Frontend","Security"],"image":"/assets/blog/cover-oauth-bff-token-storage.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"NATS JetStream \uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uc815\ucc45 \uc774\ud574\ud558\uae30","permalink":"/blog/nats-jetstream-retention"},"nextItem":{"title":"OPA\ub85c API \uad8c\ud55c(\uc778\uac00)\uc744 \uc678\ubd80\ud654\ud558\uae30","permalink":"/blog/opa-policy-authz"}},"content":"\ub85c\uadf8\uc778 \ud6c4 \ubc1b\uc740 \ud1a0\ud070\uc744 \ube0c\ub77c\uc6b0\uc800 \uc5b4\ub514\uc5d0 \uc800\uc7a5\ud574\uc57c \ud558\ub294\uc9c0, \uc120\ud0dd\uc9c0\ubcc4 \uc7a5\ub2e8\uc810\uacfc \uace0\ub974\ub294 \uae30\uc900\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ub9ac\ud504\ub808\uc2dc \ud1a0\ud070\uc740 HttpOnly \ucfe0\ud0a4\uc5d0 \ub450\uace0, \uc561\uc138\uc2a4\xb7ID \ud1a0\ud070\uc740 \uba54\ubaa8\ub9ac\ub098 \uc218\uba85\uc774 \uc9e7\uc740 localStorage\uc5d0 \ub461\ub2c8\ub2e4. \ud1a0\ud070\uc744 \ud55c\uacf3\uc5d0 \ubab0\uc544 \ub450\uba74 \uadf8 \ud55c \uacf3\uc774 \ub6ab\ub9b4 \ub54c \uc804\ubd80 \uac19\uc774 \ub098\uac11\ub2c8\ub2e4.\\n\\n\ub85c\uadf8\uc778\uc744 \ubd99\uc774\uba74 \uace7 \\"\ubc1b\uc740 \ud1a0\ud070\uc744 \uc5b4\ub514\uc5d0 \ub450\uc9c0?\\"\ub77c\ub294 \uc9c8\ubb38\uc744 \ub9cc\ub0a9\ub2c8\ub2e4. localStorage\uc5d0 \ub123\uc73c\ub77c\ub294 \uae00\ub3c4 \uc788\uace0 \uc808\ub300 \ub123\uc9c0 \ub9d0\ub77c\ub294 \uae00\ub3c4 \uc788\uc5b4\uc11c \ucc98\uc74c\uc5d0\ub294 \ud5f7\uac08\ub9bd\ub2c8\ub2e4. \uc815\ub2f5\uc774 \ud558\ub098\ub85c \uc815\ud574\uc838 \uc788\uc9c0\ub294 \uc54a\uace0, \ud1a0\ud070\uc758 \uc218\uba85\uc5d0 \ub530\ub77c \uc790\ub9ac\uac00 \uac08\ub9bd\ub2c8\ub2e4.\\n\\n## OAuth \ud1a0\ud070\uc758 \uc885\ub958: \uc561\uc138\uc2a4 \ud1a0\ud070\uacfc \ub9ac\ud504\ub808\uc2dc \ud1a0\ud070\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/oauth-bff-token-storage-2.webp\\"\\n    alt=\\"\uc561\uc138\uc2a4\xb7ID \ud1a0\ud070\uc740 \uc218\uba85\uc774 \uc9e7\uace0, \ub9ac\ud504\ub808\uc2dc \ud1a0\ud070\uc740 \uc218\uba85\uc774 \uae38\uc5b4 \ub354 \ubbfc\uac10\ud558\ub2e4\\"\\n  />\\n</figure>\\n\\nOAuth/OIDC \ub85c\uadf8\uc778\uc744 \ud558\uba74 \ubcf4\ud1b5 \ud1a0\ud070 \ub450\uc138 \uac1c\ub97c \ubc1b\uc2b5\ub2c8\ub2e4.\\n\\n- \uc561\uc138\uc2a4 \ud1a0\ud070 / ID \ud1a0\ud070: API\ub97c \ubd80\ub97c \ub54c \uc4f0\ub294 \ud1a0\ud070\uc785\ub2c8\ub2e4. \uc218\uba85\uc774 \uc9e7\uc2b5\ub2c8\ub2e4(\ubcf4\ud1b5 \ubd84 \ub2e8\uc704).\\n- \ub9ac\ud504\ub808\uc2dc \ud1a0\ud070: \uc561\uc138\uc2a4 \ud1a0\ud070\uc774 \ub9cc\ub8cc\ub418\uba74 \uc0c8\ub85c \ubc1b\uc544\uc624\ub294 \ub370 \uc4f0\ub294 \ud1a0\ud070\uc785\ub2c8\ub2e4. \uc218\uba85\uc774 \uae41\ub2c8\ub2e4.\\n\\n\uc218\uba85\uc774 \uae34 \ub9ac\ud504\ub808\uc2dc \ud1a0\ud070\uc774 \ub354 \ubbfc\uac10\ud569\ub2c8\ub2e4. \ud55c \ubc88 \ud138\ub9ac\uba74 \uadf8\ub9cc\ud07c \uc624\ub798 \uc545\uc6a9\ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub458\uc744 \uac19\uc740 \uacf3\uc5d0 \ub458\uc9c0 \ub098\ub220 \ub458\uc9c0\ubd80\ud130 \uc815\ud558\uac8c \ub429\ub2c8\ub2e4.\\n\\n## \uc800\uc7a5\ud560 \uc218 \uc788\ub294 \uacf3\\n\\n\ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ud1a0\ud070\uc744 \ub458 \uc218 \uc788\ub294 \uc790\ub9ac\ub294 \ud06c\uac8c \ub137\uc785\ub2c8\ub2e4.\\n\\n| \uc800\uc7a5\uc18c | \ud55c \uc904 \uc124\uba85 |\\n| --- | --- |\\n| \uba54\ubaa8\ub9ac(JS \ubcc0\uc218) | \ud0ed\uc774 \uc0b4\uc544 \uc788\ub294 \ub3d9\uc548\ub9cc. \uc0c8\ub85c\uace0\uce68\ud558\uba74 \uc0ac\ub77c\uc9d0 |\\n| localStorage | \ub3c4\uba54\uc778\ubcc4 \uc601\uad6c \uc800\uc7a5. JS\ub85c \uc77d\uace0 \uc500 |\\n| sessionStorage | \ud0ed \ub2e8\uc704 \uc800\uc7a5. \ud0ed \ub2eb\uc73c\uba74 \uc0ac\ub77c\uc9d0 |\\n| \ucfe0\ud0a4 | \uc694\uccad\uc5d0 \uc790\ub3d9 \ucca8\ubd80. `HttpOnly`\uba74 JS\uac00 \ubabb \uc77d\uc74c |\\n\\n## \ubb34\uc5c7\uc744 \ub9c9\uc544 \uc8fc\ub098 (XSS\uc640 CSRF)\\n\\n\uc800\uc7a5 \uc704\uce58\ub97c \uace0\ub974\ub294 \uc77c\uc740 \uacb0\uad6d \uc5b4\ub5a4 \uacf5\uaca9\uc744 \ub9c9\uc744\uc9c0 \uace0\ub974\ub294 \uc77c\uc785\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/oauth-bff-token-storage.webp\\"\\n    alt=\\"\ud1a0\ud070 \uc800\uc7a5 \uc704\uce58\ubcc4 \ube44\uad50\uc640 \uc120\ud0dd \uae30\uc900 \uacb0\uc815 \ud750\ub984\\"\\n  />\\n</figure>\\n\\n| \uae30\uc900 | localStorage | \ucfe0\ud0a4 (HttpOnly) | \uba54\ubaa8\ub9ac |\\n| --- | --- | --- | --- |\\n| XSS(\uc2a4\ud06c\ub9bd\ud2b8 \ud0c8\ucde8) \ubc29\uc5b4 | \u274c JS\uac00 \uc77d\uc74c | \u2705 JS \uc811\uadfc \ubd88\uac00 | \u25b3 \ubcc0\uc218 \uc811\uadfc \uac00\ub2a5\ud558\ub098 \uc601\uc18d \uc548 \ub428 |\\n| CSRF \ubc29\uc5b4 | \u2705 \uc790\ub3d9 \uc804\uc1a1 \uc548 \ub428 | \u274c \uc790\ub3d9 \uc804\uc1a1\ub428(SameSite\ub85c \uc644\ud654) | \u2705 |\\n| \ud06c\uae30 \ud55c\uacc4 | \ub109\ub109(5MB+) | \uc57d 4KB | \ub109\ub109 |\\n| \uc0c8\ub85c\uace0\uce68 \ud6c4 \uc720\uc9c0 | \u2705 | \u2705 | \u274c |\\n| \ud0ed \uac04 \uacf5\uc720 | \u2705 | \u2705 | \u274c |\\n\\n:::info \uc644\ubcbd\ud55c \ud55c \uacf3\uc740 \uc5c6\uc2b5\ub2c8\ub2e4\\nlocalStorage\ub294 XSS\uc5d0 \uc57d\ud558\uace0 CSRF\uc5d0 \uac15\ud569\ub2c8\ub2e4. HttpOnly \ucfe0\ud0a4\ub294 \uadf8 \ubc18\ub300\ub85c XSS\uc5d0 \uac15\ud558\uace0 CSRF\uc5d0 \uc57d\ud569\ub2c8\ub2e4. \uc5b4\ub290 \ucabd\uc744 \uace8\ub77c\ub3c4 \ud55c\ucabd \uad6c\uba4d\uc740 \ub0a8\uc2b5\ub2c8\ub2e4.\\n:::\\n\\n## \ud1a0\ud070 \uc800\uc7a5 \uc704\uce58\ub294 \uc5b4\ub5bb\uac8c \uace0\ub974\ub098\\n\\n\ud1a0\ud070 \uc885\ub958\uc5d0 \ub530\ub77c \uc800\uc7a5 \uc704\uce58\ub97c \ub098\ub215\ub2c8\ub2e4.\\n\\n1. \ub9ac\ud504\ub808\uc2dc \ud1a0\ud070(\uae34 \uc218\uba85)\uc740 HttpOnly \ucfe0\ud0a4\uc5d0 \ub461\ub2c8\ub2e4. JS\uac00 \ubabb \uc77d\uc73c\ub2c8 XSS\ub85c \ud0c8\ucde8\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. CSRF\ub294 `SameSite=Strict/Lax`\ub85c \ub9c9\uc2b5\ub2c8\ub2e4.\\n2. \uc561\uc138\uc2a4/ID \ud1a0\ud070(\uc9e7\uc740 \uc218\uba85)\uc740 \uba54\ubaa8\ub9ac\uac00 \uac00\uc7a5 \uc548\uc804\ud569\ub2c8\ub2e4. \ub2e4\ub9cc \uc0c8\ub85c\uace0\uce68\ub9c8\ub2e4 \uc0ac\ub77c\uc9c0\ubbc0\ub85c, \uadf8\ub54c \ub9ac\ud504\ub808\uc2dc \ud1a0\ud070\uc73c\ub85c \ub2e4\uc2dc \ubc1b\uc544\uc635\ub2c8\ub2e4. \ud3b8\uc758\ub97c \ub354 \uc6d0\ud558\uba74 localStorage\ub3c4 \uc120\ud0dd\uc9c0\uc9c0\ub9cc, XSS \uc704\ud5d8\uc744 \uac10\uc218\ud558\ub294 \ub300\uc2e0 \ud1a0\ud070 \uc218\uba85\uc744 \uc9e7\uac8c \uc720\uc9c0\ud574\uc57c \ud569\ub2c8\ub2e4.\\n3. \ud1a0\ud070\uc740 \uc8fc\uc18c\ucc3d\uc774\ub098 \ud504\ub7f0\ud2b8\uc5d0 \uadf8\ub300\ub85c \ub178\ucd9c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uad50\ud658\uc740 \uc11c\ubc84 \ud55c \ub2e8\uacc4\ub97c \uac70\uce69\ub2c8\ub2e4(BFF \ud328\ud134).\\n\\n## \uad8c\uc7a5 \ud328\ud134 (BFF + \ubd84\ub9ac \uc800\uc7a5)\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/oauth-bff-token-storage-3.webp\\"\\n    alt=\\"BFF\uac00 \ud1a0\ud070\uc744 \ubc1b\uc544 \ub9ac\ud504\ub808\uc2dc\ub294 HttpOnly \ucfe0\ud0a4\ub85c, \uc561\uc138\uc2a4\xb7ID\ub294 \ud504\ub7f0\ud2b8\ub85c \ub098\ub220 \uc800\uc7a5\ud558\ub294 \ud750\ub984\\"\\n  />\\n</figure>\\n\\n\uc11c\ubc84(BFF, Backend for Frontend)\ub97c \ud55c \ub2e8\uacc4 \ub450\uace0 \ud1a0\ud070\uc744 \uc885\ub958\ubcc4\ub85c \ub098\ub220 \uc800\uc7a5\ud558\uba74 \uade0\ud615\uc774 \uac00\uc7a5 \uc798 \ub9de\uc2b5\ub2c8\ub2e4.\\n\\n```text\\n[\ub85c\uadf8\uc778] \u2192 \uc778\uc99d \uc11c\ubc84\\n        \u2192 BFF\uac00 \ud1a0\ud070 \uc218\ub839\\n        \u2192 \ub9ac\ud504\ub808\uc2dc \ud1a0\ud070: Set-Cookie (HttpOnly, Secure, SameSite)\\n        \u2192 \uc561\uc138\uc2a4/ID \ud1a0\ud070: \ud504\ub7f0\ud2b8\ub85c \uc804\ub2ec \u2192 \uba54\ubaa8\ub9ac(\ub610\ub294 localStorage)\\n```\\n\\nAPI\ub97c \ubd80\ub97c \ub54c\ub294 \uc561\uc138\uc2a4 \ud1a0\ud070\uc744 \ud5e4\ub354\uc5d0 \uc2e3\uace0, 401\uc774 \uc624\uba74 \ucfe0\ud0a4\uc5d0 \ub2f4\uae34 \ub9ac\ud504\ub808\uc2dc \ud1a0\ud070\uc73c\ub85c \uac31\uc2e0\ud569\ub2c8\ub2e4.\\n\\n```ts\\n// \uc694\uccad\ub9c8\ub2e4 \uc561\uc138\uc2a4 \ud1a0\ud070 \ucca8\ubd80\\napiClient.interceptors.request.use((config) => {\\n  const token = getAccessToken();            // \uba54\ubaa8\ub9ac \ub610\ub294 localStorage\\n  if (token) config.headers.Authorization = `Bearer ${token}`;\\n  return config;\\n});\\n\\n// 401 \u2192 \ub9ac\ud504\ub808\uc2dc (refresh \ud1a0\ud070\uc740 HttpOnly \ucfe0\ud0a4\ub77c JS\uac00 \uc9c1\uc811 \uc548 \ubcf4\ub0c4)\\napiClient.interceptors.response.use(null, async (error) => {\\n  if (error.response?.status === 401) {\\n    await apiClient.post(\\"/auth/refresh\\");     // \ucfe0\ud0a4 \uc790\ub3d9 \ucca8\ubd80\\n    return apiClient(error.config);            // \uc6d0\uc694\uccad \uc7ac\uc2dc\ub3c4\\n  }\\n  throw error;\\n});\\n```\\n\\n\ub9ac\ud504\ub808\uc2dc \ud1a0\ud070\uc744 \uad7d\ub294 \ucabd(BFF) \uc608\uc2dc:\\n\\n```http\\nSet-Cookie: refresh_token=<value>; HttpOnly; Secure; SameSite=Lax; Path=/auth; Max-Age=1209600\\n```\\n\\n## \ud1a0\ud070 \uc800\uc7a5\uc5d0\uc11c \ud754\ud55c \ud568\uc815\\n\\n- \ucfe0\ud0a4 4KB \ud55c\uacc4: \ud1a0\ud070\uc744 \uc554\ud638\ud654\ud574 \ucfe0\ud0a4\uc5d0 \ub123\ub2e4 \ubcf4\uba74 4KB\ub97c \ub118\uae30 \uc27d\uc2b5\ub2c8\ub2e4. <span style={{ backgroundColor: \'#ffdce0\'}}>\ud55c\uacc4\ub97c \ub118\uc73c\uba74 \ube0c\ub77c\uc6b0\uc800\uac00 \uc624\ub958 \uc5c6\uc774 \ucfe0\ud0a4\ub97c \ubc84\ub9bd\ub2c8\ub2e4.</span> \uc800\uc7a5\ub41c \uc904 \uc54c\uc558\ub294\ub370 \ube44\uc5b4 \uc788\uc5b4 401\uc774 \ubc18\ubcf5\ub429\ub2c8\ub2e4. (\uc774 \uc0ac\uace0\ub97c \uc9c1\uc811 \uacaa\uc740 \uc774\uc57c\uae30\ub294 [\ud68c\uace0 \uae00](/blog/auth-bff-redirect-loop)\uc5d0 \uc801\uc5c8\uc2b5\ub2c8\ub2e4.)\\n- \ub3c4\uba54\uc778 \uaca9\ub9ac: A \ub3c4\uba54\uc778\uc5d0\uc11c localStorage\uc5d0 \ub123\uc740 \ud1a0\ud070\uc740 B \ub3c4\uba54\uc778\uc5d0\uc11c \ubabb \uc77d\uc2b5\ub2c8\ub2e4. \ud1a0\ud070\uc740 \uadf8\uac83\uc744 \uc4f8 \ub3c4\uba54\uc778 \ucabd\uc5d0 \uc800\uc7a5\ud574\uc57c \ud569\ub2c8\ub2e4.\\n- localStorage\ub97c \uc4f0\uba74\uc11c \ud1a0\ud070 \uc218\uba85\uc744 \uae38\uac8c \ub450\uae30: XSS\uc5d0 \ub178\ucd9c\ub41c \ucc44\ub85c \uc624\ub798 \uc720\ud6a8\ud55c, \uac00\uc7a5 \ub098\uc05c \uc870\ud569\uc785\ub2c8\ub2e4. localStorage\ub97c \uc4f4\ub2e4\uba74 \uc218\uba85\uc744 \uc9e7\uac8c \ub450\uace0 CSP \uac19\uc740 \uc644\ud654\ucc45\uc744 \ud568\uaed8 \uc801\uc6a9\ud569\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **\uadf8\ub0e5 \ub2e4 localStorage\uc5d0 \ub123\uc73c\uba74 \uc548 \ub418\ub098\uc694?**\\n  - \ub3d9\uc791\uc740 \ud569\ub2c8\ub2e4. \ub2e4\ub9cc XSS \ud55c \ubc88\uc5d0 \uae34 \uc218\uba85 \ud1a0\ud070\uae4c\uc9c0 \ud138\ub9bd\ub2c8\ub2e4. \ucd5c\uc18c\ud55c \ub9ac\ud504\ub808\uc2dc \ud1a0\ud070\ub9cc\uc774\ub77c\ub3c4 HttpOnly \ucfe0\ud0a4\ub85c \ube7c\ub294 \uac78 \uad8c\ud569\ub2c8\ub2e4.\\n- **HttpOnly \ucfe0\ud0a4\ub9cc \uc4f0\uba74 \uc81c\uc77c \uc548\uc804\ud55c \uac83 \uc544\ub2cc\uac00\uc694?**\\n  - XSS\uc5d0\ub294 \uac15\ud558\uc9c0\ub9cc CSRF\uc5d0 \ub178\ucd9c\ub429\ub2c8\ub2e4. `SameSite`\uc640 CSRF \ud1a0\ud070\uc73c\ub85c \ub9c9\uc544\uc57c \ud558\uace0, \ud06c\uae30 \ud55c\uacc4(4KB)\ub3c4 \uace0\ub824\ud574\uc57c \ud569\ub2c8\ub2e4.\\n- **sessionStorage\ub294\uc694?**\\n  - \ud0ed\ub9c8\ub2e4 \uaca9\ub9ac\ub3fc \ud0ed \uac04 \ub85c\uadf8\uc778 \uacf5\uc720\uac00 \uc548 \ub429\ub2c8\ub2e4. UX\uac00 \ub098\ube60 \uc798 \uc4f0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- OWASP: HTML5 Security / Token Storage Cheat Sheet\\n- MDN: `Set-Cookie`, `SameSite`, Web Storage API"},{"id":"opa-policy-authz","metadata":{"permalink":"/blog/opa-policy-authz","source":"@site/blog/2026-06-19-opa-policy-authz/index.md","title":"OPA\ub85c API \uad8c\ud55c(\uc778\uac00)\uc744 \uc678\ubd80\ud654\ud558\uae30","description":"\uad8c\ud55c \ud310\ub2e8 \ub85c\uc9c1\uc744 \uac01 \uc11c\ube44\uc2a4 \ucf54\ub4dc\uc5d0 \ud769\uc9c0 \uc54a\uace0, \uc815\ucc45 \uc5d4\uc9c4(OPA)\uc73c\ub85c \ube7c\uc11c \ud55c\uacf3\uc5d0\uc11c \uacb0\uc815\ud558\uac8c \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"Security","permalink":"/blog/tags/security"}],"readingTime":1.79,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"OPA\ub85c API \uad8c\ud55c(\uc778\uac00)\uc744 \uc678\ubd80\ud654\ud558\uae30","slug":"opa-policy-authz","authors":["kgenots"],"tags":["Reference","Backend","Security"],"image":"/assets/blog/cover-opa-policy-authz.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"OAuth \ud1a0\ud070, \uc5b4\ub514\uc5d0 \uc800\uc7a5\ud560\uae4c (\ucfe0\ud0a4 vs localStorage)","permalink":"/blog/oauth-bff-token-storage"},"nextItem":{"title":"SPA\ub97c \ud55c \ubc88 \ube4c\ub4dc\ud574 \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ub744\uc6b0\uae30 (\ub7f0\ud0c0\uc784 \uc124\uc815)","permalink":"/blog/spa-runtime-config"}},"content":"\uad8c\ud55c \ud310\ub2e8 \ub85c\uc9c1\uc744 \uac01 \uc11c\ube44\uc2a4 \ucf54\ub4dc\uc5d0 \ud769\uc9c0 \uc54a\uace0, \uc815\ucc45 \uc5d4\uc9c4(OPA)\uc73c\ub85c \ube7c\uc11c \ud55c\uacf3\uc5d0\uc11c \uacb0\uc815\ud558\uac8c \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\\"\uc774 \uc0ac\uc6a9\uc790\uac00 \uc774 \ub3d9\uc791\uc744 \ud574\ub3c4 \ub418\ub098\\"\ub77c\ub294 \ud310\ub2e8\uc744 \ucf54\ub4dc \uacf3\uacf3\uc5d0 \ud769\uc9c0 \uc54a\uace0, \uc815\ucc45 \uc5d4\uc9c4(OPA) \ud55c\uacf3\uc73c\ub85c \ube7c\ub0c5\ub2c8\ub2e4. \uc11c\ube44\uc2a4\ub294 \ubb3b\uae30\ub9cc \ud558\uace0, \ud5c8\uc6a9 \uc5ec\ubd80\ub294 \uc815\ucc45\uc774 \ub2f5\ud569\ub2c8\ub2e4.\\n\\n## \uc778\uc99d\uacfc \uc778\uac00\ub294 \ub2e4\ub974\ub2e4\\n\\n\uc778\uc99d(authentication)\uc740 \\"\ub2f9\uc2e0\uc774 \ub204\uad6c\uc778\uc9c0\\" \ud655\uc778\ud569\ub2c8\ub2e4. \uc778\uac00(authorization)\ub294 \\"\uadf8 \uc0ac\ub78c\uc774 \uc774 \ub3d9\uc791\uc744 \ud574\ub3c4 \ub418\ub294\uc9c0\\" \uacb0\uc815\ud569\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc778\uac00\ub97c \ub2e4\ub8f9\ub2c8\ub2e4.\\n\\n\ud1a0\ud070\uc73c\ub85c \ub85c\uadf8\uc778 \uc0ac\uc6a9\uc790\ub97c \ud655\uc778\ud588\ub354\ub77c\ub3c4(\uc778\uc99d), \uadf8 \uc0ac\ub78c\uc774 \ud2b9\uc815 \uc790\uc6d0\uc744 \uc218\uc815\ud574\ub3c4 \ub418\ub294\uc9c0(\uc778\uac00)\ub294 \ubcc4\uac1c\uc758 \ud310\ub2e8\uc785\ub2c8\ub2e4.\\n\\n## \uad8c\ud55c \uacb0\uc815\uc744 \uc65c \ubc16\uc73c\ub85c \ube7c\ub098\\n\\n\uad8c\ud55c \ud310\ub2e8\uc744 \ucf54\ub4dc\uc5d0 \uc9c1\uc811 \ub123\uc73c\uba74 \uac19\uc740 \uaddc\uce59\uc774 \uc11c\ube44\uc2a4\ub9c8\ub2e4 \uc870\uae08\uc529 \ub2e4\ub974\uac8c \ud769\uc5b4\uc9d1\ub2c8\ub2e4. \uaddc\uce59\uc774 \ubc14\ub00c\uba74 \uc5ec\ub7ec \uacf3\uc744 \ub3d9\uc2dc\uc5d0 \uace0\uccd0\uc57c \ud558\uace0, \uc5b4\ub514\uac00 \uc5b4\ub5a4 \uaddc\uce59\uc744 \uc4f0\ub294\uc9c0 \ud55c\ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n\ubb38\ub9c8\ub2e4 \uacbd\ube44\uc6d0\uc774 \uac01\uc790 \uaddc\uce59\uc744 \uc678\uc6cc \ud310\ub2e8\ud558\ub294 \uac74\ubb3c\uc744 \ub5a0\uc62c\ub824 \ubd05\ub2c8\ub2e4. \uaddc\uce59\uc774 \ubc14\ub00c\uba74 \uacbd\ube44\uc6d0\uc744 \uc804\ubd80 \ub2e4\uc2dc \uad50\uc721\ud574\uc57c \ud569\ub2c8\ub2e4. \ub300\uc2e0 \uc911\uc559 \ud1b5\uc81c\uc2e4 \ud55c \uacf3\uc5d0 \ubb34\uc804\uc73c\ub85c \ubb3c\uc5b4\ubcf4\uac8c \ud558\uba74, \uaddc\uce59\uc740 \ud1b5\uc81c\uc2e4\ub9cc \ubc14\uafb8\uba74 \ub429\ub2c8\ub2e4. OPA\uac00 \uadf8 \ud1b5\uc81c\uc2e4\uc785\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/opa-policy-authz-2.webp\\"\\n    alt=\\"\uad8c\ud55c \uaddc\uce59\uc774 \uc11c\ube44\uc2a4\ub9c8\ub2e4 \ud769\uc5b4\uc9c4 \uacbd\uc6b0\uc640, OPA \ud55c\uacf3\uc73c\ub85c \uc678\ubd80\ud654\ud574 \uac01 \uc11c\ube44\uc2a4\uac00 \ubb3b\uae30\ub9cc \ud558\ub294 \uad6c\uc870 \ube44\uad50\\"\\n  />\\n</figure>\\n\\n## PEP\uc640 PDP, \uc5ed\ud560 \ub098\ub204\uae30\\n\\n\uad8c\ud55c \uc678\ubd80\ud654\ub294 \uc5ed\ud560\uc744 \ub458\ub85c \ub098\ub215\ub2c8\ub2e4.\\n\\n| \uc5ed\ud560 | \ud558\ub294 \uc77c | \uc704\uce58 |\\n| --- | --- | --- |\\n| PEP (\uc815\ucc45 \uc2dc\ud589 \uc9c0\uc810) | \uc694\uccad\uc744 \uac00\ub85c\ucc44 \\"\ubb3c\uc5b4\ubcf4\uace0\\" \uacb0\uacfc\ub97c \uc2dc\ud589 | \uac01 \uc11c\ube44\uc2a4(\ub610\ub294 \uac8c\uc774\ud2b8\uc6e8\uc774) |\\n| PDP (\uc815\ucc45 \uacb0\uc815 \uc9c0\uc810) | \uc815\ucc45\uc744 \ud3c9\uac00\ud574 allow/deny\ub97c \\"\ub2f5\ud568\\" | OPA |\\n\\n\uc11c\ube44\uc2a4(PEP)\ub294 \ud310\ub2e8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc694\uccad \uc815\ubcf4\ub97c \ubaa8\uc544 OPA(PDP)\uc5d0 \ubb3b\uace0, \ub3cc\uc544\uc628 \ub2f5\ub300\ub85c \ud1b5\uacfc\uc2dc\ud0a4\uac70\ub098 \ub9c9\uc2b5\ub2c8\ub2e4.\\n\\n## \uc815\ucc45 \uc791\uc131\uacfc \ud3c9\uac00 (\ubc29\ubc95)\\n\\nOPA\uc758 \uc815\ucc45\uc740 Rego\ub77c\ub294 \uc5b8\uc5b4\ub85c \uc791\uc131\ud569\ub2c8\ub2e4. \\"\uc5b4\ub5a4 \uc785\ub825\uc774\uba74 \ud5c8\uc6a9\uc778\uc9c0\\"\ub97c \uc120\uc5b8\ud569\ub2c8\ub2e4.\\n\\n```rego\\npackage authz\\n\\ndefault allow := false          # \uae30\ubcf8\uc740 \uac70\ubd80 (fail-close)\\n\\nallow if {\\n    input.action == \\"GetUser\\"\\n    input.subject.role == \\"admin\\"\\n}\\n```\\n\\nPEP\ub294 \uc694\uccad\uc5d0\uc11c \uc8fc\uccb4\xb7\ub3d9\uc791\xb7\uc790\uc6d0\uc744 \ubaa8\uc544 OPA\uc5d0 \ud3c9\uac00\ub97c \uc694\uccad\ud569\ub2c8\ub2e4.\\n\\n```python\\n# PEP: \uc694\uccad \uc815\ubcf4\ub97c \ubaa8\uc544 OPA \uc5d0 \uc9c8\uc758\\ndecision = http_post(\\n    \\"http://opa:8181/v1/data/authz/allow\\",\\n    json={\\"input\\": {\\n        \\"subject\\": {\\"id\\": user_id, \\"role\\": role},\\n        \\"action\\": operation_id,     # \uc608: \\"GetUser\\"\\n        \\"resource\\": {\\"type\\": \\"user\\", \\"id\\": target_id},\\n    }},\\n)\\nif not decision[\\"result\\"]:\\n    raise Forbidden()              # deny \uba74 \ucc28\ub2e8\\n```\\n\\n\uc815\ucc45 \ud30c\uc77c\uc740 \ubc88\ub4e4\ub85c \ubb36\uc5b4 OPA\uc5d0 \ubc30\ud3ec\ud569\ub2c8\ub2e4. \uaddc\uce59\uc774 \ubc14\ub00c\uba74 \ucf54\ub4dc\ub294 \uadf8\ub300\ub85c \ub450\uace0 \uc815\ucc45 \ubc88\ub4e4\ub9cc \uac31\uc2e0\ud558\uba74 \ub429\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/opa-policy-authz-3.webp\\"\\n    alt=\\"PEP\uac00 \uc8fc\uccb4\xb7\ub3d9\uc791\xb7\uc790\uc6d0\uc744 \ubaa8\uc544 OPA\uc5d0 \uc9c8\uc758\ud558\uace0, \uc815\ucc45 \ud3c9\uac00 \uacb0\uacfc\uac00 allow\uba74 \ud1b5\uacfc deny\uba74 \ucc28\ub2e8\ub418\ub294 \ud750\ub984\\"\\n  />\\n</figure>\\n\\n## OPA \uc778\uac00 \ub3c4\uc785\uc5d0\uc11c \ud754\ud55c \ud568\uc815\\n\\n- \uc815\ucc45\uacfc \ucf54\ub4dc\uc758 \ub3d9\uae30\ud654: \uc0c8 \uc5d4\ub4dc\ud3ec\uc778\ud2b8(\ub3d9\uc791)\ub97c \ucd94\uac00\ud588\ub294\ub370 \uc815\ucc45\uc5d0 \uadf8 \ub3d9\uc791\uc744 \ube60\ub728\ub9ac\uba74, \uae30\ubcf8 \uac70\ubd80(fail-close)\uc5d0 \uac78\ub824 \ub9c9\ud799\ub2c8\ub2e4. \uc5d4\ub4dc\ud3ec\uc778\ud2b8\ub97c \ucd94\uac00\ud560 \ub54c \uc815\ucc45\uc5d0\ub3c4 \ub3d9\uc791\uc744 \ub4f1\ub85d\ud558\ub294 \uc808\ucc28\ub97c \ud568\uaed8 \ub461\ub2c8\ub2e4.\\n- \uc815\ucc45 \ubc88\ub4e4 \ubc30\ud3ec \ub204\ub77d: \uc815\ucc45\uc744 \uace0\ucce4\ub294\ub370 OPA\uc5d0 \uc0c8 \ubc88\ub4e4\uc774 \uc548 \uc62c\ub77c\uac00\uba74, OPA\ub294 \uc61b \uaddc\uce59\uc73c\ub85c \uacc4\uc18d \ud310\ub2e8\ud569\ub2c8\ub2e4. \ubc30\ud3ec\ud55c \ub4a4 \uc2e4\uc81c\ub85c \uc801\uc6a9\ub410\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.\\n- fail-open vs fail-close: OPA\uac00 \uc751\ub2f5\ud558\uc9c0 \uc54a\uc744 \ub54c \ud1b5\uacfc\uc2dc\ud0ac\uc9c0(open) \ub9c9\uc744\uc9c0(close)\ub97c \uc815\ud574\uc57c \ud569\ub2c8\ub2e4. <span style={{ backgroundColor: \'#ffdce0\'}}>\ubcf4\uc548\uc774 \uc911\uc694\ud558\uba74 \uae30\ubcf8\uc740 \uac70\ubd80(close)</span>\uc785\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **\uad8c\ud55c \uccb4\ud06c\ub97c \uac8c\uc774\ud2b8\uc6e8\uc774\uc5d0 \ub450\ub098\uc694, \uc11c\ube44\uc2a4\uc5d0 \ub450\ub098\uc694?**\\n  - \ub458 \ub2e4 \uac00\ub2a5\ud569\ub2c8\ub2e4. \uac8c\uc774\ud2b8\uc6e8\uc774\uc5d0 PEP\ub97c \ub450\uba74 \uacf5\ud1b5 \ucc98\ub9ac\uac00 \uc27d\uace0, \uc11c\ube44\uc2a4\uc5d0 \ub450\uba74 \uc790\uc6d0 \ub2e8\uc704\uc758 \uc138\ubc00\ud55c \ud310\ub2e8\uc774 \uc27d\uc2b5\ub2c8\ub2e4. \uc790\uc6d0 \uc18c\uc720\uad8c \uac19\uc740 \uc138\ubc00\ud55c \uaddc\uce59\uc740 \uc11c\ube44\uc2a4 \ucabd PEP\uac00 \uc720\ub9ac\ud569\ub2c8\ub2e4.\\n- **OPA \ud638\ucd9c\uc774 \ub9e4 \uc694\uccad\ub9c8\ub2e4\uba74 \ub290\ub9ac\uc9c0 \uc54a\ub098\uc694?**\\n  - OPA\ub97c \uac19\uc740 \ub178\ub4dc(\uc0ac\uc774\ub4dc\uce74)\uc5d0 \ub450\uba74 \ud638\ucd9c \ube44\uc6a9\uc774 \uc791\uc2b5\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \ubd80\ub2f4\ub418\uba74 \uacb0\uc815 \uacb0\uacfc\ub97c \uc9e7\uac8c \uce90\uc2dc\ud569\ub2c8\ub2e4.\\n- **\uaf2d OPA\uc5ec\uc57c \ud558\ub098\uc694?**\\n  - \uc544\ub2c8\uc694. \uad8c\ud55c \uacb0\uc815\uc744 \ucf54\ub4dc \ubc16\uc73c\ub85c \ube7c\uc11c \ud55c\uacf3\uc5d0\uc11c \uad00\ub9ac\ud558\uba74 \ub429\ub2c8\ub2e4. OPA\ub294 \uadf8 \ubc29\uc2dd\uc758 \ud45c\uc900\uc801\uc778 \uad6c\ud604\uc77c \ubfd0\uc785\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- Open Policy Agent (OPA) Docs: Rego / Bundles\\n- NIST: PEP / PDP (\uc815\ucc45 \uc2dc\ud589\xb7\uacb0\uc815 \uc9c0\uc810)"},{"id":"spa-runtime-config","metadata":{"permalink":"/blog/spa-runtime-config","source":"@site/blog/2026-06-19-spa-runtime-config/index.md","title":"SPA\ub97c \ud55c \ubc88 \ube4c\ub4dc\ud574 \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ub744\uc6b0\uae30 (\ub7f0\ud0c0\uc784 \uc124\uc815)","description":"API \uc8fc\uc18c\ucc98\ub7fc \ud658\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \uac12\uc744, \ube4c\ub4dc\uc5d0 \ubc15\uc9c0 \uc54a\uace0 \uc571\uc774 \ucf1c\uc9c8 \ub54c \uc77d\uac8c \ub9cc\ub4e4\uc5b4 \ud55c \ubc88 \ube4c\ub4dc\ub85c \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ubc30\ud3ec\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Frontend","permalink":"/blog/tags/frontend"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"}],"readingTime":1.84,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"SPA\ub97c \ud55c \ubc88 \ube4c\ub4dc\ud574 \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ub744\uc6b0\uae30 (\ub7f0\ud0c0\uc784 \uc124\uc815)","slug":"spa-runtime-config","authors":["kgenots"],"tags":["Reference","Frontend","Ops"],"image":"/assets/blog/cover-spa-runtime-config.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"OPA\ub85c API \uad8c\ud55c(\uc778\uac00)\uc744 \uc678\ubd80\ud654\ud558\uae30","permalink":"/blog/opa-policy-authz"},"nextItem":{"title":"Temporal\ub85c \ubcf4\uc0c1(Saga) \ud2b8\ub79c\uc7ad\uc158 \ub2e4\ub8e8\uae30","permalink":"/blog/temporal-saga-compensation"}},"content":"API \uc8fc\uc18c\ucc98\ub7fc \ud658\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \uac12\uc744, \ube4c\ub4dc\uc5d0 \ubc15\uc9c0 \uc54a\uace0 \uc571\uc774 \ucf1c\uc9c8 \ub54c \uc77d\uac8c \ub9cc\ub4e4\uc5b4 \ud55c \ubc88 \ube4c\ub4dc\ub85c \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ubc30\ud3ec\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ud658\uacbd\uc774 \ud558\ub098 \ub298 \ub54c\ub9c8\ub2e4 \uc571\uc744 \ub2e4\uc2dc \ube4c\ub4dc\ud558\uace0 \uc788\ub2e4\uba74, \ud658\uacbd\ubcc4 \uac12\uc774 \ube4c\ub4dc \uacb0\uacfc\ubb3c \uc548\uc5d0 \ubc15\ud600 \uc788\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4. \uc774\ub7f0 \uac12\uc740 \ube4c\ub4dc\uc5d0 \ubc15\uc9c0 \ub9d0\uace0 \uc571\uc774 \ucf1c\uc9c8 \ub54c \uc77d\ub294 \ub7f0\ud0c0\uc784 \uc124\uc815 \ud30c\uc77c\ub85c \ubd84\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\uadf8\ub7ec\uba74 \uc571\uc740 \ud55c \ubc88\ub9cc \ube4c\ub4dc\ud558\uace0, \uc124\uc815 \ud30c\uc77c\ub9cc \ud658\uacbd\uc5d0 \ub9de\uac8c \uac08\uc544 \ub07c\uc6b0\uba74 \ub429\ub2c8\ub2e4.\\n\\n## \ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785\uacfc \ub7f0\ud0c0\uc784 \uc8fc\uc785, \ubb34\uc5c7\uc774 \ub2e4\ub978\uac00\\n\\n\ucc28\uc774\ub294 \ud658\uacbd\ubcc4 \uac12\uc774 \uc815\ud574\uc9c0\ub294 \uc2dc\uc810\uc785\ub2c8\ub2e4. \ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785\uc740 \ube4c\ub4dc\ud560 \ub54c \uac12\uc744 \ucf54\ub4dc\uc5d0 \ubc15\uc544 \ub123\uace0, \ub7f0\ud0c0\uc784 \uc8fc\uc785\uc740 \uc571\uc774 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ucf1c\uc9c8 \ub54c \uac12\uc744 \uc77d\uc2b5\ub2c8\ub2e4.\\n\\n| \uad6c\ubd84 | \ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785 | \ub7f0\ud0c0\uc784 \uc8fc\uc785 |\\n| --- | --- | --- |\\n| \uac12\uc774 \uc815\ud574\uc9c0\ub294 \uc2dc\uc810 | \ube4c\ub4dc\ud560 \ub54c | \uc571\uc774 \ucf1c\uc9c8 \ub54c |\\n| \ud658\uacbd\uc774 N\uac1c\uba74 | N\ubc88 \ube4c\ub4dc | \ud55c \ubc88 \ube4c\ub4dc + \uc124\uc815 N\uac1c |\\n| \ub300\ud45c \uc608 | `import.meta.env.VITE_*` | `window.__ENV__` |\\n\\n\ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785(`VITE_*`, `REACT_APP_*` \ub4f1)\uc740 \ud3b8\ud558\uc9c0\ub9cc, \uac12\uc774 \uacb0\uacfc\ubb3c\uc5d0 \ubc15\ud600 \ubc84\ub9bd\ub2c8\ub2e4. \ud658\uacbd\uc774 \ub298\uba74 \uadf8\ub9cc\ud07c \ub2e4\uc2dc \ube4c\ub4dc\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n## \uc65c \ub7f0\ud0c0\uc784 \uc124\uc815\uc778\uac00\\n\\n\ub7f0\ud0c0\uc784 \uc124\uc815\uc774 \ud544\uc694\ud55c \uc774\uc720\ub294, \uac19\uc740 \uc571\uc744 \ud658\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \uac12\uc73c\ub85c \ub744\uc6cc\uc57c \ud560 \ub54c \ub9e4\ubc88 \ub2e4\uc2dc \ube4c\ub4dc\ud560 \uc218 \uc5c6\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ud2b9\ud788 \uace0\uac1d\uc0ac\ub9c8\ub2e4 API \uc8fc\uc18c\uac00 \ub2e4\ub978 \uc628\ud504\ub808\ubbf8\uc2a4 \ubc30\ud3ec\uc5d0\uc11c\ub294 \ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785\uc774 \uace7 \ubb34\ub108\uc9d1\ub2c8\ub2e4.\\n\\n\ud55c \ubc88 \uc778\uc1c4\ud55c \uc548\ub0b4 \ucc45\uc790\uc5d0 \ube44\uc720\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubcf8\ubb38(\uc571)\uc740 \ud55c \ubc88\ub9cc \ucc0d\uace0, \ub9c8\uc9c0\ub9c9 \uc8fc\uc18c \ud398\uc774\uc9c0(\uc124\uc815)\ub9cc \ud658\uacbd\ub9c8\ub2e4 \uac08\uc544 \ub07c\uc6c1\ub2c8\ub2e4. \ucc45\uc790\ub97c \ud1b5\uc9f8\ub85c \ub2e4\uc2dc \ucc0d\uc9c0 \uc54a\uc544\ub3c4 \ub429\ub2c8\ub2e4.\\n\\n## \uad6c\ud604 \ubc29\ubc95\\n\\n\ube4c\ub4dc \uacb0\uacfc\ubb3c \ubc14\uae65\uc5d0 \uc124\uc815 \ud30c\uc77c\uc744 \ub530\ub85c \ub450\uace0, \uc571\uc774 \uc2dc\uc791\ud560 \ub54c \uadf8 \ud30c\uc77c\uc744 \uc77d\uac8c \ud569\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/spa-runtime-config-2.webp\\"\\n    alt=\\"\ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785\uc740 \ud658\uacbd\ub9c8\ub2e4 \ub2e4\uc2dc \ube4c\ub4dc\ud558\uace0, \ub7f0\ud0c0\uc784 \uc8fc\uc785\uc740 \ud55c \ubc88 \ube4c\ub4dc\ud55c \ub4a4 \ud658\uacbd\ubcc4 \uc124\uc815 \ud30c\uc77c\ub9cc \uac08\uc544 \ub07c\uc6b0\ub294 \ube44\uad50\\"\\n  />\\n</figure>\\n\\n### 1. \uc124\uc815 \ud30c\uc77c\uc744 \ub530\ub85c \ub454\ub2e4\\n\\n\ube4c\ub4dc\uc5d0 \ud3ec\ud568\ud558\uc9c0 \uc54a\ub294 `env-config.js`\ub97c \ub9cc\ub4e4\uc5b4 \uc804\uc5ed \uac1d\uccb4\uc5d0 \uac12\uc744 \uc2e3\uc2b5\ub2c8\ub2e4.\\n\\n```js\\n// env-config.js  (\ube4c\ub4dc \uc0b0\ucd9c\ubb3c\uc774 \uc544\ub2c8\ub77c \ubc30\ud3ec \uc2dc \uac08\uc544 \ub07c\uc6b0\ub294 \ud30c\uc77c)\\nwindow.__ENV__ = {\\n  API_BASE_URL: \\"https://api.example.com\\",\\n};\\n```\\n\\n### 2. index.html\uc5d0\uc11c \uba3c\uc800 \uc77d\ub294\ub2e4\\n\\n\uc571 \ubc88\ub4e4\ubcf4\ub2e4 \uba3c\uc800 \uc124\uc815 \ud30c\uc77c\uc744 \ub85c\ub4dc\ud569\ub2c8\ub2e4.\\n\\n```html\\n<script src=\\"/env-config.js\\"><\/script>\\n<script type=\\"module\\" src=\\"/assets/index.js\\"><\/script>\\n```\\n\\n### 3. \ucf54\ub4dc\uc5d0\uc11c \uc0ac\uc6a9\ud55c\ub2e4\\n\\n```ts\\nconst API_BASE_URL =\\n  window.__ENV__?.API_BASE_URL ?? \\"http://localhost:8080\\"; // \ub85c\uceec \uae30\ubcf8\uac12\\n```\\n\\n### 4. \ud658\uacbd\ub9c8\ub2e4 \uc124\uc815 \ud30c\uc77c\ub9cc \uad50\uccb4\\n\\n\ubc30\ud3ec \ud658\uacbd\uc5d0\uc11c `env-config.js`\ub9cc \uadf8 \ud658\uacbd \uac12\uc73c\ub85c \ubc14\uafc9\ub2c8\ub2e4. \ucfe0\ubc84\ub124\ud2f0\uc2a4\ub77c\uba74 ConfigMap\uc744 \ubcfc\ub968\uc73c\ub85c \ub9c8\uc6b4\ud2b8\ud574 \uc774 \ud30c\uc77c\uc744 \ub36e\uc5b4\uc501\ub2c8\ub2e4. \uc571 \ubc88\ub4e4\uc740 \uadf8\ub300\ub85c \ub461\ub2c8\ub2e4.\\n\\n## \ud754\ud55c \ud568\uc815 (CDN \uce90\uc2dc)\\n\\n\uac00\uc7a5 \uc790\uc8fc \ub370\uc774\ub294 \ud568\uc815\uc740 CDN \uce90\uc2dc\uc785\ub2c8\ub2e4. \ud654\uba74 \ud30c\uc77c\uc740 \ube60\ub978 \uc751\ub2f5\uc744 \uc704\ud574 CDN\uc5d0 \uce90\uc2dc\ub418\ub294\ub370, <span style={{ backgroundColor: \'#ffdce0\'}}>\uc124\uc815 \ud30c\uc77c\uae4c\uc9c0 \uce90\uc2dc\ub418\uba74 \uac12\uc744 \ubc14\uafd4\ub3c4 \uc61b \uc124\uc815\uc774 \uacc4\uc18d \ub0b4\ub824\uac11\ub2c8\ub2e4.</span>\\n\\n\uc124\uc815 \ud30c\uc77c\uc5d0\ub9cc \uce90\uc2dc\ub97c \ub044\uba74 \ud574\uacb0\ub429\ub2c8\ub2e4.\\n\\n```text\\nCache-Control: no-store      # env-config.js \uc5d0\ub9cc \uc801\uc6a9\\n```\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/spa-runtime-config-3.webp\\"\\n    alt=\\"CDN\uc774 \uc124\uc815 \ud30c\uc77c\uae4c\uc9c0 \uce90\uc2dc\ud574 \uc61b \uac12\uc774 \ub0b4\ub824\uac00\ub294 \ubb38\uc81c\uc640, \uc124\uc815 \ud30c\uc77c\uc5d0\ub9cc no-store\ub97c \uc801\uc6a9\ud55c \ud574\uacb0\\"\\n  />\\n</figure>\\n\\n\uadf8 \uc678 \uc8fc\uc758\uc810:\\n\\n- \ube4c\ub4dc\ud0c0\uc784\uacfc \ub7f0\ud0c0\uc784\uc744 \uc11e\uc9c0 \uc54a\uae30: `import.meta.env`\uc640 `window.__ENV__`\ub97c \ud55c \uac12\uc5d0 \uc11e\uc73c\uba74 \uc5b4\ub290 \ucabd\uc774 \uc801\uc6a9\ub410\ub294\uc9c0 \ud5f7\uac08\ub9bd\ub2c8\ub2e4. \ud658\uacbd\ubcc4 \uac12\uc740 \ub7f0\ud0c0\uc784\uc73c\ub85c \uc77c\uc6d0\ud654\ud569\ub2c8\ub2e4.\\n- \ub85c\uceec \uae30\ubcf8\uac12 \ub450\uae30: \uc124\uc815 \ud30c\uc77c\uc774 \uc5c6\uc744 \ub54c\ub97c \ub300\ube44\ud574 \ucf54\ub4dc\uc5d0 \uc548\uc804\ud55c \uae30\ubcf8\uac12(`?? localhost`)\uc744 \ub461\ub2c8\ub2e4.\\n- \ubbfc\uac10 \uc815\ubcf4 \uae08\uc9c0: `env-config.js`\ub294 \ube0c\ub77c\uc6b0\uc800\uac00 \uadf8\ub300\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \ube44\ubc00 \ud0a4 \uac19\uc740 \ubbfc\uac10 \uac12\uc740 \uc808\ub300 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **Next.js \uac19\uc740 SSR\ub3c4 \uac19\uc740 \ubc29\ubc95\uc778\uac00\uc694?**\\n  - SSR\uc740 \uc11c\ubc84\uc5d0\uc11c \ud658\uacbd \ubcc0\uc218\ub97c \uc9c1\uc811 \uc77d\uc744 \uc218 \uc788\uc5b4 \uc0ac\uc815\uc774 \ub2e4\ub985\ub2c8\ub2e4. \uc774 \ubc29\ubc95\uc740 \uc815\uc801\uc73c\ub85c \ube4c\ub4dc\ub418\ub294 SPA(CSR)\uc5d0\uc11c \ud2b9\ud788 \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n- **`.env` \ud30c\uc77c\uc744 \uc5ec\ub7ec \uac1c \ub450\uba74 \uc548 \ub418\ub098\uc694?**\\n  - `.env.production` \ub4f1\uc740 \uacb0\uad6d \ube4c\ub4dc\ud0c0\uc784\uc5d0 \ubc15\ud799\ub2c8\ub2e4. \ud658\uacbd\uc774 \ube4c\ub4dc \ud6c4\uc5d0 \uc815\ud574\uc9c0\ub294 \uacbd\uc6b0(\uc628\ud504\ub808\ubbf8\uc2a4 \ub4f1)\uc5d0\ub294 \ub7f0\ud0c0\uc784 \uc124\uc815\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n- **\uc124\uc815 \uac12\uc774 \ub9ce\uc544\uc9c0\uba74\uc694?**\\n  - `window.__ENV__` \uac1d\uccb4\uc5d0 \ubaa8\uc74d\ub2c8\ub2e4. \ud0c0\uc785 \uc548\uc804\uc744 \uc704\ud574 \ud55c \uacf3\uc5d0\uc11c \uc77d\uc5b4 \uac80\uc99d\ud55c \ub4a4 \uc571 \uc804\uc5ed\uc5d0 \uc81c\uacf5\ud558\ub294 \ub798\ud37c\ub97c \ub450\uba74 \uc88b\uc2b5\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- MDN: `Cache-Control`\\n- 12-Factor App: Config"},{"id":"temporal-saga-compensation","metadata":{"permalink":"/blog/temporal-saga-compensation","source":"@site/blog/2026-06-19-temporal-saga-compensation/index.md","title":"Temporal\ub85c \ubcf4\uc0c1(Saga) \ud2b8\ub79c\uc7ad\uc158 \ub2e4\ub8e8\uae30","description":"\uc5ec\ub7ec \uc11c\ube44\uc2a4\uc5d0 \uac78\uce5c \uc791\uc5c5\uc744 \ud558\ub098\uc758 \ud2b8\ub79c\uc7ad\uc158\uc73c\ub85c \ubb36\uc744 \uc218 \uc5c6\uc744 \ub54c, \ubcf4\uc0c1(Saga) \ud328\ud134\uacfc Temporal \uc6cc\ud06c\ud50c\ub85c\uc6b0\ub85c \uc548\uc804\ud558\uac8c \ub418\ub3cc\ub9ac\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"Temporal","permalink":"/blog/tags/temporal"}],"readingTime":1.76,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Temporal\ub85c \ubcf4\uc0c1(Saga) \ud2b8\ub79c\uc7ad\uc158 \ub2e4\ub8e8\uae30","slug":"temporal-saga-compensation","authors":["kgenots"],"tags":["Reference","Backend","Temporal"],"image":"/assets/blog/cover-temporal-saga-compensation.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"SPA\ub97c \ud55c \ubc88 \ube4c\ub4dc\ud574 \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ub744\uc6b0\uae30 (\ub7f0\ud0c0\uc784 \uc124\uc815)","permalink":"/blog/spa-runtime-config"},"nextItem":{"title":"TSID vs UUID, \uc815\ub82c \uac00\ub2a5\ud55c ID \ub9cc\ub4e4\uae30","permalink":"/blog/tsid-vs-uuid"}},"content":"\uc5ec\ub7ec \uc11c\ube44\uc2a4\uc5d0 \uac78\uce5c \uc791\uc5c5\uc744 \ud558\ub098\uc758 \ud2b8\ub79c\uc7ad\uc158\uc73c\ub85c \ubb36\uc744 \uc218 \uc5c6\uc744 \ub54c, \ubcf4\uc0c1(Saga) \ud328\ud134\uacfc Temporal \uc6cc\ud06c\ud50c\ub85c\uc6b0\ub85c \uc548\uc804\ud558\uac8c \ub418\ub3cc\ub9ac\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\uc5ec\ub7ec \uc11c\ube44\uc2a4\uc5d0 \uac78\uce5c \uc791\uc5c5\uc5d0\ub294 \ud55c \ubc88\uc5d0 \ub418\ub3cc\ub9b4 \uacf5\ud1b5 \ub864\ubc31\uc774 \uc5c6\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub2e8\uacc4\ub9c8\ub2e4 \\"\ub418\ub3cc\ub9ac\uae30(\ubcf4\uc0c1)\\"\ub97c \uc9dd\uc9c0\uc5b4 \ub450\uace0, \uc2e4\ud328\ud558\uba74 \uc131\uacf5\ud55c \ub2e8\uacc4\ub97c \uc5ed\uc21c\uc73c\ub85c \ucde8\uc18c\ud569\ub2c8\ub2e4.\\n\\n\uc774 \uc21c\uc11c\ub97c \uc190\uc73c\ub85c \ucd94\uc801\ud558\ub294 \ub300\uc2e0 \uc6cc\ud06c\ud50c\ub85c\uc6b0 \uc5d4\uc9c4(Temporal)\uc5d0 \ub9e1\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ubd84\uc0b0 \ud2b8\ub79c\uc7ad\uc158\uc774 \uc65c \uc5b4\ub824\uc6b4\uac00\\n\\n\ubd84\uc0b0 \ud2b8\ub79c\uc7ad\uc158\uc774 \uc5b4\ub824\uc6b4 \uc774\uc720\ub294, \uc5ec\ub7ec \uc11c\ube44\uc2a4(\ub610\ub294 \uc678\ubd80 \uc2dc\uc2a4\ud15c)\uc5d0 \uac78\uce5c \uc791\uc5c5\uc744 \ud558\ub098\uc758 DB \ud2b8\ub79c\uc7ad\uc158\uc73c\ub85c \ubb36\uc744 \uc218 \uc5c6\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ud55c DB \uc548\uc758 \uc791\uc5c5\uc740 `COMMIT`/`ROLLBACK`\uc73c\ub85c \uc804\ubd80 \uc131\uacf5 \ub610\ub294 \uc804\ubd80 \ucde8\uc18c\uac00 \ub418\uc9c0\ub9cc, \uacb0\uc81c \uc11c\ube44\uc2a4\uc640 \uc7ac\uace0 \uc11c\ube44\uc2a4\uac00 \ub530\ub85c \uc788\uc73c\uba74 \uadf8\ub7f0 \uacf5\ud1b5 \ub864\ubc31\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uc608\ub97c \ub4e4\uc5b4 \\"\uacb0\uc81c \u2192 \uc7ac\uace0 \ucc28\uac10 \u2192 \ubc30\uc1a1 \ub4f1\ub85d\\"\uc5d0\uc11c \uacb0\uc81c\ub294 \ub410\ub294\ub370 \uc7ac\uace0 \ucc28\uac10\uc774 \uc2e4\ud328\ud558\uba74, \uc774\ubbf8 \ub098\uac04 \uacb0\uc81c\ub97c \ub530\ub85c \ub418\ub3cc\ub824(\ud658\ubd88) \uc918\uc57c \ud569\ub2c8\ub2e4. \uc544\ubb34\ub3c4 \ub300\uc2e0 \ub418\ub3cc\ub824 \uc8fc\uc9c0 \uc54a\uc73c\ub2c8 \uc9c1\uc811 \ub418\ub3cc\ub9bd\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/temporal-saga-compensation-2.webp\\"\\n    alt=\\"\ud55c DB \ud2b8\ub79c\uc7ad\uc158\uacfc \ub2ec\ub9ac \uc5ec\ub7ec \uc11c\ube44\uc2a4\uc5d0 \uac78\uce5c \uc791\uc5c5\uc740 \uacf5\ud1b5 \ub864\ubc31\uc774 \uc5c6\uc5b4 \ubcf4\uc0c1\uc73c\ub85c \uc9c1\uc811 \ub418\ub3cc\ub824\uc57c \ud55c\ub2e4\\"\\n  />\\n</figure>\\n\\n## Saga \ud328\ud134\uc774\ub780\\n\\nSaga \ud328\ud134\uc740 \uc5ec\ub7ec \ub2e8\uacc4\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc791\uc5c5\uc744, \uac01 \ub2e8\uacc4\uc640 \uadf8 \ub2e8\uacc4\ub97c \ub418\ub3cc\ub9ac\ub294 **\ubcf4\uc0c1(compensation) \ub3d9\uc791**\uc744 \uc9dd\uc9c0\uc5b4 \uad00\ub9ac\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \uc804\uccb4\ub97c \ud55c \ubc88\uc5d0 \ub864\ubc31\ud558\ub294 \ub300\uc2e0, \uc131\uacf5\ud55c \ub2e8\uacc4\ub9cc \uac70\uafb8\ub85c \ucde8\uc18c\ud569\ub2c8\ub2e4.\\n\\n\ud638\ud154\xb7\ud56d\uacf5\xb7\ub80c\ud130\uce74\ub97c \ubb36\uc5b4 \uc608\uc57d\ud558\ub294 \uc0c1\ud669\uc5d0 \ube44\uc720\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub80c\ud130\uce74 \uc608\uc57d\uc5d0\uc11c \uc2e4\ud328\ud558\uba74 \uc774\ubbf8 \uc7a1\uc544 \ub454 \ud56d\uacf5\uacfc \ud638\ud154 \uc608\uc57d\uc744 \ucde8\uc18c\ud574\uc57c \ud569\ub2c8\ub2e4. \uc774 \\"\ucde8\uc18c\\"\uac00 \ubcf4\uc0c1 \ub3d9\uc791\uc785\ub2c8\ub2e4.\\n\\n## \ubcf4\uc0c1\uc740 \uc5ed\uc21c\uc73c\ub85c\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/temporal-saga-compensation.webp\\"\\n    alt=\\"\uc5ec\ub7ec \ub2e8\uacc4 \uc791\uc5c5 \uc911 \uc2e4\ud328 \uc2dc \ubcf4\uc0c1 \ub2e8\uacc4\ub97c \uc5ed\uc21c\uc73c\ub85c \uc2e4\ud589\ud558\ub294 Saga \ud328\ud134\\"\\n  />\\n</figure>\\n\\n\ubcf4\uc0c1\uc740 \uc131\uacf5\ud55c \ub2e8\uacc4\uc758 \uc5ed\uc21c\uc73c\ub85c \uc2e4\ud589\ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \uc131\uacf5\ud55c \ub2e8\uacc4\ubd80\ud130 \uac70\uafb8\ub85c \ub418\ub3cc\ub824\uc57c \ub2e8\uacc4 \uc0ac\uc774\uc758 \uc758\uc874 \uad00\uacc4\uac00 \uae68\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n```text\\n\uc815\ubc29\ud5a5:  \uacb0\uc81c  \u2192  \uc7ac\uace0 \ucc28\uac10  \u2192  \ubc30\uc1a1 \ub4f1\ub85d(\uc2e4\ud328)\\n\ubcf4\uc0c1:    \uc7ac\uace0 \ubcf5\uad6c  \u2190  \uacb0\uc81c \ud658\ubd88        (\uc5ed\uc21c\uc73c\ub85c \ucde8\uc18c)\\n```\\n\\n## Temporal\ub85c \uad6c\ud604\ud558\uae30\\n\\nTemporal\uc5d0\uc11c\ub294 \uc131\uacf5\ud55c \ub2e8\uacc4\uc758 \ubcf4\uc0c1 \ub3d9\uc791\uc744 \ub9ac\uc2a4\ud2b8\uc5d0 \uc313\uc544 \ub450\uace0, \uc2e4\ud328 \uc2dc \uc5ed\uc21c\uc73c\ub85c \uc2e4\ud589\ud569\ub2c8\ub2e4.\\n\\n```python\\nfrom temporalio import workflow\\n\\n@workflow.defn\\nclass OrderWorkflow:\\n    @workflow.run\\n    async def run(self, order) -> None:\\n        compensations = []\\n        try:\\n            await workflow.execute_activity(charge_payment, order, ...)\\n            compensations.append(refund_payment)        # \uacb0\uc81c\uc758 \ubcf4\uc0c1\\n\\n            await workflow.execute_activity(reserve_inventory, order, ...)\\n            compensations.append(release_inventory)     # \uc7ac\uace0\uc758 \ubcf4\uc0c1\\n\\n            await workflow.execute_activity(register_shipping, order, ...)\\n        except Exception:\\n            # \uc131\uacf5\ud55c \ub2e8\uacc4\ub9cc \uc5ed\uc21c\uc73c\ub85c \ub418\ub3cc\ub9bc\\n            for compensate in reversed(compensations):\\n                await workflow.execute_activity(compensate, order, ...)\\n            raise\\n```\\n\\n\ud55c \ub2e8\uacc4\uac00 \uc131\uacf5\ud55c \uc9c1\ud6c4\uc5d0 \uadf8 \ubcf4\uc0c1\uc744 \ub4f1\ub85d\ud574 \ub450\uace0, \uc2e4\ud328\ud558\uba74 \uc313\uc778 \ubcf4\uc0c1\uc744 \uc5ed\uc21c\uc73c\ub85c \uc2e4\ud589\ud569\ub2c8\ub2e4.\\n\\n\\"\uc5b4\ub514\uae4c\uc9c0 \uc9c4\ud589\ub410\ub294\uc9c0\\"\ub294 Temporal\uc774 \uae30\uc5b5\ud558\ubbc0\ub85c, \uc11c\ubc84\uac00 \uc911\uac04\uc5d0 \uc8fd\uc5b4\ub3c4 \uba48\ucd98 \uc9c0\uc810\ubd80\ud130 \uc774\uc5b4\uc9d1\ub2c8\ub2e4.\\n\\n## \ud754\ud55c \ud568\uc815 (\ubcf4\uc0c1 \ub204\ub77d\uacfc \uba71\ub4f1\uc131)\\n\\n- \ubcf4\uc0c1 \ub2e8\uacc4\ub97c \ube60\ub728\ub9bc: \uc815\ubc29\ud5a5\ub9cc \uc9dc\uace0 \ubcf4\uc0c1\uc744 \uc548 \ub9cc\ub4e4\uba74, \uc2e4\ud328 \uc2dc \uacb0\uc81c\ub9cc \ub418\uace0 \uc7ac\uace0\ub294 \uc548 \uc7a1\ud78c \uc0c1\ud0dc\uac00 \ub0a8\uc2b5\ub2c8\ub2e4. \ub2e8\uacc4\ub9c8\ub2e4 \ubcf4\uc0c1\uc744 \uc9dd\uc73c\ub85c \ub461\ub2c8\ub2e4.\\n- \ubcf4\uc0c1\uc5d0 \uba71\ub4f1\uc131\uc774 \uc5c6\uc74c: \uc7ac\uc2dc\ub3c4 \ub54c\ubb38\uc5d0 \ubcf4\uc0c1\uc774 \ub450 \ubc88 \uc2e4\ud589\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. <span style={{ backgroundColor: \'#ffdce0\'}}>\\"\uc774\ubbf8 \ud658\ubd88\ub428\\"\uc774\uba74 \ub610 \ud658\ubd88\ud558\uc9c0 \uc54a\ub3c4\ub85d</span> \uba71\ub4f1\ud558\uac8c \ub9cc\ub4ed\ub2c8\ub2e4.\\n- \ubcf4\uc0c1\ub3c4 \uc2e4\ud328\ud560 \uc218 \uc788\uc74c: \ud658\ubd88 API\uac00 \uc8fd\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ubcf4\uc0c1 \ud65c\ub3d9(activity)\uc5d0\ub3c4 \uc7ac\uc2dc\ub3c4 \uc815\ucc45\uc744 \ub450\uace0, \ub05d\ub0b4 \uc2e4\ud328\ud558\uba74 \uc0ac\ub78c\uc774 \ucc98\ub9ac\ud558\ub3c4\ub85d \uc54c\ub9bd\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **Saga\uc640 2\ub2e8\uacc4 \ucee4\ubc0b(2PC)\uc740 \ubb34\uc5c7\uc774 \ub2e4\ub978\uac00\uc694?**\\n  - 2PC\ub294 \ubaa8\ub4e0 \ucc38\uac00\uc790\ub97c \uc7a0\uadf8\uace0 \ud55c \ubc88\uc5d0 \ucee4\ubc0b\ud569\ub2c8\ub2e4. Saga\ub294 \uc7a0\uadf8\uc9c0 \uc54a\uace0 \ub2e8\uacc4\ubcc4\ub85c \uc9c4\ud589\ud55c \ub4a4, \uc2e4\ud328 \uc2dc \ubcf4\uc0c1\uc73c\ub85c \ub418\ub3cc\ub9bd\ub2c8\ub2e4. \uc11c\ube44\uc2a4\uac00 \ubd84\ub9ac\ub41c \ud658\uacbd\uc5d0\uc11c\ub294 \ubcf4\ud1b5 Saga\uac00 \ud604\uc2e4\uc801\uc785\ub2c8\ub2e4.\\n- **\uaf2d Temporal\uc774\uc5b4\uc57c \ud558\ub098\uc694?**\\n  - \uc544\ub2c8\uc694. \uba54\uc2dc\uc9c0 \ud050\ub85c\ub3c4 Saga\ub97c \uad6c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \\"\uc5b4\ub514\uae4c\uc9c0 \uc9c4\ud589\ub410\ub098\\"\uc640 \uc7ac\uc2dc\ub3c4\xb7\ud0c0\uc784\uc544\uc6c3\uc744 \uc9c1\uc811 \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4. Temporal\uc740 \uadf8 \uc0c1\ud0dc \uad00\ub9ac\ub97c \ub300\uc2e0 \ud574 \uc90d\ub2c8\ub2e4.\\n- **\ubcf4\uc0c1 \uc911\uc5d0 \ub610 \uc2e4\ud328\ud558\uba74\uc694?**\\n  - \ubcf4\uc0c1\ub3c4 \uc7ac\uc2dc\ub3c4 \ub300\uc0c1\uc785\ub2c8\ub2e4. \uc790\ub3d9 \uc7ac\uc2dc\ub3c4\ub85c\ub3c4 \uc548 \ub418\uba74 \uc54c\ub9bc\uc744 \ub744\uc6cc \uc218\ub3d9 \uac1c\uc785\uc73c\ub85c \ub118\uae41\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- Temporal Docs: Workflows / Activities / Saga\\n- Microservices.io: Saga pattern"},{"id":"tsid-vs-uuid","metadata":{"permalink":"/blog/tsid-vs-uuid","source":"@site/blog/2026-06-19-tsid-vs-uuid/index.md","title":"TSID vs UUID, \uc815\ub82c \uac00\ub2a5\ud55c ID \ub9cc\ub4e4\uae30","description":"\uae30\ubcf8\ud0a4\ub85c \ud754\ud788 \uc4f0\ub294 UUID\uac00 \uc65c DB \uc778\ub371\uc2a4\uc5d0 \ubd88\ub9ac\ud55c\uc9c0, \uadf8\ub9ac\uace0 \uc2dc\uac04\uc21c\uc73c\ub85c \uc815\ub82c\ub418\ub294 TSID\ub85c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"DB","permalink":"/blog/tags/db"}],"readingTime":1.74,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"TSID vs UUID, \uc815\ub82c \uac00\ub2a5\ud55c ID \ub9cc\ub4e4\uae30","slug":"tsid-vs-uuid","authors":["kgenots"],"tags":["Reference","Backend","DB"],"image":"/assets/blog/cover-tsid-vs-uuid.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Temporal\ub85c \ubcf4\uc0c1(Saga) \ud2b8\ub79c\uc7ad\uc158 \ub2e4\ub8e8\uae30","permalink":"/blog/temporal-saga-compensation"},"nextItem":{"title":"6\uac1c\uc6d4\uc744 \ub3cc\uc544\ubcf4\uba70, \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74","permalink":"/blog/six-months-in-retrospect"}},"content":"\uae30\ubcf8\ud0a4\ub85c \ud754\ud788 \uc4f0\ub294 UUID\uac00 \uc65c DB \uc778\ub371\uc2a4\uc5d0 \ubd88\ub9ac\ud55c\uc9c0, \uadf8\ub9ac\uace0 \uc2dc\uac04\uc21c\uc73c\ub85c \uc815\ub82c\ub418\ub294 TSID\ub85c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\uc2dc\uac04\uc21c \uc815\ub82c\uacfc \uc778\ub371\uc2a4 \uc131\ub2a5\uc774 \ud544\uc694\ud558\uba74 TSID(\ub610\ub294 UUIDv7)\ub97c, \ub2e8\uc21c \uace0\uc720\uc131\ub9cc \ud544\uc694\ud558\uba74 UUIDv4\ub97c \uc501\ub2c8\ub2e4. \uac08\ub9ac\ub294 \uc9c0\uc810\uc740 DB \uc778\ub371\uc2a4\uc785\ub2c8\ub2e4. \ubb34\uc791\uc704 \uac12\uc740 \uc778\ub371\uc2a4 \uc5ec\uae30\uc800\uae30\uc5d0 \ub07c\uc5b4\ub4e4\uace0, \uc2dc\uac04\uc21c \uac12\uc740 \ub05d\uc5d0\ub9cc \ubd99\uc2b5\ub2c8\ub2e4.\\n\\n## TSID\uc640 UUID, \ubb34\uc5c7\uc774 \ub2e4\ub978\uac00\\n\\nTSID(Time-Sorted ID)\ub294 \uc0dd\uc131 \uc2dc\uac01\uc744 \uc55e\ubd80\ubd84\uc5d0 \ub2f4\uc740 64\ube44\ud2b8 \uc815\uc218 ID\ub85c, \ub9cc\ub4e0 \uc21c\uc11c\ub300\ub85c \uac12\uc774 \ucee4\uc9d1\ub2c8\ub2e4. \ubc18\uba74 UUIDv4\ub294 128\ube44\ud2b8 \ubb34\uc791\uc704 \uac12\uc774\ub77c \uc21c\uc11c \uc815\ubcf4\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\ub3c4\uc11c\uad00 \ucc45 \ubc88\ud638\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc27d\uc2b5\ub2c8\ub2e4. UUIDv4\ub294 \ucc45\ub9c8\ub2e4 \ubb34\uc791\uc704 \ubc88\ud638\ub97c \ubd99\uc774\uace0, TSID\ub294 \ub4e4\uc5b4\uc628 \uc21c\uc11c\ub300\ub85c \ubc88\ud638\ub97c \ubd99\uc785\ub2c8\ub2e4. \ub4a4\ucabd\uc774 \uc815\ub82c\ub3c4, \\"\ucd5c\uadfc\uc5d0 \ub4e4\uc5b4\uc628 \ucc45 \ucc3e\uae30\\"\ub3c4 \uc27d\uc2b5\ub2c8\ub2e4.\\n\\n## \uc65c \uc815\ub82c \uac00\ub2a5\ud55c ID\uac00 \uc911\uc694\ud55c\uac00\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/tsid-vs-uuid.webp\\"\\n    alt=\\"\ubb34\uc791\uc704 UUID\uc640 \uc2dc\uac04\uc21c \uc815\ub82c\ub418\ub294 TSID\uc758 \uc778\ub371\uc2a4 \uc0bd\uc785 \ucc28\uc774 \ube44\uad50\\"\\n  />\\n</figure>\\n\\n\uc815\ub82c \uac00\ub2a5\ud55c ID\uac00 \uc911\uc694\ud55c \uc774\uc720\ub294 DB \uae30\ubcf8\ud0a4 \uc778\ub371\uc2a4(B-tree) \ub54c\ubb38\uc785\ub2c8\ub2e4. \uc778\ub371\uc2a4\ub294 \uac12\uc744 \uc815\ub82c\ub41c \uc21c\uc11c\ub85c \uc800\uc7a5\ud558\ub294\ub370, \ubb34\uc791\uc704 UUID\ub294 \ub9e4\ubc88 \uc778\ub371\uc2a4 \uc911\uac04 \uc544\ubb34 \uacf3\uc5d0\ub098 \ub07c\uc5b4\ub4ed\ub2c8\ub2e4. \uc774\ub7ec\uba74 \ud398\uc774\uc9c0 \ubd84\ud560(page split)\uacfc \uce90\uc2dc \ubbf8\uc2a4\uac00 \uc7a6\uc544\uc838 \uc4f0\uae30 \uc131\ub2a5\uc774 \ub5a8\uc5b4\uc9d1\ub2c8\ub2e4.\\n\\nTSID\ucc98\ub7fc \uac12\uc774 \uc2dc\uac04\uc21c\uc73c\ub85c \ucee4\uc9c0\uba74, \uc0c8 \uac12\uc740 \ud56d\uc0c1 \uc778\ub371\uc2a4 \ub05d\uc5d0 \ucc28\uace1\ucc28\uace1 \ubd99\uc2b5\ub2c8\ub2e4. \uc0bd\uc785\uc774 \uac00\ubccd\uace0 \uce90\uc2dc \uc801\uc911\ub960\ub3c4 \ub192\uc2b5\ub2c8\ub2e4. \\"\ucd5c\uadfc \uc0dd\uc131\uc21c \uc815\ub82c\\"\ub3c4 `ORDER BY id`\ub9cc\uc73c\ub85c \ub429\ub2c8\ub2e4(\ubcc4\ub3c4 `created_at` \uc815\ub82c \ubd88\ud544\uc694).\\n\\n## ID \uc0dd\uc131 \ubc29\uc2dd \ube44\uad50\\n\\n| \ubc29\uc2dd | \uc815\ub82c \uac00\ub2a5 | \ud06c\uae30 | \ubd84\uc0b0 \uc0dd\uc131 | \ube44\uace0 |\\n| --- | --- | --- | --- | --- |\\n| auto-increment | \u2705 | \uc791\uc74c | \u274c (DB \uc758\uc874) | \uc5ec\ub7ec \ub178\ub4dc\uc5d0\uc11c \ucda9\ub3cc\xb7\uacbd\ud569 |\\n| UUIDv4 | \u274c \ubb34\uc791\uc704 | 128\ube44\ud2b8 | \u2705 | \uace0\uc720\ud558\uc9c0\ub9cc \uc778\ub371\uc2a4\uc5d0 \ubd88\ub9ac |\\n| TSID / Snowflake | \u2705 \uc2dc\uac04\uc21c | 64\ube44\ud2b8 | \u2705 | \uc791\uace0 \uc815\ub82c\ub428 |\\n| UUIDv7 | \u2705 \uc2dc\uac04\uc21c | 128\ube44\ud2b8 | \u2705 | UUID \ud638\ud658 + \uc815\ub82c |\\n\\n64\ube44\ud2b8\uba74 \ucda9\ubd84\ud558\uace0 \uc791\uc740 \ud0a4\ub97c \uc6d0\ud558\uba74 TSID, \ud45c\uc900 UUID \ud615\uc2dd\uc744 \uc720\uc9c0\ud558\uba74\uc11c \uc815\ub82c\ub3c4 \uc6d0\ud558\uba74 UUIDv7\uc774 \uc88b\uc740 \uc120\ud0dd\uc785\ub2c8\ub2e4.\\n\\n## TSID \uc0ac\uc6a9 \ubc29\ubc95\\n\\nTSID\ub294 \uc0dd\uc131\uacfc \uc800\uc7a5\uc774 \ub2e8\uc21c\ud569\ub2c8\ub2e4. 64\ube44\ud2b8 \uc815\uc218\uc774\ubbc0\ub85c DB\uc5d0\ub294 `BIGINT`\ub85c \ub461\ub2c8\ub2e4.\\n\\n```python\\nfrom tsidpy import TSID\\n\\nnew_id = TSID.create().number   # 64\ube44\ud2b8 \uc815\uc218, \uc2dc\uac04\uc21c \uc815\ub82c\\n```\\n\\n```python\\n# SQLAlchemy \uc608\uc2dc (BIGINT \uceec\ub7fc)\\nid: Mapped[int] = mapped_column(\\n    BigInteger,\\n    primary_key=True,\\n    default=lambda: TSID.create().number,\\n)\\n```\\n\\n## \ud754\ud55c \ud568\uc815 (\uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8 \uc815\ubc00\ub3c4)\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/tsid-vs-uuid-2.webp\\"\\n    alt=\\"TSID\ub294 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8 \uc548\uc804 \uc815\uc218 \ud55c\uacc4\ub97c \ub118\uc5b4 \uc22b\uc790\ub85c \ub0b4\ub9ac\uba74 \uac12\uc774 \ubb49\uac1c\uc9c0\ubbc0\ub85c \ubb38\uc790\uc5f4\ub85c \uc9c1\ub82c\ud654\ud55c\ub2e4\\"\\n  />\\n</figure>\\n\\n\uac00\uc7a5 \uc790\uc8fc \ub370\uc774\ub294 \ud568\uc815\uc740 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc758 \uc815\uc218 \uc815\ubc00\ub3c4\uc785\ub2c8\ub2e4. JS\uc758 `Number`\ub294 \uc548\uc804 \uc815\uc218 \ud55c\uacc4\uac00 `2^53 - 1`\uc778\ub370, <span style={{ backgroundColor: \'#ffdce0\'}}>TSID\ub294 64\ube44\ud2b8\ub77c \uc774 \ud55c\uacc4\ub97c \ub118\uc2b5\ub2c8\ub2e4.</span> \uadf8\ub300\ub85c \uc22b\uc790\ub85c \ub0b4\ub824\ubcf4\ub0b4\uba74 \ud504\ub7f0\ud2b8\uc5d0\uc11c \uac12\uc774 \ubb49\uac1c\uc9d1\ub2c8\ub2e4(precision loss).\\n\\nAPI \uc751\ub2f5\uc5d0\uc11c\ub294 TSID\ub97c \ubb38\uc790\uc5f4\ub85c \uc9c1\ub82c\ud654\ud558\uba74 \ub429\ub2c8\ub2e4.\\n\\n```json\\n// \uc22b\uc790\ub85c \ub0b4\ub9ac\uba74 \uc704\ud5d8 \u2192 \ubb38\uc790\uc5f4\ub85c\\n{ \\"id\\": \\"820182991320795727\\" }\\n```\\n\\n\uadf8 \uc678 \uc8fc\uc758\uc810:\\n\\n- \uc21c\ucc28\uc131 \ub178\ucd9c: \uc2dc\uac04\uc21c\uc774\ub77c \\"\ub2e4\uc74c ID\\"\ub97c \ucd94\uce21\ub2f9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc678\ubd80 \ub178\ucd9c \uc2dd\ubcc4\uc790\uac00 \ucd94\uce21\ub418\uba74 \uace4\ub780\ud55c \uacbd\uc6b0, \ubcc4\ub3c4 \uacf5\uac1c\uc6a9 \uc2dd\ubcc4\uc790\ub97c \ub461\ub2c8\ub2e4.\\n- DB \uceec\ub7fc \ud0c0\uc785: `INT`(32\ube44\ud2b8)\ub85c \ub450\uba74 \ub118\uce69\ub2c8\ub2e4. \ubc18\ub4dc\uc2dc `BIGINT`\ub85c \ub461\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **\uadf8\ub0e5 auto-increment \uc4f0\uba74 \uc548 \ub418\ub098\uc694?**\\n  - \ub2e8\uc77c DB\uba74 \uad1c\ucc2e\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uc5ec\ub7ec \uc11c\ube44\uc2a4\xb7\ub178\ub4dc\uc5d0\uc11c ID\ub97c \uc0dd\uc131\ud558\uba74 DB\uc5d0 \uc758\uc874\ud558\ub294 auto-increment\ub294 \ucda9\ub3cc\xb7\uacbd\ud569\uc774 \uc0dd\uae41\ub2c8\ub2e4. TSID\ub294 \ub178\ub4dc\uac00 \ub2ec\ub77c\ub3c4 \ub3c5\ub9bd \uc0dd\uc131\ub429\ub2c8\ub2e4.\\n- **UUIDv7\uc774 \uc788\ub294\ub370 \uad73\uc774 TSID\uc778\uac00\uc694?**\\n  - 64\ube44\ud2b8\ub85c \uc791\uac8c \uc4f0\uace0 \uc2f6\uc744 \ub54c TSID\uac00 \uc720\ub9ac\ud569\ub2c8\ub2e4. \ud45c\uc900 UUID \ud615\uc2dd \ud638\ud658\uc774 \uc911\uc694\ud558\uba74 UUIDv7\uc744 \uace0\ub974\uba74 \ub429\ub2c8\ub2e4. \ub458 \ub2e4 \\"\uc2dc\uac04\uc21c \uc815\ub82c\\"\uc774\ub77c\ub294 \ubaa9\uc801\uc740 \uac19\uc2b5\ub2c8\ub2e4.\\n- **\uc815\ub82c\ub418\ub294 ID\ub294 \ubcf4\uc548\uc5d0 \uc548 \uc88b\uc9c0 \uc54a\ub098\uc694?**\\n  - \ucd94\uce21 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ub0b4\ubd80 \uae30\ubcf8\ud0a4\ub85c\ub294 TSID\ub97c \uc4f0\ub418, \uc678\ubd80\uc5d0 \uadf8\ub300\ub85c \ub178\ucd9c\ud558\uc9c0 \uc54a\uac70\ub098 \ubcc4\ub3c4 \uacf5\uac1c \uc2dd\ubcc4\uc790\ub97c \ub450\uba74 \ub429\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- TSID / Snowflake ID \uba85\uc138\\n- RFC 9562: UUID (UUIDv7 \ud3ec\ud568)"},{"id":"six-months-in-retrospect","metadata":{"permalink":"/blog/six-months-in-retrospect","source":"@site/blog/2026-06-18-six-months-in-retrospect/index.md","title":"6\uac1c\uc6d4\uc744 \ub3cc\uc544\ubcf4\uba70, \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74","description":"6\uac1c\uc6d4\uac04 \ubc31\uc5d4\ub4dc\xb7\ud504\ub860\ud2b8\uc5d4\ub4dc\xb7\uc778\ud504\ub77c\ub97c \ub9cc\ub4e4\uace0 \uad74\ub824 \uc628 \uc2dc\ub9ac\uc988\ub97c \ub9c8\ubb34\ub9ac\ud569\ub2c8\ub2e4. \ubc18\ubcf5\ud574\uc11c \ubc30\uc6b4 \uac83\uacfc, \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74 \ub2e4\ub974\uac8c \ud560 \uac83\ub4e4\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-18T00:00:00.000Z","tags":[{"inline":true,"label":"Essay","permalink":"/blog/tags/essay"},{"inline":true,"label":"Retrospective","permalink":"/blog/tags/retrospective"},{"inline":true,"label":"Architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"BuildLog","permalink":"/blog/tags/build-log"}],"readingTime":1.99,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"6\uac1c\uc6d4\uc744 \ub3cc\uc544\ubcf4\uba70, \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74","slug":"six-months-in-retrospect","authors":["kgenots"],"tags":["Essay","Retrospective","Architecture","BuildLog"],"image":"/assets/blog/cover-six-months-in-retrospect.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"TSID vs UUID, \uc815\ub82c \uac00\ub2a5\ud55c ID \ub9cc\ub4e4\uae30","permalink":"/blog/tsid-vs-uuid"},"nextItem":{"title":"\ub9cc\ub4dc\ub294 \ub2e8\uacc4\uc5d0\uc11c \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\ub85c","permalink":"/blog/from-building-to-operating"}},"content":"6\uac1c\uc6d4\uac04 \ubc31\uc5d4\ub4dc\xb7\ud504\ub860\ud2b8\uc5d4\ub4dc\xb7\uc778\ud504\ub77c\ub97c \ub9cc\ub4e4\uace0 \uad74\ub824 \uc628 \uc2dc\ub9ac\uc988\ub97c \ub9c8\ubb34\ub9ac\ud569\ub2c8\ub2e4. \ubc18\ubcf5\ud574\uc11c \ubc30\uc6b4 \uac83\uacfc, \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74 \ub2e4\ub974\uac8c \ud560 \uac83\ub4e4\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\uc5ec\uc12f \ud3b8\uc744 \uc801\ub294 \ub3d9\uc548, \uc11c\ub85c \ub2e4\ub978 \uc774\uc57c\uae30\uc778 \uc904 \uc54c\uc558\ub358 \uac83\ub4e4\uc774 \uc0ac\uc2e4 \uac19\uc740 \uad50\ud6c8\uc744 \ubc18\ubcf5\ud558\uace0 \uc788\uc5c8\ub2e4\ub294 \uac78 \uc54c\uac8c \ub410\uc2b5\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9 \ud3b8\uc740 \uadf8 \ubc18\ubcf5\uc744 \ubaa8\uc73c\uace0, \uc194\uc9c1\ud558\uac8c \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74 \ubb34\uc5c7\uc744 \ub2e4\ub974\uac8c \ud560\uc9c0 \uc801\uc5b4 \ubd05\ub2c8\ub2e4.\\n\\n## \uc9c0\ub098\uc628 \uc5ec\uc12f \ud3b8\\n\\n- 1\ud3b8. [\ubaa8\ub178\ub808\ud3ec \ud558\ub098\uc5d0 15\uac1c \uc11c\ube44\uc2a4\ub97c \ub2f4\uc740 \uc774\uc720](/blog/monorepo-15-service-msa)\\n- 2\ud3b8. [\uc778\uc99d\uc744 \ubd99\uc774\ub2e4 \ub9cc\ub09c \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504](/blog/auth-bff-redirect-loop)\\n- 3\ud3b8. [\uc11c\ube44\uc2a4 \uc0ac\uc774\ub97c \uc787\ub294 \ubc95, \uc774\ubca4\ud2b8 \ubc84\uc2a4\uc640 \uc6cc\ud06c\ud50c\ub85c\uc6b0](/blog/event-bus-nats-temporal)\\n- 4\ud3b8. [\ud558\ub098\uc758 \ub808\ud3ec\ub85c \ud074\ub77c\uc6b0\ub4dc SaaS\uc640 \uc628\ud504\ub808\ubbf8\uc2a4\ub97c \ud568\uaed8 \uc6b4\uc601\ud558\uae30](/blog/one-repo-saas-and-onprem)\\n- 5\ud3b8. [\ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub85c \uc5ec\ub7ec \uc6f9 \uc571 \ub9cc\ub4e4\uae30](/blog/one-codebase-many-web-apps)\\n- 6\ud3b8. [\ub9cc\ub4dc\ub294 \ub2e8\uacc4\uc5d0\uc11c \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\ub85c](/blog/from-building-to-operating)\\n\\n## \ubc18\ubcf5\ud574\uc11c \ubc30\uc6b4 \uac83\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/six-months-in-retrospect.webp\\"\\n    alt=\\"6\uac1c\uc6d4 \ube4c\ub4dc \uc2dc\ub9ac\uc988 \uc804\uccb4 \uc9c0\ub3c4\uc640 \ubc18\ubcf5\ud574\uc11c \ubc30\uc6b4 \uad50\ud6c8\ub4e4\\"\\n  />\\n</figure>\\n\\n### 1. \uc870\uc6a9\ud788 \uc5b4\uae0b\ub098\ub294 \uc2e4\ud328\uac00 \uac00\uc7a5 \uc624\ub798 \uc0bd\ub2c8\ub2e4\\n\\n\uc774 \uc2dc\ub9ac\uc988\uc5d0\uc11c \uac00\uc7a5 \uc790\uc8fc \ub098\uc628 \ub9d0\uc785\ub2c8\ub2e4. 4KB\ub97c \ub118\uc5b4 \uc870\uc6a9\ud788 \ubc84\ub824\uc9c4 \ucfe0\ud0a4([2\ud3b8](/blog/auth-bff-redirect-loop)), \uac00\uc838\uac00\uae30 \uc804\uc5d0 \uc870\uc6a9\ud788 \uc9c0\uc6cc\uc9c4 \uba54\uc2dc\uc9c0([3\ud3b8](/blog/event-bus-nats-temporal)), \uc61b \uc124\uc815\uc744 \uc870\uc6a9\ud788 \ub0b4\uc8fc\ub358 \uce90\uc2dc([5\ud3b8](/blog/one-codebase-many-web-apps)).\\n\\n\uc14b \ub2e4 <span style={{ backgroundColor: \'#ffdce0\'}}>\uc624\ub958 \ub85c\uadf8\uac00 \uc5c6\uc5c8\uc2b5\ub2c8\ub2e4.</span> \uc2dc\uc2a4\ud15c\uc740 \\"\uc815\uc0c1\\"\uc774\ub77c\uace0 \ub2f5\ud588\uace0, \uadf8\ub798\uc11c \uac00\uc7a5 \uc624\ub798 \uc0ac\ub78c\uc744 \ubd99\uc7a1\uc558\uc2b5\ub2c8\ub2e4. \uc694\ub780\ud558\uac8c \ud130\uc9c0\ub294 \uc7a5\uc560\ub294 \uae08\ubc29 \uc7a1\ud799\ub2c8\ub2e4. \ubb34\uc11c\uc6b4 \uac74 \uc544\ubb34 \uc18c\ub9ac \uc5c6\uc774 \uc5b4\uae0b\ub098\ub294 \ucabd\uc785\ub2c8\ub2e4.\\n\\n### 2. \uacf5\ud1b5\uc740 \ud55c\uacf3\uc5d0, \ucc28\uc774\ub294 \uac00\uc7a5\uc790\ub9ac\uc5d0\\n\\n\ubc31\uc5d4\ub4dc\uc5d0\uc11c\ub3c4([1\ud3b8](/blog/monorepo-15-service-msa)), \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0\uc11c\ub3c4([5\ud3b8](/blog/one-codebase-many-web-apps)), \ub450 \uc6b4\uc601 \ud658\uacbd\uc5d0\uc11c\ub3c4([4\ud3b8](/blog/one-repo-saas-and-onprem)) \uac19\uc740 \ubaa8\uc591\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uacf5\ud1b5\ub418\ub294 \uac83\uc740 \ud55c\uacf3\uc5d0 \ubaa8\uc73c\uace0, \ud658\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \ubd80\ubd84\uc740 \ubcf8\ubb38\uc774 \uc544\ub2c8\ub77c \uac00\uc7a5\uc790\ub9ac(\ud658\uacbd \ubcc0\uc218\xb7\ube4c\ub4dc \uc124\uc815\xb7\uc124\uce58 \ub2e8\uacc4)\uc5d0\uc11c \ud761\uc218\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\ub355\ubd84\uc5d0 \\"\uc774\uac74 \uc774 \ud658\uacbd\uc6a9, \uc800\uac74 \uc800 \ud658\uacbd\uc6a9\\"\uc73c\ub85c \ucf54\ub4dc\ub97c \ucabc\uac1c\uc9c0 \uc54a\uc744 \uc218 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ud55c \ubc88 \uc9dc\uba74 \uc5ec\ub7ec \uacf3\uc5d0\uc11c \ub3cc\uc558\uc2b5\ub2c8\ub2e4.\\n\\n### 3. \uc88b\uc740 \uae30\ubcf8\uac12\ub3c4 \ud56d\uc0c1 \ub9de\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4\\n\\n\uce90\uc2dc\ub294 \ube60\ub974\ub77c\uace0 \uc788\ub294 \uc88b\uc740 \uae30\ub2a5\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc790\uc8fc \ubc14\ub00c\uc5b4\uc57c \ud558\ub294 \uc124\uc815 \ud30c\uc77c\uc5d0\ub294 \ub3c5\uc774\uc5c8\uc2b5\ub2c8\ub2e4([5\ud3b8](/blog/one-codebase-many-web-apps)). \uc124\uc815\uac12\uc744 \uc0ac\ub78c \ud310\ub2e8\uc5d0 \ub9e1\uae30\ub294 \uac83\ub3c4 \uc790\uc5f0\uc2a4\ub7fd\uc9c0\ub9cc, \ub204\uad70\uac00\ub294 \ub2e4\ub974\uac8c \uc7a1\uc544 \uc0ac\uace0\uac00 \ub0ac\uc2b5\ub2c8\ub2e4([3\ud3b8](/blog/event-bus-nats-temporal)).\\n\\n\\"\ubcf4\ud1b5\uc740 \uc774\uac8c \ub9de\ub2e4\\"\uac00 <span style={{ backgroundColor: \'#fff5b1\'}}>\uc774 \uacbd\uc6b0\uc5d0\ub3c4 \ub9de\ub294\uc9c0</span>\ub294 \ub530\ub85c \ubb3c\uc5b4\uc57c \ud588\uc2b5\ub2c8\ub2e4.\\n\\n### 4. \ub9cc\ub4e4 \uc218 \uc788\ub2e4\uc640 \uad74\ub9b4 \uc218 \uc788\ub2e4\ub294 \ub2e4\ub985\ub2c8\ub2e4\\n\\n\ub9cc\ub4dc\ub294 \ub3d9\uc548\uc5d0\ub294 \\"\ub418\ub294\uac00\\"\ub9cc \ubcf4\uba74 \ub410\uc2b5\ub2c8\ub2e4. \uc6b4\uc601\uc5d0 \ub4e4\uc5b4\uac00\ub2c8 \\"\uc9c0\uae08 \ubb34\uc5c7\uc774 \ub3c4\ub294\uac00, \uae68\uc9c0\uba74 \ub204\uac00 \uc544\ub294\uac00\\"\uac00 \ub354 \uc911\uc694\ud574\uc84c\uc2b5\ub2c8\ub2e4([6\ud3b8](/blog/from-building-to-operating)). \uc774 \ucc28\uc774\ub97c \ub2a6\uac8c \uae68\ub2ec\uc740 \uac8c \uac00\uc7a5 \ud070 \ubc30\uc6c0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74 \ub2e4\ub974\uac8c \ud560 \uac83\\n\\n- **\ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uc7a5\uce58\ub97c \uac00\uc7a5 \uba3c\uc800** \ub450\uaca0\uc2b5\ub2c8\ub2e4. \uad00\uce21\uc740 \uc6b4\uc601\uc5d0 \ub4e4\uc5b4\uac00\uc11c\uc57c \uae09\ud558\uac8c \uac16\ucdc4\uc9c0\ub9cc, \ucc98\uc74c\ubd80\ud130 \uc788\uc5c8\ub2e4\uba74 \uc55e\uc758 \uc870\uc6a9\ud55c \uc0ac\uace0\ub4e4\uc744 \ud6e8\uc52c \uc77c\ucc0d \ubd24\uc744 \uac81\ub2c8\ub2e4.\\n- **\ud658\uacbd \ucc28\uc774\ub97c \ucc98\uc74c\ubd80\ud130 \ubd80\ud488\uc73c\ub85c** \ube7c\uaca0\uc2b5\ub2c8\ub2e4. \ub098\uc911\uc5d0 \ubd84\ub9ac\ud558\ub824\ub2c8 \ubcf8\ubb38 \uacf3\uacf3\uc5d0 \ubc15\ud78c \uac00\uc815\uc744 \ucc3e\uc544 \uac77\uc5b4\ub0b4\uc57c \ud588\uc2b5\ub2c8\ub2e4.\\n- **\\"\ubc1b\uc544\uc62c \uc218 \uc788\ub2e4\\"\ub294 \uac00\uc815**\uc744 \uc904\uc774\uaca0\uc2b5\ub2c8\ub2e4. \uc778\ud130\ub137\uc774 \ub418\ub294 \ud658\uacbd\uc744 \ub2f9\uc5f0\ud558\uac8c \uc5ec\uae34 \ucf54\ub4dc\uac00, \ub9c9\ud78c \ud658\uacbd\uc5d0\uc11c \uc904\uc904\uc774 \uba48\ucdc4\uc2b5\ub2c8\ub2e4([4\ud3b8](/blog/one-repo-saas-and-onprem)).\\n- **\ubc84\uc804\uacfc \ubcc0\uacbd \uc774\ub825\uc744 \uc77c\ucc0d** \ubd99\uc774\uaca0\uc2b5\ub2c8\ub2e4. \\"\ucd5c\uc2e0\uc774 \ub9de\uaca0\uc9c0\\"\ub85c \ubc84\ud2f4 \uae30\uac04\uc774 \uc0dd\uac01\ubcf4\ub2e4 \uae38\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \uc548 \ubc14\uafc0 \uac83\\n\\n- \ubaa8\ub178\ub808\ud3ec\ub294 \ub2e4\uc2dc \uace8\ub77c\ub3c4 \uac19\uc740 \uc120\ud0dd\uc785\ub2c8\ub2e4. \uc18c\uc218\uac00 \uc804\uccb4\ub97c \ubcf4\ub294 \ub2e8\uacc4\uc5d0\uc11c\ub294 \ub9c8\ucc30\uc774 \uac00\uc7a5 \uc801\uc5c8\uc2b5\ub2c8\ub2e4.\\n- \uacbd\uacc4\ub97c \ubd84\uba85\ud788 \uae0b\ub294 \ubc29\uc2dd\ub3c4 \uadf8\ub300\ub85c \ub450\uaca0\uc2b5\ub2c8\ub2e4. \ud55c \uc11c\ube44\uc2a4\uac00 \ud55c \uac00\uc9c0 \uc77c\ub9cc \ud558\uac8c \ub9cc\ub4e0 \ub355\ubd84\uc5d0, \ud544\uc694\ud560 \ub54c \uace8\ub77c \uc870\ub9bd\ud560 \uc218 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/six-months-in-retrospect-2.webp\\"\\n    alt=\\"\ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74 \ub2e4\ub974\uac8c \ud560 \uac83\uacfc, \uadf8\ub300\ub85c \ub458 \uac83\uc758 \uc815\ub9ac\\"\\n  />\\n</figure>\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n\uc5ec\uc12f \ud3b8\uc744 \ud55c \uc904\ub85c \uc904\uc774\uba74 \uc774\ub807\uc2b5\ub2c8\ub2e4. \uacf5\ud1b5\uc740 \ubaa8\uc73c\uace0, \ucc28\uc774\ub294 \uac00\uc7a5\uc790\ub9ac\ub85c \ubc00\uace0, \uc870\uc6a9\ud55c \uc2e4\ud328\ub97c \ub4dc\ub7ec\ub0b4\uace0, \ub9cc\ub4e0 \uac83\uc744 \uad74\ub9b4 \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4.\\n\\n\uac70\ucc3d\ud55c \uacb0\ub860\uc740 \uc5c6\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uac19\uc740 \uc2e4\uc218\ub97c \ub2e4\uc74c\uc5d0\ub294 \uc870\uae08 \ub354 \uc77c\ucc0d \uc54c\uc544\ucc4c \uc218 \uc788\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uadf8\uac70\uba74 \ucda9\ubd84\ud55c 6\uac1c\uc6d4\uc774\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\uae34 \uae00 \uc77d\uc5b4 \uc8fc\uc154\uc11c \uac10\uc0ac\ud569\ub2c8\ub2e4."},{"id":"from-building-to-operating","metadata":{"permalink":"/blog/from-building-to-operating","source":"@site/blog/2026-06-17-from-building-to-operating/index.md","title":"\ub9cc\ub4dc\ub294 \ub2e8\uacc4\uc5d0\uc11c \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\ub85c","description":"\uae30\ub2a5\uc744 \ub9cc\ub4e4\ub358 \ub2e8\uacc4\uc5d0\uc11c \ub9cc\ub4e0 \uac83\uc744 \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\ub85c \ub118\uc5b4\uac00\uba70 \ubc14\ub010 \uac83\ub4e4\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4. \ubc84\uc804, \ubc30\ud3ec \uc790\ub3d9\ud654, \uadf8\ub9ac\uace0 \ubb34\uc5c7\uc774 \ub3c4\ub294\uc9c0 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uc77c\uc5d0 \ub300\ud55c \uc774\uc57c\uae30\uc785\ub2c8\ub2e4.","date":"2026-06-17T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"Architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"},{"inline":true,"label":"Retrospective","permalink":"/blog/tags/retrospective"},{"inline":true,"label":"BuildLog","permalink":"/blog/tags/build-log"}],"readingTime":1.9,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ub9cc\ub4dc\ub294 \ub2e8\uacc4\uc5d0\uc11c \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\ub85c","slug":"from-building-to-operating","authors":["kgenots"],"tags":["Tech","Architecture","Ops","Retrospective","BuildLog"],"image":"/assets/blog/cover-from-building-to-operating.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"6\uac1c\uc6d4\uc744 \ub3cc\uc544\ubcf4\uba70, \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74","permalink":"/blog/six-months-in-retrospect"},"nextItem":{"title":"\ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub85c \uc5ec\ub7ec \uc6f9 \uc571 \ub9cc\ub4e4\uae30","permalink":"/blog/one-codebase-many-web-apps"}},"content":"\uae30\ub2a5\uc744 \ub9cc\ub4e4\ub358 \ub2e8\uacc4\uc5d0\uc11c \ub9cc\ub4e0 \uac83\uc744 \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\ub85c \ub118\uc5b4\uac00\uba70 \ubc14\ub010 \uac83\ub4e4\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4. \ubc84\uc804, \ubc30\ud3ec \uc790\ub3d9\ud654, \uadf8\ub9ac\uace0 \ubb34\uc5c7\uc774 \ub3c4\ub294\uc9c0 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uc77c\uc5d0 \ub300\ud55c \uc774\uc57c\uae30\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\uc9c0\ub09c \ub2e4\uc12f \ud3b8\uc740 \\"\ubb34\uc5c7\uc744 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5c8\ub098\\"\ub97c \uc801\uc5c8\uc2b5\ub2c8\ub2e4. \uc5b4\ub290 \uc2dc\uc810\ubd80\ud130\ub294 \uc9c8\ubb38\uc774 \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4. \ub9cc\ub4dc\ub294 \uac83\ubcf4\ub2e4 \ub9cc\ub4e0 \uac83\uc744 \uad74\ub9ac\ub294 \uc77c\uc774 \ub354 \uc911\uc694\ud574\uc84c\uc2b5\ub2c8\ub2e4.\\n\\n## \uc9c8\ubb38\uc774 \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/from-building-to-operating.webp\\"\\n    alt=\\"\ub9cc\ub4dc\ub294 \ub2e8\uacc4\uc640 \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\uc758 \uc9c8\ubb38 \ucc28\uc774, \uadf8\ub9ac\uace0 \ubc84\uc804\xb7\ubc30\ud3ec \uc790\ub3d9\ud654\xb7\uad00\uce21\uc131\\"\\n  />\\n</figure>\\n\\n\ub9cc\ub4e4 \ub54c \ub358\uc9c0\ub294 \uc9c8\ubb38\uc740 \\"\uc774\uac8c \ub418\ub294\uac00?\\" \ud558\ub098\uc600\uc2b5\ub2c8\ub2e4. \ub3d9\uc791\ud558\uba74 \ub410\uc2b5\ub2c8\ub2e4.\\n\\n\uc6b4\uc601\uc5d0 \ub4e4\uc5b4\uac00\ub2c8 \uc9c8\ubb38\uc774 \ub298\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n- \uc9c0\uae08 \ubb34\uc5c7\uc774 \ub3cc\uace0 \uc788\ub294\uac00?\\n- \ubb34\uc5c7\uc774 \uc5b8\uc81c \ubc14\ub00c\uc5c8\ub294\uac00?\\n- \uae68\uc9c0\uba74 \ub204\uac00, \uc5bc\ub9c8\ub098 \ube68\ub9ac \uc544\ub294\uac00?\\n\\n\uac19\uc740 \ucf54\ub4dc\ub97c \ub450\uace0\ub3c4 \ubcf4\ub294 \uac01\ub3c4\uac00 \ub2ec\ub77c\uc84c\uc2b5\ub2c8\ub2e4. \uc774 \uc9c8\ubb38\ub4e4\uc5d0 \ub2f5\ud558\ub824\uace0 \uba87 \uac00\uc9c0\ub97c \uc0c8\ub85c \uac16\ucdc4\uc2b5\ub2c8\ub2e4.\\n\\n## \ubc84\uc804\uacfc \ubcc0\uacbd \uc774\ub825 (\\"\uc9c0\uae08 \ubb50\uac00 \ub5a0 \uc788\uc9c0?\\")\\n\\n[1\ud3b8](/blog/monorepo-15-service-msa)\uc5d0\uc11c \uc11c\ube44\uc2a4\ub97c 15\uac1c\ub85c \ub098\ub234\ub2e4\uace0 \ud588\uc2b5\ub2c8\ub2e4. \uac01 \uc11c\ube44\uc2a4\uac00 \ub530\ub85c \ubc30\ud3ec\ub418\ub2c8, \uace7 \\"\uc9c0\uae08 \uc5b4\ub290 \uc11c\ube44\uc2a4\uac00 \uc5b4\ub290 \ubc84\uc804\uc73c\ub85c \ub5a0 \uc788\ub294\uc9c0\\"\ub97c \uc544\ubb34\ub3c4 \ubaa8\ub974\ub294 \uc0c1\ud669\uc774 \ub410\uc2b5\ub2c8\ub2e4.\\n\\n\ucc98\uc74c\uc5d4 \\"\ucd5c\uc2e0\uc774 \ub9de\uaca0\uc9c0\\"\ub85c \ubc84\ud17c\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c, \ucd5c\uc2e0\uc774 \ubb34\uc5c7\uc778\uc9c0\uc870\ucc28 \ud5f7\uac08\ub838\uc2b5\ub2c8\ub2e4.\\n\\n:::info \ub0a0\uc9dc \uc5c6\ub294 \uba54\ub274\ud310\\n\ub9e4\uc77c \uba54\ub274\uac00 \ubc14\ub00c\ub294 \uc2dd\ub2f9\uc778\ub370 \uba54\ub274\ud310\uc5d0 \ub0a0\uc9dc\uac00 \uc5c6\uc2b5\ub2c8\ub2e4. \uc190\ub2d8\ub3c4, \uc8fc\ubc29\ub3c4 \\"\uc624\ub298 \ubb50\uac00 \ubc14\ub00c\uc5c8\uc9c0?\\"\ub97c \ubaa8\ub985\ub2c8\ub2e4.\\n:::\\n\\n\uadf8\ub798\uc11c \ub450 \uac00\uc9c0\ub97c \ub3c4\uc785\ud588\uc2b5\ub2c8\ub2e4.\\n\\n- \ucee4\ubc0b \uba54\uc2dc\uc9c0 \uaddc\uce59. \ubaa8\ub4e0 \ubcc0\uacbd\uc774 \\"\uae30\ub2a5 \ucd94\uac00\uc778\uc9c0, \ubc84\uadf8 \uc218\uc815\uc778\uc9c0\\"\ub97c \uc77c\uc815\ud55c \ud615\uc2dd\uc73c\ub85c \ub0a8\uae30\uac8c \ud588\uc2b5\ub2c8\ub2e4.\\n- \ubc84\uc804\uacfc \ubcc0\uacbd \uc774\ub825 \uc790\ub3d9\ud654. \uadf8 \ucee4\ubc0b\ub4e4\uc744 \ubaa8\uc544 \uc11c\ube44\uc2a4\ubcc4 \ubc84\uc804\uc744 \uc62c\ub9ac\uace0, \ubcc0\uacbd \uc774\ub825(CHANGELOG)\uc744 \uc790\ub3d9\uc73c\ub85c \ub9cc\ub4e4\uac8c \ud588\uc2b5\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \uc190\uc73c\ub85c \uc801\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n\uc5ec\uae30\uc11c \uc791\uc740 \uacb0\uc815 \ud558\ub098\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\uc5d4 \uc815\uae30 \ubc30\ud3ec(\uc8fc 1\ud68c)\ub9c8\ub2e4 \ubc84\uc804 \ubc88\ud638\ub97c \ud55c \uce78\uc529 \uc62c\ub838\ub294\ub370, \ub9e4\uc8fc \uc62c\ub9ac\ub2c8 \ubc88\ud638\uac00 \ub108\ubb34 \ube68\ub9ac \ucee4\uc84c\uc2b5\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \uc0ac\ub78c\uc774 \ubcf4\ub294 \uc815\uae30 \ubc30\ud3ec \ubb36\uc74c\uc5d0\ub294 \ub0a0\uc9dc \ub77c\ubca8\uc744 \ubd99\uc774\uace0, \uc2e4\uc81c \ubc84\uc804 \ubc88\ud638\ub294 \ubcc0\uacbd\ub7c9\uc5d0 \ub530\ub77c \uc790\ub3d9\uc73c\ub85c \uc624\ub974\uac8c \ubd84\ub9ac\ud588\uc2b5\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \uc77d\uae30 \uc88b\uc740 \ud45c\uc2dc\uc640 \uae30\uacc4\uac00 \uacc4\uc0b0\ud558\ub294 \uac12\uc744 \ub530\ub85c \ub5bc\uc5b4 \ub193\uc558\uc2b5\ub2c8\ub2e4.\\n\\n## \uc190\uc73c\ub85c \ubc30\ud3ec\ud558\ub294 \uac78 \uadf8\ub9cc\ub480\uc2b5\ub2c8\ub2e4\\n\\n\ucd08\uae30\uc5d0\ub294 \ubc30\ud3ec\ub97c \uc190\uc73c\ub85c \ud588\uc2b5\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \ud558\uba74 \uc0ac\ub78c\ub9c8\ub2e4 \uc21c\uc11c\uac00 \ub2e4\ub974\uace0, \ud55c \ub2e8\uacc4\ub97c \ube60\ub728\ub9bd\ub2c8\ub2e4. \ud2b9\ud788 \\"\ub370\uc774\ud130\ubca0\uc774\uc2a4 \ubcc0\uacbd\uc744 \uba3c\uc800, \uadf8\ub2e4\uc74c \uc11c\ube44\uc2a4 \ubc30\ud3ec\\" \uac19\uc740 \uc21c\uc11c\ub97c \ub193\uce58\uba74 \uc0ac\uace0\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \ube0c\ub79c\uce58\uc5d0 \ud569\uce58\uba74 \uc790\ub3d9\uc73c\ub85c \ubc30\ud3ec\ub418\ub3c4\ub85d \ubc14\uafe8\uc2b5\ub2c8\ub2e4. \uac1c\ubc1c\uc6a9 \ube0c\ub79c\uce58\ub294 \uac1c\ubc1c \ud658\uacbd\uc73c\ub85c, \uc6b4\uc601\uc6a9 \ube0c\ub79c\uce58\ub294 \uc6b4\uc601 \ud658\uacbd\uc73c\ub85c \ud758\ub7ec\uac00\uac8c\uc694. \uc190\uc73c\ub85c \uc62e\uae30\ub358 \uc77c\uc744 \ucee8\ubca0\uc774\uc5b4\uc5d0 \uc62c\ub838\uc2b5\ub2c8\ub2e4.\\n\\n\uc790\ub3d9\ud654\uac00 \uc88b\uc558\ub358 \uac74 \uc18d\ub3c4\ubcf4\ub2e4\ub3c4 \ub9e4\ubc88 \ub611\uac19\uc774 \ud55c\ub2e4\ub294 \ub370 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc0ac\ub78c\uc758 \ucee8\ub514\uc158\uc5d0 \ubc30\ud3ec\uac00 \uc88c\uc6b0\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## \ub4e4\uc5ec\ub2e4\ubcf4\uae30, \uc548 \ubcf4\uba74 \ubaa8\ub985\ub2c8\ub2e4\\n\\n\uc6b4\uc601\uc5d0\uc11c \uac00\uc7a5 \uba3c\uc800 \ubd80\ub52a\ud78c \ubcbd\uc740 \\"\ubb34\uc2a8 \uc77c\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0 \uc548 \ubcf4\uc778\ub2e4\\"\uc600\uc2b5\ub2c8\ub2e4. \uc9c0\ub09c \ud3b8\ub4e4\uc5d0\uc11c \ubc18\ubcf5\ub41c \uc0ac\uace0\ub4e4(\uc870\uc6a9\ud788 \ubc84\ub824\uc9c4 \ucfe0\ud0a4, \uc870\uc6a9\ud788 \uc9c0\uc6cc\uc9c4 \uba54\uc2dc\uc9c0)\uc774 \uc624\ub798\uac04 \uc774\uc720\ub3c4 \uacb0\uad6d \uac19\uc558\uc2b5\ub2c8\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\uc558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\uacc4\uae30\ud310 \uc5c6\ub294 \ucc28\ub85c \uace0\uc18d\ub3c4\ub85c\ub97c \ub2ec\ub9ac\ub294 \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc18d\ub3c4\ub3c4 \uc5f0\ub8cc\ub3c4 \ubaa8\ub974\uba74, \ubb38\uc81c\uac00 \ud130\uc9c0\uace0 \ub098\uc11c\uc57c \uc555\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uc7a5\uce58\ub97c \uac16\ucdc4\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/from-building-to-operating-2.webp\\"\\n    alt=\\"\uad00\uce21 \uc7a5\uce58\uac00 \uc5c6\uc744 \ub54c\uc640 \uac10\uc0ac\xb7\uc9c0\ud45c\xb7\ub300\uc2dc\ubcf4\ub4dc\ub97c \uac16\ucdc4\uc744 \ub54c\uc758 \ucc28\uc774\\"\\n  />\\n</figure>\\n\\n- \ub204\uac00 \uc5b8\uc81c \ubb34\uc5c7\uc744 \ud588\ub294\uc9c0 \ub0a8\uae30\ub294 \uac10\uc0ac \uae30\ub85d\\n- \ubb34\uc5c7\uc774 \uc5bc\ub9c8\ub098 \ub3c4\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uc640 \ub85c\uadf8\\n- \uc313\uc778 \ub370\uc774\ud130\ub97c \ubaa8\uc544 \ubcf4\ub294 \ub300\uc2dc\ubcf4\ub4dc\\n\\n\ub2e4 \ub9cc\ub4e0 \ub4a4\uc5d0\uc57c \uae68\ub2ec\uc558\uc2b5\ub2c8\ub2e4. \ub9cc\ub4dc\ub294 \ub3d9\uc548\uc5d0\ub294 \uad00\uce21\uc774 \uc0ac\uce58\ucc98\ub7fc \ub290\uaef4\uc9c0\ub294\ub370, \uc6b4\uc601\uc5d0 \ub4e4\uc5b4\uac00\ub2c8 \uc774\uac8c \uac00\uc7a5 \uba3c\uc800 \ud544\uc694\ud588\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9cc\ub4e4 \uc218 \uc788\ub2e4 \u2260 \uc6b4\uc601\ud560 \uc218 \uc788\ub2e4\\n\\n\uc774 \ub2e8\uacc4\ub97c \uc9c0\ub098\uba70 \uc77c\ud558\ub294 \uae30\uc900\uc774 \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4. \uc608\uc804\uc5d0\ub294 \\"\uae30\ub2a5\uc744 \uc5bc\ub9c8\ub098 \ube68\ub9ac \ub9cc\ub4dc\ub098\\"\ub85c \uc800\ub97c \uc7ac\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\uc740 <span style={{ backgroundColor: \'#fff5b1\'}}>\\"\uc774\uac78 \uacc4\uc18d \uad74\ub9b4 \uc218 \uc788\ub098\\"</span>\ub85c \uc7bd\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \uad00\ub9ac\ud560 \uc218 \uc788\ub294 \ub9cc\ud07c\ub9cc \ub9cc\ub4dc\ub294 \ucabd\uc73c\ub85c \ubc29\ud5a5\uc744 \ud2c0\uc5c8\uc2b5\ub2c8\ub2e4. \ud654\ub824\ud558\uac8c \ub9ce\uc774 \ub9cc\ub4dc\ub294 \uac83\ubcf4\ub2e4, \uc801\uac8c \ub9cc\ub4e4\ub354\ub77c\ub3c4 \ubb34\uc5c7\uc774 \ub3c4\ub294\uc9c0 \uc54c\uace0 \uace0\uce60 \uc218 \uc788\ub294 \uc0c1\ud0dc\uac00 \uc911\uc694\ud574\uc84c\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n\ub3cc\uc544\ubcf4\uba74 \uc774 \ub2e8\uacc4\uc5d0\uc11c \uc5bb\uc740 \uac74 \uc0c8 \uae30\uc220\uc774 \uc544\ub2c8\ub77c \uae30\uc900\uc774\uc5c8\ub358 \uac83 \uac19\uc2b5\ub2c8\ub2e4.\\n\\n- \uc11c\ube44\uc2a4\uac00 \ub530\ub85c \ubc30\ud3ec\ub418\uba74 \\"\uc9c0\uae08 \ubb50\uac00 \ub5a0 \uc788\uc9c0\\"\uac00 \uc548 \ubcf4\uc785\ub2c8\ub2e4. \ucee4\ubc0b \uaddc\uce59\uacfc \ubc84\uc804\xb7\ubcc0\uacbd \uc774\ub825 \uc790\ub3d9\ud654\ub85c \ub2f5\uc744 \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4.\\n- \uc190 \ubc30\ud3ec\ub294 \ub9e4\ubc88 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4. \uc790\ub3d9 \ubc30\ud3ec\ub294 \ube68\ub77c\uc11c\uac00 \uc544\ub2c8\ub77c **\ub9e4\ubc88 \ub611\uac19\uc544\uc11c** \uc88b\uc558\uc2b5\ub2c8\ub2e4.\\n- \uc548 \ubcf4\uba74 \ubaa8\ub985\ub2c8\ub2e4. \uac10\uc0ac\xb7\uc9c0\ud45c\xb7\ub300\uc2dc\ubcf4\ub4dc\ub294 \ub9cc\ub4dc\ub294 \ub3d9\uc548\uc5d0\ub294 \ubbf8\ub904 \ub450\uc5c8\ub2e4\uac00 \uc6b4\uc601\uc5d0\uc11c \uae09\ud558\uac8c \uac16\ucdc4\uc2b5\ub2c8\ub2e4.\\n\\n\uc5ec\uae30\uae4c\uc9c0\uac00 6\uac1c\uc6d4\uac04 \ubc31\uc5d4\ub4dc\xb7\ud504\ub860\ud2b8\uc5d4\ub4dc\xb7\uc778\ud504\ub77c\ub97c \ub9cc\ub4e4\uace0 \uad74\ub824 \uc628 \uae30\ub85d\uc785\ub2c8\ub2e4. \ub2e4\uc74c \ud3b8\uc5d0\uc11c\ub294 \uc774 \uacfc\uc815\uc744 \ud1b5\uc9f8\ub85c \ub3cc\uc544\ubcf4\uba70, \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74 \ubb34\uc5c7\uc744 \ub2e4\ub974\uac8c \ud560\uc9c0\ub97c \uc815\ub9ac\ud574 \ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4."},{"id":"one-codebase-many-web-apps","metadata":{"permalink":"/blog/one-codebase-many-web-apps","source":"@site/blog/2026-06-16-one-codebase-many-web-apps/index.md","title":"\ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub85c \uc5ec\ub7ec \uc6f9 \uc571 \ub9cc\ub4e4\uae30","description":"\uc5ec\ub7ec \uac1c\uc758 \uc6f9 \uc571\uc744 \ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\uc5d0\uc11c \ub9cc\ub4e4\uace0 \ubc30\ud3ec\ud55c \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4. \ud2b9\ud788 \ud55c \ubc88 \ube4c\ub4dc\ud55c \uc571\uc744 \uace0\uac1d\uc0ac\ub9c8\ub2e4 \ub2e4\ub978 \uc8fc\uc18c\ub85c \ub744\uc6b4 \ubc29\ubc95\uc744 \ub2e4\ub8f9\ub2c8\ub2e4.","date":"2026-06-16T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"Frontend","permalink":"/blog/tags/frontend"},{"inline":true,"label":"Architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"Retrospective","permalink":"/blog/tags/retrospective"},{"inline":true,"label":"BuildLog","permalink":"/blog/tags/build-log"}],"readingTime":1.88,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub85c \uc5ec\ub7ec \uc6f9 \uc571 \ub9cc\ub4e4\uae30","slug":"one-codebase-many-web-apps","authors":["kgenots"],"tags":["Tech","Frontend","Architecture","Retrospective","BuildLog"],"image":"/assets/blog/cover-one-codebase-many-web-apps.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ub9cc\ub4dc\ub294 \ub2e8\uacc4\uc5d0\uc11c \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\ub85c","permalink":"/blog/from-building-to-operating"},"nextItem":{"title":"\ud558\ub098\uc758 \ub808\ud3ec\ub85c \ud074\ub77c\uc6b0\ub4dc SaaS\uc640 \uc628\ud504\ub808\ubbf8\uc2a4\ub97c \ud568\uaed8 \uc6b4\uc601\ud558\uae30","permalink":"/blog/one-repo-saas-and-onprem"}},"content":"\uc5ec\ub7ec \uac1c\uc758 \uc6f9 \uc571\uc744 \ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\uc5d0\uc11c \ub9cc\ub4e4\uace0 \ubc30\ud3ec\ud55c \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4. \ud2b9\ud788 \ud55c \ubc88 \ube4c\ub4dc\ud55c \uc571\uc744 \uace0\uac1d\uc0ac\ub9c8\ub2e4 \ub2e4\ub978 \uc8fc\uc18c\ub85c \ub744\uc6b4 \ubc29\ubc95\uc744 \ub2e4\ub8f9\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\uc9c0\uae08\uae4c\uc9c0\ub294 \uc8fc\ub85c \ub4a4\ucabd(\ubc31\uc5d4\ub4dc\xb7\uc778\ud504\ub77c) \uc774\uc57c\uae30\ub97c \ud588\uc2b5\ub2c8\ub2e4. \uc774\ubc88 \ud3b8\uc740 \uc0ac\uc6a9\uc790\uac00 \uc9c1\uc811 \ubcf4\ub294 \ud654\uba74(\ud504\ub860\ud2b8\uc5d4\ub4dc) \ucabd\uc785\ub2c8\ub2e4.\\n\\n\uc11c\ube44\uc2a4\ub97c \uc5ec\ub7ec \uac1c\ub85c \ub098\ub204\ub2c8, \ud654\uba74\ub3c4 \ud55c \uac1c\uac00 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n- \ub85c\uadf8\uc778\uc744 \uc804\ub2f4\ud558\ub294 \uc571([2\ud3b8](/blog/auth-bff-redirect-loop)\uc5d0\uc11c \uc774\uc57c\uae30\ud55c \uc778\uc99d \uc0ac\uc774\ud2b8)\\n- \uc81c\ud488 \ud654\uba74 \uc571\uc774 \uc5ec\ub7ec \uac1c\\n\\n\uc774 \uc571\ub4e4\uc740 \uc11c\ub85c \ub2e4\ub974\uc9c0\ub9cc, \uacb9\uce58\ub294 \ubd80\ubd84\uc774 \ub9ce\uc558\uc2b5\ub2c8\ub2e4. \ub514\uc790\uc778(\ubc84\ud2bc\xb7\uc785\ub825\ucc3d \uac19\uc740 \uacf5\ud1b5 \uc694\uc18c)\uc774 \uac19\uace0, \ub85c\uadf8\uc778 \ucc98\ub9ac \ubc29\uc2dd\ub3c4 \uac19\uc2b5\ub2c8\ub2e4. \uc774\uac78 \uc571\ub9c8\ub2e4 \ub530\ub85c \ub9cc\ub4e4\uba74 \uac19\uc740 \ucf54\ub4dc\ub97c \uacc4\uc18d \ubcf5\uc81c\ud558\uac8c \ub429\ub2c8\ub2e4.\\n\\n## \uacf5\uc6a9 \ucc3d\uace0\ub97c \ub450\uc5c8\uc2b5\ub2c8\ub2e4\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/one-codebase-many-web-apps.webp\\"\\n    alt=\\"\ud558\ub098\uc758 \ud504\ub860\ud2b8\uc5d4\ub4dc \ubaa8\ub178\ub808\ud3ec\uc5d0\uc11c \uc5ec\ub7ec \uc6f9 \uc571\uc744 \ub9cc\ub4e4\uace0, \ub7f0\ud0c0\uc784 \uc124\uc815\uc73c\ub85c \ud658\uacbd\uc744 \ubd84\uae30\ud558\ub294 \uad6c\uc870\\"\\n  />\\n</figure>\\n\\n\ubc31\uc5d4\ub4dc\uc5d0\uc11c \ud588\ub358 \uac83\uacfc \uac19\uc740 \uc120\ud0dd\uc744 \ud654\uba74\uc5d0\uc11c\ub3c4 \ud588\uc2b5\ub2c8\ub2e4. <span style={{ backgroundColor: \'#fff5b1\'}}>\uc571\uc740 \uc5ec\ub7ec \uac1c\uc9c0\ub9cc, \ucf54\ub4dc\ub294 \ud55c \ub808\ud3ec\uc5d0</span> \ub450\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\ub9e4\uc7a5\uc740 \uc5ec\ub7ec \uacf3\uc774\uc9c0\ub9cc \uacf5\uc6a9 \ucc3d\uace0\uc640 \uacf5\uc6a9 \uc8fc\ubc29\uc744 \ud568\uaed8 \uc4f0\ub294 \uc2dd\uc785\ub2c8\ub2e4. \ubc84\ud2bc\xb7\uc785\ub825\ucc3d \uac19\uc740 \uacf5\ud1b5 \uc694\uc18c, \ub85c\uadf8\uc778 \ucc98\ub9ac \uac19\uc740 \uacf5\ud1b5 \uae30\ub2a5\uc740 \uacf5\uc6a9 \ud328\ud0a4\uc9c0\ub85c \ube7c\uc11c \ubaa8\ub4e0 \uc571\uc774 \uac19\uc740 \uac83\uc744 \uac00\uc838\ub2e4 \uc501\ub2c8\ub2e4.\\n\\n- \uacf5\ud1b5 \ub514\uc790\uc778 \uc694\uc18c\ub97c \ud55c \ubc88 \uace0\uce58\uba74 \ubaa8\ub4e0 \uc571\uc5d0 \ubc18\uc601\ub429\ub2c8\ub2e4.\\n- \ub85c\uadf8\uc778 \ucc98\ub9ac\ub3c4 \ud55c \uacf3\uc5d0\ub9cc \ub450\uace0 \uac01 \uc571\uc774 \ubd88\ub7ec \uc501\ub2c8\ub2e4.\\n- \uadf8\ub7ec\uba74\uc11c\ub3c4 \uc571\uc740 \uac01\uac01 \ub3c5\ub9bd\uc801\uc73c\ub85c \ube4c\ub4dc\xb7\ubc30\ud3ec\ub429\ub2c8\ub2e4. \ud55c \uc571\uc744 \uace0\uccd0\ub3c4 \ub2e4\ub978 \uc571\uc744 \ub2e4\uc2dc \ubc30\ud3ec\ud560 \ud544\uc694\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uc774 \uad6c\uc870\ub97c \ub9cc\ub4e4\uc5b4 \uc8fc\ub294 \ub3c4\uad6c(Turborepo, pnpm)\uac00 \\"\uc5b4\ub5a4 \uc571\uc774 \uc5b4\ub5a4 \uacf5\uc6a9 \ud328\ud0a4\uc9c0\ub97c \uc4f0\ub294\uc9c0\\"\ub97c \ucd94\uc801\ud574\uc11c, \ubc14\ub010 \ubd80\ubd84\uacfc \uc5f0\uad00\ub41c \uc571\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud574 \uc90d\ub2c8\ub2e4.\\n\\n## \ube4c\ub4dc\uc5d0 \ubc15\uc73c\uba74 \uc548 \ub418\ub294 \uac83\\n\\n\uc5ec\uae30\uc11c [4\ud3b8](/blog/one-repo-saas-and-onprem)\uc758 \uc628\ud504\ub808\ubbf8\uc2a4 \uc774\uc57c\uae30\uc640 \ub2e4\uc2dc \ub9cc\ub0ac\uc2b5\ub2c8\ub2e4.\\n\\n\ud654\uba74 \uc571(SPA)\uc740 \ubcf4\ud1b5 \ud55c \ubc88 \ube4c\ub4dc\ud574\uc11c \uc644\uc131\ub41c \ud30c\uc77c \ubb36\uc74c\uc744 \ub9cc\ub4e4\uace0, \uadf8\uac78 \ubc30\ud3ec\ud569\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uc774 \uc571\uc740 \ubc31\uc5d4\ub4dc API \uc8fc\uc18c\ub97c \uc54c\uc544\uc57c \ud558\uace0, \uadf8 \uc8fc\uc18c\uac00 \uace0\uac1d\uc0ac\ub9c8\ub2e4 \ub2e4\ub985\ub2c8\ub2e4. \uc6b0\ub9ac \ud074\ub77c\uc6b0\ub4dc\ub294 \uc6b0\ub9ac \uc8fc\uc18c\ub97c \uc4f0\uc9c0\ub9cc, \uc628\ud504\ub808\ubbf8\uc2a4\ub294 \uace0\uac1d\uc0ac \uc548\uc758 \uc8fc\uc18c\ub97c \uc501\ub2c8\ub2e4.\\n\\nAPI \uc8fc\uc18c\ub97c \ube4c\ub4dc\ud560 \ub54c \ucf54\ub4dc\uc5d0 \ubc15\uc544 \ubc84\ub9ac\uba74, \uace0\uac1d\uc0ac \uc218\ub9cc\ud07c \uc571\uc744 \ub2e4\uc2dc \ube4c\ub4dc\ud574\uc57c \ud569\ub2c8\ub2e4. \uc774\uac74 \uace7 \ubb34\ub108\uc9d1\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/one-codebase-many-web-apps-2.webp\\"\\n    alt=\\"\uc8fc\uc18c\ub97c \ube4c\ub4dc\uc5d0 \ubc15\ub294 \ubc29\uc2dd\uacfc \ucf24 \ub54c \uc124\uc815\uc744 \uc77d\ub294 \ubc29\uc2dd\uc758 \ube44\uad50\\"\\n  />\\n</figure>\\n\\n:::info \uc8fc\uc18c\ub97c \uc0c8\uae34 \ubd95\uc5b4\ube75 \ud2c0\\n\ubd95\uc5b4\ube75 \ud2c0\uc5d0 \uac00\uac8c \uc8fc\uc18c\ub97c \ubbf8\ub9ac \uc0c8\uaca8\uc11c \uad6c\uc6b0\uba74, \uac00\uac8c\uac00 \ub298 \ub54c\ub9c8\ub2e4 \ud2c0\uc744 \uc0c8\ub85c \ud30c\uc57c \ud569\ub2c8\ub2e4. \ube75\uc740 \ud55c \ubc88\ub9cc \uad7d\uace0 \uad6c\uc6b4 \ub4a4\uc5d0 \uc8fc\uc18c \uc2a4\ud2f0\ucee4\ub97c \ubd99\uc774\uba74, \ud2c0\uc740 \ud558\ub098\ub85c \ucda9\ubd84\ud569\ub2c8\ub2e4.\\n:::\\n\\n\uadf8\ub798\uc11c \uc8fc\uc18c \uac19\uc740 \ud658\uacbd\ubcc4 \uc124\uc815\uc744 \ube4c\ub4dc\uc5d0 \ubc15\uc9c0 \uc54a\uace0, \uc571\uc774 \ucf1c\uc9c8 \ub54c \uc77d\ub294 \\"\uc124\uc815 \ucabd\uc9c0\\"\ub85c \ube90\uc2b5\ub2c8\ub2e4. \uc571\uc740 \ud55c \ubc88\ub9cc \ube4c\ub4dc\ud558\uace0, \uc124\uce58\ub418\ub294 \ud658\uacbd\uc5d0 \ub9de\ub294 \uc124\uc815 \ucabd\uc9c0\ub9cc \uac08\uc544 \ub07c\uc6c1\ub2c8\ub2e4. \uac19\uc740 \uc571\uc774 \ud658\uacbd\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc8fc\uc18c\ub97c \ubc14\ub77c\ubcf4\uac8c \ub429\ub2c8\ub2e4.\\n\\n## \uce90\uc2dc\uac00 \uc61b \uc124\uc815 \ucabd\uc9c0\ub97c \ub4e4\uace0 \uc788\uc5c8\ub2e4\\n\\n\uc124\uc815 \ucabd\uc9c0 \ubc29\uc2dd\uc5d0\ub3c4 \ud568\uc815\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ud654\uba74 \ud30c\uc77c\uc740 \ube60\ub978 \uc751\ub2f5\uc744 \uc704\ud574 CDN(\ucf58\ud150\uce20 \uc804\uc1a1\ub9dd)\uc5d0 \uce90\uc2dc\ub418\ub294\ub370, \uce90\uc2dc\uac00 \uc124\uc815 \ucabd\uc9c0\uae4c\uc9c0 \ud568\uaed8 \ub4e4\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \uc124\uc815\uc744 \ubc14\uafd4\ub3c4 CDN\uc774 \uc61b\ub0a0 \ucabd\uc9c0\ub97c \uacc4\uc18d \ub0b4\uc8fc\ub294 \uc77c\uc774 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4. \uc0c8 \uc8fc\uc18c\ub85c \ubc14\uafe8\ub294\ub370 \uc571\uc740 \uc5ec\uc804\ud788 \uc61b \uc8fc\uc18c\ub97c \ubc14\ub77c\ubd24\uc2b5\ub2c8\ub2e4.\\n\\n\ud574\uacb0\uc740 \ub2e8\uc21c\ud588\uc2b5\ub2c8\ub2e4. \ub2e4\ub978 \ud30c\uc77c\uc740 \uce90\uc2dc\ud558\ub418, \uc124\uc815 \ucabd\uc9c0\ub9cc\uc740 \\"\uce90\uc2dc\ud558\uc9c0 \ub9d0 \uac83\\"\uc73c\ub85c \ud45c\uc2dc\ud588\uc2b5\ub2c8\ub2e4. \uc571\uc774 \ucf1c\uc9c8 \ub54c\ub9c8\ub2e4 \ud56d\uc0c1 \ucd5c\uc2e0 \ucabd\uc9c0\ub97c \uc77d\ub3c4\ub85d\uc694.\\n\\n\uc774\uac83\ub3c4 \uc55e\uc120 \uc0ac\uace0\ub4e4\uacfc \uac19\uc740 \uacb0\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \\"\ube60\ub974\uac8c \ud558\ub824\uace0 \uce90\uc2dc\ud55c\ub2e4\\"\ub294 \uc88b\uc740 \uae30\ubcf8\uac12\uc774, \uc790\uc8fc \ubc14\ub00c\uc5b4\uc57c \ud558\ub294 \ud30c\uc77c\uc5d0\ub294 \ub3c5\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uae30\ubcf8\uac12\uc774 \ud56d\uc0c1 \ub9de\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uac78 \ub610 \ubc30\uc6e0\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n\ud654\uba74 \ucabd \uc77c\uc744 \ud558\uba74\uc11c \ub4a4\ucabd\uc5d0\uc11c \ubc30\uc6b4 \uac78 \uadf8\ub300\ub85c \ub2e4\uc2dc \ubc30\uc6e0\uc2b5\ub2c8\ub2e4.\\n\\n- \uc571\uc774 \uc5ec\ub7ec \uac1c\uc5ec\ub3c4 \uacb9\uce58\ub294 \ubd80\ubd84\uc774 \ub9ce\uc73c\uba74 \uacf5\uc6a9 \ud328\ud0a4\uc9c0\ub85c \ube7c\uc11c \ud55c \ub808\ud3ec\uc5d0 \ub450\ub294 \ud3b8\uc774 \ub098\uc558\uc2b5\ub2c8\ub2e4. \uc571\uc740 \uac01\uac01 \ub3c5\ub9bd\uc801\uc73c\ub85c \ubc30\ud3ec\ud569\ub2c8\ub2e4.\\n- \ud658\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \uac12\uc740 \ube4c\ub4dc\uc5d0 \ubc15\uc9c0 \uc54a\uace0 \ucf24 \ub54c \uc77d\ub294 \uc124\uc815\uc73c\ub85c \ube90\uc2b5\ub2c8\ub2e4. \uace0\uac1d\uc0ac\uac00 \ub298\uc5b4\ub3c4 \ub2e4\uc2dc \ube4c\ub4dc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n- \uce90\uc2dc\ub294 \ube60\ub974\uc9c0\ub9cc, \uc790\uc8fc \ubc14\ub00c\ub294 \uc124\uc815 \ud30c\uc77c\uc5d0\ub294 \uce90\uc2dc\ub97c \uaebc\uc57c \ud588\uc2b5\ub2c8\ub2e4.\\n- \ubc31\uc5d4\ub4dc\ub4e0 \ud504\ub860\ud2b8\ub4e0 \uacb0\uad6d \uac19\uc740 \ubb38\uc7a5\uc774\uc5c8\uc2b5\ub2c8\ub2e4. **\uacf5\ud1b5\uc740 \ud55c\uacf3\uc5d0 \ubaa8\uc73c\uace0, \ud658\uacbd \ucc28\uc774\ub294 \uac00\uc7a5\uc790\ub9ac\uc5d0\uc11c \ud761\uc218\ud55c\ub2e4.**\\n\\n\ub2e4\uc74c \ud3b8\uc5d0\uc11c\ub294 \ub9cc\ub4dc\ub294 \ub2e8\uacc4\uc5d0\uc11c \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\ub85c \ub118\uc5b4\uac00\uba70 \ubc14\ub010 \uac83\ub4e4\uc744 \uc801\uc5b4 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ubc84\uc804\uc744 \ubd99\uc774\uace0, \ubc30\ud3ec\ub97c \uc790\ub3d9\ud654\ud558\uace0, \ubb34\uc5c7\uc774 \ub3c4\ub294\uc9c0 \ub4e4\uc5ec\ub2e4\ubcf4\uac8c \ub41c \uacfc\uc815\uc785\ub2c8\ub2e4."},{"id":"one-repo-saas-and-onprem","metadata":{"permalink":"/blog/one-repo-saas-and-onprem","source":"@site/blog/2026-06-15-one-repo-saas-and-onprem/index.md","title":"\ud558\ub098\uc758 \ub808\ud3ec\ub85c \ud074\ub77c\uc6b0\ub4dc SaaS\uc640 \uc628\ud504\ub808\ubbf8\uc2a4\ub97c \ud568\uaed8 \uc6b4\uc601\ud558\uae30","description":"\uac19\uc740 \ucf54\ub4dc\ub97c \ud074\ub77c\uc6b0\ub4dc(AWS) SaaS\uc640 \uace0\uac1d\uc0ac \uc548\uc758 \ucfe0\ubc84\ub124\ud2f0\uc2a4(\uc628\ud504\ub808\ubbf8\uc2a4) \uc591\ucabd\uc5d0\uc11c \ub3cc\ub9b0 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4. \ud2b9\ud788 \uc778\ud130\ub137\uc774 \ub9c9\ud78c \uacf3\uc5d0 \uc5b4\ub5bb\uac8c \uc124\uce58\ud588\ub294\uc9c0\ub97c \ub2e4\ub8f9\ub2c8\ub2e4.","date":"2026-06-15T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"Architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"Infra","permalink":"/blog/tags/infra"},{"inline":true,"label":"Kubernetes","permalink":"/blog/tags/kubernetes"},{"inline":true,"label":"Retrospective","permalink":"/blog/tags/retrospective"},{"inline":true,"label":"BuildLog","permalink":"/blog/tags/build-log"}],"readingTime":2.12,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ud558\ub098\uc758 \ub808\ud3ec\ub85c \ud074\ub77c\uc6b0\ub4dc SaaS\uc640 \uc628\ud504\ub808\ubbf8\uc2a4\ub97c \ud568\uaed8 \uc6b4\uc601\ud558\uae30","slug":"one-repo-saas-and-onprem","authors":["kgenots"],"tags":["Tech","Architecture","Infra","Kubernetes","Retrospective","BuildLog"],"image":"/assets/blog/cover-one-repo-saas-and-onprem.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub85c \uc5ec\ub7ec \uc6f9 \uc571 \ub9cc\ub4e4\uae30","permalink":"/blog/one-codebase-many-web-apps"},"nextItem":{"title":"\uc11c\ube44\uc2a4 \uc0ac\uc774\ub97c \uc787\ub294 \ubc95, \uc774\ubca4\ud2b8 \ubc84\uc2a4\uc640 \uc6cc\ud06c\ud50c\ub85c\uc6b0","permalink":"/blog/event-bus-nats-temporal"}},"content":"\uac19\uc740 \ucf54\ub4dc\ub97c \ud074\ub77c\uc6b0\ub4dc(AWS) SaaS\uc640 \uace0\uac1d\uc0ac \uc548\uc758 \ucfe0\ubc84\ub124\ud2f0\uc2a4(\uc628\ud504\ub808\ubbf8\uc2a4) \uc591\ucabd\uc5d0\uc11c \ub3cc\ub9b0 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4. \ud2b9\ud788 \uc778\ud130\ub137\uc774 \ub9c9\ud78c \uacf3\uc5d0 \uc5b4\ub5bb\uac8c \uc124\uce58\ud588\ub294\uc9c0\ub97c \ub2e4\ub8f9\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n[1\ud3b8](/blog/monorepo-15-service-msa)\uc5d0\uc11c \uc11c\ube44\uc2a4\ub97c \ud55c \ub808\ud3ec\uc5d0 \ubaa8\uc558\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ucf54\ub4dc\ub97c \ub3cc\ub824\uc57c \ud558\ub294 \uacf3\uc774 \ud55c \uad70\ub370\uac00 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n- \ud558\ub098\ub294 \uc6b0\ub9ac\uac00 \uc9c1\uc811 \uc6b4\uc601\ud558\ub294 \ud074\ub77c\uc6b0\ub4dc SaaS\uc785\ub2c8\ub2e4. AWS \uc704\uc5d0\uc11c \uc6b0\ub9ac\uac00 \uad00\ub9ac\ud569\ub2c8\ub2e4.\\n- \ub2e4\ub978 \ud558\ub098\ub294 \uc628\ud504\ub808\ubbf8\uc2a4\uc785\ub2c8\ub2e4. \uace0\uac1d\uc0ac \ub370\uc774\ud130\uc13c\ud130 \uc548\uc758 \ucfe0\ubc84\ub124\ud2f0\uc2a4\uc5d0 \uc81c\ud488\uc744 \ud1b5\uc9f8\ub85c \uc124\uce58\ud574 \ub4dc\ub9bd\ub2c8\ub2e4. \ub370\uc774\ud130\uac00 \ud68c\uc0ac \ubc16\uc73c\ub85c \ubabb \ub098\uac00\ub294 \uacf3\uc744 \uc704\ud574\uc11c\uc785\ub2c8\ub2e4.\\n\\n\uac19\uc740 \uc81c\ud488\uc778\ub370 \uc6b4\uc601 \ud658\uacbd\uc774 \uc815\ubc18\ub300\uc600\uc2b5\ub2c8\ub2e4. \ud55c\ucabd\uc740 \uc778\ud130\ub137\uc5d0 \ud65c\uc9dd \uc5f4\ub824 \uc788\uace0, \ud55c\ucabd\uc740 \uc778\ud130\ub137\uc774 \uc544\uc608 \ub9c9\ud600 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \ub458\uc744 **\ud558\ub098\uc758 \ub808\ud3ec\ub85c** \uac10\ub2f9\ud55c \ubc29\ubc95\uc744 \uc801\uc5b4 \ubd05\ub2c8\ub2e4.\\n\\n## \ud55c \ub808\uc2dc\ud53c, \ub450 \uc8fc\ubc29\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/one-repo-saas-and-onprem.webp\\"\\n    alt=\\"\ud558\ub098\uc758 \ub808\ud3ec\uc5d0\uc11c AWS SaaS\uc640 \uc628\ud504\ub808\ubbf8\uc2a4 \ucfe0\ubc84\ub124\ud2f0\uc2a4 \ub450 \ud658\uacbd\uc73c\ub85c \ubc30\ud3ec\ud558\ub294 \uad6c\uc870\\"\\n  />\\n</figure>\\n\\n\uac19\uc740 \uc694\ub9ac\ub97c \ub450 \uc8fc\ubc29\uc5d0\uc11c \ub9cc\ub4dc\ub294 \uc77c\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \ud558\ub098\ub294 \ubaa8\ub4e0 \uc124\ube44\uac00 \uac16\ucdb0\uc9c4 \ud070 \uc911\uc559 \uc8fc\ubc29(\ud074\ub77c\uc6b0\ub4dc)\uc774\uace0, \ud558\ub098\ub294 \uace0\uac1d\uc758 \uc9d1 \uc8fc\ubc29(\uc628\ud504\ub808\ubbf8\uc2a4)\uc785\ub2c8\ub2e4. \uc9d1 \uc8fc\ubc29\uc5d0\ub294 \uc6b0\ub9ac\uac00 \uc4f0\ub358 \uc124\ube44\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\ub808\uc2dc\ud53c(\ucf54\ub4dc)\ub97c \ub450 \ubc8c\ub85c \ub098\ub204\uba74 \uad00\ub9ac\uac00 \ubb34\ub108\uc9d1\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub808\uc2dc\ud53c\ub294 \ud55c \ubc8c\ub85c \ub450\uace0, \ud658\uacbd\uc5d0 \ub530\ub77c \ubd80\ud488\ub9cc \ubc14\uafd4 \ub07c\uc6e0\uc2b5\ub2c8\ub2e4.\\n\\n\ud658\uacbd\ub9c8\ub2e4 \ub2ec\ub77c\uc9c0\ub294 \ubd80\ubd84\uc740 \ucf54\ub4dc \ubcf8\ubb38\uc5d0\uc11c \ub5bc\uc5b4\ub0b4 \uac08\uc544 \ub07c\uc6b8 \uc218 \uc788\ub294 \ubd80\ud488\uc73c\ub85c \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \ub178\ud2b8\ubd81(\ucf54\ub4dc)\uc740 \uadf8\ub300\ub85c \uc4f0\uace0, \ub098\ub77c(\ud658\uacbd)\uac00 \ubc14\ub00c\uba74 \ucf58\uc13c\ud2b8 \uc5b4\ub311\ud130\ub9cc \ubc14\uafb8\ub294 \uc2dd\uc785\ub2c8\ub2e4.\\n\\n| \uac08\uc544 \ub07c\uc6b4 \ubd80\ud488 | \ud074\ub77c\uc6b0\ub4dc(SaaS) | \uc628\ud504\ub808\ubbf8\uc2a4 |\\n| --- | --- | --- |\\n| \ub85c\uadf8\uc778 | \ud074\ub77c\uc6b0\ub4dc \uad00\ub9ac\ud615 \uc778\uc99d | \uc9c1\uc811 \ub744\uc6b0\ub294 \uc778\uc99d \uc11c\ubc84 |\\n| \ud30c\uc77c \uc800\uc7a5\uc18c | AWS S3 | S3 \ud638\ud658 \uc800\uc7a5\uc18c(\uc9c1\uc811 \uc124\uce58) |\\n| \uc2e4\ud589 \ud658\uacbd | \uad00\ub9ac\ud615 \ucee8\ud14c\uc774\ub108 | \uace0\uac1d\uc0ac \ucfe0\ubc84\ub124\ud2f0\uc2a4 |\\n\\n\ucf54\ub4dc \uc785\uc7a5\uc5d0\uc11c\ub294 \\"\ud30c\uc77c\uc744 \uc800\uc7a5\ud55c\ub2e4\\"\ub9cc \uc54c\uba74 \ub429\ub2c8\ub2e4. \uadf8\uac83\uc774 AWS S3\uc778\uc9c0 \uc9c1\uc811 \uc124\uce58\ud55c \uc800\uc7a5\uc18c\uc778\uc9c0\ub294 \ud658\uacbd \ubcc0\uc218\ub85c \uc815\ud55c \ubd80\ud488\uc774 \ucc98\ub9ac\ud569\ub2c8\ub2e4. \ubcf8\ubb38 \ucf54\ub4dc\ub294 \uc5b4\ub290 \ud658\uacbd\uc778\uc9c0 \ubab0\ub77c\ub3c4 \ub3d9\uc791\ud569\ub2c8\ub2e4.\\n\\n\uc774 \ud328\ud134 \ub355\ubd84\uc5d0 \uc0c8 \uae30\ub2a5\uc744 \ub9cc\ub4e4 \ub54c \\"\uc774\uac74 \ud074\ub77c\uc6b0\ub4dc\uc6a9, \uc774\uac74 \uc628\ud504\ub808\uc6a9\\"\uc73c\ub85c \ub098\ub220 \uc9e4 \ud544\uc694\uac00 \uc5c6\uc5c8\uc2b5\ub2c8\ub2e4. \ud55c \ubc88 \uc9dc\uba74 \uc591\ucabd\uc5d0\uc11c \ub3d5\ub2c8\ub2e4.\\n\\n## \uc774\ubbf8\uc9c0\ub294 \ub450 \ubc8c\ub85c\\n\\n\ucf54\ub4dc\ub294 \ud55c \ubc8c\uc774\uc9c0\ub9cc, \ubc30\ud3ec \uc774\ubbf8\uc9c0\ub294 \ud658\uacbd\uc5d0 \ub530\ub77c \uc870\uae08 \ub2ec\ub790\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc628\ud504\ub808\ubbf8\uc2a4 \ucabd \uc774\ubbf8\uc9c0\uc5d0\ub294 \ucfe0\ubc84\ub124\ud2f0\uc2a4\uac00 \uc11c\ube44\uc2a4 \uc0c1\ud0dc\ub97c \ud655\uc778\ud560 \ub54c \uc4f0\ub294 \uc791\uc740 \ub3c4\uad6c(\uc0c1\ud0dc \uc810\uac80\uae30)\ub97c \ud568\uaed8 \ub123\uc5b4\uc57c \ud588\uc2b5\ub2c8\ub2e4. \ud074\ub77c\uc6b0\ub4dc \ucabd\uacfc \uc810\uac80 \ubc29\uc2dd\uc774 \ub2ec\ub790\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4([2\ud3b8](/blog/auth-bff-redirect-loop) \uc606 \ub3d9\ub124\uc778 \ud5ec\uc2a4\uccb4\ud06c \uc774\uc57c\uae30\uc640 \ub2ff\uc544 \uc788\uc2b5\ub2c8\ub2e4).\\n\\n\uc774\ub7f0 \ucc28\uc774\ub294 \ube4c\ub4dc \uc124\uc815(Dockerfile)\uc744 \ud658\uacbd\ubcc4\ub85c \ub450 \ubc8c \ub450\uc5b4 \ud761\uc218\ud588\uc2b5\ub2c8\ub2e4. \ubcf8\ubb38 \ucf54\ub4dc\ub294 \uadf8\ub300\ub85c \ub450\uace0 \ud3ec\uc7a5 \ub2e8\uacc4\uc5d0\uc11c\ub9cc \uac08\ub77c\uc9c0\uac8c \ud588\uc2b5\ub2c8\ub2e4.\\n\\n## \uac00\uc7a5 \ud070 \ubcbd, \uc778\ud130\ub137\uc774 \uc5c6\ub2e4\\n\\n\uc628\ud504\ub808\ubbf8\uc2a4\uc5d0\uc11c\ub294 <span style={{ backgroundColor: \'#ffdce0\'}}>\uc778\ud130\ub137\uc774 \uc544\uc608 \ub9c9\ud600 \uc788\uc2b5\ub2c8\ub2e4</span>(\uc5d0\uc5b4\uac2d, air-gap). \uc774\uac8c \uac00\uc7a5 \ud070 \ubcbd\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \ud074\ub77c\uc6b0\ub4dc\uc5d0\uc11c\ub294 \ud544\uc694\ud55c \ud504\ub85c\uadf8\ub7a8\uc774\ub098 \uc774\ubbf8\uc9c0\ub97c \uadf8\ub54c\uadf8\ub54c \uc778\ud130\ub137\uc5d0\uc11c \ubc1b\uc544\uc624\uba74 \ub429\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uace0\uac1d\uc0ac \uc548\uc5d0\uc11c\ub294 \uadf8\uac8c \ubd88\uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/one-repo-saas-and-onprem-2.webp\\"\\n    alt=\\"\uc778\ud130\ub137\uc774 \uc5f4\ub9b0 \ud074\ub77c\uc6b0\ub4dc\uc640 \uc778\ud130\ub137\uc774 \ub9c9\ud78c \uc628\ud504\ub808\ubbf8\uc2a4\uc758 \uc124\uce58 \ubc29\uc2dd \ube44\uad50\\"\\n  />\\n</figure>\\n\\n:::info \ube44\uc720\ub85c \ubcf4\uba74\\n\uc778\ud130\ub137\uc774 \ub418\ub294 \uacf3\uc5d0\uc11c\uc758 \uc124\uce58\ub294 \ub9c8\ud2b8\uac00 \uc606\uc5d0 \uc788\ub294 \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc7ac\ub8cc\uac00 \ub5a8\uc5b4\uc9c0\uba74 \uc0ac \uc624\uba74 \ub429\ub2c8\ub2e4. \uc5d0\uc5b4\uac2d \uc124\uce58\ub294 \uc804\uae30\ub3c4 \uc778\ud130\ub137\ub3c4 \uc5c6\ub294 \uc0b0\uc7a5\uc5d0 \ub4e4\uc5b4\uac00 \uc0b4\ub9bc\uc744 \ucc28\ub9ac\ub294 \uc77c\uc785\ub2c8\ub2e4. \ud544\uc694\ud55c \uc7ac\ub8cc\ub97c \ud558\ub098\ub3c4 \ube60\uc9d0\uc5c6\uc774 \ubbf8\ub9ac \uc2f8 \ub4e4\uace0 \uac00\uc57c \ud569\ub2c8\ub2e4. \uac00\uc11c \ube60\uc9c4 \uac78 \ubc1c\uacac\ud558\uba74 \ub2a6\uc2b5\ub2c8\ub2e4.\\n:::\\n\\n\uadf8\ub798\uc11c \uc124\uce58 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc84c\uc2b5\ub2c8\ub2e4.\\n\\n- \uc81c\ud488\uc774 \ud544\uc694\ub85c \ud558\ub294 \ubaa8\ub4e0 \ucee8\ud14c\uc774\ub108 \uc774\ubbf8\uc9c0\ub97c \ubbf8\ub9ac \ubb36\uc74c\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \ud568\uaed8 \uac00\uc838\uac14\uc2b5\ub2c8\ub2e4.\\n- \uace0\uac1d\uc0ac \uc548\uc5d0 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac(\uc774\ubbf8\uc9c0 \ubcf4\uad00\uc18c)\ub97c \ub744\uc6b0\uace0, \ubb36\uc74c\uc744 \uac70\uae30\uc5d0 \ud480\uc5c8\uc2b5\ub2c8\ub2e4. \uc124\uce58\ub294 \uc778\ud130\ub137\uc774 \uc544\ub2c8\ub77c \uc774 \uc0ac\uc124 \ubcf4\uad00\uc18c\uc5d0\uc11c\ub9cc \uc774\ubbf8\uc9c0\ub97c \ubc1b\uc2b5\ub2c8\ub2e4.\\n\\n\uc5ec\uae30\uc11c\ub3c4 \ud55c \ubc88 \ub370\uc600\uc2b5\ub2c8\ub2e4. \uc0ac\uc124 \ubcf4\uad00\uc18c\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \ubc1b\ub294 \uc18d\ub3c4\uac00 \uc0dd\uac01\ubcf4\ub2e4 \ub290\ub838\uc2b5\ub2c8\ub2e4. \uc791\uc740 \uc774\ubbf8\uc9c0\ub294 \uad1c\ucc2e\uc558\uc9c0\ub9cc, <span style={{ backgroundColor: \'#ffdce0\'}}>\ud070 \uc774\ubbf8\uc9c0\ub294 \ubc1b\ub2e4\uac00 \uc2dc\uac04\uc774 \ub108\ubb34 \uac78\ub838\uc2b5\ub2c8\ub2e4.</span> \uacb0\uad6d \uc6a9\ub7c9\uc774 \ud070 \uc774\ubbf8\uc9c0\ub294 \ubcf4\uad00\uc18c\ub97c \uac70\uce58\uc9c0 \uc54a\uace0 \ucee8\ud14c\uc774\ub108 \ub7f0\ud0c0\uc784\uc73c\ub85c \uc9c1\uc811 \uac00\uc838\uc624\ub294 \ubc29\uc2dd\uc73c\ub85c \uc6b0\ud68c\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\uc124\uce58 \uc2a4\ud06c\ub9bd\ud2b8\ub3c4 \ucc98\uc74c\uc5d4 \uc778\ud130\ub137\uc774 \ub418\ub294 \ud658\uacbd\uc744 \uac00\uc815\ud558\uace0 \uc9dc\uc5ec \uc788\uc5b4, \ub9c9\ud78c \ud658\uacbd\uc5d0\uc11c \uba87 \uad70\ub370\uac00 \uba48\ucdc4\uc2b5\ub2c8\ub2e4. \\"\ubc1b\uc544\uc62c \uc218 \uc788\ub2e4\\"\ub294 \uac00\uc815\uc774 \ucf54\ub4dc \uacf3\uacf3\uc5d0 \uc228\uc5b4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8 \uac00\uc815\uc744 \ud558\ub098\uc529 \ucc3e\uc544 \uac77\uc5b4\ub0c8\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n- \uac19\uc740 \uc81c\ud488\uc744 \ud074\ub77c\uc6b0\ub4dc SaaS\uc640 \uc628\ud504\ub808\ubbf8\uc2a4 \uc591\ucabd\uc5d0\uc11c \uc6b4\uc601\ud574\uc57c \ud588\uc2b5\ub2c8\ub2e4. \ud55c\ucabd\uc740 \uc778\ud130\ub137\uc5d0 \uc5f4\ub824 \uc788\uace0, \ud55c\ucabd\uc740 \ub9c9\ud600 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ub808\uc2dc\ud53c(\ucf54\ub4dc)\ub294 \ud55c \ubc8c\ub85c \ub450\uace0, **\ud658\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \ubd80\ubd84\ub9cc \uac08\uc544 \ub07c\uc6b0\ub294 \ubd80\ud488**\uc73c\ub85c \ube90\uc2b5\ub2c8\ub2e4(\ub85c\uadf8\uc778\xb7\uc800\uc7a5\uc18c\xb7\uc2e4\ud589 \ud658\uacbd). \ubcf8\ubb38 \ucf54\ub4dc\ub294 \uc5b4\ub290 \ud658\uacbd\uc778\uc9c0 \ubaa8\ub985\ub2c8\ub2e4.\\n- \ud658\uacbd \ucc28\uc774\ub294 \uac00\ub2a5\ud55c \ud55c **\ubcf8\ubb38\uc774 \uc544\ub2c8\ub77c \uac00\uc7a5\uc790\ub9ac**(\ube4c\ub4dc \uc124\uc815, \ud658\uacbd \ubcc0\uc218, \uc124\uce58 \ub2e8\uacc4)\uc5d0\uc11c \ud761\uc218\ud588\uc2b5\ub2c8\ub2e4.\\n- \uc5d0\uc5b4\uac2d \uc124\uce58\ub294 \\"\ud544\uc694\ud560 \ub54c \ubc1b\uc544\uc628\ub2e4\\"\ub294 \uac00\uc815\uc744 \ubaa8\ub450 \uac77\uc5b4\ub0b4\uace0, **\ud544\uc694\ud55c \uac83\uc744 \uc804\ubd80 \uc2f8 \ub4e4\uace0 \uac00\ub294** \ubc29\uc2dd\uc73c\ub85c \ubc14\uafd4\uc57c \ud588\uc2b5\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c \ud3b8\uc5d0\uc11c\ub294 \ud654\uba74(\ud504\ub860\ud2b8\uc5d4\ub4dc) \ucabd \uc774\uc57c\uae30\ub97c \ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub85c \uc5ec\ub7ec \uac1c\uc758 \uc6f9 \uc571\uc744 \ub9cc\ub4e4\uace0 \ubc30\ud3ec\ud55c \ubc29\ubc95\uc744 \uc801\uc5b4 \ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4."},{"id":"event-bus-nats-temporal","metadata":{"permalink":"/blog/event-bus-nats-temporal","source":"@site/blog/2026-06-14-event-bus-nats-temporal/index.md","title":"\uc11c\ube44\uc2a4 \uc0ac\uc774\ub97c \uc787\ub294 \ubc95, \uc774\ubca4\ud2b8 \ubc84\uc2a4\uc640 \uc6cc\ud06c\ud50c\ub85c\uc6b0","description":"\uc11c\ube44\uc2a4\ub97c \ube44\ub3d9\uae30\ub85c \uc787\ub294 \ub450 \ub3c4\uad6c(NATS \uc774\ubca4\ud2b8 \ubc84\uc2a4, Temporal \uc6cc\ud06c\ud50c\ub85c\uc6b0)\ub97c \uc0b4\ud3b4\ubcf4\uace0, \uba54\uc2dc\uc9c0 \ubcf4\uad00 \uae30\uac04\uc744 \uc798\ubabb \uc7a1\uc544 \ub370\uc778 \uc0ac\uace0\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-14T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"Architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"Backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"Retrospective","permalink":"/blog/tags/retrospective"},{"inline":true,"label":"BuildLog","permalink":"/blog/tags/build-log"}],"readingTime":2.43,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\uc11c\ube44\uc2a4 \uc0ac\uc774\ub97c \uc787\ub294 \ubc95, \uc774\ubca4\ud2b8 \ubc84\uc2a4\uc640 \uc6cc\ud06c\ud50c\ub85c\uc6b0","slug":"event-bus-nats-temporal","authors":["kgenots"],"tags":["Tech","Architecture","Backend","Retrospective","BuildLog"],"image":"/assets/blog/cover-event-bus-nats-temporal.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ud558\ub098\uc758 \ub808\ud3ec\ub85c \ud074\ub77c\uc6b0\ub4dc SaaS\uc640 \uc628\ud504\ub808\ubbf8\uc2a4\ub97c \ud568\uaed8 \uc6b4\uc601\ud558\uae30","permalink":"/blog/one-repo-saas-and-onprem"},"nextItem":{"title":"\uc778\uc99d\uc744 \ubd99\uc774\ub2e4 \ub9cc\ub09c \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504","permalink":"/blog/auth-bff-redirect-loop"}},"content":"\uc11c\ube44\uc2a4\ub97c \ube44\ub3d9\uae30\ub85c \uc787\ub294 \ub450 \ub3c4\uad6c(NATS \uc774\ubca4\ud2b8 \ubc84\uc2a4, Temporal \uc6cc\ud06c\ud50c\ub85c\uc6b0)\ub97c \uc0b4\ud3b4\ubcf4\uace0, \uba54\uc2dc\uc9c0 \ubcf4\uad00 \uae30\uac04\uc744 \uc798\ubabb \uc7a1\uc544 \ub370\uc778 \uc0ac\uace0\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n[\uc9c0\ub09c \ud3b8](/blog/auth-bff-redirect-loop)\uae4c\uc9c0 \uc11c\ube44\uc2a4\ub97c \ub098\ub204\uace0, \uac70\uae30\uc5d0 \ub85c\uadf8\uc778\uc744 \ubd99\uc600\uc2b5\ub2c8\ub2e4. \uc774\ubc88\uc5d0\ub294 \ub098\ub25c \uc11c\ube44\uc2a4\ub4e4\uc774 \uc11c\ub85c \uc5b4\ub5bb\uac8c \uc774\uc57c\uae30\ub97c \uc8fc\uace0\ubc1b\ub294\uc9c0\ub97c \ub2e4\ub904 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n## \uc9c1\uc811 \ubd80\ub974\uba74 \ud568\uaed8 \ub118\uc5b4\uc9d1\ub2c8\ub2e4\\n\\n\uc11c\ube44\uc2a4 A\uac00 \uc77c\uc744 \ub05d\ub0b8 \ub4a4 B\uc5d0\uac8c \uc54c\ub824\uc57c \ud55c\ub2e4\uace0 \ud574\ubd05\uc2dc\ub2e4. \uac00\uc7a5 \ub2e8\uc21c\ud558\uac8c\ub294 A\uac00 B\ub97c \uc9c1\uc811 \ud638\ucd9c\ud558\uba74 \ub429\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc9c1\uc811 \ud638\ucd9c\uc5d0\ub294 \ud568\uc815\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nA\uac00 B\uc5d0\uac8c \uc804\ud654\ub97c \uac78\uba74, B\uac00 \ubc1b\uc744 \ub54c\uae4c\uc9c0 A\ub294 \uc218\ud654\uae30\ub97c \ub4e4\uace0 \uae30\ub2e4\ub824\uc57c \ud569\ub2c8\ub2e4. B\uac00 \ubc14\uc058\uac70\ub098 \uc7a0\uc2dc \uc8fd\uc5b4 \uc788\uc73c\uba74, A\ub3c4 \ud568\uaed8 \uba48\ucda5\ub2c8\ub2e4. \ud55c \uc11c\ube44\uc2a4\uc758 \uc7a5\uc560\uac00 \uc804\ud654\uc120\uc744 \ud0c0\uace0 \uc606\uc73c\ub85c \ubc88\uc9c0\ub294 \uac83\uc774\uc9c0\uc694.\\n\\n\uac8c\ub2e4\uac00 \\"\uacb0\uc81c\uac00 \ub05d\ub0ac\ub2e4\\"\ub294 \uc0ac\uc2e4 \ud558\ub098\uc5d0 \uad00\uc2ec \uc788\ub294 \uc11c\ube44\uc2a4\uac00 \uc5ec\ub7ff\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc54c\ub9bc\ub3c4 \ubcf4\ub0b4\uc57c \ud558\uace0, \ud1b5\uacc4\ub3c4 \uc313\uc544\uc57c \ud558\uace0, \uc601\uc218\uc99d\ub3c4 \ubc1c\uae09\ud574\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub54c\ub9c8\ub2e4 A\uac00 \uc138 \uacf3\uc5d0 \uc804\ud654\ub97c \ub3cc\ub9ac\ub294 \uac83\uc740 \ubc88\uac70\ub86d\uace0, \ud55c \uacf3\uc774\ub77c\ub3c4 \uc548 \ubc1b\uc73c\uba74 A\uac00 \uba48\ucda5\ub2c8\ub2e4.\\n\\n## \uc0ac\uc2e4\uc740 \uac8c\uc2dc\ud310\uc5d0 \ubd99\uc785\ub2c8\ub2e4 (\uc774\ubca4\ud2b8 \ubc84\uc2a4, NATS)\\n\\n\uadf8\ub798\uc11c \uc9c1\uc811 \uc804\ud654 \ub300\uc2e0 \uac8c\uc2dc\ud310\uc744 \ub450\uc5c8\uc2b5\ub2c8\ub2e4. A\ub294 \\"\uacb0\uc81c\uac00 \ub05d\ub0ac\ub2e4\\"\ub97c \uac8c\uc2dc\ud310\uc5d0 \ubd99\uc774\uae30\ub9cc \ud569\ub2c8\ub2e4. \ub204\uac00 \ubcf4\ub294\uc9c0\ub294 \uc2e0\uacbd \uc4f0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uad00\uc2ec \uc788\ub294 \uc11c\ube44\uc2a4\uac00 \uc54c\uc544\uc11c \uc640\uc11c \uc77d\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/event-bus-nats-temporal.webp\\"\\n    alt=\\"\uc11c\ube44\uc2a4\ub97c \uc9c1\uc811 \ud638\ucd9c\ud558\uba74 \ud568\uaed8 \uba48\ucd94\ub294 \ubc29\uc2dd\uacfc, \uc774\ubca4\ud2b8 \uac8c\uc2dc\ud310\uc73c\ub85c \ubc1c\ud589\ud574 \ud544\uc694\ud55c \uc11c\ube44\uc2a4\uac00 \uace8\ub77c \uc77d\ub294 \ubc29\uc2dd\uc758 \ucc28\uc774\\"\\n  />\\n</figure>\\n\\n\uc774 \uac8c\uc2dc\ud310 \uc5ed\ud560\uc744 \ud558\ub294 \uac83\uc774 \uc774\ubca4\ud2b8 \ubc84\uc2a4(NATS)\uc785\ub2c8\ub2e4. <span style={{ backgroundColor: \'#fff5b1\'}}>\ubc1c\ud589\ud558\ub294 \ucabd\uc740 \uc218\uc2e0\uc790\ub97c \ubaa8\ub985\ub2c8\ub2e4.</span>\\n\\n- A\ub294 \uac8c\uc2dc\ud310\uc5d0 \uc0ac\uc2e4\uc744 \ubd99\uc774\uace0 \uc790\uae30 \uc77c\uc744 \uacc4\uc18d\ud569\ub2c8\ub2e4. B\uac00 \uc8fd\uc5b4 \uc788\uc5b4\ub3c4 A\ub294 \uba48\ucd94\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n- \uc54c\ub9bc\xb7\ud1b5\uacc4\xb7\uc601\uc218\uc99d \uc11c\ube44\uc2a4\uac00 \uac01\uc790 \ud544\uc694\ud55c \uae00\ub9cc \uace8\ub77c \uc77d\uc2b5\ub2c8\ub2e4.\\n- \uc218\uc2e0\uc790\uac00 \uc0c8\ub85c \ub298\uc5b4\ub3c4 A\uc758 \ucf54\ub4dc\ub294 \ubc14\ub00c\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uac8c\uc2dc\ud310\ub9cc \ubcf4\uba74 \ub418\ub2c8\uae4c\uc694.\\n\\n\uc11c\ub85c \ubaa8\ub974\uae30 \ub54c\ubb38\uc5d0 \uc11c\ub85c \ubb36\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774\uac83\uc774 \ube44\ub3d9\uae30\ub85c \uc787\ub294 \uccab \ubc88\uc9f8 \ub3c4\uad6c\uc785\ub2c8\ub2e4.\\n\\n## \uc5ec\ub7ec \ub2e8\uacc4\ub294 \uc808\ucc28\ub85c \ubb36\uc2b5\ub2c8\ub2e4 (\uc6cc\ud06c\ud50c\ub85c\uc6b0, Temporal)\\n\\n\uc774\ubca4\ud2b8\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc5ec\ub7ec \ub2e8\uacc4\ub97c \uac70\uce58\ub294\ub370, \uc911\uac04\uc5d0 \uc2e4\ud328\ud558\uba74 \uc55e \ub2e8\uacc4\ub97c \ub418\ub3cc\ub824\uc57c \ud558\ub294 \uc791\uc5c5\uc785\ub2c8\ub2e4.\\n\\n\uc608\ub97c \ub4e4\uc5b4 \\"\uc8fc\ubb38 \u2192 \uacb0\uc81c \u2192 \uc7ac\uace0 \ucc28\uac10 \u2192 \ubc30\uc1a1 \ub4f1\ub85d\\"\uc744 \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4. \uacb0\uc81c\ub294 \ub410\ub294\ub370 \uc7ac\uace0 \ucc28\uac10\uc5d0\uc11c \uc2e4\ud328\ud558\uba74, \uacb0\uc81c\ub97c \ub418\ub3cc\ub824(\ud658\ubd88) \uc918\uc57c \ud569\ub2c8\ub2e4. \uc774 \ub418\ub3cc\ub9ac\uae30(\ubcf4\uc0c1)\ub97c \uc190\uc73c\ub85c \uc9dc\ub2e4 \ubcf4\uba74 \uaf2d \ud55c \ub2e8\uacc4\ub97c \ube60\ub728\ub9bd\ub2c8\ub2e4. \\"\uc5b4\ub514\uae4c\uc9c0 \uc9c4\ud589\ub410\ub354\ub77c\\"\ub97c \ucf54\ub4dc \uacf3\uacf3\uc5d0\uc11c \ucd94\uc801\ud574\uc57c \ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\uc6cc\ud06c\ud50c\ub85c\uc6b0 \uc5d4\uc9c4(Temporal)\uc740 \uc774 \uc808\ucc28\ub97c \ud558\ub098\uc758 \ud750\ub984\uc73c\ub85c \ubb36\uc5b4 \uc90d\ub2c8\ub2e4. \ud0dd\ubc30 \uc1a1\uc7a5\uc5d0\ub294 \ub2e8\uacc4\uac00 \uc801\ud600 \uc788\uace0, \uc5b4\ub514\uae4c\uc9c0 \uc654\ub294\uc9c0\uac00 \ud56d\uc0c1 \uae30\ub85d\ub429\ub2c8\ub2e4. \uc911\uac04\uc5d0 \uba48\ucdb0\ub3c4 \uc1a1\uc7a5\uc744 \ubcf4\uba74 \ub2e4\uc74c\uc5d0 \ubb34\uc5c7\uc744 \ud560\uc9c0, \ub418\ub3cc\ub9b0\ub2e4\uba74 \uc5b4\ub514\uae4c\uc9c0 \ub418\ub3cc\ub9b4\uc9c0 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n- \uac01 \ub2e8\uacc4\uc758 \uc9c4\ud589 \uc0c1\ud0dc\ub97c \uc5d4\uc9c4\uc774 \uae30\uc5b5\ud569\ub2c8\ub2e4. \uc11c\ubc84\uac00 \uc7ac\uc2dc\uc791\ud574\ub3c4 \uba48\ucd98 \uc9c0\uc810\ubd80\ud130 \uc774\uc5b4\uc9d1\ub2c8\ub2e4.\\n- \uc2e4\ud328 \uc2dc \ub418\ub3cc\ub9ac\ub294 \ub2e8\uacc4(\ubcf4\uc0c1)\ub97c \ud750\ub984 \uc548\uc5d0 \uba85\uc2dc\uc801\uc73c\ub85c \ub461\ub2c8\ub2e4.\\n- \\"\uc5b4\ub514\uae4c\uc9c0 \ub410\ub354\ub77c\\"\ub97c \ucf54\ub4dc\uac00 \uc544\ub2c8\ub77c \uc5d4\uc9c4\uc774 \ucd94\uc801\ud569\ub2c8\ub2e4.\\n\\n\uc54c\ub9ac\uae30\ub9cc \ud558\uba74 \ub418\ub294 \uc77c\uc740 \uc774\ubca4\ud2b8\ub85c, \uc5ec\ub7ec \ub2e8\uacc4\ub97c \ucc45\uc784\uc9c0\uace0 \ub05d\ub0b4\uc57c \ud558\ub294 \uc77c\uc740 \uc6cc\ud06c\ud50c\ub85c\uc6b0\ub85c \ub098\ub220 \ub9e1\uacbc\uc2b5\ub2c8\ub2e4.\\n\\n## \ud06c\uac8c \ub370\uc778 \uc0ac\uace0, \uc6b0\uccb4\ud1b5\uc744 \ub9e4\uc77c \ube44\uc6e0\ub2e4\\n\\n\uc774\ubca4\ud2b8 \ubc84\uc2a4\uc5d0\ub294 \uac8c\uc2dc\ud310\uc5d0 \ubd99\uc740 \uae00\uc744 \uc5bc\ub9c8 \ub3d9\uc548 \ubcf4\uad00\ud560\uc9c0 \uc815\ud558\ub294 \uc124\uc815(\ubcf4\uad00 \uae30\uac04, retention)\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ubaa8\ub4e0 \uae00\uc744 \uc601\uc6d0\ud788 \ub458 \uc218\ub294 \uc5c6\uc73c\ub2c8, \uc77c\uc815 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \uc9c0\uc6c1\ub2c8\ub2e4.\\n\\n\ud55c \ubd84\uc11d\uc6a9 \uc2a4\ud2b8\ub9bc\uc5d0\uc11c \uc774 \ubcf4\uad00 \uae30\uac04\uc744 \ud558\ub8e8\ub85c \uc7a1\uc544 \ub450\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uae00\uc744 \ubaa8\uc544 \uac00\ub294 \uc9d1\uacc4 \uc791\uc5c5\uc740 \ud558\ub8e8\ubcf4\ub2e4 \ub354 \uae34 \uc8fc\uae30\ub85c \ub3cc\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/event-bus-nats-temporal-2.webp\\"\\n    alt=\\"\ubcf4\uad00 \uae30\uac04 1\uc77c\uc774 \uc9d1\uacc4 \uc791\uc5c5 \uc8fc\uae30\ubcf4\ub2e4 \uc9e7\uc544, \uac00\uc838\uac00\uae30 \uc804\uc5d0 \uba54\uc2dc\uc9c0\uac00 \uc0ad\uc81c\ub418\uace0 \uc624\ub958 \ub85c\uadf8\ub3c4 \ub0a8\uc9c0 \uc54a\uc740 \uc0ac\uace0\\"\\n  />\\n</figure>\\n\\n\uc9d1\uacc4 \uc791\uc5c5\uc774 \uae00\uc744 \uac00\uc838\uac00\uae30\ub3c4 \uc804\uc5d0, \ubcf4\uad00 \uae30\uac04\uc774 \uc9c0\ub098 \uae00\uc774 \uba3c\uc800 \uc9c0\uc6cc\uc84c\uc2b5\ub2c8\ub2e4. \ub370\uc774\ud130\uac00 \uc870\uc6a9\ud788 \ube44\uae30 \uc2dc\uc791\ud588\uc2b5\ub2c8\ub2e4.\\n\\n:::info \ub9e4\uc77c \ube44\uc6cc\uc9c4 \uc6b0\uccb4\ud1b5\\n\uc6b0\uccb4\ud1b5\uc5d0 \ud3b8\uc9c0\uac00 \ub3c4\ucc29\ud588\ub294\ub370, \uc218\ucde8\uc778\uc774 \uac00\uc838\uac00\uae30 \uc804\uc5d0 \ub9e4\uc77c \uc6b0\uccb4\ud1b5\uc744 \ube44\uc6cc \ubc84\ub838\uc2b5\ub2c8\ub2e4. \ud3b8\uc9c0\ub97c \ubcf4\ub0b8 \ucabd\ub3c4, \ubc1b\uc744 \ucabd\ub3c4 \uc798\ubabb\uc774 \uc5c6\ub294\ub370 \uc911\uac04 \uc124\uc815 \ud558\ub098 \ub54c\ubb38\uc5d0 \ud3b8\uc9c0\uac00 \uc0ac\ub77c\uc84c\uc2b5\ub2c8\ub2e4.\\n:::\\n\\n\uac00\uc7a5 \uace0\uc57d\ud55c \ubd80\ubd84\uc740 \ub530\ub85c \uc788\uc5c8\uc2b5\ub2c8\ub2e4. <span style={{ backgroundColor: \'#ffdce0\'}}>\uc5b4\ub514\uc5d0\ub3c4 \uc624\ub958\uac00 \ucc0d\ud788\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.</span> \ubc1c\ud589\uc740 \uc131\uacf5\ud588\uace0, \ubcf4\uad00 \uae30\uac04 \ub9cc\ub8cc\uc5d0 \ub530\ub978 \uc0ad\uc81c\ub3c4 \uc815\uc0c1 \ub3d9\uc791\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc2dc\uc2a4\ud15c \uc785\uc7a5\uc5d0\uc11c\ub294 \ubaa8\ub4e0 \uac83\uc774 \\"\uc815\uc0c1\\"\uc774\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\uc9c0\ub09c \ud3b8\uc758 \ucfe0\ud0a4 \uc0ac\uace0\uc640 \ub611\uac19\uc740 \uad50\ud6c8\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc624\ub958 \uc5c6\uc774 \uc870\uc6a9\ud788 \uc5b4\uae0b\ub098\ub294 \ub3d9\uc791\uc774 \uac00\uc7a5 \uc624\ub798 \uc0ac\ub78c\uc744 \ubd99\uc7a1\uc2b5\ub2c8\ub2e4.\\n\\n\ud574\uacb0\uc740 \ub450 \uac00\uc9c0\uc600\uc2b5\ub2c8\ub2e4.\\n\\n- \ubcf4\uad00 \uae30\uac04\uc744 \ub109\ub109\ud788(\uc5ec\ub7ec \ub0a0) \ud1b5\uc77c\ud588\uc2b5\ub2c8\ub2e4. \uac00\uc838\uac00\ub294 \ucabd \uc8fc\uae30\ubcf4\ub2e4 \ucda9\ubd84\ud788 \uae38\uac8c \ub480\uc2b5\ub2c8\ub2e4.\\n- \uc774 \uac12\uc744 \uac01\uc790 \uc784\uc758\ub85c \uc815\ud558\uc9c0 \ubabb\ud558\uac8c, \uacf5\ud1b5 \uc0c1\uc218 \ud558\ub098\ub85c \uace0\uc815\ud588\uc2b5\ub2c8\ub2e4. \ub204\uac00 \uc0c8 \uc2a4\ud2b8\ub9bc\uc744 \ub9cc\ub4e4\uc5b4\ub3c4 \uac19\uc740 \ubcf4\uad00 \uae30\uac04\uc744 \uc4f0\ub3c4\ub85d \ucf54\ub4dc \ucc28\uc6d0\uc5d0\uc11c \uac15\uc81c\ud588\uc2b5\ub2c8\ub2e4.\\n\\n```python\\nfrom shared.events.constants import STREAM_MAX_AGE  # \ud55c\uacf3\uc5d0\uc11c \uad00\ub9ac\\n\\nconfig = StreamConfig(\\n    name=\\"MY_STREAM\\",\\n    subjects=[\\"my-service.>\\"],\\n    max_age=STREAM_MAX_AGE.total_seconds(),  # \uc784\uc758\uc758 1\uc77c/7\uc77c \uae08\uc9c0\\n)\\n```\\n\\n\uc124\uc815\uac12\uc744 \uc0ac\ub78c\uc758 \ud310\ub2e8\uc5d0 \ub9e1\uae30\uba74 \ub204\uad70\uac00\ub294 \ub2e4\ub974\uac8c \uc7a1\uc2b5\ub2c8\ub2e4. \uc911\uc694\ud55c \uae30\ubcf8\uac12\uc740 \ucf54\ub4dc\ub85c \uace0\uc815\ud558\ub294 \ud3b8\uc774 \uc548\uc804\ud588\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n- \uc11c\ube44\uc2a4\ub97c \uc9c1\uc811 \ud638\ucd9c\ud558\uba74 \ud55c\ucabd \uc7a5\uc560\uac00 \uc606\uc73c\ub85c \ubc88\uc9d1\ub2c8\ub2e4. \uc0ac\uc2e4\uc744 \uc774\ubca4\ud2b8\ub85c \ubc1c\ud589\ud558\uba74, \ubc1c\ud589\uc790\uc640 \uc218\uc2e0\uc790\uac00 \uc11c\ub85c \ubab0\ub77c \ubb36\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n- \uc5ec\ub7ec \ub2e8\uacc4\ub97c \uac70\uce58\uace0 \ub418\ub3cc\ub9ac\uae30\uac00 \ud544\uc694\ud55c \uc791\uc5c5\uc740 \uc6cc\ud06c\ud50c\ub85c\uc6b0\ub85c \ubb36\uc5c8\uc2b5\ub2c8\ub2e4. \uc9c4\ud589 \uc0c1\ud0dc\uc640 \ubcf4\uc0c1 \uc808\ucc28\ub97c \uc5d4\uc9c4\uc774 \ub300\uc2e0 \uae30\uc5b5\ud569\ub2c8\ub2e4.\\n- \uba54\uc2dc\uc9c0 \ubcf4\uad00 \uae30\uac04\uc744 \uac00\uc838\uac00\ub294 \ucabd \uc8fc\uae30\ubcf4\ub2e4 \uc9e7\uac8c \uc7a1\uc73c\uba74, \uc218\ucde8 \uc804\uc5d0 \uc0ac\ub77c\uc9d1\ub2c8\ub2e4. \uadf8\uac83\ub3c4 **\uc624\ub958 \uc5c6\uc774** \uc870\uc6a9\ud788.\\n- \uc0ac\ub78c\uc774 \ub9e4\ubc88 \uc815\ud558\ub294 \uc124\uc815\uac12\uc740 \uc5b4\uae0b\ub098\uae30 \ub9c8\ub828\uc774\ub77c, \uc911\uc694\ud55c \uae30\ubcf8\uac12\uc740 \uacf5\ud1b5 \uc0c1\uc218\ub85c \uace0\uc815\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c \ud3b8\uc5d0\uc11c\ub294 \uc774 \uc11c\ube44\uc2a4\ub4e4\uc744 \uace0\uac1d\uc0ac \uc548\uc5d0\uc11c \uc9c1\uc811 \ub3cc\ub824\uc57c \ud588\ub358 \uc628\ud504\ub808\ubbf8\uc2a4(on-premise) \ud658\uacbd \uc774\uc57c\uae30\ub97c \ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc778\ud130\ub137\uc774 \ub9c9\ud78c \uacf3\uc5d0 \uc5b4\ub5bb\uac8c \uc124\uce58\ud588\ub294\uc9c0\ub97c \uc801\uc5b4 \ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4."},{"id":"auth-bff-redirect-loop","metadata":{"permalink":"/blog/auth-bff-redirect-loop","source":"@site/blog/2026-06-13-auth-bff-redirect-loop/index.md","title":"\uc778\uc99d\uc744 \ubd99\uc774\ub2e4 \ub9cc\ub09c \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504","description":"\ub85c\uadf8\uc778 \ud55c \ubc88 \ubd99\uc774\ub294 \uc77c\uc774 \uc65c \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0, \uadf8\ub9ac\uace0 \ucfe0\ud0a4 \ud06c\uae30 \ud55c\uacc4\uac00 \uc124\uacc4\ub97c \uc5b4\ub5bb\uac8c \ubc14\uafe8\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-13T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"Auth","permalink":"/blog/tags/auth"},{"inline":true,"label":"Backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"Frontend","permalink":"/blog/tags/frontend"},{"inline":true,"label":"Retrospective","permalink":"/blog/tags/retrospective"},{"inline":true,"label":"BuildLog","permalink":"/blog/tags/build-log"}],"readingTime":2.66,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\uc778\uc99d\uc744 \ubd99\uc774\ub2e4 \ub9cc\ub09c \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504","slug":"auth-bff-redirect-loop","authors":["kgenots"],"tags":["Tech","Auth","Backend","Frontend","Retrospective","BuildLog"],"image":"/assets/blog/cover-auth-bff-redirect-loop.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\uc11c\ube44\uc2a4 \uc0ac\uc774\ub97c \uc787\ub294 \ubc95, \uc774\ubca4\ud2b8 \ubc84\uc2a4\uc640 \uc6cc\ud06c\ud50c\ub85c\uc6b0","permalink":"/blog/event-bus-nats-temporal"},"nextItem":{"title":"\ubaa8\ub178\ub808\ud3ec \ud558\ub098\uc5d0 15\uac1c \uc11c\ube44\uc2a4\ub97c \ub2f4\uc740 \uc774\uc720","permalink":"/blog/monorepo-15-service-msa"}},"content":"\ub85c\uadf8\uc778 \ud55c \ubc88 \ubd99\uc774\ub294 \uc77c\uc774 \uc65c \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0, \uadf8\ub9ac\uace0 \ucfe0\ud0a4 \ud06c\uae30 \ud55c\uacc4\uac00 \uc124\uacc4\ub97c \uc5b4\ub5bb\uac8c \ubc14\uafe8\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n[\uc9c0\ub09c \ud3b8](/blog/monorepo-15-service-msa)\uc5d0\uc11c \uc11c\ube44\uc2a4\ub97c \uc5ec\ub7ec \uac1c\ub85c \ub098\ub208 \uc774\uc57c\uae30\ub97c \ud588\uc2b5\ub2c8\ub2e4. \uc11c\ube44\uc2a4\uac00 \ub098\ub258\uba74 \ud654\uba74(\ud504\ub860\ud2b8\uc5d4\ub4dc)\ub3c4 \uc5ec\ub7ec \uacf3\uc5d0 \ud769\uc5b4\uc9d1\ub2c8\ub2e4. \uc81c\ud488 \uc0ac\uc774\ud2b8\uac00 \ub530\ub85c \uc788\uace0, \ub85c\uadf8\uc778\uc744 \uc804\ub2f4\ud558\ub294 \uc778\uc99d \uc0ac\uc774\ud2b8\uac00 \ub530\ub85c \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\uba74 \\"\ud55c \uacf3\uc5d0\uc11c \ub85c\uadf8\uc778\ud558\uba74 \ub2e4\ub978 \uacf3\uc5d0\uc11c\ub3c4 \ub85c\uadf8\uc778 \uc0c1\ud0dc\uac00 \uc720\uc9c0\ub418\uc5b4\uc57c \ud55c\ub2e4\\"\ub294 \ubb38\uc81c\uac00 \uc0dd\uae41\ub2c8\ub2e4.\\n\\n\uc774 \ubb38\uc81c\ub97c \ud480\ub2e4\uac00 \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504\uc5d0 \ube60\uc84c\uc2b5\ub2c8\ub2e4. \uadf8 \uacfc\uc815\uc744 \uc801\uc5b4 \ubd05\ub2c8\ub2e4.\\n\\n## \uc65c \uc778\uc99d \uc0ac\uc774\ud2b8\ub97c \ub530\ub85c \ub450\uc5c8\ub098\\n\\n\ub85c\uadf8\uc778 \ud654\uba74\uc744 \uc81c\ud488\ub9c8\ub2e4 \ub9cc\ub4e4\uba74, \uc81c\ud488\uc774 \ub298\uc5b4\ub0a0 \ub54c\ub9c8\ub2e4 \ub85c\uadf8\uc778 \ucf54\ub4dc\ub3c4 \ubcf5\uc81c\ub429\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub85c\uadf8\uc778\uc740 \uc778\uc99d \uc0ac\uc774\ud2b8 \ud55c \uacf3\uc5d0\uc11c\ub9cc \ucc98\ub9ac\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/auth-bff-redirect-loop-2.webp\\"\\n    alt=\\"\uc81c\ud488 \uc0ac\uc774\ud2b8\ub4e4\uc5d0\uc11c \uc548\ub0b4 \ub370\uc2a4\ud06c(\uc778\uc99d \uc0ac\uc774\ud2b8)\ub85c \ubcf4\ub0b4 \uc2e0\uc6d0\uc744 \ud655\uc778\ud558\uace0, \ucd9c\uc785\uc99d(\ud1a0\ud070)\uc744 \ubc1b\uc544 \uc6d0\ub798 \uc790\ub9ac\ub85c \ub3cc\uc544\uc624\ub294 \ud750\ub984\\"\\n  />\\n</figure>\\n\\n\uc81c\ud488\uc740 \uc5ec\ub7ec \ub3d9(\u68df)\uc73c\ub85c \ub098\ub25c \uac74\ubb3c\uc774\uace0, \ucd9c\uc785\uc99d\uc744 \ubc1c\uae09\ud558\ub294 \uacf3\uc740 \ubcc4\ub3c4\uc758 \uc548\ub0b4 \ub370\uc2a4\ud06c \ud55c \uacf3\uc785\ub2c8\ub2e4. \uc5b4\ub290 \ub3d9\uc5d0 \ub4e4\uc5b4\uac00\ub824 \ud558\ub4e0, \ucd9c\uc785\uc99d\uc774 \uc5c6\uc73c\uba74 \uba3c\uc800 \uc548\ub0b4 \ub370\uc2a4\ud06c\ub85c \ubcf4\ub0c5\ub2c8\ub2e4. \uac70\uae30\uc11c \uc2e0\uc6d0\uc744 \ud655\uc778\ud558\uace0 \ucd9c\uc785\uc99d\uc744 \ubc1b\uc544 \ub2e4\uc2dc \uc6d0\ub798 \ub3d9\uc73c\ub85c \ub3cc\uc544\uc635\ub2c8\ub2e4.\\n\\n\ud750\ub984\uc740 \uc774\ub807\uac8c \ub429\ub2c8\ub2e4.\\n\\n1. \uc0ac\uc6a9\uc790\uac00 \uc81c\ud488 \uc0ac\uc774\ud2b8\uc5d0\uc11c \ub85c\uadf8\uc778\uc744 \ub204\ub985\ub2c8\ub2e4.\\n2. \uc778\uc99d \uc0ac\uc774\ud2b8\ub85c \ubcf4\ub0c5\ub2c8\ub2e4. \uc774\ub54c \\"\ub05d\ub098\uba74 \uc5b4\ub514\ub85c \ub3cc\uc544\uac08\uc9c0\\"(`return_to`)\ub97c \ud568\uaed8 \ub118\uae41\ub2c8\ub2e4.\\n3. \uc778\uc99d \uc0ac\uc774\ud2b8\uc5d0\uc11c \uc2e0\uc6d0\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.\\n4. \ud1a0\ud070\uc744 \uadf8\ub300\ub85c \ub118\uae30\uba74 \uc704\ud5d8\ud558\ub2c8, \ud1a0\ud070\uc744 \uc554\ud638\ud654\ud55c \uc9e7\uc740 \ucf54\ub4dc\ub97c \ub9cc\ub4e4\uc5b4 \uc81c\ud488 \uc0ac\uc774\ud2b8\ub85c \ub3cc\ub824\ubcf4\ub0c5\ub2c8\ub2e4.\\n5. \uc81c\ud488 \uc0ac\uc774\ud2b8\uac00 \uadf8 \ucf54\ub4dc\ub97c \ud1a0\ud070\uc73c\ub85c \uad50\ud658\ud569\ub2c8\ub2e4(exchange).\\n6. \ud1a0\ud070\uc744 \uc800\uc7a5\ud558\uace0, \uc6d0\ub798 \ubcf4\ub824\ub358 \ud654\uba74\uc73c\ub85c \ub3cc\uc544\uac11\ub2c8\ub2e4.\\n\\n\uc774 \ubc29\uc2dd\uc744 BFF(Backend for Frontend) \ud328\ud134\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4. \ud1a0\ud070 \uc790\uccb4\ub97c \uc8fc\uc18c\ucc3d\uc5d0 \ub178\ucd9c\ud558\uc9c0 \uc54a\uace0, \ud55c \ub2e8\uacc4 \uc548\uc804\ud558\uac8c \uad50\ud658\ud558\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.\\n\\n## \uadf8\ub7f0\ub370 \ud68c\uc804\ubb38\uc5d0 \uac07\ud614\uc2b5\ub2c8\ub2e4\\n\\n\ubb38\uc81c\uac00 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4. \ub85c\uadf8\uc778\uc744 \ub204\ub974\uba74 \uc778\uc99d \uc0ac\uc774\ud2b8\ub85c \uac14\ub2e4\uac00, \ub2e4\uc2dc \uc81c\ud488 \uc0ac\uc774\ud2b8\ub85c \uc654\ub2e4\uac00, \ub610 \uc778\uc99d \uc0ac\uc774\ud2b8\ub85c \uac00\uae30\ub97c \ub05d\uc5c6\uc774 \ubc18\ubcf5\ud588\uc2b5\ub2c8\ub2e4. \ud68c\uc804\ubb38\uc5d0 \uac07\ud78c \uac83\ucc98\ub7fc \uac19\uc740 \uc790\ub9ac\ub97c \ube59\ube59 \ub3cc\uc558\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/auth-bff-redirect-loop.webp\\"\\n    alt=\\"BFF \uc778\uc99d \ucf54\ub4dc \uad50\ud658\uc758 \uc758\ub3c4\ud55c \ud750\ub984\uacfc, \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504\ub97c \ub9cc\ub4e0 \uc138 \uac00\uc9c0 \uc6d0\uc778\\"\\n  />\\n</figure>\\n\\n\uc6d0\uc778\uc744 \ud30c\ubcf4\ub2c8 \ud55c \uac00\uc9c0\uac00 \uc544\ub2c8\ub77c \uc138 \uac00\uc9c0\uac00 \uacb9\uccd0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n### \uc6d0\uc778 1. \ub3cc\uc544\uac08 \uc8fc\uc18c\ub97c \uc783\uc5b4\ubc84\ub838\ub2e4\\n\\n\\"\ub05d\ub098\uba74 \uc5b4\ub514\ub85c \ub3cc\uc544\uac08\uc9c0\\"(`return_to`)\ub97c \uc784\uc2dc \uc800\uc7a5\uc18c(sessionStorage)\uc5d0 \ub2f4\uc544 \ub450\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \ub85c\uadf8\uc778\uc774 \ud55c \ubc88 \uc2e4\ud328\ud558\uace0 \uc7ac\uc2dc\ub3c4\ud558\ub294 \uc0ac\uc774 \uc774 \uc800\uc7a5\uc18c\uac00 \ube44\uc6cc\uc84c\uc2b5\ub2c8\ub2e4. \ub3cc\uc544\uac08 \uc8fc\uc18c\ub97c \uc783\uc73c\ub2c8, \uc778\uc99d\uc774 \ub05d\ub098\ub3c4 \uc81c\ud488 \uc0ac\uc774\ud2b8\ub85c \ubabb \uac00\uace0 \uc778\uc99d \uc0ac\uc774\ud2b8 \uc548\uc5d0\uc11c\ub9cc \ub9f4\ub3cc\uc558\uc2b5\ub2c8\ub2e4.\\n\\n:::info \ube44\uc720\ub85c \ubcf4\uba74\\n\uc548\ub0b4 \ub370\uc2a4\ud06c\uc5d0 \\"\uc800\ub294 3\ub3d9\uc5d0\uc11c \uc654\uc5b4\uc694\\"\ub77c\uace0 \uc801\uc740 \uba54\ubaa8\ub97c \ub9e1\uacbc\ub294\ub370, \uadf8 \uba54\ubaa8\uac00 \uc911\uac04\uc5d0 \uc0ac\ub77c\uc84c\uc2b5\ub2c8\ub2e4. \ucd9c\uc785\uc99d\uc740 \ubc1b\uc558\uc9c0\ub9cc \uc5b4\ub290 \ub3d9\uc73c\ub85c \uac00\uc57c \ud560\uc9c0 \ubaa8\ub974\uac8c \ub41c \uac83\uc774\uc9c0\uc694.\\n:::\\n\\n### \uc6d0\uc778 2. \ucd9c\uc785\uc99d\uc774 \uc8fc\uba38\ub2c8\uc5d0 \uc548 \ub4e4\uc5b4\uac14\ub2e4\\n\\n\uc774\uac8c \uac00\uc7a5 \ucc3e\uae30 \uc5b4\ub824\uc6e0\uc2b5\ub2c8\ub2e4. \ud1a0\ud070\uc744 \ucfe0\ud0a4\uc5d0 \uc800\uc7a5\ud558\ub824 \ud588\ub294\ub370, <span style={{ backgroundColor: \'#ffdce0\'}}>\ucfe0\ud0a4 \ud558\ub098\uc758 \ud06c\uae30 \ud55c\uacc4\ub294 \uc57d 4KB(4096\ubc14\uc774\ud2b8)</span>\uc785\ub2c8\ub2e4.\\n\\n\uadf8\ub7f0\ub370 \uc6b0\ub9ac\uac00 \ub2f4\uc544\uc57c \ud560 \ud1a0\ud070\uc740 \ub450 \uc885\ub958\uc600\uc2b5\ub2c8\ub2e4.\\n\\n- \uc2e0\uc6d0 \ud1a0\ud070(id token): \uc57d 1,500\ubc14\uc774\ud2b8\\n- \uac31\uc2e0 \ud1a0\ud070(refresh token): \uc57d 1,700\ubc14\uc774\ud2b8\\n\\n\ub450 \uac1c\ub9cc \ud574\ub3c4 3,200\ubc14\uc774\ud2b8\uc785\ub2c8\ub2e4. \uc5ec\uae30\uc5d0 \ud1a0\ud070\uc744 \uc554\ud638\ud654\ud558\uba74 \ud06c\uae30\uac00 \ub354 \ub298\uc5b4\ub0a9\ub2c8\ub2e4(\uc554\ud638\ud654\uc640 \uc778\ucf54\ub529\uc744 \uac70\uce58\uba74 \ub300\ub7b5 1.3\ubc30). \ucfe0\ud0a4\uc5d0 \ubd99\ub294 \ubd80\uac00 \uc815\ubcf4\uae4c\uc9c0 \ub354\ud558\ub2c8 4,096\ubc14\uc774\ud2b8\ub97c \ub118\uc5b4 \ubc84\ub838\uc2b5\ub2c8\ub2e4.\\n\\n\ube0c\ub77c\uc6b0\uc800\ub294 \uc774\ub54c <span style={{ backgroundColor: \'#ffdce0\'}}>\uc544\ubb34 \uc624\ub958\ub3c4 \ub0b4\uc9c0 \uc54a\uace0 \uc870\uc6a9\ud788 \ucfe0\ud0a4\ub97c \ubc84\ub9bd\ub2c8\ub2e4.</span> \uc800\uc7a5\ub41c \uc904 \uc54c\uc558\ub294\ub370 \uc2e4\uc81c\ub85c\ub294 \ube44\uc5b4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub2c8 \ub2e4\uc74c \uc694\uccad\uc5d0\uc11c \\"\uc778\uc99d \uc548 \ub428\\"\uc73c\ub85c \ub9c9\ud788\uace0, \ub2e4\uc2dc \ub85c\uadf8\uc778 \ud654\uba74\uc73c\ub85c \ub3cc\uc544\uac11\ub2c8\ub2e4. \ud68c\uc804\ubb38\uc758 \uc9c4\uc9dc \ub3d9\ub825\uc774 \uc5ec\uae30 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n:::info \ube44\uc720\ub85c \ubcf4\uba74\\n\ucd9c\uc785\uc99d\uc744 \uc8fc\uba38\ub2c8\uc5d0 \ub123\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud588\ub294\ub370, \uc8fc\uba38\ub2c8\uac00 \uc791\uc544\uc11c \ucd9c\uc785\uc99d\uc774 \ubc14\ub2e5\uc5d0 \ub5a8\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. \ubcf8\uc778\uc740 \uac00\uc9c4 \uc904 \uc54c\uace0 \ub2e4\uc74c \ubb38\uc5d0 \uac14\ub2e4\uac00 \\"\ucd9c\uc785\uc99d \uc5c6\uc73c\uc2dc\ub124\uc694\\" \ud558\uace0 \ub2e4\uc2dc \uc548\ub0b4 \ub370\uc2a4\ud06c\ub85c \ub3cc\uc544\uac00\uae30\ub97c \ubc18\ubcf5\ud569\ub2c8\ub2e4.\\n:::\\n\\n### \uc6d0\uc778 3. \uc606 \uac74\ubb3c \uc0ac\ubb3c\ud568\uc740 \ubabb \uc5f0\ub2e4\\n\\n\ud1a0\ud070\uc744 \uc778\uc99d \uc0ac\uc774\ud2b8 \ucabd \uc800\uc7a5\uc18c\uc5d0 \ub123\uc5b4 \ub450\uba74, \uc81c\ud488 \uc0ac\uc774\ud2b8\uc5d0\uc11c\ub294 \uadf8 \uac12\uc744 \uc77d\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub294 \ubcf4\uc548\uc744 \uc704\ud574 \uc0ac\uc774\ud2b8(\ub3c4\uba54\uc778)\ub9c8\ub2e4 \uc800\uc7a5\uc18c\ub97c \uaca9\ub9ac\ud569\ub2c8\ub2e4. \uc778\uc99d \uc0ac\uc774\ud2b8\uc758 \uc0ac\ubb3c\ud568\uc740 \uc81c\ud488 \uc0ac\uc774\ud2b8\uac00 \uc5f4 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n## \uc5b4\ub5bb\uac8c \ud480\uc5c8\ub098\\n\\n\uc138 \uc6d0\uc778\uc744 \uac01\uac01 \ub9c9\uc558\uc2b5\ub2c8\ub2e4.\\n\\n- **\ub3cc\uc544\uac08 \uc8fc\uc18c**\ub294 \uc27d\uac8c \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294 \uc800\uc7a5\uc18c(localStorage)\ub85c \uc62e\uacbc\uc2b5\ub2c8\ub2e4. \uc7ac\uc2dc\ub3c4\ub098 \ud0ed \uc774\ub3d9\uc5d0\ub3c4 \uc720\uc9c0\ub429\ub2c8\ub2e4.\\n- **\ud1a0\ud070 \uc800\uc7a5**\uc740 \ucfe0\ud0a4\ub97c \ud3ec\uae30\ud558\uace0, \ucf5c\ubc31 \ud654\uba74\uc5d0\uc11c \uc9c1\uc811 \uc800\uc7a5\uc18c(localStorage)\uc5d0 \ub123\ub294 \ubc29\uc2dd\uc73c\ub85c \ubc14\uafe8\uc2b5\ub2c8\ub2e4. \ucfe0\ud0a4 4KB \ud55c\uacc4\ub97c \uc6b0\ud68c\ud588\uc2b5\ub2c8\ub2e4.\\n- **\uc800\uc7a5 \uc704\uce58**\ub294 \ud1a0\ud070\uc744 \uc368\uc57c \ud558\ub294 \uc81c\ud488 \uc0ac\uc774\ud2b8 \ucabd\uc73c\ub85c \uc77c\uce58\uc2dc\ucf30\uc2b5\ub2c8\ub2e4. \uc606 \uac74\ubb3c\uc774 \uc544\ub2c8\ub77c \uc790\uae30 \uac74\ubb3c \uc0ac\ubb3c\ud568\uc5d0 \ub123\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub807\uac8c \ud558\ub2c8 \ud68c\uc804\ubb38\uc774 \uba48\ucdc4\uc2b5\ub2c8\ub2e4. \ub85c\uadf8\uc778 \ud55c \ubc88\uc774\uba74 \ud1a0\ud070\uc774 \uc81c\ub300\ub85c \uc800\uc7a5\ub418\uace0, \uc6d0\ub798 \ubcf4\ub824\ub358 \ud654\uba74\uc73c\ub85c \ub3cc\uc544\uac14\uc2b5\ub2c8\ub2e4.\\n\\n## \uadf8\ub798\uc11c \uc548\uc804\ud55c\uac00\uc694\\n\\nlocalStorage\ub294 \ud3b8\ud558\uc9c0\ub9cc \uc2a4\ud06c\ub9bd\ud2b8 \uacf5\uaca9(XSS)\uc5d0 \ucde8\uc57d\ud569\ub2c8\ub2e4. \ucfe0\ud0a4\uc758 \uc77c\ubd80 \uc635\uc158(HttpOnly)\uc740 \uc2a4\ud06c\ub9bd\ud2b8\uac00 \ud1a0\ud070\uc744 \uc77d\uc9c0 \ubabb\ud558\uac8c \ub9c9\uc544 \uc8fc\ub294\ub370, localStorage\uc5d0\ub294 \uadf8\ub7f0 \ubcf4\ud638\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \uc644\ud654\ucc45\uc744 \ub2e8\uacc4\uc801\uc73c\ub85c \ub354\ud588\uc2b5\ub2c8\ub2e4.\\n\\n- \ud398\uc774\uc9c0\uac00 \uc2e4\ud589\ud560 \uc218 \uc788\ub294 \uc2a4\ud06c\ub9bd\ud2b8\uc758 \ucd9c\ucc98\ub97c \uc81c\ud55c\ud558\ub294 \ubcf4\uc548 \uc815\ucc45(CSP)\uc744 \uc801\uc6a9\ud588\uc2b5\ub2c8\ub2e4.\\n- \ud1a0\ud070 \uc218\uba85\uc744 \uc9e7\uac8c \ub450\uc5b4, \ud639\uc2dc \ud0c8\ucde8\ub418\ub354\ub77c\ub3c4 \ud53c\ud574 \uc2dc\uac04\uc744 \uc904\uc600\uc2b5\ub2c8\ub2e4.\\n- \ub354 \ubbfc\uac10\ud55c \uac31\uc2e0 \ud1a0\ud070\uc740 \uc2a4\ud06c\ub9bd\ud2b8\uac00 \ubabb \uc77d\ub294 \ucfe0\ud0a4(HttpOnly)\ub85c \uc62e\uae30\ub294 \uc791\uc5c5\uc744 \uc9c4\ud589\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\uc644\ubcbd\ud55c \ud55c \ubc29\uc740 \uc5c6\uc5c8\uc2b5\ub2c8\ub2e4. \ud3b8\uc758(UX)\uc640 \ubcf4\uc548 \uc0ac\uc774\uc5d0\uc11c \ud55c\ucabd\uc744 \ud0dd\ud558\uba74 \ub2e4\ub978 \ucabd\uc744 \ubcf4\uac15\ud558\ub294 \uc2dd\uc73c\ub85c, \uc870\uae08\uc529 \uade0\ud615\uc744 \ub9de\ucdb0 \uac14\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n- \ud654\uba74\uc774 \uc5ec\ub7ec \uacf3\uc73c\ub85c \ub098\ub258\uba74, \\"\ud55c \uacf3\uc5d0\uc11c \ub85c\uadf8\uc778\ud558\uba74 \ub2e4\ub978 \uacf3\uc5d0\uc11c\ub3c4 \uc720\uc9c0\\"\ub77c\ub294 \ubb38\uc81c\uac00 \ub530\ub77c\uc635\ub2c8\ub2e4. \uc778\uc99d \uc0ac\uc774\ud2b8\ub97c \ud55c \uacf3\uc5d0 \ub450\uace0 \ucf54\ub4dc\ub97c \uad50\ud658\ud558\ub294 BFF \ud328\ud134\uc73c\ub85c \ud480\uc5c8\uc2b5\ub2c8\ub2e4.\\n- \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504\ub294 \uc6d0\uc778\uc774 \ud558\ub098\uac00 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4. \ub3cc\uc544\uac08 \uc8fc\uc18c \ubd84\uc2e4, \ucfe0\ud0a4 4KB \ud55c\uacc4, \ub3c4\uba54\uc778 \uc800\uc7a5\uc18c \uaca9\ub9ac\uac00 \uacb9\uccd0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n- \ud2b9\ud788 <b>\ube0c\ub77c\uc6b0\uc800\uac00 \ud070 \ucfe0\ud0a4\ub97c \uc870\uc6a9\ud788 \ubc84\ub9b0\ub2e4</b>\ub294 \uc810\uc740 \uc624\ub958 \uba54\uc2dc\uc9c0\uac00 \uc5c6\uc5b4 \ucc3e\uae30 \uc5b4\ub824\uc6e0\uc2b5\ub2c8\ub2e4. \\"\uc624\ub958 \uc5c6\uc774 \uc2e4\ud328\ud558\ub294\\" \ub3d9\uc791\uc774 \uac00\uc7a5 \uc624\ub798 \uc0ac\ub78c\uc744 \ubd99\uc7a1\uc2b5\ub2c8\ub2e4.\\n- localStorage \uc800\uc7a5\uc740 \ud3b8\uc758\ub97c \uc704\ud55c \uc120\ud0dd\uc774\uc5c8\uace0, \uadf8\ub9cc\ud07c \ubcf4\uc548 \uc644\ud654\ucc45\uc73c\ub85c \ubcf4\uac15\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c \ud3b8\uc5d0\uc11c\ub294 \uc11c\ube44\uc2a4 \uc0ac\uc774\ub97c \uc787\ub294 **\uc774\ubca4\ud2b8 \ubc84\uc2a4(NATS)\uc640 \uc6cc\ud06c\ud50c\ub85c\uc6b0(Temporal)** \uc774\uc57c\uae30\ub97c \ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ube44\ub3d9\uae30\ub85c \uc77c\uc744 \ud758\ub824\ubcf4\ub0bc \ub54c \uc0dd\uae30\ub294 \ubb38\uc81c\uc640, \ud55c \ubc88 \ud06c\uac8c \ub370\uc778 \uba54\uc2dc\uc9c0 \ubcf4\uad00 \uae30\uac04 \uc124\uc815 \uc0ac\uace0\ub97c \uc801\uc5b4 \ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4."},{"id":"monorepo-15-service-msa","metadata":{"permalink":"/blog/monorepo-15-service-msa","source":"@site/blog/2026-06-12-monorepo-15-service-msa/index.md","title":"\ubaa8\ub178\ub808\ud3ec \ud558\ub098\uc5d0 15\uac1c \uc11c\ube44\uc2a4\ub97c \ub2f4\uc740 \uc774\uc720","description":"\uc11c\ube44\uc2a4\ub294 \ub9c8\uc774\ud06c\ub85c\uc11c\ube44\uc2a4\ub85c \uc798\uac8c \ub098\ub204\uba74\uc11c, \ub808\ud3ec\ub294 \ud558\ub098\ub85c \uc720\uc9c0\ud55c \uc774\uc720\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-12T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"Architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"Backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"Retrospective","permalink":"/blog/tags/retrospective"},{"inline":true,"label":"BuildLog","permalink":"/blog/tags/build-log"}],"readingTime":3.11,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ubaa8\ub178\ub808\ud3ec \ud558\ub098\uc5d0 15\uac1c \uc11c\ube44\uc2a4\ub97c \ub2f4\uc740 \uc774\uc720","slug":"monorepo-15-service-msa","authors":["kgenots"],"tags":["Tech","Architecture","Backend","Retrospective","BuildLog"],"image":"/assets/blog/cover-monorepo-15-service-msa.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\uc778\uc99d\uc744 \ubd99\uc774\ub2e4 \ub9cc\ub09c \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504","permalink":"/blog/auth-bff-redirect-loop"},"nextItem":{"title":"6\uac1c\uc6d4\uac04 \ubc31\uc5d4\ub4dc\xb7\ud504\ub860\ud2b8\uc5d4\ub4dc\xb7\uc778\ud504\ub77c\ub97c \ub9cc\ub4e0 \uae30\ub85d (\uc2dc\ub9ac\uc988 \uc2dc\uc791)","permalink":"/blog/build-log-intro"}},"content":"\uc11c\ube44\uc2a4\ub294 \ub9c8\uc774\ud06c\ub85c\uc11c\ube44\uc2a4\ub85c \uc798\uac8c \ub098\ub204\uba74\uc11c, \ub808\ud3ec\ub294 \ud558\ub098\ub85c \uc720\uc9c0\ud55c \uc774\uc720\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\uc9c0\ub09c \ubc18\ub144 \ub3d9\uc548 \ubc31\uc5d4\ub4dc \uc11c\ube44\uc2a4\ub97c 15\uac1c\uae4c\uc9c0 \ub298\ub838\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub808\ud3ec\ub294 \ub05d\uae4c\uc9c0 \ud558\ub098\ub85c \ub450\uc5c8\uc2b5\ub2c8\ub2e4. \uc11c\ube44\uc2a4\ub9c8\ub2e4 \ub808\ud3ec\ub97c \ub450\ub294 \ubc29\uc2dd\uc774 \uc77c\ubc18\uc801\uc774\uc9c0\ub9cc, \uc800\ub294 \uadf8 \ubc18\ub300\ub97c \ud0dd\ud588\uc2b5\ub2c8\ub2e4.\\n\\n## \uc11c\ube44\uc2a4\ub97c \ub098\ub208 \uc774\uc720\\n\\n\ubaa9\ud45c\ub294 \ub2e8\uc21c\ud588\uc2b5\ub2c8\ub2e4. \ud55c \uc11c\ube44\uc2a4\ub294 \ud55c \uac00\uc9c0 \uc77c\ub9cc \ud569\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/monorepo-15-service-msa-2.webp\\"\\n    alt=\\"\uacb0\uc81c\uc640 \uc54c\ub9bc\uc744 \ud55c \ucf54\ub4dc\uc5d0 \ub454 \ud55c \ub369\uc5b4\ub9ac\uc640, \uacb0\uc81c \uc11c\ube44\uc2a4\xb7\uc54c\ub9bc \uc11c\ube44\uc2a4\ub85c \ucc45\uc784\uc744 \ub098\ub208 \ubd84\ub9ac \uad6c\uc870 \ube44\uad50\\"\\n  />\\n</figure>\\n\\n\ud55c \uc190\uc740 \uc811\uc2dc\ub97c \ub4e4\uace0, \ub2e4\ub978 \uc190\uc740 \uce7c\uc744 \uc961\ub2c8\ub2e4. \ud55c \uc190\uc73c\ub85c \ub458 \ub2e4 \ud558\ub824\uace0 \ud558\uba74 \ub458 \ub2e4 \uc5b4\uc124\ud37c\uc9d1\ub2c8\ub2e4. \uc811\uc2dc\uac00 \ud754\ub4e4\ub9ac\uba74 \uce7c\uc9c8\uc774 \ud754\ub4e4\ub9ac\uace0, \uce7c\uc744 \uac08\uba74 \uc811\uc2dc\ub97c \ub193\uce69\ub2c8\ub2e4. \uc11c\ub85c \ubb34\uad00\ud55c \uc77c\uc778\ub370 \ud55c \ub369\uc5b4\ub9ac\ub77c\uc11c \ud568\uaed8 \ud754\ub4e4\ub9ac\ub294 \uac83\uc774\uc9c0\uc694.\\n\\n\uc11c\ube44\uc2a4\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\uc785\ub2c8\ub2e4. \uacb0\uc81c\uc640 \uc54c\ub9bc\uc744 \ud55c \ucf54\ub4dc\uc5d0 \ub450\uba74, \uacb0\uc81c\ub97c \uace0\uce60 \ub54c\ub9c8\ub2e4 \uc54c\ub9bc\uc774 \ud568\uaed8 \ubd88\uc548\ud574\uc9d1\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucc45\uc784 \ub2e8\uc704\ub85c \ub098\ub204\uc5c8\uc2b5\ub2c8\ub2e4. \uacb0\uc81c\ub294 \uacb0\uc81c \uc11c\ube44\uc2a4, \uc54c\ub9bc\uc740 \uc54c\ub9bc \uc11c\ube44\uc2a4. \uac01 \uc11c\ube44\uc2a4\uac00 \ubb34\uc5c7\uc744 \ucc45\uc784\uc9c0\ub294\uc9c0 \uacbd\uacc4\ub97c \ubd84\uba85\ud788 \uadf8\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\uacbd\uacc4\ub97c \uadf8\uc73c\uba74 \ud544\uc694\ud55c \uc11c\ube44\uc2a4\ub9cc \uace8\ub77c \uc870\ub9bd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc0c8 \uae30\ub2a5\uc5d0 \\"\uc0ac\uc6a9\uc790 \ud655\uc778 + \uacb0\uc81c + \uc54c\ub9bc\\"\uc774 \ud544\uc694\ud558\uba74 \uc138 \uc11c\ube44\uc2a4\ub97c \uc870\ud569\ud558\uba74 \ub429\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \ub2e4\uc2dc \ub9cc\ub4e4 \ud544\uc694\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\uac83\uc774 \ub9c8\uc774\ud06c\ub85c\uc11c\ube44\uc2a4\ub97c \ud0dd\ud55c \uc774\uc720\uc785\ub2c8\ub2e4. \ucc45\uc784\uc758 \uacbd\uacc4\ub97c \uba85\ud655\ud788 \uae0b\uace0, \uadf8 \uc870\uac01\uc744 \ud544\uc694\uc5d0 \ub530\ub77c \uc870\ub9bd\ud558\uae30 \uc704\ud574\uc11c\uc785\ub2c8\ub2e4.\\n\\n## \ub808\ud3ec\ub294 \ub098\ub204\uc9c0 \uc54a\uc740 \uc774\uc720\\n\\n\ubcf4\ud1b5\uc740 \uc5ec\uae30\uc11c \ub808\ud3ec\ub3c4 \ud568\uaed8 \ub098\ub215\ub2c8\ub2e4. \uc11c\ube44\uc2a4\ub9c8\ub2e4 \ub808\ud3ec \ud558\ub098\uc529 \ub450\ub294 \ubc29\uc2dd\uc774\uc9c0\uc694.\\n\\n\ub2e4\ub9cc \uc18c\uc218 \uc778\uc6d0\uc5d0\uac8c\ub294 \uc774 \ubc29\uc2dd\uc774 \ubd88\ub9ac\ud55c \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc11c\ube44\uc2a4\ub294 15\uac1c\uc778\ub370 \ub2e4\ub8e8\ub294 \uc0ac\ub78c\uc740 \uba87 \uba85\uc774\ub77c, \ud55c \uba85\uc774 \ud558\ub8e8\uc5d0\ub3c4 \uc5ec\ub7ec \uc11c\ube44\uc2a4\ub97c \ub3d9\uc2dc\uc5d0 \ub9cc\uc9d1\ub2c8\ub2e4. \ub808\ud3ec\uac00 \ud769\uc5b4\uc838 \uc788\uc73c\uba74 \ub2e4\uc74c \ubb38\uc81c\uac00 \ubc18\ubcf5\ub429\ub2c8\ub2e4.\\n\\n- \uc11c\ube44\uc2a4 A\uc758 \uc751\ub2f5 \ud615\uc2dd\uc744 \ubc14\uafb8\uba74, \uc774\ub97c \uc0ac\uc6a9\ud558\ub294 B\xb7C\uae4c\uc9c0 \ub808\ud3ec \uc138 \uacf3\uc5d0 PR\uc744 \uc62c\ub824\uc57c \ud569\ub2c8\ub2e4. \uc14b\uc774 \ub530\ub85c \ubcd1\ud569\ub418\ub294 \uc21c\uac04 \uc11c\ub85c \ub9de\uc9c0 \uc54a\ub294 \uad6c\uac04\uc774 \uc0dd\uae41\ub2c8\ub2e4.\\n- \uacf5\ud1b5 \ucf54\ub4dc \ud55c \uc904\uc744 \uace0\uce58\ub824\uace0 \ubc84\uc804\uc744 \uc62c\ub824 \ubc30\ud3ec\ud558\uace0, \uc0ac\uc6a9\ud558\ub294 \ucabd\ub9c8\ub2e4 \ub2e4\uc2dc \ubc1b\uc544\uc635\ub2c8\ub2e4.\\n- \uac1c\ubc1c \uc11c\ubc84\uc5d0 \uc5b4\ub5a4 \ubc84\uc804 \uc870\ud569\uc774 \ub5a0 \uc788\ub294\uc9c0 \ud55c\ub208\uc5d0 \uc54c\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \ucf54\ub4dc\ub294 \ud55c\uacf3\uc5d0 \ubaa8\uc558\uc2b5\ub2c8\ub2e4. \uc11c\ube44\uc2a4\ub294 \ub098\ub204\ub418, \ucf54\ub4dc\ub294 \ud55c \ub808\ud3ec\uc5d0 \ub450\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.\\n\\n```text\\nbackend/\\n\u251c\u2500\u2500 apps/                      # \uc11c\ube44\uc2a4\ub2f9 \ub514\ub809\ud1a0\ub9ac 1\uac1c\\n\u2502   \u251c\u2500\u2500 account/               # \uc778\uc99d/\uc0ac\uc6a9\uc790\\n\u2502   \u251c\u2500\u2500 billing/               # \uacb0\uc81c\\n\u2502   \u251c\u2500\u2500 notification/          # \uc54c\ub9bc\\n\u2502   \u251c\u2500\u2500 ...                    # \ub3c4\uba54\uc778 \uc11c\ube44\uc2a4\ub4e4\\n\u2502   \u2514\u2500\u2500 worker-*/              # \ube44\ub3d9\uae30 \uc6cc\ucee4\\n\u251c\u2500\u2500 packages/                  # \uacf5\uc720 \ub77c\uc774\ube0c\ub7ec\ub9ac\\n\u2502   \u251c\u2500\u2500 shared/                # \uacf5\ud1b5 \ucf54\ub4dc (DB, \uc608\uc678, \uc2a4\ud0a4\ub9c8)\\n\u2502   \u251c\u2500\u2500 grpc-pb/               # \uc11c\ube44\uc2a4 \uac04 \ud1b5\uc2e0 \uaddc\uc57d\\n\u2502   \u2514\u2500\u2500 grpc-client-*/         # \uc11c\ube44\uc2a4\ubcc4 \ud074\ub77c\uc774\uc5b8\ud2b8\\n\u2514\u2500\u2500 pyproject.toml             # \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub8e8\ud2b8\\n```\\n\\n\ud55c\uacf3\uc5d0 \ubaa8\uc73c\uba74 \uacf5\ud1b5 \ucf54\ub4dc\ub97c \uace0\ucce4\uc744 \ub54c \uc0ac\uc6a9\ud558\ub294 \uc11c\ube44\uc2a4\uac00 \uc989\uc2dc \uac19\uc740 \ucf54\ub4dc\ub97c \ubd05\ub2c8\ub2e4. \ubc84\uc804\uc744 \uc62c\ub9ac\uace0 \ubc30\ud3ec\ud558\uace0 \ub2e4\uc2dc \ubc1b\uc544\uc624\ub294 \uc655\ubcf5\uc774 \uc0ac\ub77c\uc9d1\ub2c8\ub2e4. \ud1b5\uc2e0 \uaddc\uc57d\uc744 \ubc14\uafd4\ub3c4 \ubcf4\ub0b4\ub294 \ucabd\uacfc \ubc1b\ub294 \ucabd\uc774 \ud55c \ubc88\uc5d0 \ud568\uaed8 \ubc14\ub01d\ub2c8\ub2e4. \ub458\uc774 \uc5b4\uae0b\ub09c \ucc44\ub85c \ubcd1\ud569\ub420 \uc77c\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n## \ud55c \ub808\ud3ec\uc5ec\ub3c4 \ud55c \ub369\uc5b4\ub9ac\ub294 \uc544\ub2d9\ub2c8\ub2e4\\n\\n\uac00\uc7a5 \ud754\ud55c \uc624\ud574\uc785\ub2c8\ub2e4. <span style={{ backgroundColor: \'#f1f8ff\'}}>\ub808\ud3ec\uac00 \ud558\ub098\uc5ec\ub3c4 \uc11c\ube44\uc2a4\ub294 \ud55c \ub369\uc5b4\ub9ac\uac00 \uc544\ub2d9\ub2c8\ub2e4.</span> \ucf54\ub4dc\ub97c \uac19\uc740 \uc704\uce58\uc5d0 \ub458 \ubfd0, \uc2e4\ud589 \uc2dc\uc810\uc5d0\ub294 \uc5ec\uc804\ud788 \ub3c5\ub9bd\uc801\uc73c\ub85c \ub3d9\uc791\ud569\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/monorepo-15-service-msa.webp\\"\\n    alt=\\"\ub124 \uacc4\uce35(Product, Platform, Domain, Workers)\uacfc \uc704\uc5d0\uc11c \uc544\ub798\ub85c\ub9cc \ud750\ub974\ub294 gRPC \uc758\uc874, NATS\xb7Temporal \ube44\ub3d9\uae30 \ubc31\ubcf8\\"\\n  />\\n</figure>\\n\\n\ub3c5\ub9bd \uc2e4\ud589\uc744 \uc9c0\ud0a4\uae30 \uc704\ud574 \uaddc\uce59\uc744 \uc815\ud588\uc2b5\ub2c8\ub2e4.\\n\\n- **\ub370\uc774\ud130\ub294 \uac01\uc790\ub9cc**: \uac01 \uc11c\ube44\uc2a4\ub294 \uc790\uae30 \ub370\uc774\ud130\ub9cc \uc9c1\uc811 \ub2e4\ub8f9\ub2c8\ub2e4. \ub0a8\uc758 \ub370\uc774\ud130\uac00 \ud544\uc694\ud558\uba74 \ud574\ub2f9 \uc11c\ube44\uc2a4\uc5d0 \uc694\uccad\ud569\ub2c8\ub2e4. \ub0a8\uc758 \ud14c\uc774\ube14\uc744 \uc9c1\uc811 \uc870\ud68c\ud558\ub294 \uac83\uc740 \uae08\uc9c0\uc785\ub2c8\ub2e4.\\n- **\ud638\ucd9c\uc740 \uc815\ud574\uc9c4 \ud1b5\ub85c\ub85c**: \uc11c\ube44\uc2a4 \uac04 \uc9c1\uc811 \ud638\ucd9c\uc740 gRPC\ub97c \uc501\ub2c8\ub2e4. \ud615\uc2dd\uc774 \uc815\ud574\uc838 \uc788\uc5b4 \uc5b4\uae0b\ub098\uba74 \uace7\ubc14\ub85c \ub4dc\ub7ec\ub0a9\ub2c8\ub2e4.\\n- **\uc54c\ub9bc\uc740 \uc774\ubca4\ud2b8\ub85c**: \\"\uacb0\uc81c \uc644\ub8cc\\" \uac19\uc740 \uc0ac\uc2e4\uc740 \uc774\ubca4\ud2b8\ub85c \ubc1c\ud589\ud569\ub2c8\ub2e4(NATS). \ubc1c\ud589\ud558\ub294 \ucabd\uc740 \uc218\uc2e0\uc790\ub97c \ubaa8\ub985\ub2c8\ub2e4. \ud544\uc694\ud55c \uc11c\ube44\uc2a4\uac00 \uc54c\uc544\uc11c \ubc1b\uc2b5\ub2c8\ub2e4.\\n- **\uae34 \uc791\uc5c5\uc740 \uc6cc\ud06c\ud50c\ub85c\uc6b0\ub85c**: \uc911\uac04\uc5d0 \uc2e4\ud328\ud558\uba74 \ub418\ub3cc\ub824\uc57c \ud558\ub294 \uc791\uc5c5\uc740 Temporal\uc5d0 \ub9e1\uae41\ub2c8\ub2e4. \ub418\ub3cc\ub9ac\ub294 \ub85c\uc9c1\uc744 \uc9c1\uc811 \uc9dc\uba74 \ub2e8\uacc4\ub97c \ube60\ub728\ub9ac\uae30 \uc27d\uc2b5\ub2c8\ub2e4.\\n\\n\uc11c\ube44\uc2a4\uac00 \ub298\uba74 \\"\uc774 \ucf54\ub4dc\ub97c \uc5b4\ub514\uc5d0 \ub458\uc9c0\\"\uac00 \ubd80\ub2f4\uc774 \ub429\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc704\uce58\ub97c \ub124 \uacc4\uce35\uc73c\ub85c \uace0\uc815\ud588\uc2b5\ub2c8\ub2e4.\\n\\n| \uacc4\uce35 | \uc5ed\ud560 |\\n| --- | --- |\\n| Product | \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \uc9c1\uc811 \ud638\ucd9c\ud558\ub294 \uc9c4\uc785\uc810. \uc544\ub798 \uacc4\uce35\uc744 \uc870\ub9bd |\\n| Platform | \uc5ec\ub7ec \uacf3\uc774 \uacf5\uc720\ud558\ub294 \uacf5\ud1b5 \uae30\ub2a5 (\uc778\uc99d\xb7\uacb0\uc81c \ub4f1) |\\n| Domain | \ud55c \uac00\uc9c0 \ucc45\uc784\ub9cc \uac00\uc9c0\ub294 \uc11c\ube44\uc2a4 |\\n| Workers | \ub4a4\uc5d0\uc11c \ub3c4\ub294 \ube44\ub3d9\uae30 \ucc98\ub9ac |\\n\\n\uaddc\uce59\uc740 \ud558\ub098\uc785\ub2c8\ub2e4. \ud638\ucd9c\uc740 \uc704\uc5d0\uc11c \uc544\ub798\ub85c\ub9cc \ud750\ub985\ub2c8\ub2e4. \uc544\ub798 \uacc4\uce35\uc774 \uc704\ub97c \ud638\ucd9c\ud558\uba74 \uc11c\ub85c \ubb3c\ub824\uc11c \uae08\uc138 \uc5c9\ud0b5\ub2c8\ub2e4. \uc9c4\uc785\uc810 \uacc4\uce35\uc740 \ub2e8\uc21c \uc911\uacc4\uac00 \uc544\ub2c8\ub77c \uc790\uae30 \ub85c\uc9c1\uc744 \uac00\uc9c0\uba70 \uc544\ub798\ub97c \uc870\ub9bd\ud558\ub294 \uc790\ub9ac\ub77c, \uc774 \ud55c \ubc29\ud5a5 \uaddc\uce59\uc774 \ud2b9\ud788 \uc911\uc694\ud569\ub2c8\ub2e4.\\n\\n\uc0c8 \uc11c\ube44\uc2a4 \ucd94\uac00\ub3c4 \ub2e8\uc21c\ud574\uc9d1\ub2c8\ub2e4. \uc798 \ub9cc\ub4e0 \uc11c\ube44\uc2a4\ub97c \ubcf8\ub5a0 \uac19\uc740 \uad6c\uc870(`api / grpc / logic / model / schema`)\ub97c \ubcf5\uc0ac\ud558\uba74 \ub429\ub2c8\ub2e4. \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc774 \uc606 \uc11c\ube44\uc2a4\uc5d0 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ud5ec\uc2a4\uccb4\ud06c\uc5d0\uc11c \ub370\uc778 \ub300\uac00\\n\\n\uc7a5\uc810\ub9cc \uc788\uc9c0\ub294 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \ucf54\ub4dc\ub97c \ud55c\uacf3\uc5d0 \ubaa8\uc73c\ub2c8 \ud55c \uc11c\ube44\uc2a4\uc758 \uc2e4\uc218\uac00 \uc606\uc73c\ub85c \ubc88\uc9c0\uae30 \uc26c\uc6cc\uc84c\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \ud06c\uac8c \ub370\uc778 \uacf3\uc774 \ud5ec\uc2a4\uccb4\ud06c\uc785\ub2c8\ub2e4.\\n\\n\ubc30\ud3ec \uc2dc\uc2a4\ud15c\uc774 \uc11c\ube44\uc2a4 \uc0c1\ud0dc\ub97c HTTP `/health`\ub85c\ub9cc \ud655\uc778\ud558\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uc6b0\ub9ac \uc11c\ube44\uc2a4\ub294 HTTP \uc11c\ubc84\uc640 gRPC \uc11c\ubc84\ub97c \ud55c \ud504\ub85c\uc138\uc2a4\uc5d0\uc11c \ud568\uaed8 \ub744\uc6c1\ub2c8\ub2e4. gRPC \uc11c\ubc84\uac00 \uc8fd\uc5b4\ub3c4 HTTP `/health`\ub294 \uc815\uc0c1\uc73c\ub85c \uc751\ub2f5\ud588\uc2b5\ub2c8\ub2e4. \uc2dc\uc2a4\ud15c\uc740 \ud574\ub2f9 \uc11c\ubc84\ub97c \uc815\uc0c1\uc73c\ub85c \ud310\ub2e8\ud558\uace0 \ud2b8\ub798\ud53d\uc744 \uacc4\uc18d \ubcf4\ub0c8\uace0, \uadf8\ucabd\uc73c\ub85c \uac04 gRPC \uc694\uccad\uc740 \ubaa8\ub450 \uc2e4\ud328\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\uc815\uc0c1 \uc11c\ubc84\uc640 \uc11e\uc5ec \uc788\uc5b4 <span style={{ backgroundColor: \'#ffdce0\'}}>\uc2e4\ud328\uc728\uc774 100%\uac00 \uc544\ub2c8\ub77c \uc5b4\uc911\uac04\ud588\uc2b5\ub2c8\ub2e4.</span> \\"\uc8fd\uc5c8\ub2e4\\"\uac00 \uba85\ud655\ud788 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc7a5\uc560\uac00 \uac00\uc7a5 \uc624\ub798 \uac11\ub2c8\ub2e4.\\n\\n\\"\uc0b4\uc544 \uc788\ub294\uac00\\"\uc758 \uae30\uc900\uc774 \uc2e4\uc81c \ucc98\ub9ac \ub2a5\ub825\uacfc \uc5b4\uae0b\ub098 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ud5ec\uc2a4\uccb4\ud06c\ub294 \\"\ud3ec\ud2b8\uac00 \uc5f4\ub838\ub294\uac00\\"\uac00 \uc544\ub2c8\ub77c \\"\uc694\uccad\uc744 \ubc1b\uc744 \uc218 \uc788\ub294\uac00\\"\ub97c \ub2f5\ud574\uc57c \ud569\ub2c8\ub2e4. \uc11c\ubc84\ub97c \ub458 \ub744\uc6e0\ub2e4\uba74 \ub2f5\ub3c4 \ub458\uc774\uc5b4\uc57c \ud569\ub2c8\ub2e4.\\n\\n\ud574\uacb0\uc740 \ub450 \uac00\uc9c0\uc600\uc2b5\ub2c8\ub2e4.\\n\\n- gRPC \uc11c\ubc84\ub3c4 \uc0c1\ud0dc\ub97c \ubcc4\ub3c4\ub85c \uc751\ub2f5\ud558\uac8c \ud588\uc2b5\ub2c8\ub2e4. \uc774\uc81c \ubc30\ud3ec \uc2dc\uc2a4\ud15c\uc774 gRPC \ucabd\ub3c4 \uc9c1\uc811 \ud655\uc778\ud569\ub2c8\ub2e4.\\n- \uc885\ub8cc\ub97c \ub2e8\uacc4\uc801\uc73c\ub85c \ucc98\ub9ac\ud588\uc2b5\ub2c8\ub2e4. \uc885\ub8cc \uc2e0\ud638\ub97c \ubc1b\uc73c\uba74 \uba3c\uc800 \\"\uc218\uc2e0 \uc911\ub2e8\\"\uc73c\ub85c \uc804\ud658\ud574 \uc0c8 \uc694\uccad\uc744 \ub04a\uace0, \ucc98\ub9ac \uc911\uc778 \uc694\uccad\uc744 \ub9c8\uce5c \ub4a4 \ub0b4\ub824\uac11\ub2c8\ub2e4. \uc774 \uacfc\uc815\uc774 \uc5c6\uc73c\uba74 \ubc30\ud3ec\ud560 \ub54c\ub9c8\ub2e4 \uc5d0\ub7ec\uac00 \ud291\ub2c8\ub2e4.\\n\\n```python\\nasync def serve() -> None:\\n    server = aio.server(...)\\n    add_servicer_to_server(servicer, server)\\n    health_servicer = register_health_servicer(server)  # \ubc18\ud658\uac12 \ubcf4\uad00 \ud544\uc218\\n    server.add_insecure_port(listen_addr)\\n    await server.start()\\n    # \uc885\ub8cc \uc2e0\ud638 \u2192 \\"\uc218\uc2e0 \uc911\ub2e8\\" \u2192 \ub0a8\uc740 \uc694\uccad \ucc98\ub9ac \u2192 \uc885\ub8cc\\n    await wait_for_termination_with_graceful_shutdown(server, health_servicer)\\n```\\n\\n\ud3ec\ud2b8\ub3c4 \uc804 \uc11c\ube44\uc2a4\uc5d0\uc11c \ud1b5\uc77c\ud588\uc2b5\ub2c8\ub2e4. \ucd08\uae30\uc5d0\ub294 \uc11c\ube44\uc2a4\ub9c8\ub2e4 \ud3ec\ud2b8\uac00 \ub2ec\ub77c \uac8c\uc774\ud2b8\uc6e8\uc774 \uc124\uc815\uc774 \ubcf5\uc7a1\ud588\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\uc740 \ubaa8\ub4e0 \uc11c\ube44\uc2a4\uac00 \uac19\uc740 \ud3ec\ud2b8\ub97c \uc4f0\uace0, \uac8c\uc774\ud2b8\uc6e8\uc774\ub294 \uacbd\ub85c\ub85c\ub9cc \ubd84\uae30\ud569\ub2c8\ub2e4. \\"\uc774 \uc11c\ube44\uc2a4 \ud3ec\ud2b8\uac00 \ubb34\uc5c7\uc774\uc5c8\uc9c0\\"\ub77c\ub294 \uc9c8\ubb38\uc774 \uc0ac\ub77c\uc84c\uc2b5\ub2c8\ub2e4.\\n\\n## \uc5b8\uc81c \ub2e4\uc2dc \ub808\ud3ec\ub97c \ub098\ub20c\uae4c\\n\\n\ubaa8\ub178\ub808\ud3ec\uac00 \ud56d\uc0c1 \uc815\ub2f5\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc9c0\uae08 \uaddc\ubaa8\uc5d0 \ub9de\ub294 \uc120\ud0dd\uc77c \ubfd0\uc785\ub2c8\ub2e4. \ub2e4\uc74c \uc2e0\ud638\uac00 \ubcf4\uc774\uba74 \ubd84\ub9ac\ub97c \ub2e4\uc2dc \uac80\ud1a0\ud560 \uc0dd\uac01\uc785\ub2c8\ub2e4.\\n\\n- \ud2b9\uc815 \uc11c\ube44\uc2a4\ub098 \ud300\uc774 \ub098\uba38\uc9c0\uc640 \ub2e4\ub978 \uc18d\ub3c4\ub85c \ubc30\ud3ec\ud574\uc57c \ud560 \ub54c.\\n- \ube4c\ub4dc\xb7\ud14c\uc2a4\ud2b8\uac00 \ub108\ubb34 \uae38\uc5b4\uc838 \ud53c\ub4dc\ubc31\uc774 \ub290\ub824\uc9c8 \ub54c.\\n- \ucf54\ub4dc \uc18c\uc720\uad8c\uc744 \ud300\ubcc4\ub85c \ubd84\uba85\ud788 \ub098\ub220\uc57c \ud560 \ub54c.\\n\\n\uc544\uc9c1 \uadf8 \uc2dc\uc810\uc740 \uc544\ub2cc \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud55c\uacf3\uc5d0 \ub450\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n- \uc11c\ube44\uc2a4\ub294 \ucc45\uc784\uc758 \uacbd\uacc4\ub97c \uae0b\uace0 \ud544\uc694\uc5d0 \ub530\ub77c \uc870\ub9bd\ud558\ub824\uace0 \ub098\ub234\uc2b5\ub2c8\ub2e4.\\n- \ub808\ud3ec\ub294 \ub098\ub204\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uc18c\uc218 \uc778\uc6d0\uc5d0\uac8c\ub294 \ud55c\uacf3\uc5d0\uc11c \uad00\ub9ac\ud558\ub294 \ube44\uc6a9\uc774 \ub354 \ub0ae\uc2b5\ub2c8\ub2e4.\\n- \ub808\ud3ec\uac00 \ud558\ub098\uc5ec\ub3c4 \uc11c\ube44\uc2a4\ub294 \ub3c5\ub9bd\uc801\uc73c\ub85c \ub3d9\uc791\ud569\ub2c8\ub2e4. \ub370\uc774\ud130 \uaca9\ub9ac / gRPC / \uc774\ubca4\ud2b8 / \uc6cc\ud06c\ud50c\ub85c\uc6b0\ub85c \uacbd\uacc4\ub97c \uc9c0\ud0b5\ub2c8\ub2e4.\\n- \ub2e4\ub9cc \ud55c \uc11c\ube44\uc2a4\uc758 \uc6b4\uc601 \uc2e4\uc218\uac00 \uc606\uc73c\ub85c \ubc88\uc9d1\ub2c8\ub2e4. \ud5ec\uc2a4\uccb4\ud06c\ucc98\ub7fc \ud55c \ud504\ub85c\uc138\uc2a4\uac00 \uc11c\ubc84 \ub458\uc744 \ub744\uc6b0\ub294 \uc9c0\uc810\uc740 \uae30\uc900\ubd80\ud130 \ub2e4\uc2dc \ubd10\uc57c \ud569\ub2c8\ub2e4.\\n\\n\ub2e4\uc74c \ud3b8\uc5d0\uc11c\ub294 \uc774 \uc704\uc5d0 \uc62c\ub9b0 **\uc778\uc99d**\uc744 \ub2e4\ub904 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ud1a0\ud070 \ub85c\uadf8\uc778\uc744 \ubd99\uc774\uba70 \ub9cc\ub09c \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504, \uadf8\ub9ac\uace0 \ucfe0\ud0a4 \ud06c\uae30 \ud55c\uacc4\uac00 \uc124\uacc4\ub97c \uc5b4\ub5bb\uac8c \ubc14\uafe8\ub294\uc9c0 \uc801\uc5b4 \ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4."},{"id":"build-log-intro","metadata":{"permalink":"/blog/build-log-intro","source":"@site/blog/2026-06-11-build-log-intro/index.md","title":"6\uac1c\uc6d4\uac04 \ubc31\uc5d4\ub4dc\xb7\ud504\ub860\ud2b8\uc5d4\ub4dc\xb7\uc778\ud504\ub77c\ub97c \ub9cc\ub4e0 \uae30\ub85d (\uc2dc\ub9ac\uc988 \uc2dc\uc791)","description":"\uc9c0\ub09c 6\uac1c\uc6d4 \ub3d9\uc548 \ubc31\uc5d4\ub4dc, \ud504\ub860\ud2b8\uc5d4\ub4dc, \uc778\ud504\ub77c\ub97c 0\uc5d0\uc11c \ub9cc\ub4e4\uace0 \uc6b4\uc601\uae4c\uc9c0 \uc62c\ub9b0 \uacfc\uc815\uc744 \uc2dc\ub9ac\uc988\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc804\uccb4 \ubaa9\ucc28\uc774\uc790 \uc2dc\uc791\uc810\uc785\ub2c8\ub2e4.","date":"2026-06-11T00:00:00.000Z","tags":[{"inline":true,"label":"Essay","permalink":"/blog/tags/essay"},{"inline":true,"label":"Retrospective","permalink":"/blog/tags/retrospective"},{"inline":true,"label":"Architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"BuildLog","permalink":"/blog/tags/build-log"}],"readingTime":1.27,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"6\uac1c\uc6d4\uac04 \ubc31\uc5d4\ub4dc\xb7\ud504\ub860\ud2b8\uc5d4\ub4dc\xb7\uc778\ud504\ub77c\ub97c \ub9cc\ub4e0 \uae30\ub85d (\uc2dc\ub9ac\uc988 \uc2dc\uc791)","slug":"build-log-intro","authors":["kgenots"],"tags":["Essay","Retrospective","Architecture","BuildLog"],"image":"/assets/blog/cover-build-log-intro.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ubaa8\ub178\ub808\ud3ec \ud558\ub098\uc5d0 15\uac1c \uc11c\ube44\uc2a4\ub97c \ub2f4\uc740 \uc774\uc720","permalink":"/blog/monorepo-15-service-msa"},"nextItem":{"title":"\uc65c \uc9c0\uae08, Python\uc744 \uc54c\uc544\uc57c \ud560\uae4c?","permalink":"/blog/why-learn-python-now"}},"content":"\uc9c0\ub09c 6\uac1c\uc6d4 \ub3d9\uc548 \ubc31\uc5d4\ub4dc, \ud504\ub860\ud2b8\uc5d4\ub4dc, \uc778\ud504\ub77c\ub97c 0\uc5d0\uc11c \ub9cc\ub4e4\uace0 \uc6b4\uc601\uae4c\uc9c0 \uc62c\ub9b0 \uacfc\uc815\uc744 \uc2dc\ub9ac\uc988\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc804\uccb4 \ubaa9\ucc28\uc774\uc790 \uc2dc\uc791\uc810\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc5c8\ub098\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/build-log-intro-2.webp\\"\\n    alt=\\"\ubc31\uc5d4\ub4dc \uc5ec\ub7ec \uc11c\ube44\uc2a4, \uc787\ub294 \ud1b5\uc2e0\uacfc \uc774\ubca4\ud2b8, \ud504\ub860\ud2b8\uc5d4\ub4dc \uc5ec\ub7ec \uc571, \uadf8\ub9ac\uace0 \ub450 \ud658\uacbd\uc5d0\uc11c \uc2e4\ud589\ub418\ub294 \uad6c\uc131\\"\\n  />\\n</figure>\\n\\n\ubc18\ub144 \ub3d9\uc548 \ub9cc\ub4e0 \uac83\uc744 \ud55c \uc904\ub85c \uc904\uc774\uba74 <span style={{ backgroundColor: \'#fff5b1\'}}>\uc5ec\ub7ec \uac1c\uc758 \uc11c\ube44\uc2a4\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc81c\ud488\uc744, \ud074\ub77c\uc6b0\ub4dc\uc640 \uace0\uac1d\uc0ac \uc591\ucabd\uc5d0\uc11c \uad74\ub9b4 \uc218 \uc788\uac8c \ub9cc\ub4e0 \uc77c</span>\uc785\ub2c8\ub2e4.\\n\\n- \ub4a4\ucabd(\ubc31\uc5d4\ub4dc)\uc5d0\ub294 \ucc45\uc784\uc744 \uc798\uac8c \ub098\ub208 \uc5ec\ub7ec \uc11c\ube44\uc2a4\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uadf8 \uc11c\ube44\uc2a4\ub4e4\uc744 \uc787\ub294 \ud1b5\uc2e0\xb7\uc774\ubca4\ud2b8\xb7\uc791\uc5c5 \ud750\ub984\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc55e\ucabd(\ud504\ub860\ud2b8\uc5d4\ub4dc)\uc5d0\ub294 \uc5ec\ub7ec \uac1c\uc758 \uc6f9 \uc571\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n- \uc774 \ubaa8\ub4e0 \uac83\uc774 \ud074\ub77c\uc6b0\ub4dc(SaaS)\uc640 \uace0\uac1d\uc0ac \uc548(\uc628\ud504\ub808\ubbf8\uc2a4) \ub450 \ud658\uacbd\uc5d0\uc11c \ub3d5\ub2c8\ub2e4.\\n\\n\ub9cc\ub4dc\ub294 \ub3d9\uc548 \uc801\uc5b4 \ub454 \uacb0\uc815\uacfc \uc2e4\uc218\ub97c \uc77c\uacf1 \ud3b8\uc73c\ub85c \ub098\ub220 \ud480\uc5c8\uc2b5\ub2c8\ub2e4. \uac70\ucc3d\ud55c \uc815\ub2f5\uc9d1\uc740 \uc544\ub2c8\uace0, <b>\uadf8\ub54c\uadf8\ub54c \uc65c \uadf8\ub807\uac8c \ud588\uace0 \ubb34\uc5c7\uc5d0 \ub370\uc600\ub294\uc9c0</b>\ub97c \uc194\uc9c1\ud558\uac8c \uc801\uc740 \uae30\ub85d\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.\\n\\n## \uc774 \uc2dc\ub9ac\uc988\ub97c \uc77d\ub294 \ubc95\\n\\n\uc21c\uc11c\ub300\ub85c \uc77d\uc73c\uba74 \\"\uc11c\ube44\uc2a4\ub97c \ub098\ub204\uace0 \u2192 \uc787\uace0 \u2192 \ub450 \ud658\uacbd\uc5d0 \uc62c\ub9ac\uace0 \u2192 \uc6b4\uc601\uc73c\ub85c \ub118\uc5b4\uac00\ub294\\" \ud750\ub984\uc744 \ub530\ub77c\uac00\uac8c \ub429\ub2c8\ub2e4. \ub2e4\ub9cc \uac01 \ud3b8\uc740 \ub530\ub85c \uc77d\uc5b4\ub3c4 \ub429\ub2c8\ub2e4. \uad00\uc2ec \uac00\ub294 \uc8fc\uc81c\ubd80\ud130 \uace8\ub77c \ubcf4\uc154\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4.\\n\\n## \ubaa9\ucc28\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/build-log-intro.webp\\"\\n    alt=\\"6\uac1c\uc6d4 \ube4c\ub4dc \uc2dc\ub9ac\uc988, \uc77c\uacf1 \ud3b8\uc758 \uc5ec\uc815\uc744 \ud55c\ub208\uc5d0 \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ub3c4\\"\\n  />\\n</figure>\\n\\n1. [\ubaa8\ub178\ub808\ud3ec \ud558\ub098\uc5d0 15\uac1c \uc11c\ube44\uc2a4\ub97c \ub2f4\uc740 \uc774\uc720](/blog/monorepo-15-service-msa). \uc11c\ube44\uc2a4\ub294 \ub098\ub204\uba74\uc11c \ub808\ud3ec\ub294 \ud558\ub098\ub85c \ub454 \uc774\uc720\uc785\ub2c8\ub2e4.\\n2. [\uc778\uc99d\uc744 \ubd99\uc774\ub2e4 \ub9cc\ub09c \ubb34\ud55c \ub9ac\ub2e4\uc774\ub809\ud2b8 \ub8e8\ud504](/blog/auth-bff-redirect-loop). \ub85c\uadf8\uc778 \ud558\ub098\uac00 \ud68c\uc804\ubb38\uc774 \ub41c \uc0ac\uc5f0\uc785\ub2c8\ub2e4.\\n3. [\uc11c\ube44\uc2a4 \uc0ac\uc774\ub97c \uc787\ub294 \ubc95, \uc774\ubca4\ud2b8 \ubc84\uc2a4\uc640 \uc6cc\ud06c\ud50c\ub85c\uc6b0](/blog/event-bus-nats-temporal). \uc9c1\uc811 \ubd80\ub974\uc9c0 \uc54a\uace0 \uac8c\uc2dc\ud310\uc5d0 \ubd99\uc774\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n4. [\ud558\ub098\uc758 \ub808\ud3ec\ub85c \ud074\ub77c\uc6b0\ub4dc SaaS\uc640 \uc628\ud504\ub808\ubbf8\uc2a4\ub97c \ud568\uaed8 \uc6b4\uc601\ud558\uae30](/blog/one-repo-saas-and-onprem). \uc778\ud130\ub137\uc774 \ub9c9\ud78c \uacf3\uc5d0 \uc5b4\ub5bb\uac8c \uc124\uce58\ud588\ub294\uc9c0 \uc801\uc5c8\uc2b5\ub2c8\ub2e4.\\n5. [\ud558\ub098\uc758 \ucf54\ub4dc\ubca0\uc774\uc2a4\ub85c \uc5ec\ub7ec \uc6f9 \uc571 \ub9cc\ub4e4\uae30](/blog/one-codebase-many-web-apps). \ud55c \ubc88 \ube4c\ub4dc\ud55c \uc571\uc744 \uace0\uac1d\ub9c8\ub2e4 \ub2e4\ub978 \uc8fc\uc18c\ub85c \ub744\uc6c1\ub2c8\ub2e4.\\n6. [\ub9cc\ub4dc\ub294 \ub2e8\uacc4\uc5d0\uc11c \uc6b4\uc601\ud558\ub294 \ub2e8\uacc4\ub85c](/blog/from-building-to-operating). \uc9c8\ubb38\uc774 \\"\ub418\ub294\uac00\\"\uc5d0\uc11c \\"\uad74\ub9b4 \uc218 \uc788\ub098\\"\ub85c \ubc14\ub01d\ub2c8\ub2e4.\\n7. [6\uac1c\uc6d4\uc744 \ub3cc\uc544\ubcf4\uba70, \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\uba74](/blog/six-months-in-retrospect). \ubc18\ubcf5\ud574\uc11c \ubc30\uc6b4 \uac83\uacfc \ub2e4\ub974\uac8c \ud560 \uac83\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n## \ud55c \uac00\uc9c0 \ubbf8\ub9ac \ub9d0\ud558\uba74\\n\\n\uc77c\uacf1 \ud3b8\uc744 \uc801\uace0 \ub098\uc11c\uc57c \ubcf4\uc600\uc2b5\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc774\uc57c\uae30\uc778 \uc904 \uc54c\uc558\ub294\ub370, \uac19\uc740 \uad50\ud6c8\uc744 \uacc4\uc18d \ubc18\ubcf5\ud558\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n<b>\uacf5\ud1b5\uc740 \ud55c\uacf3\uc5d0 \ubaa8\uc73c\uace0, \ud658\uacbd \ucc28\uc774\ub294 \uac00\uc7a5\uc790\ub9ac\ub85c \ubc00\uace0, \uc870\uc6a9\ud55c \uc2e4\ud328\ub97c \ub4dc\ub7ec\ub0b4\uace0, \ub9cc\ub4e0 \uac83\uc744 \uad74\ub9b4 \uc218 \uc788\uac8c \ud55c\ub2e4.</b>\\n\\n\uc774 \ud55c \uc904\uc774 \uc2dc\ub9ac\uc988 \uc804\uccb4\ub97c \uad00\ud1b5\ud558\ub294 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uadf8\ub7fc [1\ud3b8](/blog/monorepo-15-service-msa)\ubd80\ud130 \uc2dc\uc791\ud558\uaca0\uc2b5\ub2c8\ub2e4."},{"id":"why-learn-python-now","metadata":{"permalink":"/blog/why-learn-python-now","source":"@site/blog/2025-07-03-why-learn-python-now/index.md","title":"\uc65c \uc9c0\uae08, Python\uc744 \uc54c\uc544\uc57c \ud560\uae4c?","description":"AI, \ub370\uc774\ud130, \uc790\ub3d9\ud654, \uadf8\ub9ac\uace0 \uc0c8\ub85c\uc6b4 \uc9c1\uad70\ub4e4\uc774 \uc0dd\uaca8\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4.","date":"2025-07-03T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"Python","permalink":"/blog/tags/python"}],"readingTime":1.29,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\uc65c \uc9c0\uae08, Python\uc744 \uc54c\uc544\uc57c \ud560\uae4c?","slug":"why-learn-python-now","authors":["kgenots"],"tags":["Tech","Python"],"image":"/assets/blog/why-learn-python-now.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"6\uac1c\uc6d4\uac04 \ubc31\uc5d4\ub4dc\xb7\ud504\ub860\ud2b8\uc5d4\ub4dc\xb7\uc778\ud504\ub77c\ub97c \ub9cc\ub4e0 \uae30\ub85d (\uc2dc\ub9ac\uc988 \uc2dc\uc791)","permalink":"/blog/build-log-intro"},"nextItem":{"title":"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ud55c \uc77c \uc815\ub9ac","permalink":"/blog/2025-h1-review"}},"content":"AI, \ub370\uc774\ud130, \uc790\ub3d9\ud654, \uadf8\ub9ac\uace0 \uc0c8\ub85c\uc6b4 \uc9c1\uad70\ub4e4\uc774 \uc0dd\uaca8\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4.  \\n\u2018MLOps \uc5d4\uc9c0\ub2c8\uc5b4\u2019, \u2018AI \ub9ac\uc11c\ucc98\u2019, \u2018\ub370\uc774\ud130 \ud37c\ube14\ub9ac\uc154\u2019\u2026  \\n\uc774\ub7f0 \ubcc0\ud654 \uc18d\uc5d0\uc11c \uac1c\ubc1c\uc790\ub294 \uc5b4\ub5a4 \uae30\uc220\uc744 \ubc30\uc6b0\uace0, \uc5b4\ub5a4 \ub3c4\uad6c\ub97c \uc775\ud600\uc57c \ud560\uae4c\uc694?\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/why-learn-python-now.webp\\"\\n    alt=\\"why-learn-python-now\\"\\n  />\\n</figure>\\n\\n## \ud83e\udded \uc775\uc219\ud55c \uae30\uc220, \ub0af\uc120 \uc2dc\ub300\\n\\n\ud55c\ub3d9\uc548 \uad6d\ub0b4 \uac1c\ubc1c \ud658\uacbd, \ud2b9\ud788 \uacf5\uacf5 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c\ub294 **Java \uae30\ubc18\uc758 Spring Boot**\uac00 \ud45c\uc900\ucc98\ub7fc \uc0ac\uc6a9\ub410\uc2b5\ub2c8\ub2e4.\\n\\n- Spring + MyBatis \uc870\ud569\\n- JSP, DAO, Service \uacc4\uce35\uc73c\ub85c \ub098\ub25c \uad6c\uc870\\n- XML \uc124\uc815\uacfc \uc815\ud615\ud654\ub41c \ud328\ud134\\n- \uacf5\uacf5\uae30\uad00 \uc911\uc2ec\uc758 \uc548\uc815\uc801 \uad6c\uc870\\n\\n> \\"\uadf8\ub7fc \uc9c0\uae08\ub3c4 Java\ub9cc\uc73c\ub85c \ucda9\ubd84\ud560\uae4c?\\"\\n\\n## \ud83e\udd16 \uc0c8\ub85c\uc6b4 \uc9c1\uad70\uc740 Python\uc744 \uc4f4\ub2e4\\n\\nAI \uac1c\ubc1c, \ub370\uc774\ud130 \ubd84\uc11d, \uc790\ub3d9\ud654, \uc2dc\uc2a4\ud15c \uc6b4\uc601\u2026\\n\uc774 \ubaa8\ub4e0 \uc601\uc5ed\uc5d0\uc11c \uc911\uc2ec\uc5d0 \uc788\ub294 \uc5b8\uc5b4\ub294 **Python**\uc785\ub2c8\ub2e4.\\n\\n- ChatGPT, HuggingFace, Llama \uac19\uc740 LLM \u2192 \ubaa8\ub450 Python \uae30\ubc18\\n- FastAPI, Django \u2192 \ube60\ub978 \ubc31\uc5d4\ub4dc \uac1c\ubc1c \uac00\ub2a5\\n- Pandas, Jupyter \u2192 \ubd84\uc11d\uacfc \ubcf4\uace0 \uc790\ub3d9\ud654\\n- Airflow, Schedule \u2192 \uc5c5\ubb34 \ud750\ub984 \uc790\ub3d9\ud654\\n- Markdown + Python \u2192 \ubb38\uc11c\ud654 \ubc0f \ud37c\ube14\ub9ac\uc2f1\\n\\nPython\uc740 \ub2e8\uc21c\ud788 \\"\ubc30\uc6cc\ub450\uba74 \uc88b\uc740 \uc5b8\uc5b4\\"\uac00 \uc544\ub2d9\ub2c8\ub2e4.  \\n**\uc9c0\uae08\uc758 \uae30\uc220 \uc0dd\ud0dc\uacc4\uc5d0\uc11c \uac00\uc7a5 \uc790\uc8fc \uc4f0\uc774\uace0, \uc2e4\uc81c\ub85c \uc4f0\uc774\ub294 \uc5b8\uc5b4**\uc785\ub2c8\ub2e4.\\n\\n---\\n\\n## \u2699\ufe0f Java\uc640 Python, \ud568\uaed8 \uc368\ubd10\uc57c \ubcf4\uc778\ub2e4\\n\\nJava\ub9cc \uc368\ubcf8 \uac1c\ubc1c\uc790\ub77c\uba74, \uc774\ub7f0 \uc758\ubb38\uc774 \ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n> \u201cJava\ub85c\ub3c4 \ub2e4 \ub418\uc9c0 \uc54a\ub098?\u201d\\n\\n\ub9de\uc2b5\ub2c8\ub2e4. Java\ub294 \uc5ec\uc804\ud788 \uc720\ud6a8\ud558\uace0, \ud2b9\ud788 \ub300\uaddc\ubaa8 \ubc31\uc5d4\ub4dc \uc2dc\uc2a4\ud15c\uc5d0 \uac15\ud569\ub2c8\ub2e4.  \\n\ud558\uc9c0\ub9cc **\uc0dd\uc0b0\uc131, \uac04\uacb0\ud568, \uc790\ub3d9\ud654, \ube60\ub978 \ud53c\ub4dc\ubc31 \ub8e8\ud504**\ub294 Python\uc774 \ud6e8\uc52c \uc720\ub9ac\ud569\ub2c8\ub2e4.\\n\\n| \ud56d\ubaa9           | Java (\uc804\uc790\uc815\ubd80\ud504\ub808\uc784\uc6cc\ud06c) | Python                      |\\n| -------------- | ------------------------- | --------------------------- |\\n| \uc0dd\uc0b0\uc131         | \uc124\uc815 \ub9ce\uace0 \uad6c\uc870 \ubcf5\uc7a1       | \ube60\ub978 \uac1c\ubc1c, \uac04\uacb0\ud55c \ucf54\ub4dc      |\\n| AI/\ub370\uc774\ud130 \uc5f0\uacc4 | \uc57d\ud568                      | \uac15\ub825\ud55c \uc0dd\ud0dc\uacc4               |\\n| \uc790\ub3d9\ud654/Ops     | \ubb34\uac70\uc6c0                    | \uacbd\ub7c9\ud654, \uc2a4\ud06c\ub9bd\ud2b8 \uce5c\ud654       |\\n| \uc9c4\uc785\uc7a5\ubcbd       | \ub192\uc74c (JVM, \ube4c\ub4dc \ub3c4\uad6c \ub4f1)  | \ub0ae\uc74c (\uac04\ub2e8\ud55c \ubb38\ubc95)          |\\n| \ud37c\ube14\ub9ac\uc2f1       | JSP, JavaDoc \ub4f1 \uc804\ud1b5\uc801    | Markdown, Jupyter \ub4f1 \uc720\uc5f0\ud568 |\\n\\n---\\n\\n## \ud83e\udde0 \ud788\uc2a4\ud1a0\ub9ac\ub97c \uc544\ub294 Python \uac1c\ubc1c\uc790\\n\\n\uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac74 **Java\ub97c \ubc84\ub9ac\uc790\ub294 \uac8c \uc544\ub2c8\ub77c**,  \\n**Java \uae30\ubc18 \uc2dc\uc2a4\ud15c\uc744 \uc774\ud574\ud558\ub294 \uc0ac\ub78c\uc774 Python\uae4c\uc9c0 \uc775\ud788\uba74 \ubb34\uae30\uac00 \ub41c\ub2e4\ub294 \uac83**\uc785\ub2c8\ub2e4.\\n\\n\uc804\uc790\uc815\ubd80\ud504\ub808\uc784\uc6cc\ud06c\ub85c \uad6c\uc131\ub41c \uc2dc\uc2a4\ud15c\uc744 \uc720\uc9c0\xb7\ubcf4\uc218\ud558\uba74\uc11c\ub3c4:\\n\\n- \ub85c\uadf8 \uc218\uc9d1 \ubc0f \ub9ac\ud3ec\ud305\uc740 Python\uc73c\ub85c\\n- \ubc30\uce58/\uc790\ub3d9\ud654 \uc2a4\ud06c\ub9bd\ud2b8\ub294 Python\uc73c\ub85c\\n- AI \uc5f0\ub3d9 \uae30\ub2a5\uc740 Python\uc73c\ub85c\\n- \uc6b4\uc601 \ub9ac\ud3ec\ud2b8 \uc790\ub3d9 \uc0dd\uc131\uc740 Python + Markdown\\n\\n> \ud788\uc2a4\ud1a0\ub9ac\ub97c \uc54c\uace0 \uc788\ub294 \uc0ac\ub78c\uc774,  \\n> \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\ub85c \ubbf8\ub798\uae4c\uc9c0 \uc124\uacc4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n---\\n\\n## \ud83d\udca1 Python\uc740 \uc120\ud0dd\uc774 \uc544\ub2c8\ub77c, \uae30\ubcf8 \ub3c4\uad6c\\n\\n\uac1c\ubc1c\uc790\ub85c\uc11c \uc2dc\uc2a4\ud15c\uc744 \uc9c0\ud0a4\ub294 \uc77c\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc,  \\n\uc774\uc81c\ub294 \uadf8 \uc704\uc5d0 \ub370\uc774\ud130\ub97c \uc5f0\uacb0\ud558\uace0, \uc790\ub3d9\ud654\ud558\uace0,  \\n\ucf58\ud150\uce20\ub85c \uc815\ub9ac\ud574 **\uc804\ub2ec\ud560 \uc218 \uc788\ub294 \uc5ed\ub7c9**\uae4c\uc9c0 \uc694\uad6c\ub429\ub2c8\ub2e4.\\n\\n\uadf8 \ubaa8\ub4e0 \uc5ed\ud560\uc744 \uc720\uc5f0\ud558\uac8c \uc18c\ud654\ud560 \uc218 \uc788\ub294 \ub3c4\uad6c\uac00 \ubc14\ub85c Python\uc785\ub2c8\ub2e4.\\n\\n---\\n\\n## \u2615\ufe0f \ub9c8\ubb34\ub9ac\ud558\uba70\\n\\n\uc9c0\uae08 \uac1c\ubc1c\uc790\uc5d0\uac8c \ud544\uc694\ud55c \uac74 \\"\uc774 \uc5b8\uc5b4\uac00 \ub354 \uc88b\ub2e4\\"\ub294 \ub17c\uc7c1\uc774 \uc544\ub2d9\ub2c8\ub2e4.  \\n**\uae30\uc220\uc774 \ubc14\ub00c\ub294 \uc774\uc720\uc640 \ubc29\ud5a5\uc744 \uc774\ud574\ud558\uace0, \uac70\uae30\uc5d0 \uc801\uc751\ud560 \uc218 \uc788\ub294 \uc900\ube44**\uc785\ub2c8\ub2e4.\\n\\nJava\ub97c \uc798 \uc544\ub294 \uac1c\ubc1c\uc790\ub77c\uba74,\\nPython\uc740 \uc5b4\ub835\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.  \\n\uc624\ud788\ub824 **\ub354 \ube68\ub9ac, \ub354 \uac15\ud558\uac8c \uc131\uc7a5\ud560 \uc218 \uc788\ub294 \uae38**\uc774 \ub420 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc800\ub791 \ud568\uaed8\ud558\uace0 \uc2f6\ub2e4\uba74 kgenots@gmail.com \ub85c \uc5f0\ub77d\uc8fc\uc138\uc694 :D"},{"id":"2025-h1-review","metadata":{"permalink":"/blog/2025-h1-review","source":"@site/blog/2025-06-03-2025-1h-retrospective/index.md","title":"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ud55c \uc77c \uc815\ub9ac","description":"2025\ub144 \uc0c1\ubc18\uae30\ub294 \uc65c \ub2ec\ub9ac\uace0 \uc788\ub294\uc9c0\ub97c \ub354 \ub9ce\uc774 \uace0\ubbfc\ud55c \uc2dc\uae30\uc600\uc2b5\ub2c8\ub2e4. \uae30\uc220\ud300 \ub9ac\ub354\ub85c\uc11c \ub9e1\ub294 \uc77c\uc774 \ub2ec\ub77c\uc84c\uace0, \ubc29\ud5a5\uc744 \ub2e4\uc2dc \uc7a1\uc544\uc57c \ud588\uc2b5\ub2c8\ub2e4.","date":"2025-06-03T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"\ud300\ub9ac\ub354\uc2ed","permalink":"/blog/tags/\ud300\ub9ac\ub354\uc2ed"},{"inline":true,"label":"\uc131\uc7a5\uae30\ub85d","permalink":"/blog/tags/\uc131\uc7a5\uae30\ub85d"}],"readingTime":0.79,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ud55c \uc77c \uc815\ub9ac","slug":"2025-h1-review","authors":["kgenots"],"tags":["Tech","\ud300\ub9ac\ub354\uc2ed","\uc131\uc7a5\uae30\ub85d"],"image":"/assets/blog/retrospective-2025-1h.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\uc65c \uc9c0\uae08, Python\uc744 \uc54c\uc544\uc57c \ud560\uae4c?","permalink":"/blog/why-learn-python-now"},"nextItem":{"title":"Amazon Linux 2023 Docker Compose \uc124\uce58","permalink":"/blog/aws-linux-2023-docker"}},"content":"2025\ub144 \uc0c1\ubc18\uae30\ub294 \uc65c \ub2ec\ub9ac\uace0 \uc788\ub294\uc9c0\ub97c \ub354 \ub9ce\uc774 \uace0\ubbfc\ud55c \uc2dc\uae30\uc600\uc2b5\ub2c8\ub2e4. \uae30\uc220\ud300 \ub9ac\ub354\ub85c\uc11c \ub9e1\ub294 \uc77c\uc774 \ub2ec\ub77c\uc84c\uace0, \ubc29\ud5a5\uc744 \ub2e4\uc2dc \uc7a1\uc544\uc57c \ud588\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/retrospective-2025-1h.webp\\"\\n    alt=\\"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ub9e1\uc558\ub358 \uc77c\ub4e4\uc744 \uc11c\ube44\uc2a4, \uc2dc\uc2a4\ud15c, \ub370\uc774\ud130, \ud234\ub9c1\uc73c\ub85c \ub098\ub220 \uc815\ub9ac\ud55c \uadf8\ub9bc\\"\\n  />\\n</figure>\\n\\n## \uc11c\ube44\uc2a4 \uad6c\ucd95\uacfc \ub9ac\ub274\uc5bc\\n\\n- IT \uc911\uc7a5\uae30 \uacc4\ud68d \uc218\ub9bd\uacfc \ubb38\uc11c\ud654\\n- \ud769\uc5b4\uc838 \uc788\ub358 \ubc31\uc624\ud53c\uc2a4 \uc2dc\uc2a4\ud15c\uc744 \ud558\ub098\ub85c \ubaa8\uc73c\ub294 \uc791\uc5c5 (ERP)\\n- \ud68c\uc0ac \ud648\ud398\uc774\uc9c0 \uac1c\ud3b8 \uae30\ud68d\\n- \uc911\uac1c\uc0ac\uc6a9 \ub9e4\ubb3c \uad00\ub9ac \uc11c\ube44\uc2a4 \uae30\ud68d\\n\\n\uae30\ud68d\uc744 \ubb38\uc11c\ub85c \ub0a8\uae30\ub294 \ub370 \uc2dc\uac04\uc744 \ub9ce\uc774 \uc37c\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc190\uc774 \ub290\ub824\uc9c0\ub294 \ub290\ub08c\uc774\uc5c8\ub294\ub370, \uac19\uc740 \ub17c\uc758\ub97c \ub450 \ubc88 \ud558\uc9c0 \uc54a\uac8c \ub418\uba74\uc11c \uc18d\ub3c4\uac00 \ubd99\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \uae30\uc220\uacfc \uc2dc\uc2a4\ud15c \uad6c\uc131\\n\\n- FastAPI \uae30\ubc18 \ub9c8\uc774\ud06c\ub85c\uc11c\ube44\uc2a4 \uc544\ud0a4\ud14d\ucc98 \uc124\uacc4\\n- AWS Aurora PostgreSQL Serverless V2\uc640 RDS Proxy \uc870\ud569 \ucd5c\uc801\ud654\\n- Whisper\uc640 Streamlit, \ubb38\uc11c \ub3c4\uad6c\ub97c \uc5ee\uc740 \ud68c\uc758 \uae30\ub85d \uc790\ub3d9\ud654\\n- n8n\uc744 \uc774\uc6a9\ud55c \uc774\uba54\uc77c \uc790\ub3d9 \ubd84\ub958\uc640 \uc2a4\ud504\ub808\ub4dc\uc2dc\ud2b8 \uae30\ub85d \uc790\ub3d9\ud654\\n\\n:::info \uc0ac\ub78c\uc774 \ud558\ub358 \ubc1b\uc544\uc4f0\uae30\\n\ud68c\uc758\ub85d\uc740 \ub204\uad70\uac00 \ud68c\uc758 \ub0b4\ub0b4 \ubc1b\uc544 \uc801\uc5b4\uc57c \ud558\ub294 \uc77c\uc785\ub2c8\ub2e4. \ub179\uc74c\uc744 \ud14d\uc2a4\ud2b8\ub85c \ubcc0\ud658\ud558\ub294 \ub2e8\uacc4\ub9cc \uae30\uacc4\uc5d0 \ub9e1\uacbc\ub354\ub2c8, \uc0ac\ub78c\uc740 \uc815\ub9ac\ud558\uace0 \ud310\ub2e8\ud558\ub294 \uc77c\ub9cc \ub2f4\ub2f9\ud558\uba74 \ub410\uc2b5\ub2c8\ub2e4.\\n:::\\n\\n\uc790\ub3d9\ud654 \ub300\uc0c1\uc740 \uc0ac\ub78c\uc774 \ubc18\ubcf5\ud558\ub2e4 \uc2e4\uc218\ud558\ub294 \uc791\uc5c5\uc73c\ub85c \ud55c\uc815\ud588\uc2b5\ub2c8\ub2e4. \ud310\ub2e8\uc774 \ud544\uc694\ud55c \uc791\uc5c5\uc740 \uadf8\ub300\ub85c \ub450\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \ub370\uc774\ud130\ub97c \uadfc\uac70\ub85c \ud55c \uae30\ud68d\\n\\n- VOC \uc790\ub3d9\ud654\ubcf4\ub2e4 B2C \ud37c\ub110 \ud655\uc7a5\uacfc \ub0b4\ubd80 IT \ub9ac\uc18c\uc2a4 \ud6a8\uc728\ud654\uc5d0 \ubb34\uac8c\ub97c \ub450\uc5c8\uc2b5\ub2c8\ub2e4\\n- \ube0c\ub79c\ub4dc \ub9c8\ucf00\ud305 \uc870\uc9c1\uacfc \ud568\uaed8 \ud611\uc5c5 \uc544\uc820\ub2e4\ub97c \ubf51\uc558\uc2b5\ub2c8\ub2e4\\n\\n\uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud560 \ub54c \uc22b\uc790\ub97c \uba3c\uc800 \ubcf8 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub410\uc2b5\ub2c8\ub2e4.\\n\\n## \ud234\ub9c1\\n\\n- Ruff\uc640 uv \uc870\ud569\uc744 \ub3c4\uc785\ud574 Python \ud504\ub85c\uc81d\ud2b8 \ud234\ub9c1\uc744 \uc815\ub9ac\ud588\uc2b5\ub2c8\ub2e4\\n\\n\ub9b0\ud2b8\uc640 \uc758\uc874\uc131 \uc124\uce58\ub97c \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uc774 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \ub3cc\uc544\ubcf4\uba70\\n\\n\uc0c1\ubc18\uae30 \ub0b4\ub0b4 \uc720\uc9c0\ud560 \uc218 \uc788\ub294 \ub9cc\ud07c\ub9cc \ub9cc\ub4e4\uc790\ub294 \uae30\uc900\uc744 \uc801\uc6a9\ud588\uc2b5\ub2c8\ub2e4. \ub9ac\ub354 \uc5ed\ud560\uc774 \ub2ec\ub77c\uc9c4 \uac83\ub3c4 \uac19\uc740 \uae30\uc900\uc5d0\uc11c \ube44\ub86f\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc9c0 \uacb0\uc815\ud558\ub294 \uc2dc\uac04\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc9c0 \uc54a\uc744\uc9c0 \uacb0\uc815\ud558\ub294 \uc2dc\uac04\uc774 \ub354 \uae38\uc5c8\uc2b5\ub2c8\ub2e4."},{"id":"aws-linux-2023-docker","metadata":{"permalink":"/blog/aws-linux-2023-docker","source":"@site/blog/2024-03-21-aws-linux-2023-docker/index.md","title":"Amazon Linux 2023 Docker Compose \uc124\uce58","description":"\ucd5c\uc2e0 \ubc84\uc804\uc758 Docker Compose\ub97c \uc774\uc6a9\ud558\uae30 \uc704\ud574 Docker Compose \ud50c\ub7ec\uadf8\uc778\uc744 \uc0ac\uc6a9\ud574\ubcf4\uc790.","date":"2024-03-21T00:00:00.000Z","tags":[{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"},{"inline":true,"label":"AWS","permalink":"/blog/tags/aws"}],"readingTime":0.33,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Amazon Linux 2023 Docker Compose \uc124\uce58","slug":"aws-linux-2023-docker","authors":["kgenots"],"tags":["Ops","AWS"],"image":"/assets/blog/unnamed-docker.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ud55c \uc77c \uc815\ub9ac","permalink":"/blog/2025-h1-review"},"nextItem":{"title":"Docker \uba85\ub839\uc5b4 \uc815\ub9ac (\uc774\ubbf8\uc9c0, \ucee8\ud14c\uc774\ub108)","permalink":"/blog/docker-commands"}},"content":"\ucd5c\uc2e0 \ubc84\uc804\uc758 Docker Compose\ub97c \uc774\uc6a9\ud558\uae30 \uc704\ud574 Docker Compose \ud50c\ub7ec\uadf8\uc778\uc744 \uc0ac\uc6a9\ud574\ubcf4\uc790.\\n\\n\x3c!--truncate--\x3e\\n\\n## Docker Compose \ud50c\ub7ec\uadf8\uc778 \uc124\uce58\\n\\n```\\n# Docker\\nsudo yum install -y docker\\nsudo usermod -aG docker ec2-user\\nsudo systemctl enable --now docker\\nexec bash\\n\\ndocker ps\\n\\n# Compose Plugin\\nsudo mkdir -p /usr/local/lib/docker/cli-plugins/\\nsudo curl -SL \\"https://github.com/docker/compose/releases/latest/download/docker-compose-linux-$(uname -m)\\" -o /usr/local/lib/docker/cli-plugins/docker-compose\\nsudo chmod +x /usr/local/lib/docker/cli-plugins/docker-compose\\n\\ndocker compose version\\n```\\n\\n## Docker Compose \ud50c\ub7ec\uadf8\uc778\uc744 docker-compose \uba85\ub839\uc5b4\ub85c \uc0ac\uc6a9\\n\\n```\\nalias docker-compose=\'docker compose --compatibility \\"$@\\"\'\\n```"},{"id":"docker-commands","metadata":{"permalink":"/blog/docker-commands","source":"@site/blog/2024-03-20-docker-commands/index.md","title":"Docker \uba85\ub839\uc5b4 \uc815\ub9ac (\uc774\ubbf8\uc9c0, \ucee8\ud14c\uc774\ub108)","description":"Docker\uc640 \uad00\ub828\ub41c \uae30\ubcf8 \uba85\ub839\uc5b4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.","date":"2024-03-20T00:00:00.000Z","tags":[{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"},{"inline":true,"label":"Virtualization","permalink":"/blog/tags/virtualization"}],"readingTime":0.86,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Docker \uba85\ub839\uc5b4 \uc815\ub9ac (\uc774\ubbf8\uc9c0, \ucee8\ud14c\uc774\ub108)","slug":"docker-commands","authors":["kgenots"],"tags":["Ops","Virtualization"],"image":"/assets/blog/unnamed-docker.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Amazon Linux 2023 Docker Compose \uc124\uce58","permalink":"/blog/aws-linux-2023-docker"},"nextItem":{"title":"PostgreSQL \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5 (ft. SaaS \uad6c\uc131)","permalink":"/blog/postgresql-saas-multitenancy"}},"content":"Docker\uc640 \uad00\ub828\ub41c \uae30\ubcf8 \uba85\ub839\uc5b4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<b>PC\ub85c \uc811\uc18d\ud558\uc2e0 \ud6c4 \ud398\uc774\uc9c0 \uc6b0\uce21 \uc0c1\ub2e8\uc758 <span style={{ backgroundColor: \'#fff5b1\'}}>\ubaa9\ucc28</span>\ub97c \uc774\uc6a9\ud558\uc2dc\uba74 \ud3b8\ub9ac\ud569\ub2c8\ub2e4.</b> (\uadf8\ub9ac\uace0 \ub4dc\ub798\uadf8 \uc548 \ub3fc\uc694...)\\n\\n## Docker Image \uad00\ub828\\n\\n### \uc774\ubbf8\uc9c0 \ubaa9\ub85d\\n\\n1. \uc804\uccb4 \uc774\ubbf8\uc9c0 \ubaa9\ub85d\\n\\n```\\ndocker images -a\\n```\\n\\n### \uc774\ubbf8\uc9c0 \uc0ad\uc81c\\n\\n1. <span style={{ backgroundColor: \'#fff5b1\'}}><b>\ud2b9\uc815 \uc774\ubbf8\uc9c0</b></span> \uc0ad\uc81c\\n\\n```\\ndocker rmi <image_id|name>\\n```\\n\\n2. <span style={{ backgroundColor: \'#ffdce0\'}}><b>\ubaa8\ub4e0 \uc774\ubbf8\uc9c0</b></span> \uc0ad\uc81c\\n\\n```\\ndocker rmi `docker images -q` -f\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc2e4\ud589\\n\\n```\\ndocker start <image_name:tag>\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc885\ub8cc\\n\\n```\\ndocker stop <container_id|name>\\n```\\n\\n---\\n\\n## Docker Container \uad00\ub828\\n\\n### \ucee8\ud14c\uc774\ub108 \ubaa9\ub85d\\n\\n1. \uc2e4\ud589\uc911\uc778 \ucee8\ud14c\uc774\ub108 \ubaa9\ub85d\\n\\n```\\ndocker ps\\n```\\n\\n2. \uc804\uccb4 \ucee8\ud14c\uc774\ub108 \ubaa9\ub85d\\n\\n```\\ndocker ps -a\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc811\uc18d\\n\\n```\\ndocker exec -it <container_id|name> /bin/bash\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc811\uc18d \uc885\ub8cc\\n\\n```\\nexit\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc0ad\uc81c\\n\\n1. <span style={{ backgroundColor: \'#fff5b1\'}}><b>\ud2b9\uc815 \ucee8\ud14c\uc774\ub108</b></span> \uc0ad\uc81c\\n\\n```\\ndocker rm <container_id|name>\\n```\\n\\n2. <span style={{ backgroundColor: \'#ffdce0\'}}><b>\ubaa8\ub4e0 \ucee8\ud14c\uc774\ub108</b></span> \uc0ad\uc81c (\ubcf5\uad6c\uac00 \ubd88\uac00\ub2a5\ud558\ub2c8 \uc8fc\uc758)\\n\\n```\\ndocker rm `docker ps -aq` -f\\n```\\n\\n3. <span style={{ backgroundColor: \'#f1f8ff\'}}><b>\uc911\uc9c0\ub41c \ubaa8\ub4e0 \ucee8\ud14c\uc774\ub108</b></span> \uc0ad\uc81c\\n\\n```\\ndocker container prune\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \ub85c\uadf8 \ud655\uc778\\n\\n1. <span style={{ backgroundColor: \'#fff5b1\'}}><b>\ud2b9\uc815 \ucee8\ud14c\uc774\ub108</b></span> \ub85c\uadf8\\n\\n```\\ndocker logs -t -f <container_id|name>\\n```\\n\\n2. <span style={{ backgroundColor: \'#ffdce0\'}}><b>\ubaa8\ub4e0 \ucee8\ud14c\uc774\ub108</b></span> \ub85c\uadf8\\n\\n```\\ndocker logs -t -f\\n```\\n\\n---\\n\\n## Docker Compose \uad00\ub828\\n\\n### \ucef4\ud3ec\uc988 \uba85\ub839\uc5b4 \ubb38\uc81c\\n\\n\uba85\ub839\uc5b4 \ud638\ud658\uc131 \uc774\uc288 \uc788\uc744 \ub54c \uc0ac\uc6a9\\n\\n```\\nalias docker-compose=\'docker compose --compatibility \\"$@\\"\'\\n```\\n\\n### \ucef4\ud3ec\uc988 \uc2e4\ud589\\n\\n1. \ud3ec\uadf8\ub77c\uc6b4\ub4dc \uc2e4\ud589\\n\\n```\\ndocker compose up\\n```\\n\\n2. \ubc31\uadf8\ub77c\uc6b4\ub4dc \uc2e4\ud589\\n\\n```\\ndocker compose up -d\\n```\\n\\n### \ucef4\ud3ec\uc988 \uc885\ub8cc\\n\\n1. \uae30\ubcf8\\n\\n```\\ndocker compose down\\n```\\n\\n2. \ubcfc\ub968 \uc81c\uac70 \ud544\uc694\uc2dc\\n\\n```\\ndocker compose down -v\\n```\\n\\n### \uc0dd\uc131\ub41c \ucee8\ud14c\uc774\ub108 \ubaa9\ub85d\\n\\n```\\ndocker compose ps\\n```\\n\\n---"},{"id":"postgresql-saas-multitenancy","metadata":{"permalink":"/blog/postgresql-saas-multitenancy","source":"@site/blog/2023-11-13-posgresql-saas-multitenancy/index.md","title":"PostgreSQL \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5 (ft. SaaS \uad6c\uc131)","description":"\uba40\ud2f0\ud14c\ub10c\uc2dc\uc758 \uc758\ubbf8\ub97c \uc54c\uc544\ubcf4\uace0 PostgreSQL \uc5d0\uc11c \uba40\ud2f0\ud14c\ub10c\uc2dc\ub97c \uad6c\uc131\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c \uc54c\uc544\ubd05\ub2c8\ub2e4.","date":"2023-11-13T00:00:00.000Z","tags":[{"inline":true,"label":"DB","permalink":"/blog/tags/db"},{"inline":true,"label":"PostgreSQL","permalink":"/blog/tags/postgre-sql"}],"readingTime":1.91,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"PostgreSQL \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5 (ft. SaaS \uad6c\uc131)","slug":"postgresql-saas-multitenancy","authors":["kgenots"],"tags":["DB","PostgreSQL"],"image":"/assets/blog/unnamed-postgresql.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Docker \uba85\ub839\uc5b4 \uc815\ub9ac (\uc774\ubbf8\uc9c0, \ucee8\ud14c\uc774\ub108)","permalink":"/blog/docker-commands"},"nextItem":{"title":"ERD \uc790\ub3d9 \uc0dd\uc131\ud558\ub294 \ubc29\ubc95 (ft. DB, SQLite)","permalink":"/blog/database-generate-erd"}},"content":"\uba40\ud2f0\ud14c\ub10c\uc2dc\uc758 \uc758\ubbf8\ub97c \uc54c\uc544\ubcf4\uace0 PostgreSQL \uc5d0\uc11c \uba40\ud2f0\ud14c\ub10c\uc2dc\ub97c \uad6c\uc131\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c \uc54c\uc544\ubd05\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \uba40\ud2f0\ud14c\ub10c\uc2dc(Multi-Tenancy) \ub780?\\n\\n\uba3c\uc800, \ud14c\ub10c\uc2dc(Tenancy)\ub780 \'\ucc28\uc6a9, \uc18c\uc791\'\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \ud558\ub098\uc758 \uc778\uc2a4\ud134\uc2a4\ub85c \uc5ec\ub7ec \uace0\uac1d\uc5d0\uac8c \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud560 \uc218 \uc788\ub294 \uc18c\ud504\ud2b8\uc6e8\uc5b4 \uc544\ud0a4\ud14d\ucc98\ub97c \'\uba40\ud2f0\ud14c\ub10c\uc2dc(Multi-Tenancy)\'\ub77c\uace0 \ud569\ub2c8\ub2e4. \ubc18\ub300\ub418\ub294 \uac1c\ub150\uc73c\ub85c \ub2e8\uc77c \uc778\uc2a4\ud134\uc2a4 - \ub2e8\uc77c \uace0\uac1d\uc778 \uacbd\uc6b0 \ub2e8\uc77c \ud14c\ub10c\uc2dc\ub77c\uace0 \ud569\ub2c8\ub2e4.\\n\\n\ub2e4\uc2dc \ub9d0\ud574, \uba40\ud2f0 \ud14c\ub10c\uc2dc\ub294 \ud558\ub098\uc758 \uc11c\ube44\uc2a4 \ub0b4\uc5d0\uc11c \'\uace0\uac1d\uc758 \uc815\ubcf4\ub97c \ubd84\ub9ac/\uad00\ub9ac\'\ud558\ub294 \uac83\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5\\n\\n\uba40\ud2f0\ud14c\ub10c\uc2dc\ub97c \uad6c\uc131\ud558\ub294 \uc804\ub7b5\uc740 \ub300\ud45c\uc801\uc73c\ub85c Silo \ubaa8\ub378, Pool \ubaa8\ub378, Bridge \ubaa8\ub378 3\uac00\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n<table style={{textAlign:\'center\'}}>\\n  <thead>\\n    <tr>\\n      <th width=\\"25%\\" rowSpan=\'2\'>Silo Model</th>\\n      <th width=\\"50%\\" colSpan=\'2\'>Bridge Model</th>\\n      <th width=\\"25%\\" rowSpan=\'2\'>Pool Model</th>\\n    </tr>\\n    <tr>\\n      <th width=\\"25%\\">Database</th>\\n      <th width=\\"25%\\">Schema</th>\\n    </tr>\\n  </thead>\\n<tbody>\\n <tr>\\n    <td>\\n      <img\\n        src=\\"/assets/blog/saas-postgresql-silo.png\\"\\n        alt=\\"saas-postgresql-silo\\"\\n      />\\n    </td>\\n    <td>\\n      <img\\n        src=\\"/assets/blog/saas-postgresql-bridge-dbs.png\\"\\n        alt=\\"saas-postgresql-bridge-dbs\\"\\n      />\\n    </td>\\n    <td>\\n      <img\\n        src=\\"/assets/blog/saas-postgresql-bridge-schemas.png\\"\\n        alt=\\"saas-postgresql-bridge-schemas\\"\\n      />\\n    </td>\\n    <td>\\n      <img\\n        src=\\"/assets/blog/saas-postgresql-pool.png\\"\\n        alt=\\"saas-postgresql-pool\\"\\n      />\\n    </td>\\n </tr>\\n </tbody>\\n</table>\\n\\n### Silo Model (\uc0ac\uc77c\ub85c \ubaa8\ub378)\\n\\n\uc0ac\uc77c\ub85c \ubaa8\ub378\uc740 \uac01 \ud14c\ub10c\ud2b8\uc5d0 \ub300\ud574\\n<span style={{ backgroundColor: \'#fff5b1\'}}><b>\ubcc4\ub3c4\uc758 DB Instance</b></span> \ub97c \ubd80\uc5ec\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n<span style={{ textDecoration: \'underline\'}}>\ubb3c\ub9ac\uc801/\ub17c\ub9ac\uc801\uc73c\ub85c \ud14c\ub10c\ud2b8 \uac04\uc758 \uc11c\ub85c \uc0c1\uad00 \uad00\uacc4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</span>\\n\ubcf4\uc548 \ubb38\uc81c\ub098 \uaddc\uc81c\ub85c \uc778\ud574 \uace0\uac1d\uc774 \ucd94\uac00 \ube44\uc6a9\uc744 \uc9c0\ubd88\ud558\uace0 \ub370\uc774\ud130\uc758 \uc644\uc804 \ubd84\ub9ac\ub97c \uc6d0\ud558\ub294 \uacbd\uc6b0 \uc81c\uacf5\ud560 \uc218 \uc788\ub294 \uc11c\ube44\uc2a4 \ud615\ud0dc\uc785\ub2c8\ub2e4.\\n\\n### Pool Model (\ud480 \ubaa8\ub378)\\n\\n\ud480 \ubaa8\ub378\uc740\\n<span style={{ backgroundColor: \'#fff5b1\'}}><b>\ub2e8\uc77c DB Instance, \ud589 \uc218\uc900 \ubcf4\uc548(RTS)</b></span>\\n\ub97c \uc0ac\uc6a9\ud558\uc5ec \uad6c\ud604\ub429\ub2c8\ub2e4. `tenant_id` \ub610\ub294 `org_id` \uc640 \uac19\uc740 Foreign Key\ub97c \ud1b5\ud574 \ud14c\ub10c\ud2b8 \ub370\uc774\ud130\uc758 \uaca9\ub9ac\ub97c \uc720\uc9c0\ud569\ub2c8\ub2e4. \uc0ac\uc77c\ub85c \ubaa8\ub378\uc5d0 \ube44\ud574 \uc6b4\uc601 \uc624\ubc84\ud5e4\ub4dc\uac00 \ub354 \uc801\uc740 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ud14c\ub10c\ud2b8\ubcc4 \ub9ac\uc18c\uc2a4 \uad00\ub9ac(\ubd84\ub9ac) \ubc0f \ubd84\uc11d\uc774 \uc5b4\ub835\ub2e4\ub294 \ub2e8\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### Bridge Model (\ube0c\ub9bf\uc9c0 \ubaa8\ub378)\\n\\n\ube0c\ub9bf\uc9c0 \ubaa8\ub378\uc740 \uc0ac\uc77c\ub85c \ubaa8\ub378\uacfc \ud480 \ubaa8\ub378\uc744 \uc870\ud569\ud55c \ubc29\uc2dd\uc785\ub2c8\ub2e4. \ub2e8\uc77c DB Instance \ub0b4\ubd80\uc5d0\uc11c\\n<span style={{ textDecoration: \'underline\'}}>\ub17c\ub9ac\uc801 Database \ubd84\ud560</span>\\n\ub610\ub294\\n<span style={{ textDecoration: \'underline\'}}>\ud14c\ub10c\ud2b8\ubcc4\ub85c Schema \uc0dd\uc131 \ubc0f \uad00\ub9ac</span>\\n\ud569\ub2c8\ub2e4. \ud480 \ubaa8\ub378\uc758 \uacb0\ud569 \uc815\ub3c4\ub97c \ub04a\uc5b4\ub0b4\uace0, \ubb3c\ub9ac\uc801\uc73c\ub85c\ub294 \ub3d9\uc77c\ud55c DB Instance\ub97c \uc0ac\uc6a9\ud558\uae30\uc5d0 \uac01\uac01\uc758 \ub2e8\uc810\uc744 \ubcf4\uc644\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n<span style={{ backgroundColor: \'#f1f8ff\'}}>PostgreSQL\uc758 \uacbd\uc6b0 Database \uc640 Table \uc0ac\uc774 Schema \ub77c\ub294 \uc77c\uc885\uc758 \ub124\uc784\uc2a4\ud398\uc774\uc2a4\ub97c \uad6c\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</span>\\n\\n## \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \ube44\uad50\\n\\n<figure style={{ display:\'flex\', justifyContent: \'center\' }}>\\n| -                                   | Silo Model        | Pool Model       | Bridge Model                      |\\n| ----------------------------------- | ----------------- | ---------------- | --------------------------------- |\\n| \ud14c\ub10c\ud2b8 \uad6c\uc131 \uc2dc\uac04                    | \ud83d\udc0c\ub9e4\uc6b0 \ub290\ub9bc       | \u26a1\ufe0f\ub9e4\uc6b0 \ube60\ub984     | \ud83d\udc22 \ub290\ub9bc(\uc2a4\ud0a4\ub9c8 \uc0dd\uc131, \ud14c\uc774\ube14 \uc0dd\uc131) |\\n| \ub370\uc774\ud130 \uc720\ucd9c \uc704\ud5d8                    | \uc548\uc804(independent) | \uc704\ud5d8(tenant_id)  | \ub35c \uc704\ud5d8(query)                    |\\n| \uacf5\uc720\ud14c\uc774\ube14 \uc0dd\uc131, <br /> \ud14c\ub10c\ud2b8 \ubcd1\ud569 | SQL\ub85c \uc218\ud589 \ubd88\uac00   | \ub9e4\uc6b0 \uc26c\uc6c0        | SQL\ub85c \uc218\ud589 \uac00\ub2a5                   |\\n| DB \ub9c8\uc774\uadf8\ub808\uc774\uc158                     | \ud83d\udc0c\ub9e4\uc6b0 \ub290\ub9bc       | \u26a1\ufe0f\ub9e4\uc6b0 \ube60\ub984     | \ud83d\udc22 \ub290\ub9bc(\uc2a4\ud0a4\ub9c8 \uc0dd\uc131, \ud14c\uc774\ube14 \uc0dd\uc131) |\\n| \uc6b4\uc601 \uc624\ubc84\ud5e4\ub4dc                       | \uc218\uc791\uc5c5            | \uac70\uc758 \uc5c6\uc74c        | \uac00\ub054 \ubc1c\uc0dd                         |\\n| \ubcf5\uc7a1\uc131                              | ...               | tenent_id\ub85c \uad00\ub9ac | search_path \ubc0f PG \uae30\ub2a5\uc73c\ub85c \ucee4\ubc84   |\\n| \ud14c\ub10c\ud2b8\ubcc4 \ub370\uc774\ud130 \ucd94\ucd9c                | \uc26c\uc6c0              | \ubc88\uac70\ub85c\uc6b4 \uc791\uc5c5    | \uc26c\uc6c0                              |\\n| \ud14c\ub10c\ud2b8\ubcc4 \uad6c\uc870 \ucee4\uc2a4\ud130\ub9c8\uc774\uc9d5          | \uac00\ub2a5              | \ubb38\uc81c             | \uac00\ub2a5                              |\\n</figure>\\n\\n## \uc120\ud638\ud558\ub294 \uc804\ub7b5\\n\\nBackEnd \ub294 \uc5ed\ud560\ubcc4\ub85c (DBA) DB + SQL / (BE) DTO + DAO + Controller / (API) API \ub85c \uad6c\ubd84\ub429\ub2c8\ub2e4.\\n\\n\uc804\ud1b5\uc801\uc778 Role \uc911\uc2ec\uc758 \uad6c\uc870\uc640\ub294 \ub2ec\ub9ac \uc11c\ube44\uc2a4\uc758 \ud655\uc7a5\uc131, \ub2e4\uc591\uc131, \ubb34\uacb0\uc131\uc744 \ud0c0\ud611\ud560 \uc218 \uc788\ub2e4\uba74,\\n<span style={{ backgroundColor: \'#fff5b1\'}}>Schema\uac00 \ubd84\ub9ac\ub41c <b>\ube0c\ub9bf\uc9c0 \ubaa8\ub378</b></span>\uc744 ORM(SQLAlchemy, Prisma, TypeORM)\uc744 \ud1b5\ud574 \uad00\ub9ac\ud558\ub294 \ubc29\uc2dd\uc744 \uc120\ud638\ud558\ub294 \ud3b8\uc785\ub2c8\ub2e4.\\n\\n\uc774 \ubc29\uc2dd\uc740 ORM\uc744 \ud1b5\ud574 \uae30\ubcf8 Schema\ub97c \uc0dd\uc131\ud558\uace0 \ud14c\ub10c\ud2b8\uac00 \uc720\uc785\ub420 \uc2dc, \ud574\ub2f9 Schema\ub97c \ubcf5\uc81c\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \ud14c\ub10c\ud2b8\ubcc4 \ub370\uc774\ud130\ub97c \uaca9\ub9ac\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \uc8fc\uc758\ud560 \uc810\uc73c\ub85c\ub294 SQL(Raw Query)\ub85c \uc9c1\uc811 Schema \ub97c \uad00\ub9ac\ud558\uac8c \ub418\uba74, Schema \ubcc4\ub85c \ub2e4\ub978 ERD \uad6c\uc131\uc774 \ub098\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub54c\ubb38\uc5d0 ORM\uc744 \ud1b5\ud574 \uae30\ubcf8 ERD \ub97c \uc218\uc815 \ubc0f \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud558\ub294 \uc804\ub7b5\uc744 \uc120\ud638\ud569\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- https://docs.aws.amazon.com/prescriptive-guidance/latest/saas-multitenant-managed-postgresql"},{"id":"database-generate-erd","metadata":{"permalink":"/blog/database-generate-erd","source":"@site/blog/2023-11-12-database-generate-erd/index.md","title":"ERD \uc790\ub3d9 \uc0dd\uc131\ud558\ub294 \ubc29\ubc95 (ft. DB, SQLite)","description":"ERD(\uc774\uc54c\ub514)\ub780 \\"Entity Relationship Diagram\\"\uc758 \uc57d\uc790\ub85c, \uac1c\uccb4-\uad00\uacc4 \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc774\ub77c\uace0\ub3c4 \ud558\uba70 \ub9d0\ub85c \ub418\uc5b4 \uc788\ub294 \uc694\uad6c\uc0ac\ud56d\uc744 \ubd84\uc11d\ud558\uc5ec \uadf8\ub9bc\uc73c\ub85c \uadf8\ub824\ub0b4\uc5b4 \uadf8 \uad00\uacc4\ub97c \ub3c4\ucd9c\ud55c \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc744 \ub9d0\ud569\ub2c8\ub2e4.","date":"2023-11-12T00:00:00.000Z","tags":[{"inline":true,"label":"DB","permalink":"/blog/tags/db"}],"readingTime":0.63,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"ERD \uc790\ub3d9 \uc0dd\uc131\ud558\ub294 \ubc29\ubc95 (ft. DB, SQLite)","slug":"database-generate-erd","authors":["kgenots"],"tags":["DB"],"image":"/assets/blog/unnamed-postgresql.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"PostgreSQL \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5 (ft. SaaS \uad6c\uc131)","permalink":"/blog/postgresql-saas-multitenancy"},"nextItem":{"title":"Database \uc124\uacc4 \ubc29\ubc95","permalink":"/blog/database-design"}},"content":"ERD(\uc774\uc54c\ub514)\ub780 \\"Entity Relationship Diagram\\"\uc758 \uc57d\uc790\ub85c, \uac1c\uccb4-\uad00\uacc4 \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc774\ub77c\uace0\ub3c4 \ud558\uba70 \ub9d0\ub85c \ub418\uc5b4 \uc788\ub294 \uc694\uad6c\uc0ac\ud56d\uc744 \ubd84\uc11d\ud558\uc5ec \uadf8\ub9bc\uc73c\ub85c \uadf8\ub824\ub0b4\uc5b4 \uadf8 \uad00\uacc4\ub97c \ub3c4\ucd9c\ud55c \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc744 \ub9d0\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n- \ucd9c\ucc98: http://wiki.hash.kr/index.php/ERD\\n\\n## ERD \uc0dd\uc131 \uc21c\uc11c\\n\\n1. DB \u2192 SQL \ud30c\uc77c \uc0dd\uc131 (\ub364\ud504)\\n2. SQL \u2192 DBML \ud30c\uc77c \uc0dd\uc131 (\ub364\ud504)\\n3. DBML \u2192 ERD \uc791\uc131\\n\\n## ERD \uc0dd\uc131 \ubc29\ubc95\\n\\n### 1. SQL \ud30c\uc77c \uc0dd\uc131 (\ub364\ud504)\\n\\nDBML\uc740 SQLite3\uc758 \ubb38\ubc95\uc744 \ucc98\ub9ac\ud558\uc9c0 \ubabb\ud569\ub2c8\ub2e4. \ub54c\ubb38\uc5d0 MySQL \ubb38\ubc95\uc5d0 \ub9de\ucdb0 SQL \ud30c\uc77c\uc744 \uc791\uc131\ud569\ub2c8\ub2e4.\\n\\n- \ud30c\uc77c\uba85: `DATABASE.sql`\\n- \uc0d8\ud50c \ud30c\uc77c: mysql_sample.sql / [\ub2e4\uc6b4\ub85c\ub4dc](/assets/blog/mysql_sample.sql)\\n\\n### 2. DBML \ud30c\uc77c \uc0dd\uc131 (\ub364\ud504)\\n\\nDBML \ud30c\uc77c \uc9c1\uc811 \uc791\uc131\ud574\ub3c4 \ub418\uc9c0\ub9cc, \uc774\ubbf8 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uc2a4\ud0a4\ub9c8\uac00 \uc788\ub294 \uacbd\uc6b0 SQL \ud30c\uc77c\ub85c\ubd80\ud130 DBML \ud30c\uc77c\uc744 \ub364\ud504\ud558\ub294 \uac83\uc774 \ub0ab\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub97c \uc704\ud574\uc11c\ub294 DBML CLI\uac00 \ud544\uc694\ud55c\ub370, \uc774\ub97c \uc2e4\ud589\ud558\ub824\uba74 Node.js\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n- Node.js \uc124\uce58 (https://nodejs.org/ko/download/)\\n\\n  - Terminal, CMD \ucc3d\uc5d0\uc11c `npm`\uc744 \uc785\ub825\ud588\uc744 \ub54c, \uc544\ub798\uc640 \uac19\uc774 \ub098\uc628\ub2e4\uba74 Node.js \uac00 \uc124\uce58\ub418\uc5b4 \uc788\ub2e4\ub294 \uc758\ubbf8\uc785\ub2c8\ub2e4.\\n\\n  ![Nodejs](/assets/blog/node-npm.webp)\\n\\n- \uba85\ub839\uc5b4 \uc21c\uc11c\\n  - DBML CLI \uc124\uce58\\n    `npm install -g @dbml/cli`\\n  - DBML \ud30c\uc77c \uc0dd\uc131\\n    `sql2dbml DATABASE.sql -o DATABASE.dbml`\\n  - \uacb0\uacfc\ubb3c: `DATABASE.dbml`\\n\\n### 3. ERD \uc0dd\uc131\\n\\n[dbdiagram.io](https://dbdiagram.io/)\uc5d0\uc11c <b>Create your diagram</b>\ub97c \ud074\ub9ad\ud569\ub2c8\ub2e4.\\n\\n\uc67c\ucabd \ud3b8\uc9d1 \uacf5\uac04\uc5d0 DATABASE.dbml\uc758 \ub0b4\uc6a9\uc744 \ubd99\uc5ec\ub123\uc73c\uba74 \uc624\ub978\ucabd\uc5d0 \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc774 \uc790\ub3d9\uc73c\ub85c \uadf8\ub824\uc9d1\ub2c8\ub2e4.\\n\\n![ERD Sample](/assets/blog/erd.webp)"},{"id":"database-design","metadata":{"permalink":"/blog/database-design","source":"@site/blog/2023-11-11-database-design/index.md","title":"Database \uc124\uacc4 \ubc29\ubc95","description":"\uc81c\uc77c \uc911\uc694\ud55c\ub370 \ub2ec\ub2ec \uc678\uc6b4 \uc774\ub860\uc740 \uc798 \uc598\uae30\ud558\uba74\uc11c \uc124\uacc4\ud560 \ub54c \ubb54\uc9c0 \ubaa8\ub974\ub294 \uc0ac\ub78c \ub108\ubb34 \ub9ce\uc544\uc11c \uae30\ub85d","date":"2023-11-11T00:00:00.000Z","tags":[{"inline":true,"label":"DB","permalink":"/blog/tags/db"}],"readingTime":0.9,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Database \uc124\uacc4 \ubc29\ubc95","slug":"database-design","authors":["kgenots"],"tags":["DB"],"image":"/assets/blog/unnamed-postgresql.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"ERD \uc790\ub3d9 \uc0dd\uc131\ud558\ub294 \ubc29\ubc95 (ft. DB, SQLite)","permalink":"/blog/database-generate-erd"},"nextItem":{"title":"Coroutine \uc54c\uc544\ubcf4\uae30","permalink":"/blog/unity-coroutine"}},"content":"\uc81c\uc77c \uc911\uc694\ud55c\ub370 \ub2ec\ub2ec \uc678\uc6b4 \uc774\ub860\uc740 \uc798 \uc598\uae30\ud558\uba74\uc11c \uc124\uacc4\ud560 \ub54c \ubb54\uc9c0 \ubaa8\ub974\ub294 \uc0ac\ub78c \ub108\ubb34 \ub9ce\uc544\uc11c \uae30\ub85d\\n\\n\x3c!--truncate--\x3e\\n\\n### Transaction (\ud2b8\ub79c\uc7ad\uc158)\\n\\n\uc5ec\ub7ec \uac1c\uc758 \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \ub3d9\uc2dc\uc5d0 \uc561\uc138\uc2a4\ud55c\uac70\ub098, \ub370\uc774\ud130 \ucc98\ub9ac\uac00 \uc911\ub2e8\ub418\ub294 \uacbd\uc6b0 <b>\ub370\uc774\ud130 \ubd80\uc815\ud569</b>\uc744 \ubc29\uc9c0\\n\\n:::info \uae08\uc735 \uac70\ub798\uc5d0 \ube44\uad50\ud558\uae30\\n\\n- \uc1a1\uae08\ud560 \ub54c,\\n  - A \uacc4\uc88c \uc794\uc561\uc744 \ubd88\ub7ec\uc628\ub2e4.\\n  - B \uacc4\uc88c \uc794\uc561\uc744 \ubd88\ub7ec\uc628\ub2e4.\\n  - A \uacc4\uc88c\uc5d0\uc11c 1\ub9cc\uc6d0 \uc778\ucd9c\ud558\ub294 \uae30\ub85d\uc744 \uc800\uc7a5\ud55c\ub2e4.\\n  - B \uacc4\uc88c\uc5d0\uc11c 1\ub9cc\uc6d0 \uc785\uae08\ud558\ub294 \uae30\ub85d\uc744 \uc800\uc7a5\ud55c\ub2e4.\\n  - A \uacc4\uc88c \uc794\uc561\uc744 \uc800\uc7a5\ud55c\ub2e4.\\n  - B \uacc4\uc88c \uc794\uc561\uc744 \uc800\uc7a5\ud55c\ub2e4.\\n\\n\uc989, 6\uac1c\uc758 \uba54\uc11c\ub4dc(\uae30\ub2a5)\ub97c \uac01\uac01 \ub9cc\ub4e4\ub354\ub77c\ub3c4, \ud2b8\ub79c\uc7ad\uc158\uc744 \uc5f4\uace0 \ub2eb\ub294 \uc0ac\uc774 6\uac1c\uc758 \uae30\ub2a5\uc774 \ubaa8\ub450 \ub3d9\uc791\ud574\uc57c\ud55c\ub2e4. <br/>\\n\ub610, C\ub77c\ub294 \ub2e4\ub978 \uace0\uac1d\uacfc B\uac00 \uac70\ub798\ub97c \ud558\ub354\ub77c\ub3c4 \uc704 A, B \uc0ac\uc774\uc758 \uac70\ub798\uc5d0\ub294 \ubb38\uc81c\uac00 \uc0dd\uae30\uc9c0 \uc54a\uc544\uc57c\ud55c\ub2e4.\\n:::\\n\\n### ACID \uc6d0\uce59\\n\\n- <b>Atomicity (\uc6d0\uc790\uc131)</b>: \uc911\uac04 \ub2e8\uacc4\uae4c\uc9c0 \uc2e4\ud589\ub418\uace0 \uc2e4\ud328\ud558\ub294 \uc77c\uc774 \uc5c6\uc5b4\uc57c \ud55c\ub2e4.\\n- <b>Consistency (\uc77c\uad00\uc131/\uc815\ud569\uc131)</b>: \ud2b8\ub79c\uc7ad\uc158 \uc804\ud6c4\uc758 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uaddc\uce59\uc740 \uac19\uc544\uc57c\\n  \ud55c\ub2e4.\\n- <b>Isolation (\ub3c5\ub9bd\uc131)</b>: \ud2b8\ub79c\uc7ad\uc158\uc740 \uc11c\ub85c \ub3c5\ub9bd\uc801\uc774\uc5b4\uc57c \ud55c\ub2e4.\\n- <b>Duration (\uc9c0\uc18d\uc131)</b>: \ud2b8\ub79c\uc7ad\uc158\uc5d0 \ub300\ud55c \ub85c\uadf8\ub294 \uc601\uad6c\uc801\uc73c\ub85c \ub0a8\uc544\uc57c \ud55c\ub2e4.\\n\\n:::info \uae08\uc735 \uac70\ub798\uc5d0 \ube44\uad50\ud558\uae30\\n\\n- Atomicity: 1\ub9cc\uc6d0 \uc1a1\uae08 \uc2dc, \uc131\uacf5\ud558\uac70\ub098 \uc2e4\ud328\ub9cc \ub0a8\uc544\uc57c\ud568. (5\ucc9c\uc6d0\uc740 \uc131\uacf5\ud558\uace0, 5\ucc9c\uc6d0 \uc2e4\ud328\ud558\uace0 \uadf8\ub7f0\uac70 \uc5c6\uc74c)\\n- Consistency: 1\ub9cc\uc6d0 \uc1a1\uae08 \uc2dc, \uc1a1\uae08 \uc804 \ud6c4 \ub0b4 \uc2e0\uc0c1\uc774 \ubc14\ub00c\uc9c0\ub294 \uc54a\uc74c. (\uc1a1\uae08 \uc804 \ub0a8\uc790\uc600\ub294\ub370, \uc1a1\uae08 \ud6c4 \uc5ec\uc790\ub77c\uac70\ub098 \uadf8\ub7f0\uac70 \uc5c6\uc74c)\\n- Isolation: A\uc5d0\uac8c 1\ub9cc\uc6d0 \uc1a1\uae08, B\uc5d0\uac8c 1\ub9cc\uc6d0 \uc1a1\uae08\ud588\ub2e4\uace0 \ub458 \uc911 \ud558\ub098\uc5d0\uac8c \ub2e4\uc9dc\uace0\uc9dc 2\ub9cc\uc6d0 \uc92c\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub294 \ub178\ub987.\\n- Durability: \uc2dc\uc2a4\ud15c \uc624\ub958\ub4e0, \uc0ac\ub78c \uc624\ub958\ub4e0 1\ub9cc\uc6d0 \uc1a1\uae08 \uc644\ub8cc \uc2dc, \uae30\ub85d\uc774 \ub0a8\uc544\uc57c \ud568. \\"\ub09c \ubcf4\ub0c8\ub294\ub370\uc694\\" \ub77c\uace0 \ub9d0\ub85c\ub9cc \ud560 \uc218\ub294 \uc5c6\ub294 \ub178\ub987.\\n\\n:::\\n\\n### \ud2b8\ub79c\uc7ad\uc158 \uace0\ub9bd\uc131 \uc218\uc900(Isolation Level)\\n\\n- TODO.\\n\\n## Q&A\\n\\n- DB\uc5d0\uc11c Table \uc774\ub984\uc744 \ubcc0\uc218(Variable)\ub85c \uc0ac\uc6a9\ud574\ub3c4 \ub418\ub098\uc694?\\n  - \uc0ac\uc6a9\ud574\ub3c4 \ub418\uc9c0\ub9cc, <b>\uad8c\uc7a5\ub418\uc9c0 \uc54a\ub294 \ubc29\ubc95</b>\uc785\ub2c8\ub2e4.\\n  - <b> \ubcf4\uc548(SQL Injection \ucde8\uc57d), \uac00\ub3c5\uc131 \ubc0f \uc720\uc9c0\ubcf4\uc218, \ucd5c\uc801\ud654 \ub610\ub294 \uc131\ub2a5 </b> \ubb38\uc81c\uc640\\n    \uad00\ub828\uc774 \uc788\uc2b5\ub2c8\ub2e4."},{"id":"unity-coroutine","metadata":{"permalink":"/blog/unity-coroutine","source":"@site/blog/2023-11-10-unity-coroutine/index.md","title":"Coroutine \uc54c\uc544\ubcf4\uae30","description":"Unity \uac8c\uc784 \uac1c\ubc1c\uc5d0\uc11c Coroutine(\ucf54\ub8e8\ud2f4)\uc740 \uc8fc\uc694\ud55c \uac1c\ub150 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \uc774 \ubb38\uc11c\uc5d0\uc11c\ub294 Unity\uc5d0\uc11c\uc758 Coroutine\uc758 \uae30\ucd08\ubd80\ud130 \uc2ec\ud654 \ub0b4\uc6a9\uae4c\uc9c0 \uc790\uc138\ud788 \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ucf54\ub8e8\ud2f4\uc740 \uac8c\uc784\uc758 \uc131\ub2a5 \ud5a5\uc0c1, \uc560\ub2c8\uba54\uc774\uc158 \uc81c\uc5b4, \uc2dc\uac04 \uae30\ubc18 \uc791\uc5c5, \ubc31\uadf8\ub77c\uc6b4\ub4dc \uc791\uc5c5 \ub4f1 \ub2e4\uc591\ud55c \uc0c1\ud669\uc5d0\uc11c \uc0ac\uc6a9\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","date":"2023-11-10T00:00:00.000Z","tags":[{"inline":true,"label":"Unity","permalink":"/blog/tags/unity"}],"readingTime":1.29,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Coroutine \uc54c\uc544\ubcf4\uae30","slug":"unity-coroutine","authors":["kgenots"],"tags":["Unity"],"image":"/assets/blog/unnamed-unity.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Database \uc124\uacc4 \ubc29\ubc95","permalink":"/blog/database-design"},"nextItem":{"title":"Markdown \uae00\uc790 \ud06c\uae30, \uc0c9\uc0c1, \ud615\uad11\ud39c \uc124\uc815 \ubc29\ubc95","permalink":"/blog/markdown-text-color"}},"content":"Unity \uac8c\uc784 \uac1c\ubc1c\uc5d0\uc11c Coroutine(\ucf54\ub8e8\ud2f4)\uc740 \uc8fc\uc694\ud55c \uac1c\ub150 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \uc774 \ubb38\uc11c\uc5d0\uc11c\ub294 Unity\uc5d0\uc11c\uc758 Coroutine\uc758 \uae30\ucd08\ubd80\ud130 \uc2ec\ud654 \ub0b4\uc6a9\uae4c\uc9c0 \uc790\uc138\ud788 \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ucf54\ub8e8\ud2f4\uc740 \uac8c\uc784\uc758 \uc131\ub2a5 \ud5a5\uc0c1, \uc560\ub2c8\uba54\uc774\uc158 \uc81c\uc5b4, \uc2dc\uac04 \uae30\ubc18 \uc791\uc5c5, \ubc31\uadf8\ub77c\uc6b4\ub4dc \uc791\uc5c5 \ub4f1 \ub2e4\uc591\ud55c \uc0c1\ud669\uc5d0\uc11c \uc0ac\uc6a9\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \uc18c\uac1c\\n\\nCoroutine\uc740 Unity\uc758 MonoBehaviour \ud074\ub798\uc2a4\uc5d0\uc11c \uc0ac\uc6a9\ub418\uba70, \uac8c\uc784 \ub85c\uc9c1\uc744 \ube44\ub3d9\uae30\uc801\uc73c\ub85c \ucc98\ub9ac\ud560 \ub54c \ud2b9\ud788 \uc720\uc6a9\ud569\ub2c8\ub2e4. Coroutine\uc740 Update() \ud568\uc218\uc640\ub294 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc2e4\ud589\ub418\uba70, \uc8fc\ub85c \uc2dc\uac04 \uae30\ubc18 \uc791\uc5c5\uc5d0 \uc801\ud569\ud569\ub2c8\ub2e4.\\n\\n![Coroutine Flow](/assets/blog/coroutine.webp)\\n\\n## Coroutine\uacfc Thread\\n\\n.NET(\ub2f7\ub137)\uc740 Multi-thread\ub97c \uc9c0\uc6d0\ud558\uc9c0\ub9cc, .NET\uc744 \uc0ac\uc6a9\ud558\ub294 \uc720\ub2c8\ud2f0\ub294 **Single-thread**\ub85c \ub3d9\uc791\ud569\ub2c8\ub2e4.\\nSingle-thread \ud658\uacbd\uc5d0\uc11c \ub3d9\uc2dc\uc5d0 \uc5ec\ub7ec \ub3d9\uc791\uc744 \ud558\uae30 \uc704\ud574(\uba40\ud2f0\uc4f0\ub808\ub4dc\ub97c \ud749\ub0b4\ub0b4\uae30 \uc704\ud574), Unity\uc5d0\uc11c\ub294 **Coroutine**\uc744 \uc0ac\uc6a9\ud574\uc57c\ud569\ub2c8\ub2e4.\\n\\n## \uae30\ubcf8\uc801\uc778 \uc0ac\uc6a9\ubc95\\n\\nCoroutine \ub0b4\uc5d0\uc11c\ub294 `yield return` \ubb38\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc591\ubcf4\ud558\uace0 \uae30\ub2e4\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uac00\uc7a5 \uc77c\ubc18\uc801\uc778 \uc0ac\uc6a9 \uc0ac\ub840 \uc911 \ud558\ub098\ub294 `yield return new WaitForSeconds(time)`\ub97c \uc0ac\uc6a9\ud558\uc5ec \ub300\uae30 \uc2dc\uac04\uc744 \uc9c0\uc815\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n```csharp\\nIEnumerator Example() {\\n    Debug.Log(\\"Start Coroutine\\");\\n    yield return new WaitForSeconds(2.0f); // 2\ucd08 \ub300\uae30\\n    Debug.Log(\\"Coroutine Resumed after 2 seconds\\");\\n}\\n```\\n\\n## Coroutine \uc2dc\uc791 (StartCoroutine)\\n\\nUnity\uc5d0\uc11c Coroutine\uc744 \uc2dc\uc791\ud558\ub294 \ubc29\ubc95\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n```csharp\\nvoid Start() {\\n    StartCoroutine(MyCoroutine());\\n}\\n\\nIEnumerator MyCoroutine() {\\n    // \ucf54\ub8e8\ud2f4 \ub0b4\uc6a9\\n    yield return null;\\n}\\n```\\n\\n## Coroutine \uc911\ub2e8 (StopCoroutine)\\n\\nCoroutine\uc744 \uc911\ub2e8\ud558\ub294 \ubc29\ubc95\uc5d0\ub294 \uc138 \uac00\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n1. `StopCoroutine(IEnumerator routine)`: \ud2b9\uc815 Coroutine\uc744 \uc911\ub2e8\ud569\ub2c8\ub2e4.\\n\\n```csharp\\nvoid StopExample() {\\n    StopCoroutine(MyCoroutine());\\n}\\n```\\n\\n2. `StopCoroutine(string methodName)`: Coroutine \ud568\uc218 \uc774\ub984\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc911\ub2e8\ud569\ub2c8\ub2e4.\\n\\n```csharp\\nvoid StopExample() {\\n    StopCoroutine(\\"MyCoroutine\\");\\n}\\n```\\n\\n3. `StopAllCoroutines()`: \ud604\uc7ac \ud074\ub798\uc2a4\uc5d0\uc11c \uc2e4\ud589 \uc911\uc778 \ubaa8\ub4e0 Coroutine\uc744 \uc911\ub2e8\ud569\ub2c8\ub2e4.\\n\\n```csharp\\nvoid StopAllExample() {\\n    StopAllCoroutines();\\n}\\n```\\n\\n## Coroutine \uc911\ucca9 (Nested Coroutine)\\n\\nCoroutine \ub0b4\uc5d0\uc11c \ub2e4\ub978 Coroutine\uc744 \uc2dc\uc791\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub807\uac8c \ud558\uba74 \uc791\uc5c5\uc744 \uc870\uc9c1\ud654\ud558\uace0 \uc758\uc874\uc131\uc744 \ucc98\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```csharp\\nIEnumerator TestRoutine() {\\n    Debug.Log(\\"Start TestRoutine\\");\\n    yield return StartCoroutine(OtherRoutine());\\n    Debug.Log(\\"Finish TestRoutine\\");\\n}\\n\\nIEnumerator OtherRoutine() {\\n    Debug.Log(\\"Start OtherRoutine #1\\");\\n    yield return new WaitForSeconds(1.0f);\\n    Debug.Log(\\"Start OtherRoutine #2\\");\\n    yield return new WaitForSeconds(1.0f);\\n    Debug.Log(\\"Start OtherRoutine #3\\");\\n    yield return new WaitForSec\'onds(1.0f);\\n    Debug.Log(\\"Finish OtherRoutine\\");\\n}\\n```\\n\\n## \uc694\uc57d \ubc0f \ud301\\n\\n1. **Coroutine**\uc740 Unity MonoBehaivour\uc758 LifeCycle\uacfc \ubcc4\uac1c\ub85c **\uba40\ud2f0\uc4f0\ub808\ub4dc\ub97c \ud749\ub0b4**\ub0b4\uae30 \uc704\ud574 \uc0ac\uc6a9\ud558\ub294 IEnumerator\ub97c \ubc18\ud658\ud558\ub294 \ud568\uc218\uc785\ub2c8\ub2e4.\\n2. **Coroutine**\uc740 StartCoroutine\uc744 \ud638\ucd9c\ud558\ub294 **MonoBehaviour\uc5d0 \uc885\uc18d**\ub418\uc5b4\uc788\uc5b4 \ud574\ub2f9 MonoBehaviour \ube44\ud65c\uc131\ud654\uc2dc \uac19\uc774 \ube44\ud65c\uc131\ud654\ub429\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\nCoroutine\uc740 \uc4f0\ub2e4 \ubcf4\uba74 \\"\uc774\uac8c \uc65c \uba48\ucdc4\uc9c0\\"\ub85c \ud55c \ubc88\uc740 \uc2dc\uac04\uc744 \uc501\ub2c8\ub2e4. \ub300\uac1c \uc6d0\uc778\uc740 \ucf54\ub8e8\ud2f4 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \uc2dc\uc791\ud55c MonoBehaviour\uac00 \uaebc\uc9c4 \ucabd\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc624\ube0c\uc81d\ud2b8 \uc218\uba85\uacfc \ud568\uaed8 \ubcf8\ub2e4\ub294 \uac83\ub9cc \uae30\uc5b5\ud574 \ub450\uba74 \ub098\uba38\uc9c0\ub294 \uc5b4\ub835\uc9c0 \uc54a\uc740 \uac83 \uac19\uc2b5\ub2c8\ub2e4.\\n\\n## \ucc38\uace0 \uc790\ub8cc\\n\\n- [Unity \uacf5\uc2dd \ubb38\uc11c - Coroutine](http://docs.unity3d.com/kr/current/Manual/Coroutines.html)\\n  - [MonoBehaviour.StartCoroutine](http://docs.unity3d.com/ScriptReference/MonoBehaviour.StartCoroutine.html)\\n  - [MonoBehaviour.StopCoroutine](http://docs.unity3d.com/ScriptReference/MonoBehaviour.StopCoroutine.html)"},{"id":"markdown-text-color","metadata":{"permalink":"/blog/markdown-text-color","source":"@site/blog/2023-11-09-markdown-text/index.md","title":"Markdown \uae00\uc790 \ud06c\uae30, \uc0c9\uc0c1, \ud615\uad11\ud39c \uc124\uc815 \ubc29\ubc95","description":"\ub9c8\ud06c\ub2e4\uc6b4 \ubb38\uc11c\uc5d0\uc11c \uae00\uc790 \ud06c\uae30 \ubc0f \uc0c9\uc0c1\uc744 \uc870\uc808\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c \uc54c\uc544\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.","date":"2023-11-09T00:00:00.000Z","tags":[{"inline":true,"label":"Markdown","permalink":"/blog/tags/markdown"}],"readingTime":0.82,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Markdown \uae00\uc790 \ud06c\uae30, \uc0c9\uc0c1, \ud615\uad11\ud39c \uc124\uc815 \ubc29\ubc95","slug":"markdown-text-color","authors":["kgenots"],"tags":["Markdown"],"image":"/assets/blog/unnamed-markdown.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Coroutine \uc54c\uc544\ubcf4\uae30","permalink":"/blog/unity-coroutine"},"nextItem":{"title":"\ube14\ub85c\uadf8 \uc0c8\ub85c \uc2dc\uc791\ud558\uae30","permalink":"/blog/blog-renewal"}},"content":"\ub9c8\ud06c\ub2e4\uc6b4 \ubb38\uc11c\uc5d0\uc11c \uae00\uc790 \ud06c\uae30 \ubc0f \uc0c9\uc0c1\uc744 \uc870\uc808\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c \uc54c\uc544\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \uae00\uc790 \ud06c\uae30 \ubc0f \uc18d\uc131\\n\\n### \uc81c\ubaa9\\n\\n| **\uc608\uc2dc**      | **\ucf54\ub4dc**    |\\n| ------------- | ----------- |\\n| <h1> H1 </h1> | `# H1`      |\\n| <h2> H2 </h2> | `## H2`     |\\n| <h3> H3 </h3> | `### H3`    |\\n| <h4> H4 </h4> | `#### H4`   |\\n| <h5> H5 </h5> | `##### H5`  |\\n| <h6> H6 </h6> | `###### H6` |\\n\\n### \uac15\uc870\\n\\n\uc774\ud0e4\ub9ad\uccb4 (\uae30\uc6b8\uc5ec\uc4f0\uae30) : _Italic_ <br />\\n\ubcfc\ub4dc\uccb4 (\uad75\uac8c\uc4f0\uae30) : **Bold**\\n\\n```\\n*Italic*\\n**Bold**\\n```\\n\\n### \uc778\uc6a9\ubb38\\n\\n> \uc778\uc6a9\ubb38\\n\\n```\\n>\uc778\uc6a9\ubb38\\n```\\n\\n### \ucf54\ub4dc\\n\\n#### \ucf54\ub4dc (\uc778\ub77c\uc778)\\n\\n`Inline Code Block`\\n\\n```\\n`Inline Code Block`\\n```\\n\\n#### \ucf54\ub4dc (\ube14\ub7ed / \uba40\ud2f0\ub77c\uc778)\\n\\n```\\nCode\\nBlock\\n```\\n\\n````\\n```\\nCode\\nBlock\\n```\\n````\\n\\n### \uac01\uc8fc\\n\\n\uac01\uc8fc[^1]\\n[^1]: \uac01\uc8fc\uc5d0 \ub300\ud55c \uc124\uba85\\n\\n```\\n\uac01\uc8fc[^1]\\n[^1]: \uac01\uc8fc\uc5d0 \ub300\ud55c \uc124\uba85\\n```\\n\\n## \uae00\uc790 \uc0c9\uc0c1\\n\\n- <span style={{ color: \'#FF0000\' }}>\\n  \ube68\uac15\\n  </span>\\n\\n- <span style={{ color: \'#0000FF\' }}>\\n  \ud30c\ub791\\n  </span>\\n\\n- <span style={{ color: \'#008000\' }}>\\n  \ucd08\ub85d\\n  </span>\\n\\n- <span style={{ color: \'#808080\' }}>\\n  \uadf8\ub808\uc774\\n  </span>\\n\\n- <span style={{ color: \'#ffd33d\' }}>\\n  \ub178\ub791\\n  </span>\\n\\n```html\\n<span style=\\"color: #FF0000\\">\ube68\uac15</span>\\n<span style=\\"color: #0000FF\\">\ud30c\ub791</span>\\n<span style=\\"color: #008000\\">\ucd08\ub85d</span>\\n<span style=\\"color: #808080\\">\ud68c\uc0c9</span>\\n<span style=\\"color: #ffd33d\\">\ub178\ub791</span>\\n```\\n\\n## \uae00\uc790 \ud615\uad11\ud39c(\ubc30\uacbd\uc0c9)\\n\\n- <span style={{ backgroundColor: \'#fff5b1\'}}>\\n  \ub178\ub780\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#f6f8fa\'}}>\\n  \ud68c\uc0c9\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#f1f8ff\'}}>\\n  \ud30c\ub791\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#ffdce0\'}}>\\n  \ube68\uac15\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#dcffe4\'}}>\\n  \ucd08\ub85d\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#f5f0ff\'}}>\\n  \ubcf4\ub77c\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#F7DDBE\'}}>\\n  \uc8fc\ud669\ud615\uad11\ud39c\\n  </span>\\n\\n```html\\n<span style=\\"background-color: #fff5b1\\">\ub178\ub780\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #f6f8fa\\">\ud68c\uc0c9\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #f1f8ff\\">\ud30c\ub791\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #ffdce0\\">\ube68\uac15\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #dcffe4\\">\ucd08\ub85d\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #f5f0ff\\">\ubcf4\ub77c\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #F7DDBE\\">\uc8fc\ud669\ud615\uad11\ud39c</span>\\n```\\n\\n[^1]: \uac01\uc8fc\uc5d0 \ub300\ud55c \uc124\uba85."},{"id":"blog-renewal","metadata":{"permalink":"/blog/blog-renewal","source":"@site/blog/2023-08-29-blog-renewal/index.md","title":"\ube14\ub85c\uadf8 \uc0c8\ub85c \uc2dc\uc791\ud558\uae30","description":"\uc7ac\ud14c\ud06c, \ubd80\ub3d9\uc0b0, \uac74\uac15 \ub4f1 \uc5ec\ub7ec \ube14\ub85c\uadf8\ub97c \uc6b4\uc601\ud558\uace0 \uc788\uc9c0\ub9cc, \uac00\uc7a5 \uc6b4\uc601\uc5d0 \uace0\ubbfc\uc774 \ub418\ub294 \ube14\ub85c\uadf8\ub294 \ud56d\uc0c1 \uac1c\ubc1c \ube14\ub85c\uadf8\uc778\uac83 \uac19\uc2b5\ub2c8\ub2e4.","date":"2023-08-29T00:00:00.000Z","tags":[{"inline":true,"label":"Essay","permalink":"/blog/tags/essay"}],"readingTime":0.76,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ube14\ub85c\uadf8 \uc0c8\ub85c \uc2dc\uc791\ud558\uae30","slug":"blog-renewal","authors":["kgenots"],"tags":["Essay"],"image":"/assets/blog/2023-08-29-blog-history1.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Markdown \uae00\uc790 \ud06c\uae30, \uc0c9\uc0c1, \ud615\uad11\ud39c \uc124\uc815 \ubc29\ubc95","permalink":"/blog/markdown-text-color"},"nextItem":{"title":"\ud611\uc5c5\uc744 \uc704\ud55c VSCode \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c","permalink":"/blog/vscode-extensions"}},"content":"\uc7ac\ud14c\ud06c, \ubd80\ub3d9\uc0b0, \uac74\uac15 \ub4f1 \uc5ec\ub7ec \ube14\ub85c\uadf8\ub97c \uc6b4\uc601\ud558\uace0 \uc788\uc9c0\ub9cc, \uac00\uc7a5 \uc6b4\uc601\uc5d0 \uace0\ubbfc\uc774 \ub418\ub294 \ube14\ub85c\uadf8\ub294 \ud56d\uc0c1 \uac1c\ubc1c \ube14\ub85c\uadf8\uc778\uac83 \uac19\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \ube14\ub85c\uadf8 \ub9ac\ub274\uc5bc\\n\\n\ub2e4\ub978 \uc8fc\uc81c\uc758 \ube14\ub85c\uadf8\uc758 \uacbd\uc6b0, \uc815\ubcf4\uc131 \uae00\ub9cc \uc62c\ub9ac\ub2e4\ubcf4\ub2c8 \uc815\ud655\ub3c4\ub9cc \uc2e0\uacbd \uc4f0\uba74 \ub418\ub294 \ud3b8\uc785\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uac1c\ubc1c \ube14\ub85c\uadf8\ub294 \ud56d\uc0c1 \uafb8\uc900\ud788 \ub0b4\uac00 \ud559\uc2b5\ud558\uace0 \uacbd\ud5d8\ud574 \ubcf8 \uc9c0\uc2dd\ub4e4\uc744 \uc801\uc5b4\uc57c\ud558\ub294 \ubd80\ub2f4\uac10\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc815\ud655\ub3c4\ub97c \uc2e0\uacbd \uc4f0\ub294\ub9cc\ud07c \uafb8\uc900\ud788 \uac1c\ubc1c\ud558\uace0 \uadf8 \uc77c\ub4e4\uc744 \uae30\ub85d\ud558\ub294 \uc77c\ub4e4\uc774 \uadf8\ub9cc\ud07c \uc27d\uc9c0 \uc54a\ub2e4\ub294 \uac83\uc774\uc9c0\uc694.\\n\\n### \ube14\ub85c\uadf8... \uc600\ub358 \uac83\\n\\nGithub Blog, Tistory, Velog \uc774\uacf3\uc800\uacf3 \ub5a0\ub3cc\uc544\ub2e4\ub2c8\uba74\uc11c \ud3ec\uc2a4\ud305\uc744 \ud588\uc73c\ub098, \uc5b4\ub514 \ud558\ub098 \uc790\ub9ac\uc7a1\uace0 \uafb8\uc900\ud788 \uc801\uc9c0 \ubabb\ud558\uace0 \ub9cc\ub4e4\uace0 \uc9c0\uc6b0\uace0\ub97c \ubc18\ubcf5\ud588\ub358 \ud754\uc801\uc774 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/2023-08-29-blog-history1.webp\\"\\n    alt=\\"tistory-blog\\"\\n  />\\n  <figcaption>Tistory \ube14\ub85c\uadf8</figcaption>\\n</figure>\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/2023-08-29-blog-history2.webp\\"\\n    alt=\\"github-blog\\"\\n  />\\n  <figcaption>Github \ube14\ub85c\uadf8...\uc600\ub358 \uac83</figcaption>\\n</figure>\\n\\n## Github Pages \uc7ac\uac1c\ubc1c\\n\\n\uc77c\uc804\uc5d0 [Jekyll](https://jekyllrb-ko.github.io/), [Gatsby](https://www.gatsbyjs.com/) \ub4f1\ub4f1 \uc5ec\ub7ec \uc2dc\ub3c4\ub97c \ud574\ubcf4\uc558\uc73c\ub098, \ub514\uc790\uc778\ub9cc \uace0\ub974\ub2e4\uac00 \uacb0\uad6d \ud3ec\uae30\ud558\uae30\ub97c \uc218\ub3c4 \uc5c6\uc774 \ubc18\ubcf5\ud588\ub358 \uac83 \uac19\uc2b5\ub2c8\ub2e4 .\\n\\n[Docusaurus](https://docusaurus.io/) \ub77c\ub294 **Meta**\uc758 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc0dd\uae34 \uac83\uc744 \ud655\uc778\ud558\uace0 [Dyte Docs](https://docs.dyte.io/)\uc758 \ud15c\ud50c\ub9bf\uc744 \uc0ac\uc6a9\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.\\n\\nDocusaurus\ub294 \uac1c\ubc1c \ubb38\uc11c\uc640 \ube14\ub85c\uadf8\ub97c \uac19\uc774 \uc798 \uad00\ub9ac\ud560 \uc218 \uc788\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc774\uc655 \ub9c8\uc74c\uba39\uace0 \ub2e4\uc2dc \uc2dc\uc791\ud55c \uae40\uc5d0 **\ud504\ub85c\ud544, \ud3ec\ud2b8\ud3f4\ub9ac\uc624, \uc774\ub825\uc11c, \ube14\ub85c\uadf8**\ub97c \ud55c\uaebc\ubc88\uc5d0 \ud1b5\ud569\ud574\uc57c\uaca0\ub2e4\ub294 \uc0dd\uac01\uc73c\ub85c \ub2e4\uc2dc \ub9cc\ub4e4\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ube14\ub85c\uadf8\uc758 \ud575\uc2ec\uc740 \uc5ed\uc2dc\ub098 \uae00\uc778\uc9c0\ub77c \uafb8\uc900\ud568\uc774 \ub610 \ud544\uc694\ud558\uaca0\uc9c0\uc694 \u3160\u3160\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n\uc544\uc9c1 \uae00 \uc19c\uc528\uac00 \uc88b\uc9c0\ub294 \ubabb\ud574\uc11c \ub9d0\ud22c\ub098 \ubb38\uc7a5\uc744 \uc801\ub294 \uc2b5\uad00\uc774 \uc88b\uc9c4 \uc54a\uc740 \uac83 \uac19\uc9c0\ub9cc, \uc774\uc655 \uac1c\uc778 \ubb38\uc11c\ub97c \ub2e4 \ubaa8\uc544 \ub193\ub294\ub2e4\uace0 \uc0dd\uac01\ud558\uace0 \uafb8\uc900\ud788 \ud574\ubd10\uc57c\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\uc0c1 ~~"},{"id":"vscode-extensions","metadata":{"permalink":"/blog/vscode-extensions","source":"@site/blog/2022-11-25-vscode-extensions/index.md","title":"\ud611\uc5c5\uc744 \uc704\ud55c VSCode \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c","description":"VSCode\uc5d0\uc11c \uc0ac\uc6a9\ub418\ub294 \uc720\uc6a9\ud55c \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c \ud3ec\uc2a4\ud2b8\uc785\ub2c8\ub2e4.","date":"2022-11-25T00:00:00.000Z","tags":[{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":2.38,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ud611\uc5c5\uc744 \uc704\ud55c VSCode \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c","slug":"vscode-extensions","authors":["kgenots"],"tags":["MacOS"],"image":"/assets/blog/vscode-extensions.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ube14\ub85c\uadf8 \uc0c8\ub85c \uc2dc\uc791\ud558\uae30","permalink":"/blog/blog-renewal"},"nextItem":{"title":"\ub9e5 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95","permalink":"/blog/mac-dock-speed-up"}},"content":"VSCode\uc5d0\uc11c \uc0ac\uc6a9\ub418\ub294 \uc720\uc6a9\ud55c \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c \ud3ec\uc2a4\ud2b8\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ub9ce\uc740 \ud68c\uc0ac\uc5d0\uc11c \uc720\ub8cc IDE\ub97c \uc4f0\uac70\ub098 \ubb34\uac70\uc6b4 Visual Studio\ub97c \uc4f0\ub294 \uac83\uacfc \ubcc4\uac1c\ub85c \ud544\uc790\ub294 \uac1c\uc778\uc801\uc73c\ub85c VSCode \uc774\uc6a9\uc744 \ucd94\ucc9c\ud569\ub2c8\ub2e4. \uae30\ubcf8 \ud504\ub85c\uadf8\ub7a8 \uc790\uccb4\uac00 \uac00\ubcbc\uc6b4 \uce21\uba74\ub3c4 \uc788\uad6c, \ud544\uc694\ud55c \ud234\uc744 \ud655\uc7a5(Extension) \ud504\ub85c\uadf8\ub7a8\ub9cc \uc124\uce58\ud574\uc8fc\uba74 \ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\uadf8 \uc911 \uc81c\uac00 \uc4f0\uba74\uc11c \ucd94\ucc9c\ud558\ub294 \ud655\uc7a5 \ud504\ub85c\uadf8\ub7a8 \uba87 \uac1c\ub97c \ub4e4\uace0\uc640 \ubd24\uc2b5\ub2c8\ub2e4.\\n\\n## 1. GitLens\\n\\n[https://marketplace.visualstudio.com/items?itemName=eamodio.gitlens](https://marketplace.visualstudio.com/items?itemName=eamodio.gitlens)\\n\\n<div class=\\"link-preview-container\\">\\n    <a \\n      href=\\"https://marketplace.visualstudio.com/items?itemName=eamodio.gitlens\\">\\n    </a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img \\n              src=\\"https://eamodio.gallerycdn.vsassets.io/extensions/eamodio/gitlens/2023.12.1104/1702285683062/Microsoft.VisualStudio.Services.Icons.Default\\"\\n              alt=\\"Article Thumbnail\\" \\n            />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">\\n              GitLens \u2014 Git supercharged - Visual Studio Marketplace\\n            </div>\\n            <div class=\\"link-preview-description\\">\\n              Extension for Visual Studio Code - Supercharge Git within VS Code \u2014 Visualize code authorship at a glance via Git blame annotations and CodeLens, seamlessly navigate and explore Git repositories, gain valuable insights via rich visualizations and powerful comparison commands, and so much more\\n            </div>\\n        </div>\\n    </div>\\n</div>\\n\\nGitLens\ub294 Git\uc774 \uc138\ud305\ub418\uc5b4 \uc788\ub294 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uc904(Line)\uc5d0 \ucee4\uc11c\ub97c \uc62c\ub9ac\uba74 \uc5b8\uc81c \ub204\uac00 \uc218\uc815\ud588\ub294\uc9c0\ub97c \uace7\ubc14\ub85c \uc54c\uac8c\ud574\uc8fc\ub294 \ud655\uc7a5 \ud504\ub85c\uadf8\ub7a8\uc785\ub2c8\ub2e4. \ud574\ub2f9 \uc791\uc5c5\uc774 \uc77c\uc5b4\ub09c \ucee4\ubc0b\uc758 \ud788\uc2a4\ud1a0\ub9ac\ub97c \ucd94\uc801\ud574\uc57c\ud558\ub294 \uacbd\uc6b0\uc5d0 \uc720\uc6a9\ud55c \ud234\uc785\ub2c8\ub2e4.\\n\\n**\uc0ac\uc6a9\uc608\uc2dc:**\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/vscode-gitlens.webp\\"\\n    alt=\\"vscode-gitlens\\"\\n  />\\n  <figcaption>GitLens \uc801\uc6a9 \uc608\uc2dc</figcaption>\\n</figure>\\n\\n## 2. indent-rainbow\\n\\n[https://marketplace.visualstudio.com/items?itemName=oderwat.indent-rainbow](https://marketplace.visualstudio.com/items?itemName=oderwat.indent-rainbow)\\n\\n<div class=\\"link-preview-container\\">\\n    <a \\n      href=\\"https://marketplace.visualstudio.com/items?itemName=oderwat.indent-rainbow\\">\\n    </a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img \\n              src=\\"https://oderwat.gallerycdn.vsassets.io/extensions/oderwat/indent-rainbow/8.3.1/1649543509070/Microsoft.VisualStudio.Services.Icons.Default\\"\\n              alt=\\"Article Thumbnail\\" \\n            />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">\\n              indent-rainbow - Visual Studio Marketplace\\n            </div>\\n            <div class=\\"link-preview-description\\">\\n              Extension for Visual Studio Code - Makes indentation easier to read\\n            </div>\\n        </div>\\n    </div>\\n</div>\\n\\nindent-rainbow\ub294 \ub4e4\uc5ec\uc4f0\uae30\uc758 \ub2e8\uacc4\ub9c8\ub2e4 \ub2e4\ub978 \uc0c9\uc0c1\uc73c\ub85c \ud45c\ud604\ud574\uc8fc\ub294 \ud655\uc7a5 \ud504\ub85c\uadf8\ub7a8 \uc785\ub2c8\ub2e4. \uae30\ubcf8 \uc0c9\uc0c1\uc740 \uc21c\uc11c\ub300\ub85c \ub178\ub791, \ucd08\ub85d, \ubcf4\ub77c, \ud30c\ub791 \uc21c\uc11c\ub300\ub85c\uc9c0\ub9cc, \ubcc4\ub3c4\ub85c \ucee4\uc2a4\ud130\ub9c8\uc774\uc9d5\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\npython \uacfc \uac19\uc774 indent(\ub4e4\uc5ec\uc4f0\uae30)\uc758 \uce78\uc218\uac00 \ub9de\uc9c0 \uc54a\uc544\uc11c \uc624\ub958\uac00 \ub098\ub294 \uacbd\uc6b0\uc5d0\ub294 \ube68\uac04\uc0c9\uc73c\ub85c \ud45c\uc2dc\uac00 \ub429\ub2c8\ub2e4. indent-rainbow\uc73c\ub85c \ub4e4\uc5ec\uc4f0\uae30 \uac04\uaca9\uc774 \ub9de\ub294\uc9c0 \uc77c\uc77c\uc774 \uccb4\ud06c\ud574\uc57c\ud558\ub294 \uc218\uace0\ub85c\uc6c0\uc744 \ub35c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n**\uc0ac\uc6a9\uc608\uc2dc:**\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/vscode-indent-rainbow.webp\\"\\n    alt=\\"vscode-indent-rainbow\\"\\n  />\\n  <figcaption>indent-rainbow \uc801\uc6a9 \uc608\uc2dc</figcaption>\\n</figure>\\n\\n## 3. Material Icon Theme\\n\\n[https://marketplace.visualstudio.com/items?itemName=PKief.material-icon-theme](https://marketplace.visualstudio.com/items?itemName=PKief.material-icon-theme)\\n\\n<div class=\\"link-preview-container\\">\\n    <a \\n      href=\\"https://marketplace.visualstudio.com/items?itemName=PKief.material-icon-theme\\">\\n    </a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img \\n              src=\\"https://pkief.gallerycdn.vsassets.io/extensions/pkief/material-icon-theme/4.32.0/1700479629849/Microsoft.VisualStudio.Services.Icons.Default\\"\\n              alt=\\"Article Thumbnail\\" \\n            />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">\\n              Material Icon Theme - Visual Studio Marketplace\\n            </div>\\n            <div class=\\"link-preview-description\\">\\n              Extension for Visual Studio Code - Material Design Icons for Visual Studio Code\\n            </div>\\n        </div>\\n    </div>\\n</div>\\n\\nMaterial Icon Theme\ub294 \ud30c\uc77c\uc758 \ud655\uc7a5\uc790 \ubc0f \uc774\ub984\uc5d0 \ub530\ub77c \ud3f4\ub354 \ubc0f \ud30c\uc77c\uc758 \uc544\uc774\ucf58\uc744 \ubcf4\uae30 \uc26c\uc6b4 \uc544\uc774\ucf58\uc73c\ub85c \ubcc0\uacbd\ud574\uc90d\ub2c8\ub2e4.\\n\\n\uc720\uc0ac \ud655\uc7a5 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c [vscode-icons](https://marketplace.visualstudio.com/items?itemName=vscode-icons-team.vscode-icons) \uac00 \uc788\uc2b5\ub2c8\ub2e4. \uae00 \uc791\uc131\uc77c \uae30\uc900\uc73c\ub85c \ub2e4\uc6b4\ub85c\ub4dc \uc218\uac00 \uac01\uac01 Material Icons Theme(15\ubc31\ub9cc), vscode-icons(12.5\ubc31\ub9cc)\uc73c\ub85c \ucde8\ud5a5 \ucc28\uc774 \uc815\ub3c4\ub85c \uc0dd\uac01\ud558\uace0 \uc88b\uc544\ud558\ub294 \uac78 \uc4f0\uba74 \ub420 \uac83 \uac19\uc2b5\ub2c8\ub2e4.\\n\\n**\uc0ac\uc6a9\uc608\uc2dc:**\\n\\n<table>\\n<thead>\\n    <tr>\\n      <th width=\\"50%\\">\uc801\uc6a9 \uc804</th>\\n      <th width=\\"50%\\">\uc801\uc6a9 \ud6c4</th>\\n    </tr>\\n  </thead>\\n<tbody>\\n <tr>\\n    <td>\\n        <img\\n          src=\\"/assets/blog/vscode-material-icon-before.webp\\"\\n          alt=\\"vscode-material-icon-before\\"\\n        />\\n    </td>\\n    <td>\\n        <img\\n          src=\\"/assets/blog/vscode-material-icon-after.webp\\"\\n          alt=\\"vscode-material-icon-after\\"\\n        />\\n    </td>\\n </tr>\\n </tbody>\\n</table>\\n\\n## 4. Color Highlight\\n\\n[https://marketplace.visualstudio.com/items?itemName=naumovs.color-highlight](https://marketplace.visualstudio.com/items?itemName=naumovs.color-highlight)\\n\\n<div class=\\"link-preview-container\\">\\n    <a \\n      href=\\"https://marketplace.visualstudio.com/items?itemName=naumovs.color-highlight\\">\\n    </a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img \\n              src=\\"https://naumovs.gallerycdn.vsassets.io/extensions/naumovs/color-highlight/2.5.0/1631530639439/Microsoft.VisualStudio.Services.Icons.Default\\"\\n              alt=\\"Article Thumbnail\\" \\n            />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">\\n              Color Highlight - Visual Studio Marketplace\\n            </div>\\n            <div class=\\"link-preview-description\\">\\n              Extension for Visual Studio Code - Highlight web colors in your editor\\n            </div>\\n        </div>\\n    </div>\\n</div>\\n\\nColor Highlight \ub294 \uc785\ub825\ub41c \uc0c9\uc0c1(rgb, hex \ub4f1)\uc744 \ubc14\ub85c \ud574\ub2f9 \ud14d\uc2a4\ud2b8\uc5d0 \uc0c9\uc0c1\uc73c\ub85c \ud45c\uc2dc\ud574\uc90d\ub2c8\ub2e4.\\n\\n**\uc0ac\uc6a9\uc608\uc2dc:**\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/vscode-color-highlight.webp\\"\\n    alt=\\"vscode-color-highlight\\"\\n  />\\n  <figcaption>indent-rainbow \uc801\uc6a9 \uc608\uc2dc</figcaption>\\n</figure>"},{"id":"mac-dock-speed-up","metadata":{"permalink":"/blog/mac-dock-speed-up","source":"@site/blog/2022-11-23-mac-dock-speed-up/index.md","title":"\ub9e5 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95","description":"MacOS \ub0b4 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ub354 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-11-23T00:00:00.000Z","tags":[{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":0.5,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ub9e5 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95","slug":"mac-dock-speed-up","authors":["kgenots"],"tags":["MacOS"],"image":"/assets/blog/mac-dock-speed-up.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ud611\uc5c5\uc744 \uc704\ud55c VSCode \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c","permalink":"/blog/vscode-extensions"},"nextItem":{"title":"Node.js, NPM \uc81c\uac70\ud558\ub294 \ubc29\ubc95 - MAC","permalink":"/blog/nodejs-uninstall"}},"content":"MacOS \ub0b4 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ub354 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\nMacOS\ub97c \uc0ac\uc6a9\ud558\ub2e4\ubcf4\uba74 \ud654\uba74 \uc544\ub798\uc5d0 \uc228\uaca8\uc9c4 \ub3c5\uc744 \ubcf4\uae30 \uc704\ud574 \ub9c8\uc6b0\uc2a4\ub97c \ud654\uba74 \uc544\ub798\ub85c \uac00\uc838\ub2e4\ub300\uba74 \uc0dd\uac01\ubcf4\ub2e4 \ud55c\ucc38 \uc788\ub2e4\uac00 \uc2a4\ub974\ub975 \ud558\uace0 \uc5f4\ub9ac\ub294 \ub3c5\uc744 \ubcfc \uc218 \uc788\uc744\uac81\ub2c8\ub2e4. \uc774\ub97c \ub2f5\ub2f5\ud574\ud558\ub294 \ubd84\ub4e4\uc774 \uc788\uae30\uc5d0 \ub3c5\uc774 \uc5f4\ub9ac\ub294 \uc18d\ub3c4\ub97c \ube60\ub974\uac8c \ud560 \uc218 \uc788\ub294 \uba87 \uac00\uc9c0 \ud574\uacb0 \ubc29\ubc95\uc744 \uac00\uc9c0\uace0 \uc640 \ubd24\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-dock-speed-up.webp\\"\\n    alt=\\"mac-dock-speed-up\\"\\n  />\\n</figure>\\n\\n## \ubc29\ubc95 1. \ub2e8\ucd95\ud0a4\ub97c \uc774\uc6a9\ud574 \uc790\ub3d9 \uc228\uae40/\ubcf4\uc774\uae30 \uc124\uc815\\n\\n\ub2e8\ucd95\ud0a4 **options + command + D** \ub97c \uc785\ub825\ud558\uba74 \ud654\uba74 \uc544\ub798 \uac00\ub824\uc838 \uc788\ub358 \ub3c5\uc774 \uc62c\ub77c\uc624\uac8c \ub429\ub2c8\ub2e4. \ub610 \ubc18\ub300\ub85c \uc228\uae30\ub294 \uac83\ub3c4 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n## \ubc29\ubc95 2. \ud130\ubbf8\ub110\uc744 \ud1b5\ud574 \ub3c5 \uc124\uc815\uac12 \ubcc0\uacbd\\n\\n1. \uc560\ub2c8\uba54\uc774\uc158 \uc5c6\uc774 \ubc14\ub85c \ub728\uac8c \ud558\ub294 \ubc29\ubc95\\n\\n```\\ndefaults write com.apple.dock autohide-time-modifier -int 0;killall Dock\\n```\\n\\n2. \uc560\ub2c8\uba54\uc774\uc158 \uc18d\ub3c4\ub97c \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95\\n\\n```\\ndefaults write com.apple.dock autohide-time-modifier -float 0.15;killall Dock\\n```\\n\\n3. \uc6d0\ub798 \uc0c1\ud0dc\ub85c \ubcf5\uad6c\ud558\ub294 \ubc29\ubc95\\n\\n```\\ndefaults delete com.apple.dock autohide-time-modifier;killall Dock\\n```"},{"id":"nodejs-uninstall","metadata":{"permalink":"/blog/nodejs-uninstall","source":"@site/blog/2022-11-21-nodejs-uninstall/index.md","title":"Node.js, NPM \uc81c\uac70\ud558\ub294 \ubc29\ubc95 - MAC","description":"Node.js \ubc84\uc804 \ubcc0\uacbd\uc774\ub098 \ucda9\ub3cc \ub4f1 \uc5ec\ub7ec \ubb38\uc81c\ub85c \uc778\ud574 Node.js\ub97c \uc9c0\uc6cc\uc57c \ud558\ub294 \uacbd\uc6b0, \uae54\ub054\ud788 \uc9c0\uc6b0\ub294 \ubc29\ubc95\uc744 \uc54c\ub824\ub4dc\ub9bd\ub2c8\ub2e4.","date":"2022-11-21T00:00:00.000Z","tags":[{"inline":true,"label":"NodeJS","permalink":"/blog/tags/node-js"},{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":0.63,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Node.js, NPM \uc81c\uac70\ud558\ub294 \ubc29\ubc95 - MAC","slug":"nodejs-uninstall","authors":["kgenots"],"tags":["NodeJS","MacOS"],"image":"/assets/blog/nodejs-uninstall.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ub9e5 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95","permalink":"/blog/mac-dock-speed-up"},"nextItem":{"title":"\ub9e5 \uc790\ub3d9\uc2e4\ud589 \ud56d\ubaa9 \uc124\uc815 \ubc29\ubc95","permalink":"/blog/mac-startup-program"}},"content":"Node.js \ubc84\uc804 \ubcc0\uacbd\uc774\ub098 \ucda9\ub3cc \ub4f1 \uc5ec\ub7ec \ubb38\uc81c\ub85c \uc778\ud574 Node.js\ub97c \uc9c0\uc6cc\uc57c \ud558\ub294 \uacbd\uc6b0, \uae54\ub054\ud788 \uc9c0\uc6b0\ub294 \ubc29\ubc95\uc744 \uc54c\ub824\ub4dc\ub9bd\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/nodejs-uninstall.webp\\"\\n    alt=\\"nodejs-uninstall\\"\\n  />\\n</figure>\\n\\n## 1. Node.js \uae54\ub054\ud558\uac8c \uc9c0\uc6b0\ub294 \ubc29\ubc95\\n\\n### [Node.js](https://nodejs.org/) \ud648\ud398\uc774\uc9c0\uc5d0\uc11c \ubc1b\uc558\uc744 \ub54c,\\n\\n```\\nsudo rm -rf /usr/local/lib/node\\nsudo rm -rf /usr/local/lib/node_modules\\nsudo rm /usr/local/lib/dtrace/node.d\\nsudo rm /usr/local/share/man/man1/node.1\\nsudo rm -rf /usr/local/share/doc/node\\nsudo rm -rf /usr/local/share/systemtap/tapset/node.stp\\nsudo rm -rf /usr/local/include/node\\nsudo rm /usr/local/bin/node\\nsudo rm /usr/local/bin/npm\\nsudo rm /usr/local/bin/npx\\n```\\n\\n### Homebrew \uc5d0\uc11c \ubc1b\uc558\uc744 \ub54c,\\n\\n```\\nbrew uninstall node\\nbrew doctor\\nbrew cleanup\\n```\\n\\n### \uc124\uce58\ub41c NPM \uce90\uc2dc, \ud658\uacbd\ud30c\uc77c\uae4c\uc9c0 \uc81c\uac70\ud558\ub824\uba74,\\n\\n```\\nsudo rm -rf /Users/$USER/.npm\\nsudo rm -rf ~/.npm\\n```\\n\\n## 2. Node.js \uc124\uce58 \ubc0f \uc81c\uac70 \uc5ec\ubd80 \ud655\uc778 \ubc29\ubc95\\n\\n```\\n// node \ubc84\uc804 \ud655\uc778\\nnode -v\\t\\t//\ubc84\uc804\ud45c\uae30(x.x.x)\uac00 \ub098\uc624\uba74 \uc124\uce58\ub41c \uc0c1\ud0dc\\n        \\t//command not found: node \uac00 \ub098\uc624\uba74 \uc81c\uac70\ub41c \uc0c1\ud0dc\\n\\n// npm \ubc84\uc804 \ud655\uc778\\nnpm -v\\t\\t//\ubc84\uc804\ud45c\uae30(x.x.x)\uac00 \ub098\uc624\uba74 \uc124\uce58\ub41c \uc0c1\ud0dc\\n        \\t//No such file or directory \uac00 \ub098\uc624\uba74 \uc81c\uac70\ub41c \uc0c1\ud0dc\\n```"},{"id":"mac-startup-program","metadata":{"permalink":"/blog/mac-startup-program","source":"@site/blog/2022-11-19-mac-startup-program/index.md","title":"\ub9e5 \uc790\ub3d9\uc2e4\ud589 \ud56d\ubaa9 \uc124\uc815 \ubc29\ubc95","description":"Mac \ubd80\ud305 \ub610\ub294 \ub85c\uadf8\uc778 \uc2dc \uc790\ub3d9\uc73c\ub85c \uc2e4\ud589\ub418\ub294 \uc2dc\uc791\ud504\ub85c\uadf8\ub7a8\uc744 \uad00\ub9ac\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-11-19T00:00:00.000Z","tags":[{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":0.67,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ub9e5 \uc790\ub3d9\uc2e4\ud589 \ud56d\ubaa9 \uc124\uc815 \ubc29\ubc95","slug":"mac-startup-program","authors":["kgenots"],"tags":["MacOS"],"image":"/assets/blog/mac-startup-program.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Node.js, NPM \uc81c\uac70\ud558\ub294 \ubc29\ubc95 - MAC","permalink":"/blog/nodejs-uninstall"},"nextItem":{"title":"\ub9e5 \ud654\uba74\ucea1\ucc98 \uc2dc, \ucc3d \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95","permalink":"/blog/mac-remove-window-shadow"}},"content":"Mac \ubd80\ud305 \ub610\ub294 \ub85c\uadf8\uc778 \uc2dc \uc790\ub3d9\uc73c\ub85c \uc2e4\ud589\ub418\ub294 \uc2dc\uc791\ud504\ub85c\uadf8\ub7a8\uc744 \uad00\ub9ac\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-startup-program.webp\\"\\n    alt=\\"mac-startup-program\\"\\n  />\\n</figure>\\n\\nMacOS \ubd80\ud305 \uc2dc, \uc0ac\uc6a9\uc790\uc758 \uae30\ud638\uc5d0 \ub530\ub77c \uc790\ub3d9 \uc2e4\ud589\uc774 \ud544\uc694\ud55c \uc571\ub4e4\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n_AlDente(\ubc30\ud130\ub9ac \uad00\ub9ac \ud504\ub85c\uadf8\ub7a8),_\\n\\n_Rectangle(\ud654\uba74 \ubd84\ud560 \ub2e8\ucd95\ud0a4 \uc124\uc815),_\\n\\n_Karabiner(\ud0a4\ubcf4\ub4dc \uc124\uc815),_\\n\\n_\uce74\uce74\uc624\ud1a1(?)_\\n\\n\uc704\uc640 \uac19\uc740 \uc798 \ub9cc\ub4e4\uc5b4\uc9c4 \uc571\ub4e4\uc740 \uc571 \ub0b4\ubd80 \uc124\uc815\uc73c\ub85c \ub300\ubd80\ubd84 \uc790\ub3d9\uc73c\ub85c \ub4f1\ub85d\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \uadf8\ub807\uc9c0 \uc54a\uc740 \uc571\ub4e4\ub3c4 \uc885\uc885 \uc788\ub294\ub370\uc694.\\n\\n\ub300\ud45c\uc801\uc73c\ub85c \uc81c\uac00 \uc0ac\uc6a9\uc911\uc778 _TermHere(\ud30c\uc778\ub354 \ud604\uc7ac \uacbd\ub85c\uc5d0\uc11c \ud130\ubbf8\ub110 \uc5f4\uae30)_ \uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub7f0 \uacbd\uc6b0, \ub85c\uadf8\uc778 \ud56d\ubaa9\uc744 \uc9c1\uc811 \uad00\ub9ac\ud574 \uc904 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ub85c\uadf8\uc778 \ud56d\ubaa9 \uc124\uc815\ud558\ub294 \ubc29\ubc95\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-spotlight.webp\\"\\n    alt=\\"mac-spotlight\\"\\n  />\\n</figure>\\n\\n**Command + Space bar** \ub610\ub294 **\uc6b0\uc0c1\ub2e8 \uac80\uc0c9 \uc544\uc774\ucf58**\uc744 \ub20c\ub974\uace0,\\n\\nSpotlight \uac80\uc0c9\uc744 \uc5f4\uc5b4 \'**\uc2dc\uc2a4\ud15c \uc124\uc815**\'\uc744 \uc785\ub825\ud558\uace0 \ub4e4\uc5b4\uac00\uc90d\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-system-config.webp\\"\\n    alt=\\"mac-system-config\\"\\n  />\\n</figure>\\n\\n\uc704\uc640 \uac19\uc774 \uc2dc\uc2a4\ud15c \uc124\uc815 \ucc3d\uc774 \ub72c \ud6c4,\\n\\n\uc67c\ucabd \uc0c1\ub2e8 \uac80\uc0c9\uc5d0\uc11c \'**\ub85c\uadf8\uc778 \ud56d\ubaa9**\' \uc744 \uc785\ub825\ud574\uc90d\ub2c8\ub2e4.\\n\\n_\\\\- Spotlight \uac80\uc0c9\uc5d0\uc11c \'\ub85c\uadf8\uc778 \ud56d\ubaa9\' \uac80\uc0c9\ud574\ub3c4 \ubc14\ub85c \ub4e4\uc5b4\uac00\uc9c0\ub124\uc694._\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-login-program.webp\\"\\n    alt=\\"mac-login-program\\"\\n  />\\n</figure>\\n\\n\ub85c\uadf8\uc778 \uc2dc \uc5f4\uae30 \ud56d\ubaa9\uc5d0\uc11c + \ub610\ub294 - \ubc84\ud2bc\uc744 \ud1b5\ud574 \uc751\uc6a9 \ud504\ub85c\uadf8\ub7a8\uc744 \ucd94\uac00 \ub610\ub294 \uc81c\uac70\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n_\uc774 \ud3ec\uc2a4\ud2b8\ub294 MacOS Ventura(\ubca4\ud22c\ub77c) 13.0.1 \ubc84\uc804\uc5d0\uc11c \uc791\uc131\ub418\uc5c8\uc2b5\ub2c8\ub2e4._"},{"id":"mac-remove-window-shadow","metadata":{"permalink":"/blog/mac-remove-window-shadow","source":"@site/blog/2022-11-19-mac-remove-window-shadow/index.md","title":"\ub9e5 \ud654\uba74\ucea1\ucc98 \uc2dc, \ucc3d \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95","description":"\ub9e5\uc5d0\uc11c \ucc3d \uc601\uc5ed\uc744 \ucea1\uccd0\ud560 \ub54c, \ucc3d \ud06c\uae30\ubcf4\ub2e4 \ub113\uc740 \uc601\uc5ed(\uadf8\ub9bc\uc790 \ud3ec\ud568)\uc758 \uacb0\uacfc\ubb3c\uc774 \ub098\uc624\ub294 \uacbd\uc6b0\uc758 \ub300\ucc98 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-11-19T00:00:00.000Z","tags":[{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":0.91,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ub9e5 \ud654\uba74\ucea1\ucc98 \uc2dc, \ucc3d \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95","slug":"mac-remove-window-shadow","authors":["kgenots"],"tags":["MacOS"],"image":"/assets/blog/mac-remove-window-shadow.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ub9e5 \uc790\ub3d9\uc2e4\ud589 \ud56d\ubaa9 \uc124\uc815 \ubc29\ubc95","permalink":"/blog/mac-startup-program"},"nextItem":{"title":"npm \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubaa8\ub4c8 \uc81c\uac70\ud558\ub294 \ubc29\ubc95 (depcheck)","permalink":"/blog/npm-remove-unused-packages"}},"content":"\ub9e5\uc5d0\uc11c \ucc3d \uc601\uc5ed\uc744 \ucea1\uccd0\ud560 \ub54c, \ucc3d \ud06c\uae30\ubcf4\ub2e4 \ub113\uc740 \uc601\uc5ed(\uadf8\ub9bc\uc790 \ud3ec\ud568)\uc758 \uacb0\uacfc\ubb3c\uc774 \ub098\uc624\ub294 \uacbd\uc6b0\uc758 \ub300\ucc98 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-remove-window-shadow.webp\\"\\n    alt=\\"mac-remove-window-shadow\\"\\n  />\\n</figure>\\n\\nMacOS \ub0b4\uc5d0\uc11c \ucc3d \ucea1\uccd0\ub97c \ud558\uba74\uc11c \uc0dd\uacbc\ub358 \uadf8\ub9bc\uc790\uac00 \ud3ec\ud568\ub418\uc5b4 \ucc0d\ud788\ub294 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubcf4\ub3c4\ub85d \ud558\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9e5\uc5d0\uc11c \ucc3d \ucea1\ucc98 \ubc29\ubc95\\n\\n\uc6b0\uc120, \ub9e5\uc5d0\uc11c \ucc3d \ucea1\ucc98(\uc2a4\ud06c\ub9b0\uc0f7)\ub97c \ud558\ub294 \ubc29\ubc95\uc740,\\n\\n**Shift + Command + 4** \ud0a4\ub97c \ub204\ub985\ub2c8\ub2e4. \uc774 \uc0c1\ud0dc\uc5d0\uc11c **Space bar** \ub97c \ub204\ub974\uba74 \ub9c8\uc6b0\uc2a4\uac00 \uce74\uba54\ub77c \ubaa8\uc591\uc73c\ub85c \ubc14\ub01d\ub2c8\ub2e4.\\n\\n\uc774 \uc0c1\ud0dc\uc5d0\uc11c \uc6d0\ud558\ub294 \ucc3d\uc5d0 \uc62c\ub824\ub450\uace0 **Enter**\xa0\ub97c \ub204\ub974\uba74 \ucc3d\uc774 \ucea1\ucc98\uac00 \ub429\ub2c8\ub2e4.\\n\\n## \uadf8\ub9bc\uc790 \uc720\ubb34 \ucc28\uc774 \ube44\uad50\\n\\n<table>\\n<thead>\\n    <tr>\\n      <th width=\\"50%\\">with shadow</th>\\n      <th width=\\"50%\\">without shadow</th>\\n    </tr>\\n  </thead>\\n<tbody>\\n <tr>\\n    <td>\\n        <img\\n          src=\\"/assets/blog/mac-capture-with-shadow.webp\\"\\n          alt=\\"mac-capture-with-shadow\\"\\n          style={{border: \\"1px solid red\\"}}\\n        />\\n    </td>\\n    <td>\\n        <img\\n          src=\\"/assets/blog/mac-capture-without-shadow.webp\\"\\n          alt=\\"mac-capture-without-shadow\\"\\n          style={{border: \\"1px solid red\\"}}\\n        />\\n    </td>\\n </tr>\\n </tbody>\\n</table>\\n\\n\uc67c\ucabd \ucea1\ucc98\ubcf8\uc740 \ubcc4\ub3c4\uc758 \uc124\uc815\uc5c6\uc774 \ucc3d \ucea1\ucc98\ub97c \ud588\uc744 \ub54c\uc758 \uacb0\uacfc\ubb3c\uc785\ub2c8\ub2e4. \uc774 \uacbd\uc6b0, \ucc3d \ubc16\uc758 \uadf8\ub9bc\uc790 \ubd80\ubd84\uae4c\uc9c0 \ud3ec\ud568\ud558\uc5ec \ucea1\ucc98\uac00 \ub429\ub2c8\ub2e4. \ubc18\ub300\ub85c \uc624\ub978\ucabd \ucea1\ucc98\ubcf8\uc740 \uadf8\ub9bc\uc790 \uc81c\uac70 \uc124\uc815\uc744 \ud558\uc600\uae30\uc5d0, \ucc3d \ubc16\uc758 \uadf8\ub9bc\uc790\ub97c \uc81c\uc678\ud558\uace0 \ucc3d \ubd80\ubd84\ub9cc \uae54\ub054\ud558\uac8c \ucea1\ucc98\uac00 \ub41c \ubaa8\uc2b5\uc785\ub2c8\ub2e4.\\n\\n_\ucc3d \ucea1\ucc98 \uc2dc, \ubc30\uacbd\uc740 \ud22c\uba85 \ucc98\ub9ac\ub41c \uc0c1\ud0dc\uc785\ub2c8\ub2e4._\\n\\n## \ucc3d \ud06c\uae30\uac00 \ub2e4\ub978\uac70 \uc544\ub2cc\uac00\uc694?\\n\\n\uc704 \ud654\uba74\uc5d0\uc11c \uadf8\ub9bc\uc790\ub97c \ud3ec\ud568\ud55c \ucea1\ucc98 \uc774\ubbf8\uc9c0\uac00 \uc791\uc544\ubcf4\uc774\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \ucc3d\uc758 \ud06c\uae30\ub294 \uac19\uace0, \uc5ec\ubc31\uc744 \ud3ec\ud568\ud55c \uacb0\uacfc\ubb3c\uc774 \uc774\ubbf8\uc9c0\uc758 \ud06c\uae30\uac00 \ud07d\ub2c8\ub2e4.\\n\\n## \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95\\n\\n### \uadf8\ub9bc\uc790 \uc81c\uac70 \ud65c\uc131\ud654\\n\\n\'\ud130\ubbf8\ub110\' \uc571\uc744 \uc5f4\uace0 \uc544\ub798 \uba85\ub839\uc5b4\ub97c \uc21c\uc11c\ub300\ub85c \uc2e4\ud589\ud574\uc90d\ub2c8\ub2e4.\\n\\n\uc544\ub798 \uba85\ub839\uc5b4\ub97c \uc2e4\ud589\ud574\uba74 \uc544\ubb34 \uba54\uc138\uc9c0 \ub098\uc624\uc9c0 \uc54a\uc9c0\ub9cc \uc801\uc6a9\uc774 \ub41c \uc0c1\ud0dc\uc785\ub2c8\ub2e4.\\n\\n```\\ndefaults write com.apple.screencapture disable-shadow -bool true\\nkillall SystemUIServer\\n```\\n\\n### \uadf8\ub9bc\uc790 \uc81c\uac70 \ube44\ud65c\uc131\ud654 (\uc6d0\uc0c1\ubcf5\uad6c)\\n\\n\uc704\uc5d0\uc11c \uba85\ub839\uc5b4\ub97c \uc2e4\ud589\ud588\ub358 \uac83\ucc98\ub7fc \'\ud130\ubbf8\ub110\' \uc571\uc744 \uc5f4\uace0 \uc544\ub798 \uba85\ub839\uc5b4\ub97c \uc21c\uc11c\ub300\ub85c \uc2e4\ud589\ud574\uc90d\ub2c8\ub2e4.\\n\\n```\\ndefaults write com.apple.screencapture disable-shadow -bool false\\nkillall SystemUIServer\\n```"},{"id":"npm-remove-unused-packages","metadata":{"permalink":"/blog/npm-remove-unused-packages","source":"@site/blog/2022-09-08-npm-remove-unused-packages/index.md","title":"npm \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubaa8\ub4c8 \uc81c\uac70\ud558\ub294 \ubc29\ubc95 (depcheck)","description":"\ud504\ub85c\uc81d\ud2b8 \ub0b4\ubd80\uc5d0\uc11c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 npm module\uc744 package.json\uc5d0\uc11c \ud655\uc778 \ubc0f \uc81c\uac70\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-09-08T00:00:00.000Z","tags":[{"inline":true,"label":"NPM","permalink":"/blog/tags/npm"}],"readingTime":0.67,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"npm \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubaa8\ub4c8 \uc81c\uac70\ud558\ub294 \ubc29\ubc95 (depcheck)","slug":"npm-remove-unused-packages","authors":["kgenots"],"tags":["NPM"],"image":"/assets/blog/npm-remove-unused-packages.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ub9e5 \ud654\uba74\ucea1\ucc98 \uc2dc, \ucc3d \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95","permalink":"/blog/mac-remove-window-shadow"},"nextItem":{"title":"npm package.json \uc21c\uc11c \uc815\ub82c\ud558\ub294 \ubc29\ubc95 (sort-package-json)","permalink":"/blog/npm-sort-package-json"}},"content":"\ud504\ub85c\uc81d\ud2b8 \ub0b4\ubd80\uc5d0\uc11c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 npm module\uc744 package.json\uc5d0\uc11c \ud655\uc778 \ubc0f \uc81c\uac70\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/npm-remove-unused-packages.webp\\"\\n    alt=\\"npm-remove-unused-packages\\"\\n  />\\n</figure>\\n\\n\ud504\ub85c\uc81d\ud2b8\ub97c \uc7a5\uae30\uac04 \uc9c4\ud589\ud558\ub2e4\ubcf4\uba74, node module \uc744 \uc124\uce58\ud558\uace0 \uc9c0\uc6b0\uace0\ub97c \ubc18\ubcf5\ud558\ub294 \uacbd\uc6b0\uac00 \uc0dd\uae41\ub2c8\ub2e4.\\n\\nrequire \ub098 import \ub97c \ud1b5\ud574 node module \uc0ac\uc6a9 \ubd80\ubd84\uc740 \uc9c0\uc6b0\uae30 \ud3b8\ud558\uc9c0\ub9cc, \uc124\uce58 \ub2f9\uc2dc\uc5d0 \ucd94\uac00\ub41c package.json \ub0b4\ubd80\uc758 dependencies\uc640 devDependencies \uc5d0\uc11c\ub294 \uc9c0\uc6b0\uc9c0 \ubabb\ud574 \ub0a8\ub294 \uacbd\uc6b0\uac00 \uc885\uc885 \uc0dd\uae30\uace4 \ud569\ub2c8\ub2e4.\\n\\ndepcheck\ub97c \uc774\uc6a9\ud558\uba74 \ubbf8\uc0ac\uc6a9\uc0c1\ud0dc\ub85c dependencies\uc640 devDependencies\uc5d0 \uc801\ud600\uc788\ub294 node module\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n**\uc8fc\uc758\uc0ac\ud56d\uc73c\ub85c lint, prettier \ub4f1 runtime \ucf54\ub4dc\uc5d0\uc11c \ud638\ucd9c\ub418\uc9c0 \uc54a\uace0 \uac1c\ubc1c\uc744 \uc704\ud574\uc11c\ub9cc \uc0ac\uc6a9\ub418\ub294 module\ub3c4 \uc0ac\uc6a9\ub418\uc9c0 \uc54a\ub294 \ubaa8\ub4c8\uc5d0 \ud3ec\ud568\ub420 \uc218 \uc788\uc73c\ub2c8 \uc219\ub828\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \ubaa8\ub974\ub294 \ubaa8\ub4c8 \uc81c\uac70\ub294 \uc0bc\uac00\ud558\ub294 \uac83\uc744 \ucd94\ucc9c\ud569\ub2c8\ub2e4.**\\n\\n## \uc0ac\uc6a9\ubc29\ubc95\\n\\n```\\nnpx depcheck\\n```\\n\\n## \ucc38\uace0\\n\\nhttps://github.com/depcheck/depcheck\\n\\n<div class=\\"link-preview-container\\">\\n  <a href=\\"https://github.com/depcheck/depcheck\\"></a>\\n\\n  <div class=\\"link-preview-top\\">\\n    <div class=\\"link-preview-image\\">\\n      <img\\n        src=\\"https://opengraph.githubassets.com/c2050797da1d240a5d0f73c6995e3f7ca7044ccb6585a61df8c72f8d1065c9c0/depcheck/depcheck\\"\\n        alt=\\"Article Thumbnail\\"\\n      />\\n    </div>\\n\\n    <div class=\\"link-preview-content\\">\\n      <div class=\\"link-preview-title\\">\\n        GitHub - depcheck/depcheck: Check your npm module for unused\\n        dependencies\\n      </div>\\n      <div class=\\"link-preview-description\\">\\n        Check your npm module for unused dependencies. Contribute to\\n        depcheck/depcheck development by creating an account on GitHub.\\n      </div>\\n    </div>\\n\\n  </div>\\n</div>"},{"id":"npm-sort-package-json","metadata":{"permalink":"/blog/npm-sort-package-json","source":"@site/blog/2022-09-08-npm-sort-package-json/index.md","title":"npm package.json \uc21c\uc11c \uc815\ub82c\ud558\ub294 \ubc29\ubc95 (sort-package-json)","description":"npm install \ud560 \ub54c, \uc124\uce58\ud55c \uc21c\uc11c\ub300\ub85c \uc791\uc131\ub418\ub294 package.json\uc744 \uc54c\ud30c\ubcb3 \uc21c\uc11c\ub85c \uc815\ub9ac\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-09-08T00:00:00.000Z","tags":[{"inline":true,"label":"NPM","permalink":"/blog/tags/npm"}],"readingTime":0.65,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"npm package.json \uc21c\uc11c \uc815\ub82c\ud558\ub294 \ubc29\ubc95 (sort-package-json)","slug":"npm-sort-package-json","authors":["kgenots"],"tags":["NPM"],"image":"/assets/blog/npm-sort-package-json.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"npm \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubaa8\ub4c8 \uc81c\uac70\ud558\ub294 \ubc29\ubc95 (depcheck)","permalink":"/blog/npm-remove-unused-packages"}},"content":"npm install \ud560 \ub54c, \uc124\uce58\ud55c \uc21c\uc11c\ub300\ub85c \uc791\uc131\ub418\ub294 package.json\uc744 \uc54c\ud30c\ubcb3 \uc21c\uc11c\ub85c \uc815\ub9ac\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/npm-sort-package-json.webp\\"\\n    alt=\\"npm-sort-package-json\\"\\n  />\\n</figure>\\n\\npackage.json \uc758 dependencies \ub098 devDependencies \uac00 \uc54c\ud30c\ubcb3 \uc21c\uc11c\ub300\ub85c \uc815\ub9ac\ud558\uace0 \uc2f6\uc744 \ub54c, package.json\uc758 \ud0a4 \uc21c\uc11c\uac00 \uc11e\uc5ec\uc788\uc5b4\uc11c license \ub4f1 \ud2b9\uc815 \ud0a4\ub97c \ucc3e\uae30 \uc5b4\ub824\uc6cc \ud560 \ub54c \ud130\ubbf8\ub110\uc5d0\uc11c **npx sort-package-json**\ub9cc \uc785\ub825\ud574\uc8fc\uba74 \ud574\ub2f9 \ub514\ub809\ud1a0\ub9ac \ub0b4 package.json \ub0b4\uc6a9\uc774 \uc815\ub9ac\uac00 \ub429\ub2c8\ub2e4.\\n\\n## \uc0ac\uc6a9\ubc29\ubc95\\n\\n```\\nnpx sort-package-json\\n```\\n\\npackage.json \ud30c\uc77c\uc774 \uc874\uc7ac\ud558\ub294 \ud3f4\ub354\uc5d0\uc11c \ud130\ubbf8\ub110\uc744 \uc5f4\uace0 \uc704 \uba85\ub839\uc5b4\ub97c \uc2e4\ud589\ud569\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\\n\\nhttps://github.com/keithamus/sort-package-json\\n\\n<div class=\\"link-preview-container\\">\\n    <a href=\\"https://github.com/keithamus/sort-package-json\\"></a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img src=\\"https://opengraph.githubassets.com/9baae571fe9d426d5a6ba3cc1cef97baa5b8f9497fce5a54886a46088e04548f/keithamus/sort-package-json\\" alt=\\"Article Thumbnail\\" />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">GitHub - keithamus/sort-package-json: Sort an Object or package.json based on the well-known package.json keys</div>\\n            <div class=\\"link-preview-description\\">Sort an Object or package.json based on the well-known package.json keys - GitHub - keithamus/sort-package-json: Sort an Object or package.json based on the well-known package.json keys</div>\\n        </div>\\n    </div>\\n</div>"}]}}')}}]);